(window.FREALLY_I18N = window.FREALLY_I18N || {})["ar"] = {"hero.headline":"<span class=\"hl-muted\">جلسة واحدة.</span> <span class=\"hl-bright\">أربعة منتجين.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">بلا خادم.</span>","hero.cycle":"بلا خادم.|بلا حساب.|بلا ذكاء اصطناعي.","hero.tagline":"محطة عمل صوتية يعمل فيها أربعة منتجين داخل الجلسة نفسها في الوقت نفسه.","what.title":"ما هذا","what.p1":"كل محطة عمل صوتية هي برنامج للاعب واحد. صنع تسجيل مع شخص في بلد آخر ما زال يعني تصدير الأجزاء ورفعها والانتظار وإعادة استيرادها وفقدان الخيط — وبعد ستة أشهر لا أحد يتذكر من كتب خط الباص.","what.p2":"‏Oscillate محطة عمل كاملة بُنيت على الافتراض المعاكس. تلصق رمز غرفة في محادثة فينضم إلى جلستك حتى ثلاثة منتجين آخرين: ترى كاميراتهم، وتسمعهم، وتتحرك مؤشراتهم على خطك الزمني — وعند الانتهاء يطبع ورقة توزيع تقول من كتب ماذا.","what.p3":"هو مجاني اليوم، ولا يوجد خادم خلفه. رمز الغرفة نفسه هو عرض الاتصال: أول شخص يلصق رمزًا، وبعد ذلك تتولى الغرفة التمرير للجميع. لا شيء يجب إبقاؤه يعمل، ولا شيء يُدفع، ولا شيء يستطيع أحد إطفاءه.","features.title":"ما بداخله","features.room.title":"الغرفة","features.room.body":"حتى أربعة منتجين، من جهاز إلى جهاز، بلا حساب وبلا خادم. مؤشرات حيّة ودردشة وصوت ومربعات كاميرا ومشاركة شاشة. تراجعك يسترجع تغييرك أنت، ولا يسترجع تغيير غيرك أبدًا.","features.arrangement.title":"التوزيع","features.arrangement.body":"مسارات صوت وMIDI بلا حدود، ومقاطع تُرسم من محتواها نفسه، ومسارات أتمتة، وتجميع التسجيلات، ومجموعات، وعلامات، وخريطة إيقاع وميزان. كل تعديل يُتراجع عنه بضغطة واحدة مهما بلغ عدد المقاطع التي مسّها.","features.pianoRoll.title":"لفّة البيانو","features.pianoRoll.body":"نحو تسعين مقامًا مع الإبراز والالتقاط والطيّ، ونوتات شبحية من أي مقطع آخر، ومسار شدّة بمقبض لكل نوتة، ولوحة مفاتيح تُعزف عليها ويعزف فيها مفتاح واحد تآلفًا كاملًا.","features.plugins.title":"تشغيل الإضافات","features.plugins.body":"‏VST3 وCLAP، كلٌّ في عمليته الخاصة، فالإضافة التي تنهار تُطفئ جهازًا واحدًا بدل أن تأخذ جلستك معها. تعويض التأخير عبر الرسم البياني كله، مُثبت باختبار إلغاء لا بمجرد ادّعاء.","features.devices.title":"آلاته الخاصة","features.devices.body":"خمس وثمانون آلة ومؤثرًا، لوحاتها مرسومة من وصف الجهاز نفسه — فالرقم على المقبض هو الرقم الذي يستعمله الصوت فعلًا، مقيسًا إلى عُشر الديسيبل — وواجهات ترسم الصوت المارّ عبرها، حيًّا.","features.lessons.title":"الدروس","features.lessons.body":"خمس عشرة دورة، يومًا بيوم، من البيانو والغيتار إلى كتابة الأغاني والمزج. تُعرض كل خطوة على المسرح أولًا، ثم يستمع إليك الدرس وأنت تعزف، على هذا الحاسوب فقط ودون أن يسجّل شيئًا، ويسمّي المازورة والنبضة والإصلاح.","features.finalCheck.title":"الفحص النهائي","features.finalCheck.body":"ماستر لكل وجهة، تُصدَّر معًا ويُقاس كلٌّ منها من ملفه. استمع إلى المزيج كما يعزفه هاتف أو سيارة، وافحص جهارة كل قسم، وقِس ملفًا على مواصفات تسليم.","features.suggest.title":"«اقتراح» و«امزجه من أجلي»","features.suggest.body":"كل بطاقة مؤثر تقيس ما يصلها وتقترح ضبطًا، مع أسبابه. وزرٌّ واحد يضبط المزيج كله ويوصل الماستر إلى هدفه، في خطوة تراجع واحدة. حساب، لا نموذج.","features.pitch.title":"نقل الطبقة والتمديد","features.pitch.body":"ارفع امتدادًا من تسجيل أو اخفضه مع الحفاظ على صيغه الصوتية، ولائم مقطعًا مع الإيقاع دون تغيير طبقته. ولا يُمس ملفك أبدًا.","features.phone.title":"المزيج على هاتفك","features.phone.body":"أرسل المزيج وكل جزء إلى هاتف على شبكة Wi-Fi لديك عبر رمز QR، وامزجها هناك واحفظها ملفات. لا شيء لتثبيته، ولا شيء يغادر شبكتك.","features.retro.title":"Oscillate Retro Record","features.retro.body":"الدقائق الأخيرة مما عزفته، محفوظة في الذاكرة، فيظل ممكنًا حفظ اللقطة التي لم تضغط زر التسجيل لها قط. يسأل أولًا، ولا يكتب شيئًا حتى تحفظ.","features.cut.title":"القَطْع","features.cut.body":"ارسم ضربة نصل عبر التوزيع فتشقّ كل مقطع تمرّ به؛ وزاوية الضربة تحدد ميل التلاشي المتقاطع. هذه هي لغة الحركة التي بُنيت عليها الواجهة كلها.","features.kumite.title":"الكوميتي وورقة التوزيع","features.kumite.body":"وضع مبارزة إيقاعات يملك فيه كل دور موازيره الخاصة، وسجل تأليف مستخرج من سجل التعديلات، مخصومًا منه كل عمل تراجع عنه أحد.","features.free.title":"مجاني، وبلا ذكاء اصطناعي","features.free.body":"لا فئات ولا فترة تجربة ولا حساب ولا مفتاح ترخيص. لا نموذج ولا استدلال ولا أي شيء «ذكي» — وهذا ليس وعدًا: بوابة بناء تفشل فور دخول أي بيئة تعلّم آلي إلى رسم الاعتماديات.","ladder.title":"الطريق إلى 1.0","ladder.intro":"سطر واحد لكل درجة. إنه السلّم نفسه الذي تتبعه الخطة الداخلية — إن تحرك أحدهما تحرك الآخر، وبوابة بناء تقارن بينهما.","ladder.rung.v0.0.1":"الأساس، والعمود الفقري لـ CI، والترخيص وEULA — ونافذة فارغة تُثبَّت من الآن على ثلاثة أنظمة تشغيل.","ladder.rung.v0.1.0":"الغلاف ومحرّك الصوت. يبدو مثل Oscillate ويُصدر صوتًا.","ladder.rung.v0.2.0":"المشروع وعرض التوزيع. إنه محطة عمل صوتية.","ladder.rung.v0.2.5":"المحرّرات — لفّة البيانو، وشبكة الإيقاع، والأتمتة، والتجميع، والقَطْع، والكاتا، وإرجاع الجلسة.","ladder.rung.v0.3.0":"استضافة الإضافات والأجهزة المرفقة — VST3 وCLAP خارج العملية، وتسعة وستون جهازًا خاصًا به.","ladder.rung.v0.4.0":"أدوات الكتابة — مستعرض الملفات، وتحويل المسارات المنفصلة إلى مولّدات، ومسار التصدير.","ladder.rung.v0.4.5":"قرار المضيّ أو عدمه في الويب، والإفلات على الخط الزمني، وواجهة لكل جهاز، والصوت الحصري.","ladder.rung.v0.5.0":"الغرفة: النواة — اتصال بلا خادم، والحضور، والمزامنة، والدردشة.","ladder.rung.v0.5.5":"الغرفة: البث الحي — الصوت، والفيديو، ومشاركة الشاشة، والتسليم، والكوميتي، وورقة التوزيع.","ladder.rung.v0.6.0":"الهوية — مسار الكلمات، والفاصل الزمني للجلسة، وبطاقات الجلسة، وصفحة الشكر.","ladder.rung.v0.6.5":"مظهر العائلة، نفسه في كل تطبيقات Freally — مقابض ومنزلقات وأزرار مُصيَّرة في Blender، ووضعان فاتح وداكن بأخضر Freally، وأصوات للواجهة وشريط عنوان داكن — ومكتبة آلات واحدة مشتركة مع Freally MIDI Master.","ladder.rung.v0.7.0":"محرّك واحد — حِزم الصوت والآلات المشتركة مثبّتة على وسم واحد، وأسس الدرجات التالية وقد أُدخلت، ومؤشّر عائلة Freally ومفاتيح التبديل فيها.","ladder.rung.v0.8.0":"Freally MIDI Master وFlipcopy وTakelight مدمجة — إضافات مرفقة في المستعرض مع درس تعليمي، وأغاني MIDI Master تُسحب إلى التوزيع، وتصدير يحمل معه الإضافات المستضافة.","ladder.rung.v0.9.0":"المسرح — أيادٍ ثلاثية الأبعاد تعزف أي مسار MIDI، وأصوات جديدة، ومضخّم وآلة إيقاع، ومستعرض الآلات.","ladder.rung.v0.10.0":"النوتات — تدوين موسيقي بجودة الطباعة، وTAB للغيتار، وقارئ النوتات، والكلمات تحت المدرج الموسيقي، وPDF.","ladder.rung.v0.11.0":"الدروس — خمس عشرة دورة، و«أرِني»، والاستماع الحي عبر مدخلك الخاص، مع التقييم.","ladder.rung.v0.12.0":"أدوات الاستوديو الخاصة — تحريك طبقة الصوت، وتمديد الزمن، والتحليل الحي، ومضاعِف صوتي وأداة خفض تلقائي، وماستر لكل وجهة، والفحوص النهائية.","ladder.rung.v0.13.0":"MixSir — المزج على هاتفك، مقترنًا عبر رمز QR.","ladder.rung.v0.14.0":"أجهزة جديدة، الموجة الأولى — الترددات المنخفضة والإيقاع.","ladder.rung.v0.15.0":"أجهزة جديدة، الموجة الثانية — آلات لمصمّم الصوت.","ladder.rung.v0.16.0":"أجهزة جديدة، الموجة الثالثة — زر تسجيل يعود بالزمن إلى الوراء، والبحث عن الأصوات المتشابهة بين أصواتك.","ladder.rung.v0.17.0":"المعيار الرائد وزوج الترددات المنخفضة — Oscillate Sub وOscillate Width، مرتبطَين.","ladder.rung.v0.18.0":"المعادلة والديناميكيات بمستوى رائد — كل معادِل وضاغط ومحدِّد ومزيل للصفير وبوابة يُرفع إلى أفضل ما في صنفه، ومعها Oscillate Resonance.","ladder.rung.v0.19.0":"التلوين والمساحة والحركة بمستوى رائد — رفعُ مستوى التشبّع والصدى والريفيرب والتعديل والمرشّحات؛ وOscillate Shaper وVoice Changer وEcho Reverb.","ladder.rung.v0.20.0":"Oscillate Wavetable — مُركِّب رائد هجين بجداول الموجات.","ladder.rung.v0.21.0":"Oscillate Analog، ورفعُ مستوى المُركِّب متعدد الطبقات ومُعايِن العيّنات والطبول والمشغّل.","ladder.rung.v0.22.0":"Oscillate Retake — محرر النوتات والمغنّي من Freally Retake، مدمجان فيه.","ladder.rung.v0.23.0":"Oscillate Master، وحزمة الإصلاح ومحرر الطيف، والنماذج المدرَّبة هنا.","ladder.rung.v0.24.0":"كل جهاز مرفق وكل إعداد مسبق من المصنع يبلغ المستوى الرائد.","ladder.rung.v1.0.0-beta":"النسخة التجريبية — تجميد جديد للميزات، والتطبيق كله بمظهر واحد و18 لغة، وهذا الموقع وقد أُعيدت كتابته. تتكرر حتى ينتهي الاختبار. لا تنزيلات على هذه الصفحة.","ladder.rung.v1.0.0-rc":"المرشّح للإصدار — التقوية، والمراجعة الشاملة، واختبار كل ميزة في تطبيق الإصدار، في محرّك Windows وفي محرّكَي macOS وLinux. يتكرر حتى يصمد أحدها نظيفًا.","ladder.rung.v1.0.0":"مستقر ومجاني، وفي داخله Freally MIDI Master وFlipcopy وTakelight. تُفتح التنزيلات لاحقًا.","ladder.note":"الدرجة التي تمّت مبنية وموجودة على فرع التطوير. ليست تنزيلًا: لا توجد تنزيلات، ولن توجد قبل 1.0.0.","honest.title":"الأمور التي تضعها معظم المواقع في الأسفل","honest.peers.title":"أربعة منتجين، لا خمسة","honest.peers.body":"تتسع الغرفة لأربعة أشخاص. لا خادم يمرّر الصوت، فكل واحد يُرسل إلى الجميع، والاتصال الخامس هو النقطة التي ينفد عندها رفع منزلي عادي. أربعة هو الرقم الذي ينجح، لا الرقم الذي يبدو جميلًا.","honest.failure.title":"نحو واحد من كل عشرة اتصالات لن ينعقد","honest.failure.body":"بعض الشبكات تمنح كل اتصال صادر عنوانًا مختلفًا، واثنان من هذا النوع لا يجد أحدهما الآخر دون مُرحِّل في المنتصف. المُرحِّل يكلّف نطاقًا تردديًا إلى الأبد، وهذه فاتورة مستمرة لا يستطيع تطبيق مجاني تحمّلها — لذلك يأتي Oscillate بلا مُرحِّل ويتيح لك وضع مُرحِّلك في الإعدادات. وحين يفشل اتصال، يسمّي أيًّا من الأسباب التسعة كان.","honest.code.title":"ما الذي يحتويه رمز الغرفة فعلًا","honest.code.body":"هو عرض الاتصال نفسه، ويحمل العنوان العام لحاسوبك. عامله كأنه كلمة مرور: أرسله لمن تعمل معهم فقط. والتطبيق يقول لك ذلك في اللحظة التي تنسخ فيها رمزًا.","honest.downloads.title":"لا تنزيلات قبل 1.0.0","honest.downloads.body":"لا نسخة تجريبية على هذه الصفحة، ولا بناء معاينة، ولا وصول مبكر. محطة عمل تعمل نصف عمل أسوأ من واحدة لم توجد بعد.","honest.ai.title":"لا ذكاء اصطناعي، وكيف يُفرض ذلك","honest.ai.body":"بوابة بناء تمشي في رسم الاعتماديات وتفشل أمام أي بيئة استدلال، وأي ملف نموذج، وأي مكتبة تحليلات أو إبلاغ عن الأعطال. إنها خاصية في البناء لا جملة على موقع.","honest.updater.title":"الاتصال الوحيد الذي يجريه التطبيق","honest.updater.body":"فحص التحديثات، ولا يجري إلا حين تضغط الزر أو تُفعّل الفحص عند بدء التشغيل — وهو معطّل افتراضيًا. يطلب ملفًا ثابتًا واحدًا ولا يرسل شيئًا عنك ولا عن جهازك، وكل تحديث موقَّع، ولا يُثبَّت أي تحديث دون اختيارك.","site.tagline":"محطة عمل صوتية يعمل فيها أربعة منتجين داخل الجلسة نفسها في الوقت نفسه.","footer.licence":"ملكية خاصة — جميع الحقوق محفوظة. © Mike Weaver. الاستخدام مجاني اليوم؛ وقد تُباع الإصدارات المستقبلية. ليس مفتوح المصدر.","footer.yours":"ما تصنعه به لك أنت. لا يدّعي مؤلف Oscillate أي ملكية على المشاريع أو ملفات MIDI أو الصوت أو النسخ النهائية التي تنشئها به.","features.7ffdfbe91dc1":"محطة عمل صوتية كاملة فيها غرفة: حتى أربعة منتجين في جلسة واحدة، في الوقت الفعلي، بلا حساب وبلا خادم.","features.02a7818a6ee0":"تصف هذه الصفحة Freally Oscillate كما سيكون في الإصدار 1.0 — الدرجة التي ينتهي عندها السلّم — ولا تصف شيئًا مما خُطّط له بعده.","features.b4a6bff8b8c9":"كل رقم هنا عدٌّ لما يحمله الإصدار 1.0. لا شيء مقدَّر، ولا شيء مُقرَّب إلى الأعلى. يعزف Freally Secretarium مكتبة الآلات نفسها التي يعزفها Freally MIDI Master: مكتبة واحدة يثبّت كلاهما نسختها، لا نسختان تتباعدان مع الوقت.","features.7ec427c672a2":"منتجين في غرفة واحدة","features.d6f79cef6f38":"آلةً ومؤثرًا من صنعه","features.3a6743460cf9":"آلةً في Freally Secretarium","features.18c9c4777852":"مقامًا في لفّة البيانو","features.7241e8c55883":"طقم طبول","features.23131443a715":"سمات، فاتحة وداكنة، بأخضر Freally","features.9bb4817f8251":"لغة، ومنها لغات تُكتب من اليمين إلى اليسار","features.09b3154dfa60":"حسابات يلزمك إنشاؤها","features.35b8cb8439d7":"نماذج ذكاء اصطناعي","features.38055402e560":"السعر اليوم","features.da9afac0d7b7":"إنه مجاني اليوم. كلّه.","features.f997324cb19b":"كل ميزة، للجميع. لا فئة مدفوعة، ولا فترة تجربة تنتهي، ولا مفتاح ترخيص، ولا حساب، ولا شراء داخل التطبيق.","features.22f1bb054323":"ما تصنعه به لك أنت. لا يدّعي مؤلف Oscillate أي ملكية على المشاريع أو ملفات MIDI أو الصوت أو النسخ النهائية التي تنشئها به، ولا يطلب أي عائدات ولا ذكرًا لاسمه.","features.c74ea9dc9cd2":"ما يفعله","features.45a1b4ecfbf5":"غرفة لا خادم خلفها","features.c3ea64baf32c":"أرسل رمز غرفة إلى من تعمل معه، فيستطيع حتى ثلاثة منتجين آخرين الانضمام إلى جلستك: مؤشراتهم على خطك الزمني، ودردشة، وصوت، ومربعات كاميرا، ومشاركة شاشة. من جهاز إلى جهاز، بلا حساب وبلا خادم في المنتصف.","features.225507990407":"تراجعك لك أنت","features.cb2c6359ccf6":"يسترجع <kbd>Ctrl</kbd>+<kbd>Z</kbd> آخر تغيير أجريته أنت ولا يسترجع تغيير غيرك أبدًا، حتى وتعديلاتهم تصل. وسجل التعديلات الذي يقف خلفه هو أيضًا مزامنة الغرفة وإرجاع الجلسة وورقة التوزيع.","features.056c3540052c":"التسليم","features.be31856f2db7":"سلّم مسارًا واحدًا لمتعاون واستعده بمفتاح واحد. وما دام في يده فهو الكاتب الوحيد عليه — حتى بالنسبة إليك — وهذا مفروض حيث تُفحص التعديلات، لا في الواجهة فقط.","features.f4d5f7765113":"الكوميتي","features.d3a91a73c5cc":"وضع مبارزة إيقاعات يملك فيه كل دور موازيره الخاصة. العدّ التنازلي مجرد عدّ تنازلي؛ والمازورات هي القاعدة، فلا يمكن أن يختلف حاسوبان أبدًا على أيّ تعديل كان مشروعًا.","features.6ed23a3037fc":"ورقة التوزيع","features.68481398e863":"من كتب ماذا، مستخرجًا من سجل التعديلات، مخصومًا منه كل عمل تراجع عنه أحد. نقطة بداية لحديث عن الحقوق والنسبة، لا وثيقة قانونية — وهي تقول ذلك.","features.6ffb37f5c47d":"اللقطات تنتقل؛ والعيّنات لا تنتقل أبدًا","features.2dc43d70f9ea":"اللقطة المسجّلة في الغرفة تقع على الخط الزمني لدى الجميع. أما العيّنة التي اشتريتها فلا تُرسل أبدًا: ترسل الغرفة الإشارة إليها، ويُخبَر المتعاون الذي لا يملك الحزمة بالعيّنات التي يحتاجها.","features.c3e61cb4f392":"MixSir — المزيج على هاتفك","features.e0dafbc1f74f":"أرسل المزيج وكل جزء إلى هاتف على شبكة Wi-Fi لديك عبر رمز QR. يُفتح في متصفح الهاتف دون أن تثبّت شيئًا، ويُمزج هناك بالكسب والبان والكتم والإفراد، ويُحفظ أي جزء على الهاتف ملفًّا. ولا ينتقل إلا عبر شبكتك أنت، خلف مفتاح صُنع لذلك الاقتران وحده. جديد في v0.16.0.","features.2e5511855cbc":"التوزيع","features.b9277cfd1dc1":"مسارات صوت وMIDI بلا حدود، ومقاطع تُرسم مما هي عليه، وأتمتة على كل منزلق وكل بان وكل عنصر تحكم في جهاز، والتجميع، والمجموعات، والعلامات، وخرائط الإيقاع والميزان. النمط الموضوع عشر مرات نمط واحد: عدّله مرة فيتغير كل موضع له، إلى أن تجعل أحدها فريدًا.","features.3a0225628776":"مُطلِق المقاطع وعدة توزيعات","features.09461b13e994":"أطلِق المقاطع والمشاهد كاملة على المازورة، ودع مشهدًا يتبع آخر، وسجّل ما أطلقته عائدًا إلى التوزيع في خطوة تراجع واحدة. ويضم المشروع عدة توزيعات لأغنية واحدة، لكلٍّ منها مقاطعه وعلاماته فوق المسارات نفسها والمازج نفسه. وتُرسم الأنماط رسمًا متكررًا على طول المسار، ويستقر شريط تكبير فوق الخط الزمني، ولكل أداة مفتاحها. جديد في v0.16.0.","features.3933d56d65a8":"القَطْع وإرجاع الجلسة","features.7e57d69f84a4":"ارسم ضربة نصل عبر التوزيع فتشقّ كل مقطع تمرّ به، وزاوية الضربة تحدد التلاشي المتقاطع. ومرّر تاريخ الجلسة كما تمرّر فيديو، وأنشئ فرعًا من أي نقطة فيه.","features.dac11b27d868":"لفّة البيانو","features.8b5fc8a25fa8":"نحو تسعين مقامًا مع الإبراز والالتقاط والطيّ، ونوتات شبحية من أي مقطع آخر، ومسار شدة بمقبض لكل نوتة، ومسارات لعدد مرات عزف كل نوتة ولمدى تجوّل شدتها، ولوحة مفاتيح يمكن لمفتاح واحد فيها أن يعزف تآلفًا كاملًا.","features.a40e410cd4b9":"رف الأنماط","features.6c8a2c880e29":"ابنِ جزءًا صفًّا صفًّا فوق التوزيع، بالنقر على الخطوات داخل الرف مباشرة: كل صف على سطر واحد بضوء مساره وبانه ومستوى صوته وإفراده، ورسم بياني لشدة كل خطوة وبانها وضبطها الدقيق للنغمة واحتمالها. يكرّر وضع النمط النمطَ المفتوح على أصوات مساراته نفسها دون المساس بالأغنية، ويضعه «وضع النمط» في الأغنية مرتبطًا. جديد في v0.9.0، ومصقول في v0.10.0.","features.510ceece9d3b":"Drum Machine وشبكة الإيقاع","features.e81deb2b9e8b":"ست عشرة وسادة على أربعة أطقم مدمجة، تُختار كل ضربة بحسب قوة عزفك، مع ما يصل إلى أربع طبقات لكل وسادة، والخنق، والعكس، وتسوية المستوى. شبكة الإيقاع مُتسلسِل خطوات بالسوينغ والشدة، وخريطة الطبول تعزف على طقمك طبولًا كُتبت لطقم آخر، ويمكن لوحدة التحكم بالوسادات لديك أن تتعلّم الوسادات. جديد في v0.9.0.","features.87200be7fce5":"المسرح","features.c40c7b78e163":"أيادٍ على بيانو أو غيتار أو باص أو وحدة تحكم بالوسادات أو طقم طبول ثلاثي الأبعاد تعزف أي مسار MIDI في تزامن مع شريط النقل. اختر الكاميرا والجودة ولون البشرة، واعزف بنفسك على المسار المجهَّز. جديد في v0.9.0.","features.578fae09a667":"النوتة الموسيقية وTAB وملف PDF","features.ca873a2c8b0a":"أي مسار MIDI مدوّنًا كنوتة موسيقية في لوحة خاصة به: مدرج بمفتاح صول أو بمفتاح فا أو مدرج مزدوج، وتدوين TAB للغيتار والباص مع مخططات التآلفات، وأوراق طبول تقول أي يد أو قدم تعزف كل ضربة، والكلمات تحت النوتات. تنقلب الصفحات مع الأغنية وتضيء النوتات المسموعة، وتُصدَّر الأغنية كلها ملفَّ PDF بمقاس A4 مع صفحة غلاف والاعتمادات، أو تُطبع. جديد في v0.10.0.","features.cb4ad503e340":"الدروس","features.60f0879d73b2":"خمس عشرة دورة، تتعلّمها يومًا بيوم: البيانو والغيتار والباص والطبول، وقراءة النوتة والإيقاع، والأذن والنظرية، وكتابة الأغاني، والكلمات، والراب، والتوزيع، والمزج. يعزف «أرني» كل خطوة على المسرح أولًا، وتقرؤها «القراءة بصوت عالٍ» بصوت حاسوبك نفسه، ويستمع الدرس إلى آلتك عبر واجهتك الصوتية، على هذا الحاسوب فقط ودون أن يسجّل شيئًا، ثم يسمّي المازورة والنبضة والإصلاح. ومشروعك ينتظر، دون أن يُمس، بينما تتعلّم. جديد في v0.12.0.","features.50f00c2a81bc":"مستعرض الآلات","features.72db395b279f":"الآلات الـ 1648 كلها في مجلدات حسب العائلة، ونجمة للآلات التي تعود إليها، وأصوات من صنعك، واستماع تجريبي يعزف نوتات المسار المحدد نفسه عبر كل آلة. ويجمع PACK حتى 25 ضربة مفردة ويصدّرها ملفات WAV. جديد في v0.9.0.","features.e840a6b2c21b":"البحث عن المتشابه ومطابقة الركلة والباص","features.4db0c395341e":"يرتّب البحث عن المتشابه أشباه صوت أو حلقة MIDI عبر مجلداتك، كلٌّ منها مع سببه: إعادة حفظ، أو تغيير في المستوى، أو قصّ، أو تغيير في الطبقة أو تمديد، أو الإيقاع نفسه. وترتّب مطابقة الركلة والباص كل باص في مجلد مقابل ركلة، مع إعادة الضبط التي تجعل الاثنين متوافقين في النغمة. قياس، لا نموذج. جديد في v0.16.0.","features.2f4a9c0d9ce6":"العزف الحي","features.ea63c07ebd35":"تعزف لوحة مفاتيح MIDI المسار المجهَّز مع تحويل الطبقة، ومدى للثني، ومنحنى لقوة الضغط، وتآلفات في مقام المشروع. وتصل عجلة ثني النغمة وعجلة التعديل والضغط إلى آلات المكتبة وإلى إضافاتك. جديد في v0.9.0.","features.a4592301df0c":"التسجيل والتجميع","features.3b56c85ac1f3":"تسجيل الصوت ولوحة مفاتيح MIDI عتادية على Windows وmacOS وLinux. تتكدّس اللقطات بعضها تحت بعض، وتختار الأجزاء التي تريدها، واللقطات التي لم تخترها لا تُحذف أبدًا. يُكتب الصوت على القرص لحظة وصوله، فلا يكلّف العطل إلا الكتلة الأخيرة لا اللقطة.","features.724e8a91b5e7":"Oscillate Retro Record","features.d2c74ab7b9ea":"الدقائق الأخيرة من مدخل الصوت لديك ومن لوحة مفاتيح MIDI، محفوظة في ذاكرة هذا الحاسوب، فيظل ممكنًا حفظ اللقطة التي عزفتها قبل أن تضغط زر التسجيل: مقطعًا على مسار عند المازورة التي عزفتها فيها، أو ملفَّ WAV بتاريخه ووقته. يسأل أولًا، ويُظهر ضوءًا ما دام يحتفظ بأي شيء، ولا يكتب شيئًا حتى تحفظ. جديد في v0.16.0.","features.7784d462ad95":"نقل الطبقة والتمديد","features.835c8aaec6ac":"ارفع امتدادًا من تسجيل أو اخفضه حتى أوكتاف كامل مع الحفاظ على صيغه الصوتية، فيبقى الصوت هو نفسه، ولائم مقطعًا مع الإيقاع دون تغيير طبقته. ولا يُمس ملفك أبدًا، وكل تصدير وكل متعاون يسمع الشيء نفسه. جديد في v0.12.0.","features.0baacdf5d6c4":"إضافاتك، كلٌّ في عملية خاصة بها","features.5fab46c33502":"‏VST3 وCLAP. الإضافة التي تنهار تجعل جهازها رماديًّا وتترك الجلسة تعمل. تعويض التأخير يشمل الرسم البياني كله ومُثبت باختبار إلغاء، والإضافة غير الموجودة على هذا الجهاز تصبح عنصرًا نائبًا مسمّى، فيبقى المشروع المفتوح في مكان آخر في توقيته.","features.74ed3ebdb3f9":"آلاته ومؤثراته الخاصة","features.71af57e5f2e7":"خمسة وثمانون جهازًا، منها Freally Secretarium وآلاته الـ 1648، ومضاعِف يخرج متطابقًا في كل مرة، وخافض يحرّكه مسار آخر، وجهاز يحفر للكيك مكانه، وباص reese يبقى صوته المنخفض (sub) أحاديًّا، وأربعون إحساسًا إيقاعيًا مكتوبًا باليد، وصفارة، وتأخير صدوي بطلقات الليزر، وعمود صخري حُبيبي، وعاصفة، ومن الجديد في v0.17.0 زوج الترددات المنخفضة: Oscillate Sub، جهير عميق يتبع ما تعزفه، وOscillate Width، الذي يوسّع ما فوقه ولا يُرقّق المجموع الأحادي أبدًا، ويتشاركان نقطة فصل واحدة حين يُربطان. كل لوحة مرسومة من وصف الجهاز نفسه، فالرقم على المقبض هو الرقم الذي يستعمله الصوت فعلًا؛ وكل واجهة ترسم الصوت المارّ عبرها، حيًّا؛ وتُنسخ إعدادات الجهاز سطرًا واحدًا يمكنك لصقه في دردشة.","features.afc35db2da83":"أجهزة تقرأ التوزيع","features.8d6419ade018":"ستة أجهزة تفعل ما لا تستطيعه الإضافة، لأن الإضافة لا ترى الأغنية التي هي داخلها: ضاغط يكون ممسكًا باللازمة سلفًا حين تصل، وبوابة تنفتح لضربة قبل حدوثها، وتأخير صدوي يفرغ نحو خط المازورة. لا يضيف أيٌّ من الستة تأخيرًا.","features.bdb597b1232d":"المازج","features.6b2a31033aa1":"شريط لكل مسار فيه منزلق وبان وكتم وإفراد ورف الأجهزة ومقياس يُرسم من الصوت الذي أنتجه المحرّك فعلًا، ومقابض للمنخفض والمتوسط والمرتفع والغرفة والصدى والحرارة وتعديل الطبقة والحُبيبي بجانب ضاغط خاص به. يسمّي رادار الحجب مسارين يتنازعان النطاق نفسه ويسمّي التردد؛ وتعرض لوحة الجهارة قيمة LUFS المتكاملة وقصيرة المدى والمدى والذروة الحقيقية مقابل ما تستهدفه كل خدمة بث.","features.cf29337c35e2":"الفحص النهائي","features.6acd50767d2a":"ماستر لكل وجهة، من Spotify وApple Music إلى القرص المضغوط والنادي والبث الإذاعي، تُصدَّر معًا من مزيج واحد ويُقاس كلٌّ منها من ملفه مقابل هدفه. استمع إلى المزيج كما يعزفه هاتف أو سيارة أو حاسوب محمول أو سماعة صغيرة أو سماعات أذن داخلية، بمستوى مطابَق ودون أن يُطبع في الملف أبدًا؛ ويفحص درج الجهارة جهارة كل قسم، ويتحقق فحص المواصفات من ملف مقابل مواصفات تسليم ويكتب التقرير. جديد في v0.12.0.","features.5b8f86b084dc":"«اقتراح» و«امزجه من أجلي»","features.b8fee5c42dca":"كل بطاقة مؤثر تقيس ما يصلها وتقترح ضبطًا مع أسبابه، يُطبَّق في خطوة تراجع واحدة. ويضبط «امزجه من أجلي» كل جزء ويوصل الماستر إلى الوجهة التي علّمتها، في خطوة تراجع واحدة أيضًا. إنه حساب على القياس، لا نموذج، فيحصل المزيج نفسه على الجواب نفسه. جديد في v0.12.0.","features.787726eabc9d":"مسار الكلمات","features.1c110149d613":"كلمات الأغنية مسارًا على الخط الزمني، مقفلة على رأس التشغيل، تُستورد من <code>.txt</code> أو <code>.lrc</code> وتُنسخ إلى داخل المشروع، بخط مصمَّم ليُغنّى منه من الطرف الآخر للغرفة. قاموس من 327,000 كلمة يُكمل ويصحّح أثناء كتابتك، وكل مقطع يقع على نوتته، وعلامات النبر والقوافي بنظامها وشبكة الإيقاع تساعدك على الكتابة. جديد في v0.10.0.","features.c01fa2f5481f":"بطاقات الجلسة والفاصل الزمني للجلسة","features.ef0a07e0d7a5":"اختصار واحد يُصيّر صورة للجلسة بحجم 1200×630 لتنشرها. ويعيد الفاصل الزمني للجلسة بناء الجلسة كلها من سجل تعديلاتها صورةً متحركة بفصول — حتى الجلسة التي لم يخطر لأحد أن يسجّلها.","features.8b8dc99cf84d":"جلستك تُفتح من دون Oscillate","features.3ab5583a8c27":"يكتب المجلد المرافق مسارات منفصلة وملفات MIDI يستطيع أي DAW آخر فتحها، مصطفّة عند المازورة 1، بالصيغة ومعدل العيّنات وعمق البت التي تختارها.","features.d91ad4caafa2":"المظهر العائلي","features.cc88394d86d7":"مقابض ومنزلقات وأزرار مُصيَّرة في Blender، ووضعان فاتح وداكن بأخضر Freally، وأصوات قصيرة للواجهة يمكنك إطفاؤها، وثماني عشرة لغة مع كتابة حقيقية من اليمين إلى اليسار — المظهر نفسه في كل تطبيقات Freally.","features.c87ebc921598":"لا شيء يتّصل بالخارج من خلفك","features.587fbb00c1bb":"لا حساب ولا قياس عن بُعد. لا يستعمل الشبكة إلا في أربع مناسبات: غرفة فتحتها أو انضممت إليها، واستعلام العنوان أثناء إنشاء تلك الغرفة، وفحص للتحديثات يبقى معطّلًا حتى تفعّله، وMixSir، الذي يقدّم مزيجك لهاتف على شبكتك أنت، ولا يفعل ذلك إلا ما دمت ترسله. تبقى تقارير الأعطال على قرصك ما لم تختر إرسال أحدها.","features.ae2bbaa95738":"لا ذكاء اصطناعي، والبناء يفرض ذلك","features.db3a0428cdec":"لا نموذج، ولا استدلال، ولا شيء توليدي. بوابة بناء تمشي في رسم الاعتماديات وتفشل أمام أي بيئة استدلال أو ملف نموذج، فذلك خاصية في البناء لا جملة على موقع.","features.389cb06662bc":"جنبًا إلى جنب مع أبرز محطات العمل الصوتية","features.1b20c8037295":"‏Freally Oscillate كما سيكون في الإصدار 1.0، بجانب سبعة منتجات تجارية كما تُباع في 1 أكتوبر 2026 — مأخوذة من صفحات كل منتج ومتجره ودليله ومقالات الدعم الخاصة به. الأسعار هي أسعار القائمة بالدولار الأمريكي.","features.dbdcc26cbc1a":"‏Freally Oscillate 1.0 وسبع محطات عمل صوتية تجارية، ميزةً ميزة","features.0c4e9f0c201a":"Freally Oscillate 1.0","features.2088ae055e42":"FL Studio 2026","features.c2373bf58922":"Ableton Live 12","features.89d4cb070d7f":"Logic Pro","features.dec97310271f":"Bitwig Studio 6","features.41e8da85de51":"Cubase Pro 15","features.9a8405135cab":"Pro Tools","features.4da4dbb45aea":"Soundtrap","features.a6a1efe40897":"السعر في 1 أكتوبر 2026، بالدولار الأمريكي","features.4ade5154bd22":"مجاني اليوم","features.20f8fb981865":"$99–$449، لمرة واحدة","features.566c95f474af":"$99–$749، لمرة واحدة","features.19be45f9b5eb":"$199.99 لمرة واحدة، أو $12.99 شهريًا","features.5e5b2a65eaea":"$99–$399، لمرة واحدة","features.7113d664c5d8":"$579.99، لمرة واحدة","features.9a1ba45b0bfd":"إصدار Intro مجاني؛ $99–$599 سنويًا","features.385bc90ff4a3":"خطة مجانية؛ $11.99–$20.99 شهريًا","features.40cbef707220":"يعمل على Windows وmacOS وLinux","features.85a39ab345d6":"نعم","features.deb0147a950c":"جزئيًا","features.1abbc130b8d9":"Windows وmacOS","features.1ea442a134b2":"لا","features.3f2f41cd023d":"macOS فقط","features.d48bbcde1043":"تطبيقات لـ Windows وmacOS؛ وLinux عبر المتصفح","features.3cb6a5ed0829":"يستضيف إضافات VST3","features.6bba86a6bb28":"Audio Units فقط","features.7d13d66c4393":"AAX فقط","features.0c8436827b99":"المؤثرات فقط، في الخطة العليا","features.dcbac1a42d75":"يستضيف إضافات CLAP","features.3592cc9add20":"الإضافة التي تنهار تترك الجلسة تعمل","features.b37c33f4180d":"كل إضافة، دائمًا","features.4c8d11154068":"اختياري، VST فقط","features.2089380a1ba9":"على Apple silicon","features.151339072593":"لم يُتحقَّق منه","features.fc8d60587699":"يمكن استعماله دون أي حساب على الإطلاق","features.b7d5af4a8c98":"عدة منتجين يعملون في جلسة واحدة في الوقت نفسه","features.7e6677e2efad":"حتى أربعة، في الوقت الفعلي","features.ba260ef541c6":"تسجيل عازف واحد عن بُعد","features.c7514e6ebfe8":"مسارًا مسارًا، عبر السحابة","features.36bd8f7a0c2d":"في الوقت الفعلي، في سحابته","features.956234fe74b6":"صوت وكاميرا مع المتعاونين، مدمجان","features.62f1fa1162e0":"مع ذلك العازف","features.c870c00fa541":"دردشة نصية فقط","features.9f3893904d3d":"تعاون بلا خادم ولا حساب في المنتصف","features.b5db35f851fe":"من جهاز إلى جهاز","features.4c5f872abb2f":"تسليم مسار لمتعاون ثم استعادته","features.f28162be8d9f":"ملكية المسار، بالطلب","features.c3b01984557c":"وضع مبارزة إيقاعات","features.1d662dd62590":"ورقة توزيع مستخرجة ممّن عدّل ماذا","features.e6195e7cff54":"لا ميزات ذكاء اصطناعي أو تعلّم آلي","features.f0774f2a34b1":"تفرضه بوابة بناء","features.7a210d79eda9":"لا شيء مُدرج","features.e5498b8a441d":"<strong>باختصار:</strong> كل منتج آخر في ذلك الجدول يطلب حسابًا، وكلٌّ منها يطلب مالًا مقابل مجموعة ميزاته الكاملة. اثنان منها يتيحان لعدة أشخاص تحرير مشروع واحد — Pro Tools مسارًا مسارًا عبر سحابته، وSoundtrap في الوقت الفعلي في سحابته الخاصة. أما Oscillate فيضع أربعة منتجين في توزيع واحد في الوقت الفعلي، من جهاز إلى جهاز، بلا حساب، وهو مجاني اليوم.","features.52242b315ce6":"جُمع في 1 أكتوبر 2026. علامة «لا» أمام ميزة تعني أنها غير موجودة في قوائم ميزات ذلك المنتج نفسه أو ملاحظات إصداره أو دليله في ذلك التاريخ. المنتجات تتغير، وهذا الجدول يصفها كما كانت حينها. أسماء المنتجات علامات تجارية لأصحابها.","features.6977b748edc2":"لماذا بُني بهذه الطريقة","features.662d60837a2d":"لا خادم، فلا شيء يمكن إطفاؤه","features.85567c225aa3":"رمز الغرفة هو عرض الاتصال نفسه. ومن دون خادم لا شيء يجب إبقاؤه يعمل، ولا شيء يُدفع، ولا شيء يستطيع أحد إطفاءه — وهذا أيضًا سبب أن الغرفة تتسع لأربعة منتجين لا لأربعين: كل مشارك يرسل إلى كل مشارك آخر.","features.16275f3a5af9":"سجل واحد، أربعة استعمالات","features.d2a4cd186952":"كل تعديل عملية في سجل واحد. التراجع ومزامنة الغرفة وإرجاع الجلسة وورقة التوزيع أربع قراءات له، ولهذا يمكن أن يكون تراجعك لك وحدك، ولهذا يمكن استخراج نسبة العمل إلى أصحابه بدل كتابتها يدويًا.","features.af0df7623348":"الانهيار يصيب جهازًا واحدًا، لا الجلسة","features.600105cd00bc":"كل إضافة مستضافة تعمل في عملية خاصة بها، والتطبيق نفسه لا يستطيع حتى تحميل إضافة. الإضافة التي تتعثر تجعل جهازها رماديًّا، ويستمر شريط النقل في التشغيل.","features.908ec1ae94d2":"الرقم الذي تراه هو الرقم الذي في الصوت","features.b6fc9acbd76d":"تُرسم المقاييس مما أنتجه المحرّك، وقراءة المقبض من القيمة التي تستعملها معالجة الإشارة، والقياس الذي تأخر يقول ذلك. لا شيء على الشاشة تنبؤ.","features.944f018d9f74":"يبقى على جهازك","features.70a55e97f377":"لا تغادر مشاريعك وصوتك وملفات MIDI حاسوبك إلا حين تكون في غرفة مع أحد — وعندها تذهب مباشرة إلى الأشخاص الذين فيها، لا عبر سحابة أحد.","features.bd873b549bc7":"ما لم يصل بعد","features.735112899b1c":"بوضوح، لأن قائمة ميزات تُخفي ثغراتها لا تستحق القراءة. كل ما سبق هو ما خُطّط لأن يحمله الإصدار 1.0، وهذا ما يزال يقف بين هنا وهناك.","features.d9d391384838":"ما لن يفعله الإصدار 1.0","features.7d48e18b39c1":"<strong>استضافة إضافات AU أو VST2.</strong> إنه يستضيف VST3 وCLAP.","features.a1eea7d00cdd":"<strong>استعمال ASIO.</strong> على Windows طريق التأخير المنخفض هو WASAPI الحصري، ويخبرك Oscillate بالوضع الذي حصلت عليه فعلًا.","features.1bcf2a5c1071":"<strong>استيعاب أكثر من أربعة منتجين في الغرفة.</strong> الاتصال الخامس هو النقطة التي ينفد عندها رفع منزلي عادي.","features.37e6fd7fe6f5":"<strong>ترحيل اتصال لا ينعقد.</strong> نحو واحد من كل عشرة لن ينعقد دون مُرحِّل في المنتصف؛ يسمّي Oscillate السبب، وتقبل الإعدادات مُرحِّلك الخاص.","features.d32646eadd7e":"<strong>مشاركة الشاشة من macOS.</strong> مشاركة الشاشة على Windows وLinux؛ وعلى macOS الزر غائب ويقول السبب.","features.3b50036d04c0":"لا نسخة تجريبية على هذه الصفحة، ولا بناء معاينة، ولا وصول مبكر. حتى 1.0.0 الجواب الصادق عن «من أين أحصل عليه» هو <em>ليس بعد</em>.","docs.lede":"الدليل: كل لوحة، وكل محرّر، والغرفة، والإضافات، والحدود.","docs.831d0f72d242":"البداية","docs.365101815fb2":"النافذة ولوحاتها","docs.2e5511855cbc":"التوزيع","docs.dac11b27d868":"لفّة البيانو","docs.a232ac37bd92":"شبكة الإيقاع","docs.1a3a9fb87365":"محرّر الموجة","docs.a40e410cd4b9":"رف الأنماط","docs.d909750b1bbb":"الأتمتة","docs.a4592301df0c":"التسجيل والتجميع","docs.724e8a91b5e7":"Oscillate Retro Record","docs.2f4a9c0d9ce6":"العزف الحي","docs.bdb597b1232d":"المازج","docs.529d3ce4c95e":"المسرح","docs.10e78b267d72":"النوتات","docs.cb4ad503e340":"الدروس","docs.9514b7ff4860":"الإضافات","docs.c80fbc216c04":"الأجهزة المرفقة","docs.4854ad4c206c":"مستعرض الملفات","docs.542aa51c9ff9":"الغرفة","docs.c3e61cb4f392":"MixSir — المزيج على هاتفك","docs.ba5e0c669f84":"الكوميتي وورقة التوزيع","docs.787726eabc9d":"مسار الكلمات","docs.3664895579f0":"التصدير","docs.b04b9b7961b7":"الفحص النهائي","docs.74a883a037bc":"الإعدادات","docs.22e2bada8f1c":"التحديثات","docs.46e978d0c193":"الاختصارات","docs.69bd78234ffb":"الخصوصية والشبكة","docs.8e388ee7590d":"الحدود، بوضوح","docs.c3af076f92c5":"حل المشكلات","docs.05df7711cd6c":"يُثبَّت Oscillate كأي تطبيق سطح مكتب آخر ويعمل دون اتصال بالإنترنت. في أول مرة تفتحه تُعرض عليك الاتفاقية؛ وعليك قبولها قبل أن يُفتح التطبيق، ويمكنك إعادة فتحها في أي وقت من <strong>الإعدادات ▸ حول ▸ عرض الاتفاقية</strong>.","docs.fb63caf27515":"بعد ذلك تجد نفسك في جلسة اسمها <em>مشروع جديد</em>. لا يُحفظ شيء في أي مكان حتى تحفظه أنت، باستثناء سجل الأعطال — الذي يدوّن كل تغيير لحظة إجرائه، فلا يكلّفك العطل شيئًا بدل أن يكلّفك عمل ما بعد الظهر كله.","docs.shot.start":"نافذة Oscillate عند التشغيل الأول: مفاتيح النقل «تشغيل» و«إيقاف» و«تسجيل» داخل إطار أحمر في أعلى اليسار، وتحتها رف الأنماط، وأسفله الترتيب.","docs.81a2f5639f44":"النافذة عند التشغيل الأول. المفاتيح المؤطَّرة هي أزرار النقل: التشغيل والإيقاف والتسجيل، في أعلى اليسار.","docs.a8522c985343":"اضغط <kbd>Space</kbd> للتشغيل والإيقاف. اسحب صوتًا من مستعرض الملفات إلى مسار، أو انقر نقرًا مزدوجًا على جزء فارغ من مسار MIDI لإنشاء مقطع والبدء بالكتابة.","docs.ebd61574858f":"النافذة بلا إطار، ويرسم Oscillate أزرار التصغير والتكبير والإغلاق الخاصة به. وتُفتح نظيفة: شريط النقل، ورف الأنماط مثبّتًا فوق التوزيع، والتوزيع. وتُظهَر كل لوحة وتُخفى بزرها في شريط العنوان، أو ببندها في قائمة <strong>عرض</strong>، أو بمفتاح:","docs.99a52df3ff3d":"المفتاح","docs.d0d91173008b":"اللوحة","docs.1f36becc3aa7":"ما هي","docs.d6f6a04891cc":"مستعرض الملفات","docs.495763c88db7":"أصواتك وإضافاتك وأجهزة Oscillate الخاصة، مع معاينة.","docs.30330bf56a43":"رف الأنماط","docs.6d2af2be1078":"أنماط تبنيها صفًّا صفًّا، مثبّتة فوق التوزيع وبينهما فاصل.","docs.936a161c3931":"المحرّر","docs.05db484cdeb8":"لفّة البيانو وشبكة الإيقاع والأتمتة ومحرّر الموجة.","docs.8ae012d51747":"المازج","docs.f1972360c8eb":"المنزلقات والمقاييس ورادار الحجب ولوحة الجهارة.","docs.911ea89c43d9":"الغرفة","docs.b0ab31730a7d":"رموز الغرف وقائمة الحاضرين والدردشة والصوت والكاميرات ومشاركة الشاشة، ومزيجك مُرسلًا إلى هاتفك.","docs.de838855e4a6":"المسرح","docs.5b84a6db221d":"أيادٍ تعزف مسارات MIDI لديك على آلة ثلاثية الأبعاد، في تزامن مع شريط النقل.","docs.b696ffb49270":"أي مسار MIDI مدوّنًا كنوتة موسيقية، يتبع رأس التشغيل.","docs.7a7b5b9b8db5":"خمس عشرة دورة، تتعلّمها يومًا بيوم: كل درس يريك الطريقة، ثم يستمع إليك وأنت تعزف.","docs.48e75eca2fe2":"ماستر لكل وجهة، يُفحص كما يشغّله هاتف وسيارة، مقطعًا مقطعًا ومقابل مواصفات التسليم.","docs.f58d0e706b34":"على macOS، كل <kbd>Ctrl</kbd> أدناه هو <kbd>Cmd</kbd>.","docs.c06b71382c0f":"لوحات في نوافذ خاصة بها","docs.80fe13adbb5b":"يعيش <strong>المازج</strong> و<strong>مستعرض الملفات</strong> و<strong>المحرّر</strong> و<strong>الغرفة</strong> و<strong>الفحص النهائي</strong> في نوافذ خاصة بها، مخفيةً حتى تفتحها. يخفي <strong>✕</strong> في نافذة اللوحة النافذةَ؛ ويثبّت <strong>⇲</strong> فيها اللوحةَ داخل النافذة الرئيسية ظاهرةً؛ ويُخرج <strong>⇱</strong> في اللوحة المثبّتة اللوحةَ إلى نافذتها من جديد. ورف الأنماط يُثبَّت ويُخرَج بالطريقة نفسها. ويُحفظ مكان كل لوحة على هذا الحاسوب، وتواصل نافذة اللوحة عملها على شاشة ثانية. أما المسرح والنوتات والدروس فتبقى دائمًا في النافذة الرئيسية.","docs.966384c2cfde":"تُفتح نافذة اللوحة أول مرة بجانب النافذة الرئيسية، متدرّجةً، وبعد ذلك حيث تركتها، أو بجانب النافذة الرئيسية من جديد إن غابت تلك الشاشة. وتُفتح نافذة المحرّر أول مرة بمقاس 1360 × 928، بما يتسع لشريط أدوات لفّة البيانو وأوكتافين ومسار الأتمتة ومسارات لقطاته؛ وحين يكون المحرّر مثبّتًا يحتفظ بـ 260 بكسل ويتمرّر.","docs.7b1c22e704ec":"نافذة اللوحة التي كانت مفتوحة حين أُغلق Oscillate تُفتح من جديد عند التشغيل التالي، حيث تركتها، بمجرد ظهور النافذة الرئيسية وقبول الاتفاقية؛ والنافذة التي لم تعد شاشتها موجودة تعود بجانب النافذة الرئيسية. والنافذة التي أغلقتها تبقى مغلقة. ويُدوَّن ما كان مفتوحًا كلما فتحت النوافذ وأغلقتها، لا عند الخروج فقط، فيبقى محفوظًا حتى بعد عطل مفاجئ.","docs.771bc108d512":"التثبيت السابق للإصدار 0.10.0 ينتقل إلى هذا التخطيط مرة واحدة، عند أول تشغيل له، ويحتفظ بأحجام لوحاته. وأثناء الجولة الإرشادية (<strong>مساعدة ▸ دليل تعليمي</strong>)، يدخل مستعرض الملفات والمحرّر إلى النافذة الرئيسية لتتمكن من الإشارة إليهما، ثم يعودان إلى نافذتيهما حين تنتهي.","docs.2ae2bf6b8884":"اسحب الفاصل بين لوحتين لتغيير حجمهما. وتحت عرض 1280 بكسل تنطوي اللوحات الجانبية من تلقاء نفسها، لأن التوزيع يفقد قابليته للاستعمال قبلها.","docs.226516acde25":"خط زمني بمسطرة من المازورات والنبضات، وشبكة تتبع التكبير، ورؤوس مسارات على الجانب، ومقاطع تُرسم مما هي عليه فعلًا — موجة حقيقية للصوت، ونوتات حقيقية للنمط.","docs.78d11d4d5db9":"تحرير المقاطع","docs.0bfc00f5a7ca":"اسحب مقطعًا لتحريكه؛ واضغط <kbd>Alt</kbd> أثناء السحب لنسخه.","docs.bb5fc5708305":"اسحب أيًّا من طرفيه للقص؛ واسحب الزاوية العلوية للتلاشي.","docs.c379e75c7075":"اسحب مقبض التكرار على الحافة اليمنى لتكراره.","docs.196e45387bc2":"يسترجع <kbd>Ctrl</kbd>+<kbd>Z</kbd> الحركة كاملة — ضغطة واحدة مهما بلغ عدد المقاطع التي مسّتها.","docs.65ca08c3ec91":"القَطْع","docs.51e37ec2c2d8":"اضغط <kbd>C</kbd> للنصل واسحب ضربة عبر التوزيع. كل مقطع تعبره الضربة ينشق حيث عبرته، وزاوية الضربة تحدد طول التلاشي المتقاطع: الضربة العمودية قطع حاد، والمائلة مزج طويل. اضغط <kbd>V</kbd> للعودة إلى المؤشر.","docs.102bcc2b6fcb":"تحويل مقطع إلى النوع الآخر","docs.e6513c30872c":"انقر بزر الفأرة الأيمن على مقطع MIDI واختر <strong>تصيير إلى صوت</strong>؛ وانقر بالزر الأيمن على مقطع صوتي واختر <strong>تحويل إلى MIDI</strong>. وفي الحالتين تقع النتيجة <em>بجانب</em> الأصل لا فوقه، وضغطة تراجع واحدة تعيد كل شيء كما كان.","docs.04d699e071c9":"يُصيَّر النمط عبر كل ما على ذلك المسار: الآلة في خانتها ثم كل مؤثر صوتي بعدها. الجهاز الذي أطفأته ليس في التصيير. وكذلك، عن قصد، منزلق المسار نفسه والبان الخاص به — فالمقطع الجديد يُعزف عبرهما، وطبعهما فيه يعني تطبيقهما مرتين.","docs.8d98a4cb90a8":"تحويل الصوت إلى MIDI غير كامل ويقول ذلك: يخبرك كم ضربة لم يستطع قراءة طبقة منها. وحلقة الطبول تتحول إلى لا شيء على الإطلاق، وهذا هو الجواب الصادق.","docs.b64ff2ff46f9":"قفل المسار","docs.3badbc0f4fad":"القفل الموجود على رأس مسار الصوت أو مسار MIDI، وعلى شريطه في المازج، وعلى شارته في شريط النوتات، يقفل المسار. وما دام مقفلًا، يُرفض كل تغيير على نوتاته ومقاطعه بجملة تسمّي المسار وتطلب فتح قفله، أيًّا كان مصدر التغيير: لفّة البيانو، أو شبكة الإيقاع، أو رف الأنماط، أو التوزيع، أو ملف مُفلَت، أو التسجيل، أو التراجع. ولا يمكن حذف المسار أيضًا ما دام مقفلًا. أما اللقطة التي كانت قيد التسجيل حين جاء القفل فتصل مع ذلك حين تتوقف. وفي الغرفة يصل القفل إلى الجميع، ومن ذلك الحين تُرفض التغييرات التي يجريها كل شخص بنفسه على المسار.","docs.364d70c63c7b":"ويبقى مزجه حرًّا: اسمه ولونه ومنزلقه والبان والكتم والإفراد وأجهزته وتوجيهه، كلها تظل قابلة للتغيير. ويُحفظ القفل مع المشروع، ويُتراجع عنه بضغطة تراجع واحدة، ويصل إلى كل من في الغرفة.","docs.a707a40e3f2b":"الأدوات ومفاتيحها","docs.4696ab63ac11":"يضم شريط أدوات التوزيع أدواته، ولكلٍّ منها مفتاح. وتستجيب المفاتيح ما دام التركيز على التوزيع، فتحتفظ لوحة مفاتيح الحاسوب بنوتاتها في غيره، ويحتفظ المحرّر بمفاتيحه الخاصة. ويمكن تغيير كلٍّ منها في <strong>الإعدادات ▸ الاختصارات</strong>.","docs.c74ea9dc9cd2":"ما تفعله","docs.27a3afb9e655":"تحديد: اضغط مقطعًا، أو اسحب مربعًا، و<kbd>Shift</kbd> يضيف إليه","docs.926996af2b7c":"رسم: مقطع صوتي جديد للتسجيل فيه","docs.d268870bb66a":"رسم متكرر: النمط أو المقطع المنتقى، يُرسم على طول المسار","docs.cae171a2c418":"مسح: كل مقطع تبلغه نقرة أو سحبة","docs.c6ff289d9370":"كتم: كل مقطع تعبره سحبة، يُكتم أو يُلغى كتمه","docs.b750b8649775":"إزاحة المحتوى: ينزلق ما يُعزف داخل المقطع؛ وعلى الحافة تتحرك الحافة وينزلق معها ما يُعزف داخله","docs.36c14f300243":"قص: النصل، كما في «القَطْع» أعلاه","docs.e8cff43cb178":"استماع: المقطع المضغوط يُعزف وحده حتى تُفلته","docs.2d9590dbdef9":"مع أداة الرسم المتكرر أو أداة المسح، تزيل النقرة اليمنى أو السحب بالزر الأيمن المقاطع؛ و<kbd>Shift</kbd> مع النقرة اليمنى يظل يفتح قائمة المقطع. والإزاحة على حافة لا تحرّك إلا ذلك المقطع؛ وتبقى المقاطع المحيطة به حيث هي. والاستماع يعزف عبر المعاينة، لا عبر شريط النقل أبدًا: المقطع الصوتي من حيث يبدأ في ملفه، والنمط عبر آلة مساره. ويُسمع دون مؤثرات المسار، والمقطع الممدَّد بسرعة ملفه الأصلية.","docs.3dd9a67f3b93":"رسم الأنماط رسمًا متكررًا","docs.b1f731cac156":"يسرد المنتقي الذي بجانب المسارات ما يمكن رسمه: أنماط رف الأنماط، وأنماط MIDI، والمقاطع الصوتية، والحالي منها مضاء. اضغط أحدها لتنتقيه، فتُختار أداة الرسم المتكرر. والنقرة على مسار فارغ تضعه في موضع المحاذاة، والسحب يرسم نسخًا متلاصقة على طول المسار، حول المقاطع الموجودة فيه؛ وكل سحبة تُلغى بضغطة تراجع واحدة. والنسخ مرتبطة بنمطها، كما هو حال النمط الموضوع دائمًا: عدّله فتتغير كل نسخة، إلى أن تجعل إحداها فريدة.","docs.9848f51e01bf":"الضغط على مقطع بأداة المؤشر أو أداة الرسم أو أداة الرسم المتكرر يجعل نمطه هو النمط الحالي. ويرشّح <strong>عرض</strong> في المنتقي محتواه حسب النوع، ويُبقي <strong>غير المستخدمة فقط</strong> الأنماط التي لا يعزفها أي توزيع بعد، ويرتّبه <strong>الترتيب</strong> حسب الإنشاء أو الاسم أو الطول أو الاستخدام، ويعزف <strong>استمع إليه</strong> النمط الذي تقف عليه مفاتيح الأسهم.","docs.cae463c6e49a":"شريط التكبير","docs.25f57d4fd0f6":"الشريط الذي فوق المسطرة هو الجزء الظاهر على الشاشة من الأغنية. اسحب وسطه للتمرير، واسحب أيًّا من طرفيه للتكبير أو التصغير حول الطرف الآخر، وانقر عليه نقرًا مزدوجًا لملاءمة الأغنية كاملة. وحين يكون التركيز على الشريط، تمرّره مفاتيح الأسهم و<kbd>Page Up</kbd> و<kbd>Page Down</kbd> و<kbd>Home</kbd> و<kbd>End</kbd>، ويغيّر <kbd>Ctrl</kbd> مع سهم التكبير؛ وتحرّكه مفاتيح التكبير و<kbd>Ctrl</kbd>+العجلة أيضًا. وتحته صورة صغيرة للأغنية كلها، مقاطع كل مسار فيها بلونه. وفوق الشريط، تكبّر العجلة وتصغّر وطرفه الأيسر ثابت في مكانه، ويمرّره <kbd>Shift</kbd>+العجلة.","docs.d01650cb106c":"المزيد من المقطع","docs.b69a3372dea1":"<kbd>Alt</kbd> مع حافة مقطع صوتي يمدّده إلى طول جديد مع الحفاظ على طبقته، من ربع طوله إلى أربعة أضعافه. والمقطع المعكوس أو المكرَّر لا يمكن تمديده، ويقول ذلك.","docs.67a47eb07dd6":"يعيد <strong>الاسم واللون…</strong> في قائمة المقطع تسمية المقطع ويعطيه أحد ألوان رأس المسار، أو لون المسار نفسه.","docs.722bad976090":"ينسخ <kbd>Ctrl</kbd>+<kbd>C</kbd> المقاطع المحددة، ويلصقها <kbd>Ctrl</kbd>+<kbd>V</kbd> عند رأس التشغيل، مع الحفاظ على المسافات بينها.","docs.0e0083d2f7c1":"قائمة «ترتيب»","docs.d052ab0af057":"تعمل قائمة <strong>ترتيب</strong> في شريط أدوات التوزيع على المقاطع المحددة أو المسار المحدد. وكل بند يغيّر الأغنية يُلغى بضغطة تراجع واحدة؛ أما اختيار المقاطع والنسخ والتكبير فليست كذلك.","docs.cdea6d45b927":"<strong>التقطيع عند كل خط من الشبكة</strong>، أو <strong>عند نقاط الهجوم</strong> (في الصوت، بكاشف محرّر الصوت نفسه)، أو <strong>عند مناطق ملفه</strong> (نقاط الإشارة cue والمناطق التي يحملها ملف WAV).","docs.a81713b16dde":"<strong>دمج الأنماط المحددة في نمط واحد</strong>: تصبح مقاطع الأنماط في المسار نمطًا جديدًا واحدًا يعزف كل نوتة كانت تعزفها.","docs.423bba8b62c0":"<strong>تجميع المقاطع المحددة</strong>: الضغط على أحدها يحدد المجموعة كلها، فتتحرك وتُكتم وتُحذف كوحدة واحدة، حتى تفك تجميعها.","docs.0b4bedb80285":"<strong>تحديد كل نسخة</strong> من مقطع، أو <strong>المقاطع المكتومة</strong>، أو <strong>المتداخلة</strong>، أو <strong>المكدّسة</strong>، أو <strong>عكس التحديد</strong>.","docs.ed8f4699971e":"<strong>كتم</strong> و<strong>إلغاء كتم التحديد</strong>، و<strong>محاذاة البدايات على الشبكة</strong>.","docs.09a71aaece1b":"ينقل <strong>إدراج وقت بطول الحلقة</strong> كل مقطع وكل علامة بعد بداية الحلقة إلى الأمام بمقدار طولها؛ ويُخرج <strong>حذف امتداد الحلقة</strong> ما بداخلها ويسدّ الفجوة. والمقطع الذي يعبر حافة الامتداد يبقى حيث كان.","docs.81acc44d9e0f":"<strong>كل المسارات صغيرة</strong> أو <strong>متوسطة</strong> أو <strong>كبيرة</strong>.","docs.4d5b9e912dcc":"<strong>استنساخ المسار المحدد</strong>، بأجهزته وأتمتته ومقاطعه، تحته مباشرة؛ و<strong>تسمية المسار المحدد باسم أول مقطع فيه</strong>؛ و<strong>نقل المسار المحدد إلى الأعلى</strong> أو <strong>إلى الأسفل</strong>.","docs.77c05e6e69ab":"<strong>التكبير إلى التحديد</strong>، و<strong>العلامة السابقة</strong> و<strong>العلامة التالية</strong> (<kbd>Alt</kbd>+<kbd>←</kbd> و<kbd>Alt</kbd>+<kbd>→</kbd>).","docs.7ba68fe8ebf8":"وتعرض <strong>المحاذاة</strong> أيضًا نوتة من الثاني والثلاثين، وسدس الخطوة، و<strong>حواف المقاطع</strong>، التي تُلصق المقطع بحافة مقطع آخر حين يكون قريبًا منها، وتضعه على الشبكة في غير ذلك.","docs.87453fed8996":"علامات تفعل شيئًا","docs.262f0a5ac20a":"انقر بالزر الأيمن على علامة في المسطرة لتختار ما تفعله: لا شيء، أو <strong>تبدأ الأغنية هنا</strong> (حين تعزف من البداية؛ وتغلب أبكر علامة من هذا النوع)، أو <strong>العودة إلى هنا من العلامة التالية</strong>، أو <strong>القفز إلى العلامة التالية</strong>، أو <strong>التوقف هنا</strong>. والنقرة اليمنى نفسها تغيّر الميزان بدءًا من المازورة التي تحت المؤشر، أو تزيل تغييرًا من حيث يبدأ.","docs.6feff1f9ed51":"عدة توزيعات","docs.36f67f42cacb":"يمكن أن يضم المشروع عدة توزيعات للأغنية نفسها. تبدّل القائمة المنسدلة <strong>التوزيع</strong> في شريط أدوات التوزيع بينها؛ وتضم قائمة <strong>التوزيعات</strong> بجانبها <strong>توزيع جديد</strong> و<strong>نسخ هذا التوزيع</strong> و<strong>إعادة تسمية هذا التوزيع</strong> و<strong>حذف هذا التوزيع</strong> (ما لم يكن الوحيد)، وبند <strong>دمج «…» في هذا</strong> لكل توزيع من التوزيعات الأخرى. ولكلٍّ منها مقاطعه وعلاماته وخطوات تراجعه الخاصة، فوق المسارات والأنماط والمازج التي تتقاسمها، والتشغيل والدمج (bounce) والتصدير تعزف دائمًا التوزيع الظاهر على الشاشة. والتبديل إلى توزيع وإنشاؤه ونسخه ليست خطوات تراجع أبدًا. والمشروع الذي صُنع قبل ذلك يُفتح توزيعًا واحدًا، كما كان.","docs.4b2647bad0e5":"في الغرفة، يُرفض تغيير التوزيع الذي من شأنه أن يرسل أكثر من 1024 تغييرًا دفعة واحدة، أي نحو 500 مقطع، بجملة تقول ذلك: سواء أكان تبديلًا أم دمجًا أم توزيعًا جديدًا أم نسخًا أم حذفًا. أغلق الغرفة لتغيير توزيع بهذا الحجم.","docs.2f4a35fdf295":"مُطلِق المقاطع","docs.047aa27c23ee":"يفتح <strong>إظهار مُطلِق المقاطع</strong>، في شريط أدوات التوزيع، شبكةً فوق الخط الزمني: عمود لكل مسار صوت ومسار MIDI، وصف لكل مشهد. اضغط خانة لتُطلق مقطعها على مسارها، متكررًا، بدل ما كان ذلك المسار يعزفه؛ والخانة الفارغة توقف المسار. وسهم المشهد يُطلق صفّه كله. ويختار <strong>الإطلاق عند</strong> متى يقع الإطلاق: <em>المازورة التالية</em> أو <em>النبضة التالية</em> أو <em>فورًا</em> (بعد نبضة واحدة ما دامت الأغنية قيد التشغيل). والإطلاق والأغنية متوقفة يبدأ تشغيلها.","docs.81be37a5a73c":"تقول الخانة <em>يعزف</em> ما دام مقطعها يعزف، و<em>في الانتظار</em> ما دام ينتظر. ولكل عمود زر <strong>إيقاف</strong> لمساره، ويوقف <strong>إيقاف كل المسارات</strong> المسارات كلها، ويعيد <strong>العودة إلى التوزيع</strong> كل مسار إلى التوزيع. وتتنقّل مفاتيح الأسهم بين الخانات، ويضغط <kbd>Enter</kbd> أو <kbd>Space</kbd> إحداها.","docs.c2c7a824e62c":"يصنع <strong>مشهد جديد من المقاطع تحت مؤشر التشغيل</strong> صفًّا مما يُعزف هناك، ويصنع <strong>مشهد فارغ جديد</strong> صفًّا فارغًا؛ وتضع قائمة الخانة المقطع المحدد فيها، المقطع الصوتي تحت مسار صوت ومقطع MIDI تحت مسار MIDI، أو تُفرغها. وبعد 1 إلى 64 مازورة يمكن أن يتابع المشهد من تلقاء نفسه: <em>المشهد التالي</em> أو <em>المشهد السابق</em> أو <em>المشهد الأول</em> أو <em>أي مشهد</em> (مشهد آخر، عشوائيًا) أو <em>إيقاف الكل</em> أو <em>بلا متابعة</em>.","docs.d0302eb0b177":"الإطلاق ليس خطوة تراجع أبدًا. ومع تفعيل <strong>سجّل الأداء</strong>، يُكتب ما أطلقته في التوزيع حيث عُزف، بدل ما كان لتلك المسارات هناك، ويُلغى بضغطة تراجع واحدة؛ ويُترك المسار المقفل كما كان، ويقول ذلك.","docs.2b18129f93b9":"انقر نقرًا مزدوجًا على مقطع MIDI لفتحه. النقرة على شبكة فارغة ترسم نوتة، و<kbd>P</kbd> يختار «رسم»، الذي يرسم دائمًا؛ انظر <a href=\"#roll-tools\">الأدوات</a> أدناه. لوحة المفاتيح على الجانب الأيسر تعزف الآلة التي على المسار، ويمكن ضبط مفتاح واحد ليعزف تآلفًا كاملًا.","docs.42a0052bf1b6":"المقامات","docs.ddbef0217d41":"نحو تسعين مقامًا. اختيار أحدها يُبرز نوتاته، و<kbd>Ctrl</kbd>+<kbd>K</kbd> ينقل المحدَّد إليه. والطيّ يخفي كل صف ليس من المقام، فيحوّل الشبكة الكروماتية إلى شبكة يمكنك قراءتها.","docs.2cafc9e7c3b3":"عمليات النوتات","docs.0baf2bf51650":"التكميم — يلتقط النوتات المحددة إلى الشبكة","docs.ea07e2f557fe":"الأنسنة — يزيحها عنها قليلًا","docs.0ab966bf90ea":"ليجاتو — يمدّ كل نوتة حتى تلاقي التالية","docs.6a31f294ca42":"يعكس ترتيب النوتات المحددة","docs.4cde53316a6e":"ينقلها إلى مقام المقطع","docs.16aac93d1c5b":"تكرار في المكان","docs.6e14c1f152dd":"تكرار بعدها — الطريقة المعتادة لبناء جزء","docs.3acb04d66cdb":"إزاحة بمقدار قسم واحد من الشبكة","docs.22667e7b7cca":"نقل نصف درجة؛ ومع <kbd>Shift</kbd>، أوكتاف","docs.af2e3ba89e9f":"لمسار الشدة تحت الشبكة مقبض لكل نوتة. ويمكن رسم نوتات شبحية من أي مقطع آخر خلف المقطع الذي تحرّره، وهكذا تكتب خط باص مقابل جزء التآلفات دون التنقل ذهابًا وإيابًا.","docs.1d72dc650e42":"الأدوات","docs.b6bd035c8802":"<strong>الأداة</strong> في اللفّة هي <em>تحديد</em> أو <em>رسم</em> أو <em>رسم متتابع</em> أو <em>محو</em> أو <em>كتم</em> أو <em>تقطيع</em>، ويبدّل <kbd>P</kbd> بين «رسم» و«تحديد». وأيًّا كانت الأداة، تمحو النقرة اليمنى أو السحب بالزر الأيمن النوتات التي يعبرها، ويرسم <kbd>Ctrl</kbd>+سحب مربعًا لاختيار النوتات، و<kbd>Shift</kbd> يضيف إليه. والنقرة على شبكة فارغة ترسم نوتة بطول المحاذاة، إلا إذا كانت هناك نوتات مختارة، فتلغي الاختيار حينئذٍ؛ ومع «رسم» ترسم دائمًا. والسحب على نوتة يحرّكها، وحافتاها، حيث يُظهر المؤشر [ و ]، تطيلانها وتقصّرانها. وما دامت النوتة تُسحب، تتحرك معها أعمدتها في المسارات التي تحتها.","docs.7f660c0fd5ab":"تختار الأداة ما يفعله السحب العادي على شبكة فارغة. فـ <em>رسم متتابع</em> يضع نوتة في كل خطوة محاذاة يعبرها السحب ولا نوتة فيها؛ و<em>محو</em> يزيل ما يعبره؛ و<em>كتم</em> يكتم النوتات أو يلغي كتمها، والنوتة المكتومة تُرسم مجوّفة؛ و<em>تقطيع</em> يقطع كل نوتة يعبرها. ومع «محو» و«كتم» و«تقطيع» يؤدي الضغط على نوتة عمل تلك الأداة أيضًا، ما لم تضغط <kbd>Ctrl</kbd>.","docs.41b4d9d1f165":"ترسم الشبكة خطًا عند كل خطوة محاذاة متباعدة بما يكفي لقراءتها، والثلاثيات ثلاثياتٍ، مع تظليل المازورات بالتناوب، أو النبضات بالتناوب عند التكبير، وتتبع مازوراتها موازين الأغنية. وتعرض <strong>المحاذاة</strong> أيضًا 1/32، وثلاثية السادس عشر، وسدس الخطوة، و<em>حواف النوتات</em> و<em>العلامات</em>. ويُفتح المقطع والمحاذاة على السادس عشر، وأداة «تحديد» مختارة، وارتفاع صفوفه 18 px.","docs.083fa2e74b39":"التآلفات والألوان","docs.87929e0f6173":"يرسم <strong>الختم</strong> تآلفًا مع كل نقرة بدل نوتة واحدة: <em>كبير</em> أو <em>صغير</em> أو <em>منقوص</em> أو <em>مزيد</em> أو <em>معلّق رابع</em> أو <em>سابع مهيمن</em> أو <em>سابع صغير</em> أو <em>أوكتاف</em>، و<em>نوتة واحدة</em> يعيدك إلى النوتة المفردة. وتُعلِّم ستة عشر لونًا النوتات: <strong>إعطاء النوتات المختارة هذا اللون</strong>، أو <strong>اختيار نوتات هذا اللون</strong>. ويُكتب اسم كل نوتة عليها حيث يتسع له، ويختار مفتاحٌ من لوحة المفاتيح على اليسار كل نوتة من طبقته.","docs.8f42006d363d":"قوائم «تحرير» و«أدوات أخرى» و«التكبير»","docs.3070984d94ad":"<strong>تحرير</strong>: <strong>قص</strong> و<strong>نسخ</strong> و<strong>لصق عند أول مازورة ظاهرة</strong> (<kbd>Ctrl</kbd>+<kbd>X</kbd>، <kbd>Ctrl</kbd>+<kbd>C</kbd>، <kbd>Ctrl</kbd>+<kbd>V</kbd>)؛ وكتم النوتات المختارة أو إلغاء كتمها؛ وتدويرها خطوة إلى اليسار أو اليمين؛ واختيار كل النوتات، أو عكس الاختيار، أو اختيار النوتات المكتومة أو النوتات خارج النبضة؛ و<strong>خصائص النوتة…</strong>؛ وتجميع النوتات المختارة وفك تجميعها، فتتحرك المجموعة وتُحذف كوحدة واحدة؛ وجعلها نوتات انزلاق أو نوتات تنساب إلى موضعها، أو إيقاف ذلك.","docs.26835f506821":"<strong>أدوات أخرى</strong>: <strong>تكميم إلى النصف</strong> أو <strong>مع التأرجح</strong>؛ والأطوال إلى 25 أو 50 أو 75 أو 150 %؛ و<strong>النهايات إلى الشبكة</strong>؛ و<strong>كل نوتة بطول خطوة واحدة</strong>؛ وشدة العزف إلى 50 أو 80 أو 125 أو 150 %؛ و<strong>الحصر</strong> للنوتات ضمن أوكتافين، من C1–B2 إلى C5–B6.","docs.e1551223f247":"<strong>التكبير</strong>: تكبير، أو تصغير، أو <strong>احتواء كل النوتات</strong> أو <strong>احتواء النوتات المختارة</strong>.","docs.fe1be326be6b":"خصائص النوتة، والانزلاق والانسياب","docs.28b425b7cc4f":"انقر نقرًا مزدوجًا على نوتة، أو اضغط <strong>خصائص النوتة</strong>، لترى كل أرقام النوتات المختارة: البداية والطول والطبقة والشدة وشدة الإفلات والاحتمال ومدى الشدة والبان والضبط الدقيق للطبقة وMod X وMod Y واللون، وكلٌّ منها تكتبه بالأرقام، مع <em>مختلطة</em> حيث تختلف النوتات المختارة. وتجعل <strong>نوتة انزلاق</strong> النوتةَ لا تضرب شيئًا وتثني المسار إلى طبقتها. ويضرب <strong>انسياب (بورتامنتو)</strong> النوتةَ انطلاقًا من النوتة التي قبلها ثم تنساب إلى موضعها على امتداد نوتة من السادس عشر، أو على امتداد طولها هي إن كان أقصر.","docs.dbcb2e907348":"يحرّك الانزلاق عجلة ثني النغمة للمسار، فتنثني معه كل نوتة تصدح على ذلك المسار، ولا تتبعه الإضافة بدقة إلا ضمن مدى الثني الخاص بها.","docs.3d8c81644dbb":"مسارات إضافية","docs.189f039326bf":"تتقاسم المسارات التي تحت الشبكة فاصلًا واحدًا تسحبه، ويُحفظ موضعه على هذا الحاسوب، ويعرض <strong>إضافة مسار</strong> أيضًا <strong>التوزيع</strong> (البان) و<strong>الضبط الدقيق</strong> و<strong>شدة الإفلات</strong> و<strong>Mod X</strong> (عجلة التعديل) و<strong>Mod Y</strong> (الضغط). وشدة الإفلات هي سرعة ترك كل نوتة: فـ One-Shot Sampler وMultisampler وDrum Machine وOscillate Grain Layers وOscillate Siren تطول رنّتها مع الإفلات البطيء وتقصر مع السريع، وتُبلَّغ إضافاتك بها.","docs.599e5055f4d0":"تسمع آلات Oscillate نفسها التي تعزف العيّنات البانَ والضبطَ الدقيق للطبقة، أما الإضافات فلا. ويسمع Oscillate Grain Layers قيمتَي Mod X وMod Y نوتةً نوتة، ويسمع Oscillate Siren قيمة Mod Y؛ أما كل آلة أخرى، وإضافاتك، فتسمعهما للمسار كله لحظة ضرب كل نوتة.","docs.db4c8113ce8e":"يمكن لمسار CC أن يكتب مذبذبًا منخفض التردد (LFO): اختر <strong>موجة المذبذب</strong> (جيبية أو مثلثية أو مربعة أو منشارية)، و<strong>سرعة المذبذب</strong> (من مازورة إلى نوتة من السادس عشر)، و<strong>عمق المذبذب</strong> (من 25 إلى 100 %)، ثم <strong>اكتب المذبذب على طول النمط</strong>، أو على المدة المختارة، في ضغطة تراجع واحدة. ولا يزال مسار CC يُرسم ويُحفظ لكنه لا يُعزف: لا تقرؤه أي آلة بعد.","docs.caf0b843d7e7":"مسطرة اللفّة","docs.2b2fc69a8046":"للّفة مسطرة خاصة بها. اسحب فيها لتسمع النوتات، وانقر عليها نقرًا مزدوجًا لتضع علامة؛ وتظهر علامات الأغنية في اللفّة، ويمرّ رأس التشغيل عبرها. ويختار <kbd>Alt</kbd>+سحب امتدادًا من الوقت، ويلغيه <kbd>Alt</kbd>+نقر. ثم تُدرج قائمة <strong>تحرير</strong> فراغًا بطوله، فيطول النمط؛ أو تقطع النوتات وتُدرج فراغًا؛ أو تحذف المدة المختارة، فيقصر النمط دون أن يتجاوز آخر نوتة فيه أبدًا؛ أو تقتطع إليها؛ أو تُلغيها؛ أو تضع علامة عندها. و<strong>تتبّع مؤشر التشغيل</strong> هو نفسه الذي في التوزيع: إن فُعّل في أحدهما فُعّل في كليهما.","docs.e7b1751c9fce":"المقطع نفسه معروضًا صفًّا لكل طبل بدل صف لكل طبقة، ومرتّبًا على هيئة مُتسلسِل خطوات. ومع تفعيل <strong>الأصوات المستخدمة فقط</strong>، لا يحصل على صف إلا الطبول التي يعزفها المقطع. كل ما في جدول لفّة البيانو أعلاه يعمل هنا أيضًا — فهي النوتات نفسها في الأسفل — و<strong>كلفيفة بيانو</strong> تعيدك إلى اللفّة.","docs.1de3df70ddf4":"الخطوات","docs.b94b8809bf80":"انقر على خطوة لتضع ضربة أو تزيلها. اسحب على امتداد صف لتملأ الخطوات، أو لتفرغها إن كانت الخطوة الأولى التي ضغطتها مملوءة. اسحب بالزر الأيمن مستطيلًا لتزيل الضربات التي داخله، واسحب عائدًا لتعيدها؛ والنقرة اليمنى وحدها تزيل الضربة التي تحتها. وكل سحبة ضغطة تراجع واحدة.","docs.0203ffa34c13":"تُرسم كل ضربة عمودًا بطول شدتها، والضربة التي عُزفت قبل خطوتها أو بعدها تحمل علامة تدل على ذلك. انقر على اسم صف فتظهر شدّاته في مسار تحت الشبكة: اسحب عبر الأعمدة لتعيد رسمها.","docs.5e9d430d1cc7":"يؤخّر <strong>السوينغ</strong>، من 50 إلى 75 %، نوتات السادس عشر الواقعة بين النبضات. والضربة المعزوفة خارج الشبكة تبقى حيث عُزفت.","docs.c4f07fe24936":"لكل صف <strong>M</strong> لكتمه و<strong>S</strong> لإفراده بينما يواصل بقية الطقم العزف، وله <strong>مجموعة الخنق</strong>: الطبل يُسكت كل طبل آخر في مجموعته، كما يقطع الهاي هات المغلق الهاي هات المفتوح. وعلى مسار Drum Machine تُسمّى الصفوف بأسماء وساداته، ومجموعة الخنق للصف هي مجموعة الوسادة نفسها.","docs.e890f4ead6fc":"خريطة الطبول","docs.041ee2a55b4c":"الطبول المكتوبة لتخطيط طقم آخر يمكنها أن تعزف القطع الصحيحة من طقمك. اضغط <strong>خريطة الطبول</strong> واختر في <strong>القراءة حسب</strong> ما يُقرأ الجزء على أساسه: General MIDI أو Ableton Drum Rack أو FL Studio FPC أو Logic Drummer أو EZdrummer / Superior Drummer أو Addictive Drums. كل نوتة في الجزء تحصل على صف فيه ضرباتها، وفي <strong>يعزف</strong> ما تعزفه: قطعة من طقمك، أو 808 / خط الباص، أو <em>ليست في الطقم</em>. الصف الذي تغيّره يُعلَّم، و<strong>إعادة الضبط</strong> تعيده كما كان.","docs.82482887ca62":"النوتات نفسها لا تتغير أبدًا. أطفئ الخريطة فيُعزف الجزء تمامًا كما جاء؛ وما دامت مفعّلة، يتبعها التشغيل والتصدير والمقطع المسحوب إلى الخارج والمسرح جميعًا.","docs.2b9c9a02b3e1":"وحدة التحكم بالوسادات لديك","docs.706ed9a82528":"في <strong>الإعدادات ▸ MIDI ▸ وحدة تحكم بالوسادات</strong>، اضغط <strong>تعلُّم</strong> واضرب كل وسادة من الوسادات الـ 16 حين يُطلب منك، بدءًا من أسفل اليسار؛ و<kbd>Esc</kbd> يلغي. ومنذ ذلك الحين، ما دام المسار المجهَّز يعزف بـ Drum Machine، تعزف وسادات وحدة التحكم لديك وساداته. وإلى أن تعلّمها، يُستخدم التخطيط الشائع: النوتات 36–51 بدءًا من أسفل اليسار، وهو ما يعود إليه <strong>نسيان</strong>.","docs.ad0418c17aab":"يختار <strong>التخطيط</strong> الطبل الذي تعزفه كل وسادة: التخطيط الافتراضي أو تخطيط <em>الأداء</em> المعكوس، ويختار <strong>الأصابع</strong> الأصابع التي يعزف بها المسرح جزء الوسادات، من سبابة واحدة إلى كل الأصابع.","docs.59321ef7fc8a":"انقر نقرًا مزدوجًا على مقطع صوتي لتفتحه في المحرّر: موجته، وتحتها ما يمكن فعله بالصوت. ولا شيء من ذلك يغيّر ملفك.","docs.887110a8f108":"نقل الطبقة","docs.d97419fdaf8a":"اسحب عبر الموجة لتختار امتدادًا، واضبط <strong>أنصاف النغمات</strong> (−12 إلى +12) و<strong>سنتات</strong> (−50 إلى +50)، واضغط <strong>انقل الطبقة</strong>. فينتقل الامتداد مع الحفاظ على صيغه الصوتية (formants)، فيبقى الصوت المرفوع درجةً كاملة يبدو الصوت نفسه. وتُرسم النقلات شريطًا تحت الموجة، ويزيلها <strong>امسح نقلات الطبقة</strong> كلها بضغطة واحدة. وكل نقلة خطوة تراجع واحدة.","docs.18c66cec3729":"يحسب Oscillate الصوت المنقول بعيدًا عن خيط الصوت، مع شريط تقدّم، ويحفظه في مجلد بياناته؛ وإلى أن يجهز يُعزف المقطع كما كان. ولا يُزيح القصّ نقلةً أبدًا، وكل تصدير يحملها، وفي الغرفة يصنع الآخرون الصوت نفسه من الأرقام نفسها.","docs.c0a913f88834":"ملاءمة المقطع للإيقاع","docs.4e3b3aca2bff":"يجعل <strong>ملاءمة الإيقاع</strong> المقطعَ يتبع إيقاع المشروع بمجرد أن يحدّد <strong>طول المادة بالمازورات</strong> طوله. ويعزفه <strong>تغيير النغمة</strong> أسرع أو أبطأ، كالشريط، فتتحرك طبقته مع الإيقاع؛ ويغيّر <strong>تمديد (يحفظ الطبقة)</strong> طوله ويحفظ طبقته، على الطبول والتآلفات كما على صوت منفرد. ويُصنع الصوت الممدَّد بالطريقة نفسها التي تُصنع بها نقلة الطبقة. ولا يستطيع المقطع المعكوس أو المتكرر اتباع الإيقاع بعد، ويقول ذلك.","docs.a904c7da9d0d":"ما زال المقطع المنقولة طبقته أو الممدَّد يُرسم كملفه: فالموجة تُظهر التسجيل، لا الصوت الذي يُعزف.","docs.5cc9827d169c":"يستقر الرف مثبّتًا فوق التوزيع، وبينهما فاصل، منذ أول مرة يُفتح فيها Oscillate. ويُظهره <kbd>Ctrl</kbd>+<kbd>2</kbd>، أو زره في شريط العنوان، أو <strong>عرض ▸ رف الأنماط</strong>، ويخفيه. وهو يعمل كما يعمل نظيره في FL Studio: ابنِ جزءًا هنا، واسمعه وحده، وضعه في الأغنية حين يجهز.","docs.d6b550dc23cd":"الأنماط والصفوف","docs.70d3e456e7e3":"اضغط <strong>نمط جديد</strong> لإنشاء نمط. ويضيف <strong>+</strong> في أسفل اليسار صفًّا: اختر آلة من رفوف المستعرض، باحثًا فيها بالاسم، فيُنشئ مسار MIDI جديدًا بتلك الآلة ويمنحه صفًّا، وكل ذلك في خطوة تراجع واحدة. والقائمة نفسها تضيف مسارًا موجودًا في الأغنية.","docs.0d6fa14f3070":"الصف مسارٌ: اسمه و<strong>الأجهزة</strong> فيه هي اسم المسار وأجهزته، فيعزف عبر آلة ذلك المسار ومؤثراته. لكل صف MIDI جزؤه الخاص منذ البداية؛ والقائمة التي بجانبه تربطه بجزء آخر بدلًا منه، أو تبدأ له جزءًا جديدًا بـ <strong>جزء فارغ جديد</strong>.","docs.4c079b8f8d6a":"الصف على سطر واحد","docs.453ea9f5b586":"يمتد كل صف على سطر واحد، كما تمتد القناة في رف FL Studio: ضوؤه، المضاء ما دام المسار يعزف والمطفأ ما دام مكتومًا؛ ومقبضا البان ومستوى الصوت؛ والوجهة التي يعزف إليها، الرئيسي أو مجموعة؛ واسمه؛ و<strong>S</strong>، زر إفراده (انقر مع <kbd>Ctrl</kbd> لتُفرده إلى جانب المسارات المُفردة الأخرى). والمقبضان هما بان المسار ومنزلقه في المازج نفسه، فإدارة أحدهما تحرّك شريط المازج، والمازج يحرّك المقبض. و<strong>تحرير</strong> و<strong>وضع</strong> و<strong>تحريك لأعلى</strong> و<strong>إزالة</strong> أزرار صغيرة في نهاية الصف.","docs.34700af9e0c1":"يفتح <strong>تحرير</strong> جزء الصف في لفّة البيانو، أو في شبكة الإيقاع إن كان مسار طبول. ويضعه <strong>وضع</strong> على مساره عند رأس التشغيل. ويضع <strong>وضع النمط</strong> كل صف على مساره عند رأس التشغيل في خطوة تراجع واحدة، ويبقى كل موضع مرتبطًا بجزئه: عدّل النمط فيتغير معه كل موضع.","docs.770d88831365":"الخطوات في الرف","docs.26de49bf873c":"خطوات الصف موجودة هناك في الرف مباشرة، في مجموعات من أربع تتناوب في تظليلها، وكل خطوة مضاءة ساطعة بقدر شدّتها. الصف اللحني سطر واحد من الخطوات على نوتة تختارها بجانبه. وصف الطبول ينفتح إلى سطر من الخطوات لكل صوت من أصواته، و<strong>الأصوات</strong> تطويه. انقر على خطوة لتفعّلها، واسحب لترسم سلسلة منها، واسحب بالزر الأيمن لتمحو سلسلة؛ وكل سحبة خطوة تراجع واحدة، و<kbd>Enter</kbd> أو <kbd>Space</kbd> يفعّل الخطوة التي عليها التركيز. والخطوة التي تفعّلها تعزف صوتها حين يكون التشغيل متوقفًا.","docs.09f96634c283":"اللحن المكتوب في لفّة البيانو خارج شبكة الخطوات يظهر في صفه لفّةَ بيانو صغيرة تمتد عبر الخطوات. انقر عليه نقرًا مزدوجًا، أو اضغط <kbd>Enter</kbd> عليه، لتفتحه في المحرّر.","docs.fa59df488bcb":"الرسم البياني","docs.7b51047c96dc":"انقر على اسم صف لتفتح رسمه البياني تحته: القيم التي تحملها كل خطوة — <strong>شدّة الضغط</strong> و<strong>توزيع</strong> و<strong>ضبط دقيق للنغمة</strong> و<strong>الاحتمال</strong> و<strong>مدى الشدة</strong>. ارسم عبر الأعمدة أو اكتب قيمة؛ وكل مسحة خطوة تراجع واحدة.","docs.21a5f2258e03":"يُسمع البان والضبط الدقيق للنغمة لكل خطوة على Drum Machine وOne-Shot Sampler وMultisampler وPercussion Sampler، أثناء عزف الأغنية وفي التصدير. أما Modelled Synth، الذي يعزف آلات المكتبة، وSection Player وLayer Rack فلا تعزفهما بعد، والإضافة تسمع كل خطوة في الوسط وبنغمتها الصحيحة.","docs.3a6bb00d5a4c":"الطول والخطوة والسوينغ","docs.037d8fb8ba6f":"لكل نمط طوله الخاص في <strong>المازورات</strong>، حتى 16 مازورة، و<strong>الخطوة</strong> الخاصة به من 1/4 إلى 1/32، و<strong>السوينغ</strong> الخاص به. وتغيير الطول أو الخطوة يغيّر معه كل جزء في النمط، والخيار الذي يحتاج إلى أكثر من 256 خطوة في الصف الواحد يظهر رماديًّا.","docs.95cea773b379":"تُرسم الخطوات الواقعة بعد نهاية النمط باهتة. اضغط عليها أو اسحب عبرها، أو اسحب المقبض على الخطوة الأخيرة، لتجعل النمط بذلك الطول أو أقصر؛ أو اضبط العدد بـ <strong>−</strong> والرقم و<strong>+</strong> بجانب <strong>الخطوات</strong>.","docs.af43070008b9":"النمط والأغنية","docs.2bbc3c96888d":"بجانب شريط النقل مفتاح تبديل: <strong>النمط</strong> أو <strong>الأغنية</strong>. في <em>النمط</em>، يكرّر زر التشغيل النمط المفتوح على آلات مساراته ومؤثراتها وإعدادات المازج الخاصة بها، بإيقاع الأغنية، دون المساس بالتوزيع. الخطوة التي تفعّلها أثناء العزف تُسمع في الدورة التالية، ويُظهر الرف الخطوة التي تُعزف. افتح نمطًا آخر فيتكرر هو بدلًا منه. و<em>الأغنية</em> تعيد رأس التشغيل إلى حيث كان في الأغنية.","docs.9bb80d88f81b":"وضع النمط طريقة للاستماع، لا تعديل: لا يراه التراجع ولا الغرفة ولا التصدير أبدًا. المسارات التي ليست في النمط صامتة، وأتمتة الأغنية لا تُعزف، ويمكنك التسجيل من جديد بمجرد أن تعود إلى <em>الأغنية</em>.","docs.2195edf6dd56":"كل منزلق وكل بان وكل عنصر تحكم في جهاز يمكن أتمتته. افتح مسار أتمتة المسار، واختر الهدف، وارسم. تلتقط النقاط إلى الشبكة؛ واضغط <kbd>Alt</kbd> لوضع نقطة بحرية. ويمكن ثني المنحنى بين نقطتين بسحب منتصفه.","docs.f82da0230788":"<strong>الكاتا</strong> أشكال أتمتة ترسمها مرة وتطبعها في أي مكان — تضخّم، أو مسح مرشّح، أو انخفاض بشكل السلسلة الجانبية — فتصبح الحركة التي أعجبتك قابلة لإعادة الاستعمال بدل إعادة رسمها.","docs.1a01d11683c6":"جهّز مسارًا للتسجيل، واضغط زر التسجيل، واعزف. يُكتب الصوت على القرص لحظة وصوله بدل الاحتفاظ به في الذاكرة، فلا يكلّفك العطل إلا الكتلة الأخيرة لا اللقطة كلها.","docs.91afc456637e":"سجّل فوق المازورات نفسها مرة أخرى فتحصل على لقطة ثانية مكدّسة تحت الأولى. اختر الأجزاء التي تريدها من كل واحدة فيجمع Oscillate التركيبة. <strong>اللقطات التي لم تخترها لا تُحذف أبدًا</strong> — هذا معنى «اللقطات الظلّية»، ولهذا لا يكلّفك تغيير رأيك بعد أسبوع شيئًا.","docs.cebcc1706c05":"يُضبط العدّ التمهيدي في <strong>الإعدادات ▸ التسجيل</strong>. وهو معطّل افتراضيًا.","docs.9409997795f7":"يفتح <strong>النقل ▸ Oscillate Retro Record…</strong> لوحة Retro Record. وهو يحتفظ بالدقائق الأخيرة من مدخل الصوت لديك ومن لوحة مفاتيح MIDI في ذاكرة هذا الحاسوب، فيظل ممكنًا حفظ لقطة عزفتها قبل أن تضغط زر التسجيل.","docs.c9791d9964aa":"في المرة الأولى، يسأل <strong>هل تُحفَظ الدقائق الأخيرة من مدخلك؟</strong>، ولا يحتفظ بشيء حتى تضغط <strong>السماح والبدء</strong>. وبعد ذلك لا يحتفظ بمدخلك إلا ما دام <strong>الالتقاط</strong> مفعّلًا، ولا يبدأ الالتقاط من تلقاء نفسه أبدًا، ولا حتى عند تشغيل التطبيق. وحين يُطفأ، يبقى ما يحتفظ به حتى يمحوه <strong>مسح كل شيء</strong> من الذاكرة، فورًا. وما دام يلتقط أو يحتفظ بأي شيء، يبقى ظاهرًا في المقدمة في كل نافذة من نوافذ Oscillate ضوءٌ بحالته (<em>يلتقط</em> أو <em>ينتظر</em> أو <em>يحتفظ</em>)، والوقت المحفوظ والذاكرة التي يأخذها، ولا يخفيه أي إعداد.","docs.d959459cef30":"ما يحتفظ به","docs.1e04e7f44341":"<strong>المدخل</strong> مدخل واحد أو زوج ستيريو من جهاز الصوت المختار في <strong>الإعدادات ▸ الصوت</strong>، أو <em>MIDI فقط</em>؛ ولوحة مفاتيح MIDI لديك تُحفظ في الحالتين. و<strong>مدة الاحتفاظ</strong> هي مقدار ما يُحفظ، من 30 ثانية إلى ساعة، وخمس دقائق ما لم تختر غير ذلك، وتُعرض الذاكرة التي تأخذها كل مدة قبل أن تختارها. و<strong>صيغة الحفظ</strong> هي <em>24 بت</em> أو <em>16 بت</em> أو <em>فاصلة عائمة 32 بت</em>، و<strong>متى</strong> هي <em>دائمًا</em> أو <em>أثناء التشغيل</em> أو <em>عند تجهيز مسار</em>. وتغيير المدة أو الصيغة أو المدخل يمسح ما يحتفظ به ويبدؤه من جديد فارغًا، وتنبّهك اللوحة إلى ذلك أولًا.","docs.a342ade123d1":"تُظهر الموجة ما يحتفظ به، والأحدث على اليمين. اسحب عبرها لتختار ما تحفظه؛ وتحرّك مفاتيح الأسهم الاختيار، ويوسّعه <kbd>Shift</kbd> مع سهم، ويمسحه <kbd>Esc</kbd>. وإن لم يصل شيء مدة ثانية ونصف أثناء الالتقاط، يقول أين قد يكون Windows أو macOS أو Linux يحجب الميكروفون عنه.","docs.096b73624b09":"الحفظ","docs.82e23335c315":"يحفظ <strong>حفظ</strong>، أو <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>R</kbd> في أي نافذة من نوافذ Oscillate، ما يحتفظ به Retro Record؛ ومع اختيار امتداد على الموجة، لا يحفظ <strong>حفظ الاختيار</strong> إلا إياه. وإن لم يكن يحتفظ بشيء، يفتح هذا المفتاح Retro Record بدلًا من ذلك. ويختار <strong>ضغطة واحدة تحفظ</strong> بين <em>كل ما هو محفوظ</em> وآخر امتداد تختاره فقط.","docs.705171c008eb":"يحدد <strong>الحفظ بصيغة</strong> وجهة الحفظ. يُنزل <em>مقطع على مسار</em> الصوتَ على مسار الصوت المجهَّز والنوتات على مسار MIDI المجهَّز، أو على مسار جديد، عند المازورة التي عزفتها فيها، أو عند رأس التشغيل إن كانت الأغنية متوقفة. ويكتب <em>ملف WAV</em> ملفَّ WAV مسمّى بالتاريخ والوقت، وبجانبه ملف MIDI إن كنت قد عزفت نوتات.","docs.8460d5410f82":"يقصّر <strong>تخطي الصمت</strong> فترات الهدوء الطويلة أثناء الحفظ، مع تلاشٍ حتى لا يُصدر أي وصل نقرة. ويستمع <strong>قياس الغرفة</strong> إلى ثلاث ثوانٍ من الهدوء ويضبط العتبة أعلى منه بمقدار 9 dB. ويُرفض الحفظ الذي لن يحوي شيئًا، أي حين يُتخطّى كل صوت بوصفه هدوءًا ولا تكون أي نوتة قد عُزفت، ويقول ذلك.","docs.6b7cc94c730b":"الحفظ من أي مكان","docs.2f7eea744072":"ويمكن لمفتاح قدم MIDI أن يحفظ أيضًا. يبقى <strong>مفتاح القدم</strong> على <em>متوقف</em> حتى تختار <em>دواسة الاستدامة (CC 64)</em>، أو تضغط <strong>تعلّم مفتاح القدم</strong> ثم الدواسة أو المفتاح الذي تريده. والضغطة الواحدة حفظة واحدة، مهما ارتدّت الدواسة.","docs.f5a0c0a1e073":"في <strong>الإعدادات ▸ التسجيل</strong>، يجعل <strong>اختصار Retro Record العام</strong> المفتاح نفسه يحفظ من أي برنامج، وOscillate في الخلفية، ويضع <strong>Retro Record في علبة النظام</strong> أيقونة في علبة النظام تضم قائمتها <strong>حفظ Retro Record</strong> و<strong>إظهار Oscillate</strong>. وكلاهما معطّل حتى تفعّله.","docs.df507f038d45":"لا يسمع Retro Record إلا المدخل الحي: فالدمج (bounce) أو التصدير لا يصل إليه أبدًا. وما يحتفظ به، ومكان كتابة الحفظ، مذكوران في <a href=\"#privacy\">الخصوصية والشبكة</a>.","docs.17b03b206557":"صِل لوحة مفاتيح MIDI واخترها في <strong>مدخل MIDI</strong> ضمن <strong>الإعدادات ▸ MIDI</strong>. فهي تعزف المسار المجهَّز، كما تفعل لوحة المفاتيح الظاهرة على الشاشة في لفّة البيانو، وإذا فُصلت أعادت الاتصال من تلقاء نفسها حين تعود. يضيء <strong>نشاط النوتات</strong> مع وصول النوتات، وإن لم يكن أي مسار مجهَّزًا أخبرك القسم بذلك.","docs.6d35ffc10fcb":"طريقة العزف","docs.3a26213a86f3":"يحرّك <strong>تحويل الطبقة</strong> كل مفتاح على لوحة المفاتيح العتادية حتى أربعة أوكتافات في أي من الاتجاهين. و<strong>مدى ثني النغمة</strong> هو مقدار ما تثنيه عجلة ثني النغمة: بمقدار نصفَي درجة في كل اتجاه ما لم تغيّره، وحتى أربعة أوكتافات؛ أما الإضافة فتثني بمداها الخاص. و<strong>منحنى قوة الضغط</strong> إما <em>خطي</em>، أو <em>ناعم</em> حيث تعزف اللمسة الخفيفة بصوت أعلى، أو <em>قاسٍ</em> حيث يتطلب العزف بصوت مرتفع ضغطة حازمة.","docs.b0013f90aea7":"تحوّل <strong>الكوردات</strong> كل مفتاح إلى تآلف في مقام المشروع: ثلاثي أو سباعي أو تساعي، بحسب <strong>حجم الكورد</strong>. وينطبق ذلك على كل مفتاح يصل إلى المسار المجهَّز — لوحة المفاتيح العتادية، واللوحة الظاهرة على الشاشة، ومفاتيح الحاسوب التي تكتب بها فيها.","docs.b308d15ed7fd":"العجلات","docs.c7e25b23a89c":"تثني عجلة ثني النغمة النوتات التي تمسكها، والنوتة التي تُضرب والعجلة خارج موضع سكونها تبدأ مثنيّة. وتُدخل عجلة التعديل وضغط القناة الاهتزاز (vibrato) على آلات المكتبة. والإضافات المستضافة من نوع VST3 وCLAP تستقبل الثلاثة جميعًا، كما تستقبلها في أي DAW آخر.","docs.81cdc8394f11":"على المسرح، وعلى الوسادات","docs.0d942d8f36fb":"ما دام المسرح يتبع المسار المجهَّز، فإن ما تعزفه على لوحة مفاتيح MIDI أو تكتبه في لوحة مفاتيح لفّة البيانو يظهر على آلته؛ انظر <a href=\"#stage\">المسرح</a>. ويمكن لوحدة تحكم بالوسادات أن تعزف وسادات Drum Machine بعد أن تتعلّمها؛ انظر <a href=\"#drum-grid\">شبكة الإيقاع</a>.","docs.fceb67e7d5a2":"<kbd>Ctrl</kbd>+<kbd>4</kbd>. شريط لكل مسار فيه منزلق وبان وكتم وإفراد ورف الأجهزة ومقياس يُرسم من الصوت الذي أنتجه المحرّك فعلًا — لا من تنبؤ أبدًا.","docs.fc9ca9fe7259":"مقابض الشريط","docs.ab21191b71d4":"في شريط كل مسار مقابض <strong>منخفض</strong> و<strong>متوسط</strong> و<strong>مرتفع</strong> و<strong>غرفة</strong> و<strong>صدى</strong> و<strong>حرارة</strong> و<strong>تعديل الطبقة</strong> و<strong>حُبيبي</strong>، وتحتها ضاغط خاص به: مفتاحه، وضوء يُظهر متى يقتطع شيئًا، و<strong>العتبة</strong> و<strong>النسبة</strong> و<strong>الهجوم</strong> و<strong>التحرير</strong> و<strong>التعويض</strong>. والضاغط مطفأ حتى تشغّله، والحُبيبي عند 0 % خارج مسار الإشارة. ويُحفظ كل مقبض مع المشروع، ويمكن أتمتته، ويتحرك في خطوة تراجع واحدة. والمقبض الوحيد في الرئيسي هو الحُبيبي.","docs.4e127e233a98":"تبقى المقابض مطويّة حتى تضغط <strong>المقابض</strong>؛ وحين تكون مطويّة، يقتصر المازج على المنزلقات والمقاييس، وتواصل المؤثرات عملها.","docs.8eaced166021":"رادار الحجب","docs.bea60461bd8b":"اضغط <strong>الرادار</strong> فيراقب Oscillate أزواج المسارات التي تتنازع النطاق نفسه — الباص والطبلة الكبيرة، والصوت الغنائي والـ pad — ويسمّي الزوج والتردد. يستهلك المعالج ما دام مفعّلًا، والتلميح يقول ذلك.","docs.6f550e9b860d":"الزوج الذي لم يُسمع بعد يظهر عليه <strong>لم يُسمع بعد</strong>، لا «نظيف». وإذا كان في الجلسة مسارات أكثر مما يراقبه الرادار، فهو يخبرك بذلك أيضًا بدل أن يعرض جزءًا منها بصمت.","docs.e0b651a4ea3c":"الجهارة والذروة الحقيقية","docs.5a27169c5088":"اضغط <strong>الجهارة</strong> لترى LUFS المتكاملة وقصيرة المدى والمدى والذروة الحقيقية، مع جدول بما تستهدفه كل خدمة بث وما ستفعله بالماستر لديك. ويحمل كل هدف تاريخ آخر مرة تُحقِّق منه.","docs.bfc4dfe30bdc":"إذا تأخر المقياس يومًا تحت الضغط فإنه يقول ذلك — <em>«تأخر المقياس، فبعض الصوت لم يُقَس قط»</em>. والرقم الذي لا تحذير بجانبه يعني قياسًا كاملًا.","docs.fcbd76890ab6":"توازن الصوت ↔ MIDI","docs.5395f9abcc77":"يمزج المنزلق في شريط النوتات مسارات الصوت في المشروع مقابل مسارات MIDI فيه: في أقصى اليسار لا يُعزف إلا الصوت، وفي أقصى اليمين لا يُعزف إلا MIDI، وفي الوسط يُعزف كلاهما كاملين. يُسمع أثره فورًا وينساب دون طقطقات، ويُحفظ مع المشروع، ولا يحرّك منزلق أي مسار أبدًا. والتصدير والمسارات المنفصلة (stems) وتجميد المسارات تتجاهله كلها. انقر عليه نقرًا مزدوجًا لتعيده إلى الوسط.","docs.eadb0d7c2b3a":"ولكل شريط قفل المسار أيضًا؛ انظر <a href=\"#lock\">قفل المسار</a>.","docs.bb68efe46235":"<kbd>Ctrl</kbd>+<kbd>6</kbd>، أو <strong>عرض ▸ المسرح</strong>، يفتح المسرح: آلة ثلاثية الأبعاد واليدان اللتان تعزفان عليها مسارات MIDI لديك، في تزامن مع شريط النقل — عبر تغيّرات الإيقاع، وعند دوران الحلقة، وأينما مرّرت. ويُحمَّل أول مرة تفتحه، فلا يصبح بدء Oscillate أبطأ بوجوده.","docs.b2c1bf6636d4":"<strong>تتبّع</strong> قائمة منسدلة بمسارات MIDI في المشروع، بمربع اختيار لكل منها، و<em>الكل</em> معلَّم في البداية، ويقود المسارُ الذي تحدده في التوزيع أو المازج. وعلى البيانو تُعزف حتى أربعة أجزاء معًا، يُعرف كلٌّ منها باسم مساره — لحن، أو تآلفات، أو باص، أو لحن مقابل — أو بموقعه إن لم يُعرف بالاسم: فيميل الباص والتآلفات إلى اليد اليسرى، واللحن واللحن المقابل إلى اليمنى، ولا تتقاطع اليدان إلا حيث لا يمكن عزف الفقرة الموسيقية بغير ذلك. ويعزف الغيتار الجزء الواحد المختار في <strong>يعزف</strong>، ويعزف الباص خط الباص، ولا ينضم إليهما مسار الطبول أبدًا. وما هو معلَّم يدوم طوال الجلسة. وما دام المسرح مفتوحًا، فإن إبقاء المؤشر على المسطرة يُظهر صورة صغيرة للمسرح في تلك اللحظة.","docs.b854e3db884e":"ما يقف على المسرح","docs.fc50699f9956":"لكلٍّ من البيانوهات والغيتارات والباصات والطبول أيادٍ خاصة تعزفه. والآلات المرفقة Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano، وGuitar وNylon Guitar وElectric Guitar وMuted Guitar، وPluck Bass وSlap Bass وUpright Bass، يظهر كلٌّ منها بهيئته، وElectric Guitar الموصول بـ Guitar Amp يظهر غيتار روك. وأي آلة أخرى تُعزف على البيانو الكبير.","docs.b13f8d00411c":"يظهر مسار Drum Machine على هيئة وحدة تحكم من 16 وسادة تعزفها أيادٍ تقرع بالأصابع، وتضيء وساداتها حين تُضرب. وأي مسار طبول آخر يظهر على هيئة طقم استوديو يُعزف بالعصي والقدمين.","docs.501f27b7d77e":"تضع <strong>الآلة</strong> على المسرح بيانو أو غيتارًا أو باصًا آخر لمسار ما، أو وحدة التحكم بالوسادات أو طقم الطبول لمسار طبول. وهي تغيّر الشكل واليدين فقط: يبقى الصوت صوت آلة المسار نفسها.","docs.81c02d3967f8":"عناصر التحكم الخاصة بكل آلة","docs.727825c6add3":"<strong>البيانو:</strong> <strong>أسماء المفاتيح</strong> على كل المفاتيح أو على البيضاء فقط أو على لا شيء، و<strong>أرقام الأصابع</strong> من 1 إلى 5.","docs.772ca78133a2":"<strong>الغيتار:</strong> <strong>يعزف</strong> يحدد ما يعزفه — التآلفات أو اللحن أو لحنًا مقابلًا — بيدين تضربان الأوتار وتنقرانها، مع الانزلاقات والطَّرق (hammer-on) والسحب (pull-off).","docs.8f7c1096c8f0":"<strong>الباص:</strong> <strong>الأوتار</strong> أربعة أو خمسة على Pluck Bass وSlap Bass. ومع أربعة أوتار، تُعزف النوتات الأدنى من E المنخفضة بأوكتاف أعلى.","docs.72dd5a83030f":"<strong>الغيتار أو الباص:</strong> <strong>المرافقة</strong> — عند إطفائها يُفرَد المسار ويُسمع وحده، وعند تشغيلها تعزف المسارات الأخرى معه — وعازف <strong>أعسر</strong>، و<strong>أرقام الأصابع</strong> على اليد التي تضغط على الدساتين، وعلى الغيتارات الكهربائية وغيتارات الروك وعلى Pluck Bass، شكل مقطع <strong>أسلاك الدساتين</strong> ومعدنها، وهما يغيّران مظهر الآلة لا صوتها.","docs.f7034c6b7a2d":"<strong>طقم الطبول:</strong> عازف طبول <strong>أعسر</strong>.","docs.a9b675db7c20":"الكاميرات","docs.4c038fd542ad":"يتيح لك <strong>العرض</strong> النظر من منظور <em>أمامي</em> أو <em>علوي</em> أو <em>جانبي</em>، أو الاقتراب من يد: اليد اليسرى أو اليمنى على البيانو، أو اليد التي تضغط على الدساتين أو التي تنقر الأوتار على الغيتار، أو اليدين على الوسادات، أو اليدين أو القدمين عند الطقم. انقر على المسرح ليصير التركيز عليه، فينساب <kbd>V</kbd> إلى العرض التالي ويعود <kbd>Shift</kbd>+<kbd>V</kbd> إلى السابق. وفي كل مكان آخر تحتفظ هذه المفاتيح بوظائفها المعتادة.","docs.faf2ae9b7dc0":"وما دام المسرح ظاهرًا، يتنقّل <kbd>Alt</kbd>+<kbd>V</kbd> و<kbd>Alt</kbd>+<kbd>Shift</kbd>+<kbd>V</kbd> بين العروض بالطريقة نفسها من أي مكان، أينما كان التركيز.","docs.2dfb06bbe520":"الجودة ولون البشرة","docs.1c4f1647ab9b":"<strong>الجودة</strong> إما <em>تلقائية</em>، وإما ثابتة: <em>عالية</em> أو <em>متوسطة</em> أو <em>منخفضة</em>. والجودة التلقائية تحكم على مستوى الجودة بأبطأ إطاراته لا بمتوسطها، فلا تخفّض التفاصيل إلا حيث يتعثّر الجهاز فعلًا، وتقول ذلك حين تفعل. و<strong>لون البشرة</strong> يمنح اليدين واحدًا من ستة ألوان. ويُحفظ كلاهما على هذا الحاسوب.","docs.944860301e3b":"العزف على المسرح","docs.e84f7ce0faa7":"حين يتبع المسرح المسار المجهَّز يمكنك العزف عليه: انقر على مفاتيح البيانو أو أوتار الغيتار أو الوسادات، وما تعزفه على لوحة مفاتيح MIDI أو تكتبه في لوحة مفاتيح لفّة البيانو يظهر على الآلة. وما دامت عجلة ثني النغمة أو عجلة التعديل أو الضغط في لوحة مفاتيح MIDI خارج موضع السكون، تُظهرها قراءة صغيرة. وحين يتبع أي مسار آخر، يطلب منك رأس المسرح أن تجهّزه.","docs.32f7674d29c2":"حامل النوتة","docs.2f8af7ba544e":"الأوراق على حامل النوتة في المسرح هي نفسها التي تدوّنها لوحة النوتات للمسار الذي يتبعه المسرح؛ انظر <a href=\"#sheets\">النوتات</a>. وتنقلب صفحاتها من تلقاء نفسها بالوتيرة المضبوطة في <strong>الإعدادات ▸ المظهر</strong> — بضعف السرعة عند <em>سريعة</em>، وبقطع مباشر عند <em>تقليل</em> — والنوتة التي تعزفها اليدان مضاءة.","docs.3df54afb81cf":"للجميع","docs.78c6a91c0856":"يمكن الوصول إلى كل عنصر تحكم على المسرح من لوحة المفاتيح، ولكلٍّ منها اسم يقرؤه قارئ الشاشة، والمسرح نفسه مسمّى بما يقف عليه والمسار الذي يتبعه — <em>المسرح: Grand Piano، يتبع Keys</em>. ومع تفعيل تقليل الحركة، في <strong>الإعدادات ▸ المظهر</strong> أو من إعداد نظامك، تنتقل الكاميرا من عرض إلى التالي مباشرة بدل أن تنساب، وتواصل اليدان العزف.","docs.e4c4c4cc66eb":"على macOS وLinux","docs.a38e5531ae92":"على macOS يعزف المسرح مع الأغنية، كما يفعل على Windows: فجهاز Mac يرسم الأبعاد الثلاثية على بطاقة رسوميات حقيقية. أما Linux فيرسم نافذة Oscillate بـ WebKit، الذي قد يرسم الأبعاد الثلاثية على المعالج دون أن يقول ذلك، لذا يقف المسرح هناك ثابتًا ليبقى التطبيق سلسًا، ويقول السبب: يرسم إطارًا لكل تغيير — حين توقف التشغيل، أو تحرّك رأس التشغيل، أو تغيّر العرض — بدل أن يعزف مع الأغنية، وتنتقل الكاميرا بقطع مباشر بدل أن تنساب. وجهاز Mac الذي لا بطاقة رسوميات فيه أصلًا، كالآلة الافتراضية، يقف ثابتًا بالطريقة نفسها.","docs.05ec58676b0b":"حين يتعذّر ذلك","docs.7652f24d0166":"النافذة التي لا تستطيع رسم WebGL 2 تُظهر <em>العرض ثلاثي الأبعاد غير متاح</em> والسبب، ولا تُظهر مسرحًا فارغًا أبدًا. والمسار الذي فيه نوتات أكثر مما يعزفه المسرح يُذكر باسمه، مع عدد نوتاته وعدد ما يستطيع المسرح استيعابه: قسّمه إلى مسارات أقصر، أو تتبّع مسارًا آخر.","docs.bfcae0954b62":"<kbd>Ctrl</kbd>+<kbd>7</kbd>، أو <strong>عرض ▸ النوتات</strong>، أو زر النوتات في شريط العنوان، يُظهر لوحة النوتات: أي مسار MIDI مدوّنًا كنوتة موسيقية، يتبع رأس التشغيل. وهي مثبّتة تحت المسرح، فوق المحرّر، ومخفية حتى تفتحها. وتبقى دائمًا في النافذة الرئيسية، لأن صفحاتها تنقلب على ساعة النافذة الرئيسية. ولا يُحمَّل منها شيء حتى تُعرض أول ورقة، فلا يصبح بدء Oscillate أبطأ بوجودها.","docs.dbc863f4a58d":"ما تحمله الورقة","docs.e2e4a9222290":"يُدوَّن كل مسار MIDI فيه نوتات على مدرج بمفتاح صول أو بمفتاح فا أو على مدرج مزدوج، يُختار بحسب النوتات التي يعزفها. ويتغيّر الميزان والمقام حيث يتغيّران في المشروع، وتحصل كل علامة قسم على علامة تمرين، وتصبح المازورات الصامتة سكتات متعددة المازورات، وتبدو الصفحات كالورق، مع اسم المشروع و<em>صفحة n من N</em>. وتُباعَد المدرجات بحسب ما تحمله، فلا تتصادم أبدًا عوارض الطبول، ولا نوتات الغيتار المنخفضة فوق تدوين TAB الخاص به، ولا الكلمات. وتُدوَّن مئتا مازورة في نحو ربع ثانية.","docs.53fe7e8fa768":"<strong>الورقة للقراءة فقط.</strong> إنها عرضٌ لمسارها: عدّل النوتات في لفّة البيانو فتتبعها الورقة.","docs.be2f58fbb4f7":"تدوين TAB وأوراق الطبول","docs.5cf1a74f1eaf":"يُدوَّن مسار الغيتار بمفتاح صول منخفضًا أوكتافًا (8vb) فوق TAB بستة أسطر، مع مخططات التآلفات وأسهم الضرب على الأوتار. ويُدوَّن الباص فوق TAB بأربعة أسطر، أو بخمسة على باص بخمسة أوتار. والدساتين هي نفسها التي تعزف عليها أيدي المسرح. ومسار الطبول يكتب تحت كل ضربة اليد أو القدم التي تعزفها: <em>R</em> أو <em>L</em> أو <em>RF</em> أو <em>LF</em>.","docs.99a1f9b6751d":"الكلمات تحت النوتات","docs.803b68dc26c8":"تُدوَّن الكلمات التي في مسار الكلمات الخاص بالمسار تحت نوتاته، والمقطع الممدود بـ <code>_</code> يرسم خط امتداده؛ انظر <a href=\"#lyrics\">مسار الكلمات</a>.","docs.b956e8e07a54":"شريط النوتات","docs.c763ac7681d9":"الشريط الممتد على طول أعلى اللوحة. تأتي شارة المدونة الكاملة أولًا، ثم شارة لكل مسار MIDI فيه نوتات، بترتيب التوزيع؛ وحين تتجاوز الشاراتُ طول الشريط يتمرّر جانبيًّا. وتحمل شارة كل مسار:","docs.51870c937279":"رقم مفتاحه واسمه: انقر على الاسم لتقرأ ورقته، ومرة أخرى لتعود؛","docs.b0bbcf140652":"<strong>M</strong> و<strong>S</strong>: كتم المسار وإفراده نفساهما، الزرّان ذاتهما اللذان على رأس المسار وعلى شريطه في المازج (انقر <strong>S</strong> مع <kbd>Ctrl</kbd> لتُفرده إلى جانب الآخرين)؛","docs.ffbfdce6aedb":"<strong>قفل</strong>: قفل المسار؛ انظر <a href=\"#lock\">قفل المسار</a>؛","docs.e1403ae0c46a":"وعلى Windows وmacOS، مقبض سحب يُخرج MIDI المسار من Oscillate، إلى سطح المكتب أو إلى برنامج آخر. انقر على المقابض لتختار عدة مسارات وتسحبها معًا. ومقبض المدونة الكاملة، <strong>اسحب الكل</strong>، يسحب مسار كل ورقة.","docs.79d6deab7900":"بعد الشارات يأتي منزلق الصوت ↔ MIDI (انظر <a href=\"#mixer\">توازن الصوت ↔ MIDI</a>) وزرّا <strong>PDF</strong> و<strong>طباعة</strong>، اللذان يظهران رماديين أثناء إعداد ملف PDF أو طباعة.","docs.28288fa30f54":"الطاولة","docs.6787febdf396":"تحت شريط النوتات، تبسط الطاولة الصفحة الأولى من كل ورقة على هيئة بطاقة، بترتيب الشريط. انقر على إحداها، أو اضغط <kbd>Enter</kbd> عليها، لتقرأها. تُرسم البطاقات والأغنية متوقفة؛ وإن فتحت الطاولة في منتصف الأغنية فإنها تعرض أسماء الأوراق حتى تتوقف الأغنية.","docs.70729b5d0c2d":"القارئ","docs.ae0ea2772a41":"الورقة التي تفتحها تمتد بكامل عرض اللوحة، وصفحاتها واحدة تحت الأخرى. وما دامت لوحة النوتات ظاهرة، تفتح المفاتيح من <kbd>1</kbd> إلى <kbd>9</kbd> الأوراق التسع الأولى بترتيب شريط النوتات، و<kbd>1</kbd> هو المدونة الكاملة؛ والمفتاح نفسه مرة أخرى، أو <kbd>Esc</kbd>، يعيدك إلى الطاولة. وحقل النص الذي تكتب فيه يحتفظ بأرقامه. ويمكن تغيير كل مفتاح من هذه المفاتيح في <strong>الإعدادات ▸ الاختصارات</strong>.","docs.eb8223ab78ba":"أثناء عزف الأغنية، تنقلب الصفحات من تلقاء نفسها، فيبقى السطر الذي يُعزف ظاهرًا والسطر التالي تحته. والنوتات المضاءة هي دائمًا النوتات المسموعة: المسار المكتوم لا يضيء شيئًا، وما دام مسارٌ مُفردًا لا تضيء إلا المسارات المُفردة، وفي المدونة الكاملة تضيء كل نوتة على مدرج مسارها. وقائمة الأقسام تنقل رأس التشغيل إلى قسم، فتنقلب كل ورقة معه. و<em>صفحة n من N</em> تخبرك أين أنت.","docs.d1edfe59d41d":"إن لم يكن في أي مسار MIDI نوتة، تقول اللوحة ذلك. والمسار الذي فيه نوتات أكثر مما تستطيع ورقة تدوينه يحتفظ بشارته، وتذكر ورقته عدد ما يعزفه وعدد ما تتسع له الورقة: قسّمه إلى مسارات أقصر لتقرأه ورقةً.","docs.b91c8440ec46":"<kbd>Ctrl</kbd>+<kbd>8</kbd>، أو <strong>عرض ▸ الدروس</strong>، أو زر الدروس في شريط العنوان، يُظهر لوحة الدروس: خمس عشرة دورة، تتعلّمها يومًا بيوم. وتُفتح عمودًا بجانب التوزيع وتبقى دائمًا في النافذة الرئيسية. ولا يُحمَّل منها شيء حتى تفتحها أول مرة، فلا يصبح بدء Oscillate أبطأ بوجودها.","docs.24c8b6c0abca":"نص الدروس نفسه، أي كلمات كل خطوة، بالإنجليزية حاليًا؛ أما كل زر وتسمية ورسالة حوله فبلغتك.","docs.2ef08f855c58":"الدورات","docs.e8a6f7aa2805":"يضم تبويب <strong>الدورات</strong> الدورات الخمس عشرة، في قائمة منسدلة وشريط: البيانو، وقراءة النوتة، والإيقاع، وتدريب الأذن، والنظرية للمنتجين، وكتابة الأغاني، وكتابة الكلمات، والراب والتدفق، وتوزيع الأغنية، والمزج، وقرع الطبول بالأصابع، وطقم الطبول، والغيتار، والغيتار الكلاسيكي، والباص. وتُظهر كلٌّ منها ضوء تقدّم من عشرة أجزاء وعدد الأيام التي اجتزتها، والدورة التي لم تبدأها تقول ما الذي تبدأ بعده. وتحتها تمتد أيام الدورة المفتوحة على خط واحد، مجمّعةً حسب الأسبوع تحت أقسامها، ويُعرف كلٌّ منها بشكله إلى جانب لونه: مجتاز، أو حيث أنت، أو مراجعة، أو نقطة تحقق، أو لم تبلغه بعد؛ وتتنقّل مفاتيح الأسهم على طوله. وتُظهر عدّادات الوقت هذا الدرس، وكل الدروس، والأيام التي تمرّنت فيها. ويفتح <strong>متابعة</strong>، زر اللوحة الوحيد، اليومَ والخطوة حيث توقفت. واليوم الذي لم تبلغه بعد يُفتح مع ذلك، ويقول ذلك.","docs.2b065c7c9ce4":"اليوم","docs.a94682304567":"يعرض تبويب <strong>اليوم</strong> اليومَ الذي فتحته، خطوة خطوة: <em>شاهد</em>، و<em>جرّب</em>، و<em>على الإيقاع</em>، و<em>اعزف كاملًا</em>، وسؤال سمعي تجيب عنه (<em>استمع</em>)، وأغنية تصنعها (<em>اصنع</em>)، وغير ذلك. والخطوة التي تعزف تضع موسيقاها على مسارات حقيقية بآلة الدورة، مع عدّ تمهيدي بطول مازورة، ويعزفها شريط النقل في Oscillate نفسه؛ ويضيء المسرح المفاتيح أو الزند أو اللوحات التي تطلبها الخطوة. اضغط <strong>ابدأ</strong> واعزف معها على لوحة مفاتيح MIDI، أو على آلتك إن كانت الدورة تستمع. وتُجتاز الخطوة بثلاث محاولات ناجحة متتالية.","docs.a669864312ff":"بجانبه أدوات التمرين: يد واحدة بينما يعزف المسرح الأخرى، وحلقة من المازورات التي تختارها، والإيقاع الذي يرتفع نحو إيقاع الخطوة نفسها كلما أصبت. واليوم الذي أتقنته يعود لاحقًا للمراجعة.","docs.aeffaf06d287":"بعد اللقطة يقول التقييم ما أحسنت فيه وما يجب إصلاحه، مسمّيًا المازورة والنبضة والإصلاح، ثلاثة أشياء على الأكثر، الأكثر كلفةً أولًا. واللقطة المسموعة عبر مدخلك تقول إنها قُيِّمت بالأذن. وفي خطوة الصنع، يمكن تعليم هدف أخطأته عن قصد بـ<strong>علّمه مقصودًا</strong>، فيتوقف احتسابه.","docs.b76c42cb4bf3":"أرني","docs.ce107014268a":"يعزف لك <strong>أرني</strong> الخطوة أولًا، واليدان عن قرب على المسرح، بنصف السرعة أو بثلاثة أرباعها أو كاملة، ويمكنه تكرار مقطع منها في حلقة. لا يُستمع إلى شيء ولا يُقيَّم شيء. ويعيدك <strong>العودة إلى الخطوة</strong> إليها.","docs.38e07b2a0ca5":"القراءة بصوت عالٍ","docs.57b7c4396a9e":"حين تُفعَّل <strong>القراءة بصوت عالٍ</strong>، تقرأ نص الخطوة بأحد الأصوات الخاصة بحاسوبك، فتضيء كل كلمة لحظة قراءتها وتُبقي سطرها ظاهرًا. لا يأتي أي صوت مع Oscillate: فإن لم يكن أي صوت مثبتًا قالت ذلك، ويمكن إضافة صوت من إعدادات نظامك. وفي شريطها <strong>ترجيع</strong> و<strong>اقرأ</strong> و<strong>إيقاف مؤقت</strong> و<strong>إيقاف</strong> و<strong>تقديم سريع</strong>، والسرعة من النصف إلى الضعف، و<strong>الصوت</strong>، وعدّاد للقراءة. وما دام التركيز في لوحة الدروس، يقرأ <kbd>Space</kbd> أو يوقف مؤقتًا، ويرجع <kbd>Shift</kbd>+<kbd>←</kbd> جملةً ويتقدّم <kbd>Shift</kbd>+<kbd>→</kbd> جملةً.","docs.0a4a6d09bcdb":"الاستماع إليك","docs.41d09f811435":"في الدورة التي تستطيع سماعك، يجعل مفتاح <strong>الاستماع</strong> في شريط الدرس الدرسَ يسمع آلتك أو صوتك بدل مفاتيح MIDI. فهو يسمع مدخل جهاز الصوت المختار في <strong>الإعدادات ▸ الصوت</strong>: النوتات وتوقيتها، والتآلفات، وضربات طقم الطبول، ومقاطع الراب اللفظية. ويختار <strong>المدخل…</strong> أيًّا من قنواته، أو كل القنوات ممزوجة، ويُظهر المستوى والتآلف الذي يسمعه.","docs.758985129d60":"يُظهر <strong>الموالف</strong> كم سنتًا تعلو النوتة أو تنخفض، لونيًا أو وترًا وترًا للغيتار أو الباص، مع A4 في أي قيمة من 415 إلى 466 Hz. وتقيس <strong>المعايرة</strong> كم يستغرق الصوت ليغادر Oscillate ويعود إليه، فيقع ما تعزفه في وقته: ترسل <strong>حلقة راجعة</strong> ثماني نقرات عبر كابل من المخرج إلى المدخل، أو من سماعاتك إلى الميكروفون؛ وفي <strong>عزف مرافق</strong> تصفّق أو تعزف مع كل نقرة. ويحفظ <strong>إبقاء</strong> القياس لذلك المدخل. وإلى أن يُعايَر المدخل، يستعمل Oscillate تقديره الخاص ويوسمه بأنه تقدير. وما دام درسٌ يستمع، ينتظر الموالف والمعايرة.","docs.420e5b8d6f43":"يُضاء ضوء <strong>يستمع</strong> تمامًا ما دام المدخل مفتوحًا، وعندئذ فقط يُسمع أي شيء. وما يُسمع يُحلَّل على هذا الحاسوب لحظة وصوله ثم يُترك: لا يُسجَّل شيء ولا يُحفظ ولا يُرسل. انظر <a href=\"#privacy\">الخصوصية والشبكة</a>.","docs.72eecb4a3785":"تعزف <strong>المراقبة</strong>، في شريط الدرس، مدخلك عبر مسار الدرس الخاص لتسمع نفسك، أو الغيتار أو الباص عبر المضخّم. وهي معطّلة افتراضيًا، لأن الميكروفون يُحدث تغذية راجعة عبر السماعات: البس سماعات رأس. وتُحفظ لكل دورة، ولا تسجّل شيئًا هي أيضًا.","docs.fb7ef24de47f":"خطوات الصنع","docs.c85be82fcfea":"تفتح خطوة الصنع أدوات Oscillate نفسها في مشروع الدرس: التوزيع مع أغنية البداية الخاصة بالخطوة وأقسامها علاماتٍ، أو مسار الكلمات وشبكة التدفق فيه، أو المازج مع حلقة الخطوة. ويقيس <strong>افحص</strong> ما صنعته مقابل أهداف الخطوة، وهدفُ المزج يُقاس على المزيج نفسه بعد تصييره، ويقول ما وجد. ويجلب <strong>حمّل المثال</strong> مثالًا، بعد أن يحفظ أغنيتك كما هي الآن نسخةً أولًا. وفي الراب والتدفق، يسمع <strong>أدِّ الراب</strong> لقطةً عبر مدخلك ويقيس توقيت كل مقطع لفظي مقابل موضعه؛ ولا تُسجَّل اللقطة أبدًا. وتحتفظ كل خطوة صنع بصفحة في الدفتر.","docs.e715e082f478":"مشروعك، موضوع جانبًا","docs.1670ea12541a":"يعمل الدرس في مشروع خاص به. أما مشروعك فيُوضع جانبًا في الذاكرة، دون أن يُمس، مع تغييراته غير المحفوظة وسجل التراجع فيه، ويقول ذلك شريطٌ في أعلى اللوحة ما دام درسٌ مفتوحًا. ويعيده زر <strong>العودة إلى مشروعي</strong> تمامًا كما كان، وكذلك يفعل «مشروع جديد» و«افتح» والغرفة والخروج من التطبيق. ولا يمكن فتح درس ما دامت غرفة مشتركة.","docs.1f37b96dbaaf":"السجل وملف الأعمال","docs.c762307fbf0f":"يعرض تبويب <strong>السجل</strong> تقدّمك في كل دورة وعدّادات الوقت؛ وكل صفحة من الدفتر، تفتح كلٌّ منها يومها عند خطوتها؛ ونسخ أغنيتك المسمّاة، كلٌّ منها مقارَنة بالأغنية الآن وتُستعاد في خطوة تراجع واحدة؛ والورقة الرئيسية، التي تُفتح في لوحة النوتات. ويصنع <strong>ملف الأعمال PDF</strong> ملف PDF لأغنيتك. ويُحفظ كل ذلك في مجلد بيانات Oscillate على هذا الحاسوب.","docs.e3d7060ad727":"إذا استُخدم Freally Handscore على هذا الحاسوب، فإن تقدّم دروسه وملف أعماله والكلمات التي طلبت منه أن يُبقيها كما كُتبت تُنقل في أول مرة تحتاجها الدروس، مرة واحدة فقط، ولا تُغيَّر ملفات Handscore نفسها أبدًا.","docs.c3c5f9066bd3":"الكلاسيكيات","docs.7e15cf2f46f6":"تضم <strong>الكلاسيكيات</strong> 62 أغنية من الملك العام، يمكن البحث فيها بالعنوان، والمقاطع التدريبية: سلّم موسيقي، وأربيجيو، ويد تعبر فوق الأخرى، وغير ذلك. افتح أيًّا منها <strong>كدرس</strong>، في مشروع الدرس الخاص، أو <strong>كمشروع</strong>، فيُضاف بعد ما في مشروعك في خطوة تراجع واحدة.","docs.9812a95cbb66":"لا يجوز أن يُسحب من Oscillate إلا تآلفات القطعة الكلاسيكية. وكل مسار تضيفه القطعة الكلاسيكية للحنها يبقى معلَّمًا بأنه لها، رغم إعادة التسمية والتراجع والحفظ، وأي سحب كان سيُخرج واحدًا منها، من مساره أو من التوزيع أو من شريط النوتات أو بزر <strong>اسحب الكل</strong>، يُرفض ويقول السبب.","docs.24653cacd405":"يستضيف Oscillate إضافات <strong>VST3 وCLAP</strong>، وتعمل كل إضافة في عملية خاصة بها. الإضافة التي تنهار تجعل جهازها رماديًّا وتترك جلستك تعمل.","docs.4c2bf768921f":"تظهر إضافاتك في مستعرض الملفات تحت <em>الإضافات</em>. اسحب إحداها إلى مسار، أو حدّد المسار وانقر عليها. افتح محرّرها الخاص من رف الأجهزة — الواجهة الحقيقية التي اشتريتها، لا قائمة منزلقات — وإغلاقه ثم إعادة فتحه يعيده بالحجم الذي كان عليه.","docs.657f210c6f73":"تعويض التأخير يشمل الرسم البياني كله، ومُثبت باختبار إلغاء: الإشارة نفسها عبر جهاز يُبلغ عن تأخيره وحوله، فتلغي إحداهما الأخرى حتى الصمت. والإضافة غير الموجودة على هذا الجهاز تصبح عنصرًا نائبًا مسمّى يظل يحتسب عيّناته، فيبقى المشروع المفتوح في مكان آخر في توقيته.","docs.e8fa69bd1ae0":"يصل تعبير كل نوتة الخاص بها إلى الإضافة على تلك النوتة وحدها: ضغطها وجرسها (Mod Y وMod X لكل نوتة في لفّة البيانو)، وثنيها الخاص، والضبط الدقيق للطبقة والبان لخطوةٍ ما. وتسمعها إضافة CLAP تعبيراتِ نوتات (note expressions)، وإضافة VST 3 أحداثَ تعبير النوتة (note-expression events)، والضغطَ ضغطًا متعدد الأصوات. والإضافة التي لا تأخذ أيًّا منها تسمع ما كانت تسمعه دائمًا، وإضافة CLAP التي لا تقرأ إلا MIDI تتلقى ضغط النوتة لمسةً لاحقة متعددة الأصوات.","docs.dbc9556fe13a":"خمس وثمانون آلة ومؤثرًا تأتي داخل Oscillate، ومنها <strong>Freally Secretarium</strong>. كل لوحة مرسومة من وصف الجهاز نفسه، فالقراءة على المقبض هي الرقم الذي تستعمله معالجة الإشارة فعلًا، لا رقم ثانٍ يتفق معه معظم الوقت.","docs.57ba00ce7687":"الواجهات","docs.b1223c1040cb":"يُظهر الجهاز ما يفعله بالصوت المارّ عبره، حيًّا، ما دامت بطاقته ظاهرة. فالمعادل أو المضخّم يرسم منحناه فوق الطيف الداخل والخارج؛ والضاغط أو المحدِّد أو البوابة يرسم منحنى المستوى والصوتُ يسير عليه، والخفضَ ينساب مقابل العتبة، وإبرتَه؛ ومزيل الصفير يرسم نطاقه فوق الطيف؛ والمشبِّع يرسم منحنى النقل والصوتُ نقطةٌ عليه؛ وجهاز الستيريو يرسم حقله ومدى توافق الجانبين؛ وأجهزة التأخير والصدى المتردد (reverb) ومؤثرات التعديل ترسم المستوى على امتداد المازورة، ويرسم الصدى المتردد مدى سرعة تلاشي ذيله. ومع تفعيل تقليل الحركة، تتحدّث القراءات ولا ينساب شيء.","docs.be3ae6fa5bfb":"كل واجهة تُقاس من صوت الجهاز نفسه، ولا تُرسم أبدًا من إعداداته، ورسمها لا يكلّف الصوت شيئًا يمكن قياسه. ويظهر حتى ستة عشر منها حيًّا في وقت واحد؛ وما زاد على ذلك تُرسم بطاقته ساكنة وتقول ذلك. ولا يرسم التصدير أو الدمج (bounce) أو التجميد في أي بطاقة أبدًا.","docs.6a4181898f49":"سلاسل الوصفات","docs.3c86c1f5f519":"تُنسخ إعدادات الجهاز سطرًا واحدًا يمكنك لصقه في دردشة. ويُحفظ رف كامل — الأجهزة المرفقة والإضافات المستضافة معًا — ملفًّا يُستدعى على أي مسار في خطوة تراجع واحدة، حتى على جهاز تنقصه إحدى إضافاته.","docs.4effad823b04":"اقتراح","docs.a17ac75033a7":"لكل بطاقة من بطاقات المؤثرات الخاصة بـ Oscillate زر <strong>اقتراح</strong>. فهو يعزف المسار وحده حتى تلك البطاقة، خارج الزمن الحقيقي، لمدة تصل إلى 90 ثانية من حيث يبدأ صوت الجزء أول مرة؛ ويستنتج ماهية الجزء من اسم المسار؛ ويقترح ضبطًا، مع أسبابه في جمل: المعادل يسوّي أسوأ رنين، والضاغط يأخذ الخفض الذي يناسب الجزء، ومزيل الصفير يستقر على الصفير الذي قاسه، والتأخير يقع على شبكة الإيقاع. ولا يتغير شيء حتى تضغط <strong>تطبيق</strong>، الذي يضبط كل عنصر تحكم يسمّيه في خطوة تراجع واحدة. والجهاز الذي عمله مسألة ذوق يقول ذلك ولا يقترح شيئًا، والإضافة المستضافة ليس فيها «اقتراح».","docs.d41fd773be92":"يفعل زر <strong>اقتراح لمقابض القناة</strong>، أعلى رف المسار المحدد، الشيء نفسه لمقبضي المنخفض والمرتفع وللضاغط في الشريط. إنه حساب على ما قيس، لا نموذج، فيحصل المزيج نفسه على الاقتراح نفسه في كل مرة. ولضبط المزيج كله دفعة واحدة، انظر <a href=\"#final-check\">امزجه من أجلي</a>.","docs.30b64302573c":"Oscillate Doubler","docs.956a79b573ac":"يضاعف جزءًا كأنه غُنّي أو عُزف مرة أخرى: <strong>الأصوات</strong> حتى أربعة، كلٌّ منها مُزاح النغمة حتى 30 سنتًا (<strong>إزاحة النغمة</strong>)، ومؤخَّر من 5 إلى 40 ms (<strong>التأخير</strong>)، وموزَّع عبر الحقل الستيريو (<strong>الانتشار</strong>)، ويُضبط خلطها بـ<strong>المزج</strong>. وتنجرف الأصوات انطلاقًا من بذرة المشروع و<strong>البذرة</strong> الخاصة بالجهاز، فيخرج التصدير متطابقًا في كل مرة، ويفترق مضاعِفان في أغنية واحدة كلٌّ في اتجاه. وإعداداته المسبقة هي Tape Double وWide Double وStack وSubtle.","docs.5841824db95a":"Oscillate Ducker","docs.a5d084563a9d":"يخفض مسارًا بينما يعزف مسار آخر، فيفسح الباص المكان لطبلة الكيك. اختر المسار الآخر في <strong>‏Sidechain من</strong> على البطاقة: يُسمع بعد أجهزة ذلك المسار وقبل منزلقه، فحتى الكيك المكتومة تحرّكه، ويبقى الاثنان متزامنين مهما أضافت أجهزة أيٍّ من المسارين من تأخير. ويشكّله <strong>العمق</strong> و<strong>العتبة</strong> و<strong>زمن الهجوم</strong> و<strong>زمن التحرر</strong> و<strong>الإمساك</strong> و<strong>مرشح تمرير عالٍ للسلسلة الجانبية</strong>، وترسم واجهته ما يقتطعه. وإعداداته المسبقة هي Kick Pump وGentle Duck وVoice Over.","docs.cf62c3a32ff8":"يبقى المفتاح محفوظًا رغم إعادة التسمية والحفظ، وفي الغرفة. وإذا حُذف مسار المفتاح، قالت البطاقة ذلك ومرّ الصوت دون مساس؛ وتراجعٌ واحد يعيد المفتاح.","docs.233e3485af27":"Oscillate Kick Carve","docs.75b2088ada20":"يخفض الباص في شريحة المنطقة المنخفضة التي يصدح فيها الكيك فقط، وفقط ما دام يرنّ هناك، فلا تتحرك توافقيات الباص التي فوقها أبدًا. اختر الكيك في <strong>‏Sidechain من</strong> على البطاقة. و<strong>الوضع</strong> إما <em>Spectrum</em>، أي 24 نطاقًا عبر المنطقة المنخفضة، أو <em>Bell</em>، أي قطع واحد يتبع طبقة الكيك نفسها، والنطاقات حين لا تكون للكيك طبقة. ويشكّله <strong>العمق</strong> (حتى 24 dB) و<strong>الضبط</strong> و<strong>التتبّع</strong> و<strong>الإمساك</strong> و<strong>عرض Q</strong> و<strong>أدنى المدى</strong> و<strong>أقصى المدى</strong> (من 20 إلى 400 Hz) و<strong>الوسط فقط</strong> وحتى 5 ms من <strong>الاستباق</strong>، ويبقى باقي المزيج متزامنًا مع الاستباق. وعند عمق صفر يمرّ الباص كما هو بتًّا ببت. وثمانية إعدادات مسبقة، من Sub Pocket إلى Wide Bass Safe.","docs.7932b1559e62":"Oscillate Bass Unison","docs.a56a284bec6e":"يحوّل موجة منشارية أو 808 إلى باص reese متحرّك: من صوتين إلى ثمانية أصوات، مُزاحة الضبط حتى 35 سنتًا، تدور عبر 4 إلى 12 من <strong>المراحل</strong> من نوع all-pass، و<strong>المعدل</strong> من 0.02 إلى 10 Hz أو متزامن مع الإيقاع، منتشرةً على اتساع، بينما يبقى كل ما تحت <strong>نقطة الفصل</strong> (من 40 إلى 300 Hz) أحاديًّا ودون مساس، فيسمعه كله مكبّر الترددات المنخفضة (sub) الأحادي في النادي وسماعة الهاتف الوحيدة. ويصل <strong>العرض</strong> إلى 150 %، وتضمن <strong>حماية الأحادي</strong>، المفعّلة في البداية، ألا يفقد الصوت عند جمعه إلى الأحادي أكثر من 3 dB. ويُبلغ عن تأخير نحو 15 ms. وثمانية إعدادات مسبقة، من Classic Reese إلى Extreme Phase.","docs.2b8b78b8fed7":"Oscillate Groove وأحاسيسه الأربعون","docs.ec707d526419":"جهاز نوتات ينقل الطبول التي تُعزف إليه إلى إحساس مسمّى. و<strong>الإحساس A</strong> واحد من أربعين، من <em>Grid Tight</em> و<em>Laid-Back Backbeat</em> إلى <em>Loose Drummer</em>، ويمكن مزجه بإحساس ثانٍ؛ ويصل <strong>العمق</strong> إلى 200 %، ولكل مسار من مساراته الاثني عشر، من الكيك إلى الإيقاعيات، إزاحته وعمقه الخاصان، بالاستيفاء أو بالالتقاط. وحين يكون أولًا على المسار، يقرأ نوتات المقطع مسبقًا، فلا تحتاج النوتة المقدَّمة إلى أي تأخير مضاف؛ أما المفتاح المعزوف حيًّا، أو Groove يأتي لاحقًا في السلسلة، فينتظر بمقدار <strong>الاستباق</strong> لديه، حتى 80 ms.","docs.d5fdbcc59e0f":"تحمّل <strong>المكتبة</strong> إحساسًا، ويحفظ <strong>احفظ كإحساس</strong> إحساسك الخاص، ويكتب <strong>اطبع المقطع المفتوح بهذا الإحساس</strong> المقطعَ المفتوح في المحرّر، بتوقيت معاد، مقطعَ MIDI جديدًا بعده مباشرة. وقد كُتبت الأحاسيس الأربعون يدويًا من أجل Oscillate؛ ولم يؤخذ أيٌّ منها من تسجيل أو من منتج آخر.","docs.0fa45a3c7e03":"و<strong>Oscillate Groove Kit</strong> شريكه: اثنا عشر طبلًا مُركَّبًا صوتيًا على نوتات General MIDI، وصنج هاي-هات مغلق يخنق المفتوح، و<strong>النمط</strong> (<em>Backbeat</em> أو <em>Half-Time</em> أو <em>Four on the Floor</em> أو <em>Boom Bap</em> أو <em>Shuffle</em> أو <em>Two-Step</em> أو <em>Sixteenths</em>) ليُعزف بإحساس ما.","docs.ba87b5cbd2e5":"Oscillate Chord Trigger","docs.e034e184c3ec":"مفتاح واحد يعزف تآلفًا كاملًا مع باصه، بقيادة أصوات تجعله يتحرك بأقل قدر ممكن. وتُقسم لوحة المفاتيح ثلاثة أقسام: الباص تحت <strong>تقسيم الباص</strong>، وأدوات التحكم من <strong>تقسيم التحكم</strong> فما فوق (المفاتيح الخمسة الأولى تختار القلب، والسادس يُمسك، والسابع يُفلت كل شيء)، والتآلفات بينهما، مرتّبةً بحسب <strong>خريطة الأوتار</strong>: <em>Chromatic</em> أو <em>Major Key</em> أو <em>Minor Key</em>. وسبعة وعشرون شكلًا للتآلفات وثمانية من صنعك، تُبنى على شبكة من ثلاثة أوكتافات؛ وخربشة (strum) حتى 60 ms؛ واثنا عشر إعدادًا مسبقًا.","docs.9184c71643db":"وسائده بقياس 64 px، أو 96 مع <strong>أهداف أكبر</strong>، ويعزفها صف الأرقام. ويتيح <strong>المسح بالمُبدِّل</strong> العزف عليه بخيار <em>مُبدِّل واحد</em>، الذي يتقدّم من تلقاء نفسه كل 0.5 إلى 5 ثوانٍ، أو بخيار <em>مُبدِّلان</em>، كلٌّ منهما مفتاح أو نوتة MIDI أو متحكّم تعلّمه إياه. وتعزف الوسائد المسار المجهَّز، وتدوم إعدادات المسح طوال الجلسة.","docs.6e6483d51004":"Oscillate Glide","docs.841c74d1890b":"انزلاقات لخطوط 808. يختار <strong>الانزلاق عند</strong> أي النوتات تنزلق إلى التالية: <em>Every Note</em> أو <em>Every Offbeat Note</em> أو <em>Every Nth Note</em> أو <em>Notes Shorter Than</em> أو <em>Leaps Of</em> أو <em>Marked In The Lane</em> أو <em>Never</em>، على <strong>زمن الانزلاق</strong> من 5 ms إلى 2 s أو متزامنًا مع الإيقاع، وعلى أحد ستة منحنيات. وتضم واجهته مسارًا من خطوات «انزلاق» و«إمساك» و«تخطٍّ» يصل طوله إلى أربع مازورات، وهو الذي يحكم ما دام «الانزلاق عند» على <em>Marked In The Lane</em>. ويثني بخطوات من 14 بت، ويُبلغ إضافاتك بـ <strong>مدى الانحناء</strong> لديه (من 1 إلى 48 نصف درجة؛ ولا تحتاج آلات Oscillate نفسها إليه)، ويقيّد الانزلاق الذي يتجاوزه أو يقسمه. ويمكن أن يغذّيه باص Chord Trigger. واثنا عشر إعدادًا مسبقًا.","docs.be0210423b57":"Oscillate Siren","docs.d8547fe03218":"آلة لصفارات الشرطة النائحة، وصفارات الإنذار من الغارات الجوية، والصفارات ثنائية النغمة، وصفارات الدَّب، على دوّار يدور ويصنع <strong>التباطؤ</strong> فيه، من 0.2 إلى 12 ثانية، الصعودَ والهبوط. واثنا عشر نموذجًا في <strong>الدوّار</strong>، وغلاف للطبقة، وانسياب، ومذبذب منخفض التردد (LFO) من 0.01 إلى 40 Hz، و<em>Mono</em> و<em>Legato</em> و<em>Poly 8</em> و<em>Latch</em>. وتضم واجهته <strong>الأصوات</strong> (صفارات، ودَب، وضربات ريف، وطلقات ليزر، ونوابض: اثنان وستون إعدادًا مسبقًا)، و<strong>نمط الإنذار</strong> من 16 إلى 32 خطوة يُعزف ما دام مفتاح مضغوطًا، وتسلسل تعديل من 16 خطوة، ومصفوفة تعديل من اثنتي عشرة خانة، مع غلافين وثلاثة مذبذبات منخفضة التردد. وتعمل مذبذباته بمعدل 4× افتراضيًا، حيث يكون التشوّه الطيفي (aliasing) فيها دون −80 dB.","docs.f2c72a5ac00c":"Oscillate Dispersion Delay","docs.7c0d75bc2840":"تنشر حتى 512 من <strong>المراحل</strong> من نوع all-pass الضربةَ عبر تردداتها فتحوّلها إلى طلقة ليزر: يمتد التأخير على خط، أو لكل أوكتاف، أو على هيئة جرس بين <strong>التردد المنخفضات</strong> و<strong>التردد المرتفعات</strong>، فتتأخر المنخفضات أو المرتفعات، مع تغذية راجعة محدودة داخل الحلقة، وجانب أيمن مُزاح عن الأيسر بمقدار <strong>إزاحة الاستريو</strong>. ثم يأتي صدى شريطي من 1 ms إلى 2 s، مع <strong>تغذية الصدى الراجعة</strong> والتموّج والارتجاف (wow وflutter) و<strong>فقد الترددات العالية</strong> و<strong>التشبع</strong> و<strong>نتوء الرأس</strong>. وترسم واجهته التأخير الذي تصنعه المراحل فعلًا، ترددًا بترددٍ (متصلًا لليسار، ومتقطعًا لليمين، والأعلى للأكثر تأخرًا)، والمجال الاستريو. ولا يضيف أي تأخير في المعالجة (latency).","docs.046ff4ef99fb":"Oscillate Grain Layers","docs.5c26c1dc2d28":"حتى ثماني عيّنات من عيّناتك مكدّسة كطبقات صخرية، يقرؤها مثقاب يختار عمقُه ما يصدح. وتجمع واجهته <strong>العمود</strong> و<strong>الجيولوجيا</strong> (التعرية تُبلي العمود، والطي يثنيه، والصدع يشقّه) و<strong>الحبيبات</strong> و<strong>العزف</strong> و<strong>التعبير</strong>، ثم أربعة مذبذبات منخفضة التردد (LFO) وغلافين ومصفوفة تعديل من ست عشرة خانة، على ستة عشر صوتًا، ببذرة ثابتة فيخرج التصيير متطابقًا في كل مرة. وتحرّك قيمة Mod X للنوتة المثقاب، وتذهب قيمة Mod Y إلى حيث يقول <strong>الضغط إلى</strong>. واثنا عشر إعدادًا مسبقًا من المصنع، طبقاتها مصنوعة بالشيفرة.","docs.a8acd4c1d4ce":"ضع ملفًا على طبقة، أو الملف الذي استمعت إليه في مستعرض الملفات. ويحمل <strong>احتفظ بصوت هذه الطبقة داخل المشروع</strong> الصوتَ في ملف المشروع، ويبحث <strong>ابحث عن هذا الملف مجددًا في مجلداتك</strong> عن ملف نُقل من مكانه. وتُعرض الذاكرة التي تأخذها طبقاته، حتى 1 GiB. والجودة <em>Draft</em> أو <em>Normal</em> أو <em>High</em>، و<strong>حد الحبيبات</strong> من 16 إلى 64 حبيبة، و48 في البداية. ويُرسم مقطعه العرضي حيًّا على Windows؛ ومع تفعيل تقليل الحركة، وعلى macOS وLinux، يبقى ثابتًا.","docs.de620d7ae16d":"Oscillate Storm","docs.874e219ea058":"مطر ورعد ورياح مصنوعة من فيزيائها، فلا شيء يتكرر ولا تُستعمل أي عيّنة. يسقط المطر على ثمانية أسطح، من سقف من الصفيح ونافذة إلى بُقعة ماء وبِركة، ويصل الرعد متأخرًا بقدر بُعد برقه. وتعرض خريطة العاصفة <strong>مناطق المطر</strong>، بالأمتار، حيث تضع المستمع وما يصل إلى ثماني مناطق، أو <strong>البرق</strong>، بالكيلومترات، حيث يأخذ <strong>ارسم برقًا</strong> نقرة لكل نقطة ثم <kbd>Enter</kbd>، حتى أربعة بروق، ويعيد <strong>تفرعات جديدة</strong> رسم تفرعاتها. ومقبضا ماكرو، المطر والعاصفة.","docs.6ca928351fc7":"المفتاح عند <strong>التقسيم</strong> أو فوقه يشغّل الطقس ويُسقط قطرة بطبقته، مقيّدةً بـ <strong>الأساس</strong> و<strong>المقام</strong> و<strong>الالتقاط إلى المقام</strong>؛ والمفتاح تحته يُطلق برقًا، ونوتته تختار أيًّا من البروق الأربعة. وتجلب عجلة التعديل العاصفة، وCC 11 المطر، وCC 74 الرياح، وتقرّب عجلة ثني النغمة المستمع أو تبعده. و<strong>الخرج</strong> هو العاصفة كاملة أو المطر أو الرعد أو الرياح؛ واثنان وستون إعدادًا مسبقًا للمطر والرعد والعواصف الكاملة؛ والجودة <em>Draft</em> أو <em>Normal</em> أو <em>Ultra</em>. ويكتب <strong>صيّر الطبقات الثلاث</strong> المطر والرعد والرياح في ثلاثة ملفات WAV يساوي مجموعها المسار، كلٌّ منها مسمّى باسم المسار وطبقته، في المجلد الذي تحدده <strong>الإعدادات ▸ التصدير</strong> (أو في مجلد تختاره إن لم تحدد مجلدًا)، مكان أي ملف بالاسم نفسه. وهو ستيريو فقط.","docs.ee618caedce6":"Oscillate Sub","docs.035d8010d670":"يضع جهيرًا عميقًا (sub-bass) تحت ما تعزفه. يتبع <strong>جهير 1</strong> طبقة ما يدخل إليه ويعزف تحتها موجة جيبية، تُعرض طبقتها بالهرتز أو اسمَ نوتة، وله <strong>زمن الهجوم</strong> و<strong>التلاشي</strong> والانزلاق الخاصة به؛ وتُبقيه <strong>محاذاة الطور</strong> في طور المصدر نفسه، فلا يلغي أحدهما الآخر أبدًا، وإن لم تكن هناك طبقة يتبعها صمت. ويعزف <strong>وضع جهير 1</strong> على <em>Fixed</em> بدلًا من ذلك طبقة واحدة تحددها أنت. ويأخذ <strong>جهير 2</strong> نطاق المصدر المحيط بـ<strong>تردد جهير 2</strong> (و<strong>عرض جهير 2</strong> هو مدى اتساع ما يصغي إليه) فيخفضه أوكتافًا أو اثنين، أو بأنصاف الدرجات عبر <strong>نقل النغمة</strong>؛ ويُبقي <strong>التنعيم</strong> عند 0 هجمة الكيك، ويعزف أحاديًّا أو <strong>ستيريو</strong>.","docs.77fea442e4ad":"<strong>الجودة</strong> إما <em>Best</em> أو <em>Balanced</em> أو <em>Light</em>: يُبلغ Best وBalanced عن تأخيرهما، أما Light فلا تأخير له. وتضيف <strong>النغمة</strong> توافقيات كي تبقى المنطقة المنخفضة مسموعة على الهاتف، و<strong>الطابع</strong> فيها <em>Tube</em> أو <em>Tape</em> أو <em>Transistor</em> أو <em>Rectifier</em>، مع إفراط في العينات بأربعة أضعاف حين يكون <strong>الإفراط في العينات</strong> مفعّلًا. ويسوّي <strong>الثبات</strong> خط باص يقفز مستواه، نطاقًا بنطاق تحت 150 Hz، ويزيل <strong>كتم الترددات المنخفضة</strong> المنطقة المنخفضة الخاصة بالمصدر تحت <strong>نقطة الفصل</strong>. وتعرض الواجهة الطبقة التي يسمعها، ومستوى كل جهير، ومحلّلًا للمنطقة المنخفضة بثلاث درجات من الدقة. وخمسون إعدادًا مسبقًا.","docs.dd33436797ff":"Oscillate Width","docs.89b76ea18568":"يوسّع ما تعزفه دون أن يُرقّقه في الأحادي أبدًا: فما يضيفه إلى جانب يأخذه من الآخر، فيبقى المجموع الأحادي هو ما دخل تمامًا. ثلاثة نطاقات، تفصل بينها <strong>نقطة الفصل 1</strong> و<strong>نقطة الفصل 2</strong> (400 Hz و4 kHz في البداية)، ويُوسَّع كلٌّ منها من 0 إلى 200 % بـ<strong>عرض المنخفض</strong> و<strong>عرض المتوسط</strong> و<strong>عرض العالي</strong>؛ وتحدد <strong>القوة</strong> مدى إبعاد الجانبين أحدهما عن الآخر. أفرِد نطاقًا لتسمعه وحده. وتعزف <strong>المراقبة</strong> نتيجة <em>Stereo</em>، أو ما أُضيف فقط (<em>Side</em>)، أو الوسط، لتثبت أنه لم يتحرك أبدًا (<em>Mid</em>). وتُبقي <strong>مطابقة المستوى</strong> المصدر الأحادي الموسَّع بالعلوّ الذي كان عليه، ويُدخل <strong>مفعّل</strong> الجهاز ويُخرجه دون نقرة، ويعرض مقياس ترابط ومقياس زوايا (goniometer) المجال الستيريو. ولا تأخير له. وخمسون إعدادًا مسبقًا.","docs.b5736b2402bd":"زوج الترددات المنخفضة","docs.1232bc16caa2":"في مستعرض الملفات، يضع زر <strong>إدراج الزوج</strong>، الموجود بجانب كلٍّ من الجهازين، Oscillate Sub ثم Oscillate Width على المسار المحدد، مرتبطَين. ويمكن أيضًا ربط Width بـ Sub على مسار آخر، من قائمة <strong>‏Sub المرتبط</strong> في واجهته. وما داما مرتبطين يتشاركان نقطة فصل واحدة: حرّكها في أيٍّ من الواجهتين فتتحرك في كلتيهما. ولا يوسّع Width ما تحتها أبدًا، فيبقى الجهير العميق أحاديًّا؛ وتظلّل واجهة Width النطاق الذي يصنعه Sub، وتُعلِّم واجهة Sub نقطة فصل Width. واثنا عشر إعدادًا مسبقًا للزوج تضبط الجهازين معًا. اختر <em>غير مرتبط</em> لتدع كلًّا منهما يمضي في طريقه.","docs.afc35db2da83":"أجهزة تقرأ التوزيع","docs.6a537022e329":"ستة منها تفعل شيئًا لا تستطيعه أي إضافة، لأن الإضافة لا ترى التوزيع الذي هي داخله. ضاغط يمسك اللازمة قبل وصولها؛ وبوابة تنفتح لضربة قبل حدوثها بمازورتين؛ وتأخير صدوي يفرغ <em>نحو</em> خط المازورة فينتهي ذيله بدل أن يُقطع. قراءة مازورتين من الصوت مسبقًا تأخير يدفع ثمنه الجميع؛ أما قراءة البنية فلا تكلّف شيئًا، وكلها تُعلن تأخيرًا صفريًا.","docs.70640caedc3c":"Drum Machine","docs.eb1ebac609ad":"ست عشرة وسادة، مرتّبة كوحدة تحكم بالوسادات والوسادة 1 في أسفل اليسار، تعزف واحدًا من أربعة أطقم مدمجة: <em>Sub</em> و<em>Floor</em> و<em>Neon</em> و<em>Wire</em>. تُختار كل ضربة من ثلاث طبقات بحسب قوة عزفك، وتتناوب بين لقطتين، فلا تكرّر الدحرجة نفسها تمامًا أبدًا. والمشاريع التي استعملت Pad Grid تُفتح على Drum Machine مع الحفاظ على مستوياتها ومجموعات الخنق فيها.","docs.a713154a6b75":"حدّد وسادة لتشكّل صوتها: دوزانها، وانزلاقًا في حدّة النغمة، وغلافًا، والبان، ومرشّحًا، ومجموعة خنق، وحتى أربع طبقات في <strong>الطبقات</strong>، يمكنك أن تطبّق على كل منها <strong>عكس</strong> أو <strong>تسوية المستوى</strong>. وتتناوب الطبقات <em>حسب قوة الضغط</em> أو <em>بالتناوب</em> (round robin). و<strong>أعد إلى صوت الطقم</strong> يعيد الوسادة إلى أصلها.","docs.2d67d5bec326":"بجانب الوسادات، تسرد <strong>الضربات المفردة</strong> أصوات الطقم نفسه و<strong>حزم الإيقاع</strong> الإحدى عشرة، مصنّفة حسب النوع. انقر على أحدها لتسمعه، ثم ضعه على الوسادة المحددة أو أضفه إليها طبقةً. ويضع <strong>أضف عيّنات…</strong> ملفاتك الخاصة على الوسادات.","docs.b36ebe696a5d":"Guitar Amp وغيتارات الروك","docs.a86f689c0403":"<strong>Guitar Amp</strong> مضخّم وكابينة 4×12 بطابعين صوتيين، <em>Crunch</em> و<em>High Gain</em>، وبمُعدِّلَي مستوى <strong>الدخل</strong> و<strong>الخرج</strong> حتى 24 dB صعودًا أو هبوطًا. ويوضع على أي مسار.","docs.187394fb7629":"يضم رف <strong>السلاسل</strong> في مستعرض الملفات غيتارَي روك جاهزين للعزف، <em>Overdriven Guitar</em> و<em>Distortion Guitar</em>: Electric Guitar عبر Guitar Amp، ثم صدى وغرفة صغيرة، ومستواهما مضبوط ليجلسا حيث كان الغيتار الجاف. يضع <strong>تحميل</strong> أحدهما على مسار MIDI المحدد بدل أجهزته، في خطوة تراجع واحدة.","docs.d9cbf26377f3":"Granular Wash","docs.6f3189efd73f":"مقبض واحد، <strong>المقدار</strong>، يحوّل الصوت إلى سحابة من الحبيبات تحافظ على النوتة وتضيف الأوكتاف الذي فوقها والذي تحتها، مع صدى يمدّها لثوانٍ. يبدأ عند 50 %؛ وعند 100 % تسمع الغلالة الصوتية وحدها.","docs.4af1f7550444":"أغلفة على كل آلة","docs.c6f6907e5d27":"لكل آلة في المكتبة أربعة أغلفة يمكنك تفعيلها: <strong>مستوى الصوت</strong> و<strong>المرشّح</strong> و<strong>حدّة النغمة</strong> و<strong>التوزيع</strong>. يبدأ كل منها من شكل — <em>Init</em> أو <em>نقر</em> أو <em>بساط</em> أو <em>تصاعد</em> أو <em>بوابة</em> أو <em>ارتداد</em> — أو ترسم شكلك الخاص على منحناه: اسحب نقطة، أو انقر نقرًا مزدوجًا لتضيف نقطة أو تزيلها، حتى 16 نقطة من صنعك.","docs.8acbbdd5d1ca":"يمكن للغلاف أن يثبت عند نقطة ما دام المفتاح مضغوطًا ويعود منها في حلقة، وأن يتقيّد بالإيقاع، وأن يتبع الشدة والمفتاح المعزوف، وأن يبدأ من جديد مع كل مازورة، وأن يتحوّل تدريجيًا بين شكليه A وB. والشكل المرسوم يُحفظ في المشروع وفي ملفات الرف، لكنه لا يُحفظ في سطر إعدادات ملصوق. ومع إطفاء كل الأغلفة، يكون صوت الآلة تمامًا كما كان.","docs.0d2dfd82f8ee":"<kbd>Ctrl</kbd>+<kbd>1</kbd>. شاشة رئيسية من الأماكن — <em>الآلات</em>، <em>مؤثرات صوتية</em>، <em>مؤثرات MIDI</em>، <em>الإضافات</em> — تنقر لتدخلها، وزر <strong>اختر مجلدًا</strong>، والمجلدات التي أضفتها مسرودة بأسمائها.","docs.0f220b622119":"يبحث المرشّح فيما <em>هو</em> الجهاز وفي اسمه أيضًا، فكتابة <code>valve</code> تجد <code>Tube Saturator</code> و<code>Amp Head</code>.","docs.00254cbab0ed":"المعاينة","docs.04348aea2702":"انقر على جهاز فتسمع عرضه الخاص — نوتة مختارة وطول مقيس لكل آلة — مع موجة ورأس تشغيل وتكرار، و<kbd>←</kbd>/<kbd>→</kbd> لتشغيله إلى الخلف أو إلى الأمام. وجّهه إلى مجلد من مجلداتك فيعاين عيّناتك بالطريقة نفسها. خمس من الآلات مُعايِنات عيّنات (samplers) وتقول ذلك بدل أن تعزف صمتًا: فهي تنتظر ملفًّا من ملفاتك، تعطيها إياه عبر <strong>أضف عيّنات…</strong> على الجهاز، أو عبر <strong>اختر ملفًا لهذه الطبقة…</strong> في Oscillate Grain Layers.","docs.008365bb240d":"الآلات","docs.3e31f02db58e":"الآلات الـ 1648 كلها على رفَّي <em>الآلات</em> و<em>Factory Expansion</em>، في مجلدات حسب العائلة، والقائمة تتمرّر بسلاسة مهما طالت. انقر على صف، أو تنقّل في القائمة بمفاتيح الأسهم، لتسمعه؛ وإبقاء المؤشر على صف يعزفه أيضًا. وإذا كان مسار MIDI محددًا، فما تسمعه هو نوتات ذلك المسار نفسه بدءًا من رأس التشغيل، تُعزف عبر الآلة التي تقف عليها. و<strong>إضافة</strong> تضع الآلة على المسار المحدد.","docs.018dc52d1917":"في قائمة الآلات وفي <strong>أصواتي</strong>، يتنقّل <kbd>↑</kbd> و<kbd>↓</kbd> بين الصفوف ويعزفان كل صف منها، وينقل <kbd>←</kbd> و<kbd>→</kbd> بين أزرار الصف؛ وعلى اسم الآلة يظلّان يعزفانها إلى الخلف وإلى الأمام. ويقفز <kbd>Home</kbd> و<kbd>End</kbd> و<kbd>Ctrl</kbd>+<kbd>Home</kbd> و<kbd>Ctrl</kbd>+<kbd>End</kbd> إلى الأطراف، وكل قائمة محطة واحدة لـ <kbd>Tab</kbd>. ومرشّحا العائلة والدور قائمتان منسدلتان، بمربع اختيار لكل خيار.","docs.c45ed4856c9f":"النجمة على الصف تضع الآلة في <strong>المميّزة بنجمة</strong>. وفي <strong>أصواتي</strong>، يحفظ <strong>احفظ الصوت</strong> الآلة التي على مسار MIDI المحدد، بإعداداتها كما هي الآن، تحت اسم ومجلد من اختيارك، جاهزةً لتضيفها بـ <strong>إضافة</strong> إلى أي مسار.","docs.0a1f4adb6f56":"PACK","docs.c6b2b316b1be":"لكل صف آلة زر PACK، يضيف ضربة مفردة منها إلى <strong>حزمة الضربات المفردة</strong> تحت المستعرض، حتى 25. اعزف كل واحدة، أو استبدلها بلقطة أخرى من الآلة نفسها، أو أخرجها. ويكتب <strong>تصدير</strong> كل ضربة مفردة في الحزمة ملفَّ WAV في مجلد تختاره، ولا يكتب أبدًا فوق ملف موجود هناك.","docs.5a8b10fcbead":"سحب ملف إلى الداخل","docs.b40583c5f830":"اسحب ملف <code>.wav</code> أو <code>.mid</code> مباشرة من مستكشف Windows أو Finder إلى مازورة في التوزيع فيقع <strong>حيث أفلتّه</strong>. يذهب MIDI إلى مسارات MIDI، والصوت إلى المسارات الصوتية، والنوع الخاطئ يُرفض مع ذكر السبب بدل أن يُعطى مسارًا خاصًّا به.","docs.5d740606fafb":"الملف المُفلَت <strong>يُضمّ إلى المشروع</strong> ولا يُشار إليه فقط. أفلِت شيئًا من مجلد مؤقت واحذف الأصل، فيبقى المقطع يعمل.","docs.b7ba15ad34d4":"البحث عن المتشابه","docs.6086461c1507":"يفتحه <strong>إظهار البحث عن المتشابه</strong> في مستعرض الملفات. اختر <strong>المرجع</strong>، صوتًا أو حلقة MIDI من المجلد الذي أنت فيه، واضغط <strong>ابحث عن المتشابه</strong>: يُرتَّب كل ملف مشابه في مجلدات مستعرض الملفات وحزم الإيقاع المرفقة بدرجة من 100، حتى 200 منها، كلٌّ منها بوصف <em>نسخة مطابقة</em> أو <em>الصوت نفسه</em> أو <em>صوت مشابه</em> أو <em>مغيَّر الطبقة أو ممدَّد</em> أو <em>الإيقاع نفسه</em>، مع سببه بالكلمات: الصوت نفسه في ملف آخر، أو تغيير في المستوى، أو قصّ، أو نسخة أحادية، أو معدل عيّنات آخر، أو تغيير في الطبقة أو تمديد، أو تغيّر في النبرة، أو الإيقاع نفسه مُزاحًا أو بضعف السرعة. ويعزف <strong>استماع</strong> <em>A: المرجع</em> أو <em>B: الملف المشابه</em> أو <em>A+B معًا</em>، متحاذيين في التوقيت.","docs.d601313e7e44":"في أول مرة يُفتح فيها خلال الجلسة، يقرأ المجلدات في الخلفية، وبعد ذلك لا يقرأ إلا ما هو جديد أو معدّل؛ ويقرؤها <strong>أعد قراءة المجلدات</strong> الآن، ويوقف <strong>إيقاف القراءة</strong> القراءة. ولا يقرأ إلا ملفات WAV وMIDI. إنه قياس، بلا نموذج: يُعثر على تغييرات الطبقة حتى ثلاثة أنصاف درجة وعلى التمديد حتى 12 %، وما بعد ذلك لا يَعِد بشيء. وما يحتفظ به فهرسه مذكور في <a href=\"#privacy\">الخصوصية والشبكة</a>.","docs.903a1771c064":"مطابقة الركلة والباص","docs.385e4ddb76c4":"في مجلد فيه صوتان أو أكثر، تظهر <strong>مطابقة الركلة والباص</strong> في مستعرض الملفات. اختر <strong>الركلة</strong> واضغط <strong>رتّب أصوات الباص</strong>: يُقرأ كل ملف WAV آخر في المجلد على أنه باص وتُحسب له <strong>الدرجة</strong> من 100، بحسب <strong>الفاصل</strong>، أي مدى جلوس طبقة الركلة على أساس الباص أو خامسته أو أوكتافه؛ و<strong>الخشونة</strong>، أي مقدار تضارب الصوتين أحدهما مع الآخر؛ و<strong>التداخل</strong>، أي المنطقة المنخفضة التي يتقاسمانها؛ و<strong>توافق التلاشي</strong>، أي هل يختفي ذيل الركلة قبل أن يستقر الباص.","docs.f58b0fef366e":"يعطي <strong>إعادة الضبط</strong> عدد السنتات التي تضع الركلة على أساس الباص أو خامسته أو أوكتافه، ويعزف <strong>استمع</strong> مازورة من أربع ركلات، بعد إعادة ضبطها، فوق الباص بسرعة 120 BPM. والركلة التي ليس لها جسم نغمي تقول ذلك ولا تقترح إعادة ضبط، والملف الذي تتعذّر قراءته يُسرد في الآخر. وتقرأ المطابقة أول أربع ثوانٍ من كل ملف، حتى 2000 صوت باص، ولا تحتفظ بشيء. إنها قياس، بلا نموذج.","docs.b24ba56ae294":"<kbd>Ctrl</kbd>+<kbd>5</kbd>. اضغط <strong>إنشاء رمز غرفة</strong>، وانتظر الرمز، وأرسله إلى من تعمل معه. يلصقه هو ويرسل إليك رمزه، فتلصقه أنت في <strong>اسمح له بالدخول</strong>، وتصبحان في الجلسة نفسها.","docs.shot.room":"لوحة الغرفة: زر «إنشاء رمز غرفة» داخل إطار أحمر يحمل الرقم 1، وزر «اسمح له بالدخول» — حيث تلصق الرمز الذي أرسله إليك أحدهم — داخل إطار يحمل الرقم 2.","docs.0548c5c7cd35":"1 يُنشئ رمزك. و2 هو مكان رمزه. ⚠ ما إن يوجد رمز حتى تصبح الجملة التي بجانبه هي الأهم: عامله كأنه كلمة مرور، لأنه يحتوي على العنوان العام لحاسوبك.","docs.41a1acbef296":"ما تحصل عليه","docs.4e795a73e99f":"قائمة حاضرين، لكل واحد لونه، ومؤشراتهم تتحرك على توزيعك.","docs.e2168f0fe102":"دردشة. تبقى ما بقيت الغرفة، ولا يُكتب منها شيء على القرص.","docs.83623938eb6f":"صوت ومربعات كاميرا ومشاركة شاشة — كلها مطفأة حتى تضغط شيئًا.","docs.5161add1f5a4":"<strong>تراجعك لك أنت.</strong> يسترجع <kbd>Ctrl</kbd>+<kbd>Z</kbd> آخر تغيير أجريته أنت ولا يسترجع تغيير غيرك أبدًا، حتى وتعديلاتهم تصل.","docs.ab67452f2acf":"<strong>التسليم</strong> — سلّم مسارًا واحدًا لشخص واستعده بمفتاح واحد. وما دام في يده فهو الكاتب الوحيد عليه، حتى بالنسبة إليك.","docs.6a62a97df77a":"ما لا ينتقل أبدًا","docs.c61d0ae17869":"<strong>اللقطة التي سجّلتها تنتقل. والعيّنة التي اشتريتها لا تنتقل أبدًا.</strong> حين ينضم شخص إلى جلسة تستعمل حزمة عيّنات لا يملكها، يحصل على قائمة اسمها <em>العيّنات التي تحتاجها</em> مع السبب: Oscillate لا يرسل العيّنات بين الحواسيب أبدًا. النسخة المطابقة بايتًا ببايت هي ما تنتجه القرصنة، وهذا المنتج لن يكون طريقًا إليها.","docs.0cce48095d62":"حين لا يتصل","docs.7a85d27236d6":"نحو واحد من كل عشرة اتصالات لن ينعقد، ويسمّي Oscillate أيًّا من الأسباب التسعة كان — من <em>لم يُعثر على شبكة</em> إلى <em>شبكتك تعطي كل خادم عنوانًا مختلفًا</em>. هذا الأخير يحتاج إلى مُرحِّل في المنتصف؛ وفي <strong>الإعدادات ▸ التعاون</strong> حقل لمُرحِّلك الخاص.","docs.17644a30eafc":"يضع MixSir الأغنية على هاتف متصل بشبكة Wi-Fi لديك، لتستمع إليها وتمزجها بعيدًا عن المكتب، دون أن تثبّت شيئًا على الهاتف. في لوحة <strong>الغرفة</strong> (<kbd>Ctrl</kbd>+<kbd>5</kbd>)، تحت <strong>الهاتف</strong>، اضغط <strong>أرسل إلى هاتفي</strong>. فيصيّر Oscillate المزيج وجزءًا واحدًا لكل مسار عليه مقاطع، وإضافاتك ضمنها، ويسردها تحت <strong>ما سيراه الهاتف</strong>. وحين يقول <strong>جاهز على شبكتك</strong>، يظهر رمز QR.","docs.c1e2f9c2bdf0":"امسح الرمز بكاميرا الهاتف، وهو على شبكة Wi-Fi نفسها التي عليها الحاسوب، فيُفتح المزيج في متصفح الهاتف. ويُحمَّل كل جزء على الهاتف لحظة فتح الصفحة؛ وما إن تقول الصفحة إنها جاهزة، تظل الأجزاء تعزف والشبكة مطفأة، ما دامت الصفحة مفتوحة.","docs.9126b986fc96":"على الهاتف","docs.592290a5fa7c":"<strong>المازج.</strong> شريط للمزيج وشريط لكل جزء، مع الكسب والبان والكتم والإفراد. يعزف زر التشغيل المزيجَ كما أُرسل. المس جزءًا، أو كسبه أو بانه أو كتمه أو إفراده، فتُعزف الأجزاء بدلًا منه، كما توازنها أنت؛ واكتم المزيج لتسمع الأجزاء، أو أفرده لتسمع المزيج وحده. ولا يُعزف المزيج والأجزاء أحدهما فوق الآخر أبدًا.","docs.27a679645074":"<strong>حفظ جزء.</strong> يحفظ كل شريط جزءه على الهاتف: ملفَّ WAV بكسب ذلك الشريط وبانه، يُصنع على الهاتف نفسه، أو ملفَّ MP3 بمعدل 192 kbps يُجلب من الحاسوب، فيحتاج إلى الشبكة.","docs.fb7ea2c82263":"يعزف <strong>الاستماع عند المكتب</strong> المزيجَ من الحاسوب، بصيغة Opus، ولا يحفظ شيئًا.","docs.69571d7ebce2":"<strong>توليد.</strong> حين يكون لـ MIDI Master الذي تستضيفه باب أوامره (في إصدار قادم من MIDI Master)، تعرض الصفحة مفتاح <strong>توليد</strong>: اضغطه فيصنع MIDI Master لقطة جديدة على الحاسوب، وتنفتح نافذته، ويمكن التراجع عن اللقطة في سجل MIDI Master نفسه كأي لقطة أخرى. وحتى ذلك الحين لا تذكر الصفحة شيئًا عن التوليد.","docs.803617a467e8":"يسمع الهاتف الأغنية كما كانت حين ضغطت <strong>أرسل إلى هاتفي</strong>: والتعديل بعد ذلك يحتاج إلى إرسال آخر. ويمكن أن يبلغ طول الأغنية عشر دقائق، مع ما يصل إلى 127 مسارًا فيها شيء؛ والأغنية الأطول، أو التوزيع الفارغ، يُرفض بجملة تقول ذلك.","docs.96495dd1cb07":"الرمز مفتاح","docs.34a09397f380":"يحمل الرمز مفتاحًا صُنع لهذا الاقتران وحده، والعنوان الذي تحته يحمل المفتاح نفسه: كل من يمسح الرمز، أو لديه العنوان، يستطيع سماع الأغنية حتى توقف الإرسال أو تقترن من جديد. عامله كما تعامل رمز الغرفة. ويضع <strong>انسخ العنوان</strong> العنوانَ في الحافظة.","docs.8490e9d3c2a9":"يُنهي <strong>أوقف الإرسال إلى الهاتف</strong>، وهو أيقونة الإيقاف، المشاركةَ، وكذلك يفعل الاقتران من جديد، الذي يصنع مفتاحًا جديدًا ويُنهي القديم، أو إغلاق Oscillate. وخمسة طلبات بمفتاح خاطئ، أو بلا مفتاح، تُنهي الاقتران من تلقاء نفسها، وتقول اللوحة <strong>متوقف</strong>.","docs.f9a0489529f8":"يُخدَم الهاتف عبر HTTP عادي على المنفذ 7434، على شبكتك أنت. والاتصال غير مشفّر، فأرسل إلى هاتفك على شبكة تثق بها. وإن كان برنامج آخر يشغل المنفذ 7434، أو لم يكن الحاسوب على أي شبكة يمكن أن يشاركها هاتف، تقول اللوحة ذلك. وعلى شبكة VPN، قد يكون العنوان مما لا يستطيع الهاتف الوصول إليه.","docs.3dddae9cbb86":"<strong>الكوميتي</strong> وضع مبارزة إيقاعات يملك فيه كل دور موازيره الخاصة. العدّ التنازلي مجرد عدّ تنازلي، لكن المازورات هي القاعدة — فلا يمكن أن يختلف حاسوبان أبدًا على أيّ تعديل كان مشروعًا.","docs.aa8f79385db8":"<strong>ورقة التوزيع</strong> تقول من كتب ماذا، مستخرجة من سجل التعديلات، مخصومًا منها كل عمل تراجع عنه أحد. إنها نقطة بداية لحديث عن الحقوق والنسبة، لا وثيقة قانونية، وهي تقول ذلك.","docs.9129cdbc7eff":"حدّد مسارًا صوتيًّا غنائيًّا واضغط <strong>كلمات الأغنية</strong>. يظهر مسار من الكلمات مقفل على رأس التشغيل. أضف أسطرًا، وانقل سطرًا مازورة إلى الأمام أو إلى الخلف، وقسّم سطرًا إلى مقاطع لفظية، ووجّه لقطة مسجّلة إلى الكلمات التي تخصها.","docs.64413b5bc744":"استورد ملف <code>.txt</code> أو <code>.lrc</code> فتُنسخ الكلمات <strong>إلى داخل المشروع</strong> — انقل الملف بعد ذلك وتبقى الكلمات في مكانها.","docs.f935e3c9c7fe":"الخط مصمّم ليُغنّى منه من الطرف الآخر للغرفة، لا ليُقرأ عن قرب. وكل تعديل على الكلمات عملية، فيسترجعه <kbd>Ctrl</kbd>+<kbd>Z</kbd> مثل أي شيء آخر.","docs.30c821abae69":"الكتابة بمساعدة القاموس","docs.7cbdc2099480":"يُكمل محرّر الأسطر الكلمةَ التي تكتبها من قاموس إنجليزي يضم 327,000 كلمة: تظهر بقية الكلمة الأرجح بعد مؤشر الكتابة، و<kbd>Tab</kbd> يعتمدها. ويُظهر شريط تحت السطر الكلمة كما كتبتها واقتراحاتها. و<kbd>Shift</kbd>+<kbd>Tab</kbd>، أو <strong>✓</strong> بجانب الكلمة، يُبقيها كما كُتبت: الكلمة التي تُبقيها لا تُصحَّح بعد ذلك أبدًا، وتُقترح عليك من حينها. وتبقى الكلمات التي أبقيتها على هذا الحاسوب.","docs.a5c2d92c7274":"يصحّح مفتاح تبديل <strong>التهجئة</strong> في مسار الكلمات الكلمةَ المكتوبة خطأً عند انتهائها. وهو مفعّل افتراضيًا حين يكون Oscillate بالإنجليزية ومعطّل في اللغات الأخرى، لأن القاموس إنجليزي، ويُحفظ اختيارك على هذا الحاسوب. و<kbd>Backspace</kbd> مباشرة بعد التصحيح يعيد كلمتك. ويعمل الإكمال والأدوات أدناه بالطريقة نفسها والمفتاح مفعّل أو معطّل.","docs.33802db20e24":"المقاطع على نوتاتها","docs.df726c0bd8c5":"اكتب <code>-</code> بين مقاطع الكلمة، و<code>_</code> لتمدّ مقطعًا على النوتة التالية. وعلى مسار يعزف نوتات، يضع <strong>قسّم</strong> كل مقطع على نوتته، ويُظهر كل سطر مدى ملاءمته للنوتات التي تحته: <em>4/4</em> حين تتطابق، و<em>+2</em> لزيادة مقطعين، و<em>−1</em> لنوتة متبقية. والسطر الأطول من نوتاته لا يمكن تقسيمه، ويقول السبب؛ والكلمة التي تقسمها سكتة إلى نصفين تُذكر باسمها.","docs.edd3ba06a90f":"النبر والقوافي والإيقاع","docs.0a571dae45e8":"تُعلِّم <strong>علامات النبر</strong> المقطعَ المنبور في كل كلمة في مسار الكلمات، ويكتبه الملقّن بخط عريض.","docs.f545becb9d77":"تلوّن <strong>القوافي</strong> آخر كلمة في كل سطر بحسب قافيتها، وتضع قبل السطر حرفه في نظام قوافي قسمه، ونظامَ القسم كاملًا — <em>AABB</em>، <em>ABAB</em>… — على سطره الأول، وتَسِم العبارة المستهلكة بـ <em>شائع</em>.","docs.1d1d44de93c4":"تضع <strong>شبكة الإيقاع</strong> مقاطع كل مازورة على شبكة السادس عشر، مع العدّ، وعلامةٍ حيث يقع آخر مقطع في المازورة على النبضة الرابعة، ومدى الانضباط، والعَروض: نسبة المقاطع المنبورة التي تقع على نبضة قوية أو نوتة طويلة أو ذروة في اللحن.","docs.dbb2a72d9b7f":"يقيس <strong>أدِّ الراب</strong>، في شبكة الإيقاع، توقيت لقطة مسجّلة تحددها على المسار مقابل المقاطع الموضوعة، ويعلّم كل مقطع بأنه مبكر أو متأخر. وهو يقرأ لقطة، لا ميكروفونًا أبدًا، ولا يولّد شيئًا.","docs.cebc83e88cfb":"ورقة اللحن","docs.17bc21413b45":"يفتح زر <strong>ورقة اللحن</strong> في مسار الكلمات لحنَ المسار وكلماته ورموز التآلفات في قارئ لوحة النوتات. والتآلفات هي تآلفات المسار نفسه، أو تآلفات أول مسار آخر يعزف تآلفات.","docs.b3307da67465":"<strong>ملف ▸ تصدير مجلد مرافق…</strong> يكتب المسارات المنفصلة (stems) وملفات MIDI التي يستطيع أي DAW آخر فتحها. تصطف المسارات المنفصلة عند المازورة 1، فاستيرادها في مكان آخر لا يعني دفع ثلاثين ملفًّا إلى أماكنها.","docs.271287d739a7":"الصيغة ومعدل العيّنات وعمق البت والتشويش المقصود ومكان الحفظ كلها في <strong>الإعدادات ▸ التصدير</strong>.","docs.d20207c90bc7":"يمكن أن تكون الأغنية بأي طول: يُكتب المجلد المرافق ونسخ الماستر على القرص أثناء تصييرها بدل أن تُحفظ في الذاكرة. ولا يمكن لملف WAV أو AIFF أن يتجاوز 4 GB، والتصدير الذي كان سيتجاوزها يُرفض ولا يترك شيئًا خلفه. أما المسار المسحوب إلى الخارج صوتًا فما زال محدودًا بعشر دقائق.","docs.1419f63cf3ba":"<strong>بطاقات الجلسة.</strong> <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>C</kbd>، أو <strong>ملف ▸ بطاقة الجلسة…</strong>، تُصيّر صورة للجلسة بحجم 1200×630 — الإيقاع والمفتاح الموسيقي وعدد المسارات والمقاطع والطول وشكل التوزيع — لتنشرها. لا يمكن وضع رمز غرفة عليها: فهو بطول كيلوبايتات ويحتوي على عنوانك العام، لذا الخيار موجود ومعطّل ويقول السبب.","docs.a684e2a13540":"النوتات بصيغة PDF","docs.5c5543df78a1":"<strong>ملف ▸ تصدير النوتات بصيغة PDF…</strong>، أو زر <strong>PDF</strong> في شريط النوتات، يُعدّ ملف PDF واحدًا بمقاس A4: صفحة غلاف، والاعتمادات، وورقة كل مسار، والمدونة الكاملة، ويُحفظ حيث تختار في مربع حوار الحفظ الخاص بنظامك، الذي يقترح اسم المشروع. ويعدّ سطرٌ الصفحاتِ أثناء إعدادها، ثم يقول إن ملف PDF قد حُفظ، أو إنه لا يوجد ما يوضع فيه، أو إنه سيكون كبيرًا جدًا، أو لماذا فشل. وإلغاء مربع الحوار لا يقول شيئًا.","docs.f28c2866474a":"تذكر <strong>صفحة الغلاف</strong> المقام والإيقاع والميزان، وكل تغيير فيها مع المازورة التي يقع عندها، وعدد المازورات، والنوتات إجمالًا ومسارًا مسارًا. وتسمّي <strong>الاعتمادات</strong> الكتّاب، الذين لا تزال نوتاتهم في الأغنية، والمنتجين، الذين لا تزال مقاطعهم أو أجهزتهم فيها، من سجل المشروع نفسه: بالأسماء المضبوطة في <strong>الإعدادات ▸ التعاون ▸ اسمك داخل الغرفة</strong>، أو باسم المتعاون مأخوذًا من اسم المستخدم الخاص به. ومن لم يقدّم اسمًا قط يُحسب في العدد، ولا يُطبع أبدًا كمعرّف. ويُستبعد المغنّون والعيّنات وشركة التسجيل، لأن السجل لا يمكنه معرفتهم.","docs.d8a5cfa121d2":"طباعة النوتات","docs.43a69487c481":"<strong>ملف ▸ طباعة النوتات…</strong>، أو زر <strong>طباعة</strong> في شريط النوتات، يرسل الصفحات نفسها إلى مربع حوار الطباعة في نظامك: ولا شيء غيرها من النافذة، على ورق A4 أبيض في أيٍّ من السمتين. وفي العربية تُقرأ صفحة الغلاف والاعتمادات من اليمين إلى اليسار.","docs.a5d84ebf2f4a":"<kbd>Ctrl</kbd>+<kbd>9</kbd>، أو <strong>عرض ▸ الفحص النهائي</strong>، أو زره في شريط العنوان، يفتح الفحص النهائي: ماستر لكل مكان تذهب إليه الأغنية، يُفحص كلٌّ منها قبل أن يغادر. وهو نافذة خاصة به، مثل المازج، ويثبّته <strong>⇲</strong> فيه تحت المازج في النافذة الرئيسية. وتبويباته هي <strong>النسخ النهائية</strong> و<strong>السماعات</strong> و<strong>درج الجهارة</strong> و<strong>فحص المواصفات</strong>.","docs.eaa4d72d14bf":"ماستر لكل وجهة","docs.515031535d57":"في تبويب <strong>النسخ النهائية</strong>، علّم الأماكن التي تذهب إليها الأغنية في القائمة المنسدلة للوجهات، بمربع اختيار لكلٍّ منها أو <em>الكل</em>: Spotify أو Apple Music أو YouTube أو Amazon Music أو Tidal أو Deezer أو SoundCloud أو قرص مضغوط أو نادٍ أو البث الإذاعي وفق EBU R 128 أو ATSC A/85. ويظهر بجانب كلٍّ منها هدف الجهارة الخاص به وسقف الذروة الحقيقية، ويعطي الجدول أدناه كل صف معلَّم مع الملف الذي يطلبه. ويقول الصف إن كان الرقم من الخدمة نفسها أم القيمة الافتراضية لـ Oscillate حيث لا تنشر الخدمة رقمًا، مع مصدره واليوم الذي قُرئ فيه. والهدف إرشاد، لا وعدٌ أبدًا بأن تقبل خدمةٌ ملفًا. وما تعلّمه يُحفظ على هذا الحاسوب.","docs.4455f6266bc0":"يصنع زر <strong>تصدير نسخ الماستر</strong> ماسترًا لكل صف معلَّم، معًا، من المزيج نفسه: يُحدّ كلٌّ منها عند سقفه، ويُوصَل إلى جهارته، ويُكتب بصيغته، ثم يُقاس من الملف على القرص، ويقول الجدول إن كان يستوفي صفّه. وتُحفظ معًا في مجلد واحد يحمل اسم المشروع، حيث ترسل <strong>الإعدادات ▸ التصدير</strong> صادراتك.","docs.a7ab3056096a":"استمع كأنه","docs.9dda3184a093":"في تبويب <strong>السماعات</strong>، يُسمعك <strong>استمع كأنه</strong> ما تسمعه كما هو، <strong>مسطّح</strong>، أو كما يعزفه <strong>هاتف</strong> أو <strong>سيارة</strong> أو <strong>حاسوب محمول</strong> أو <strong>سماعة صغيرة</strong> أو <strong>سماعات أذن داخلية</strong>. وكل سماعة مطابَقة المستوى، فيغيّر التبديلُ لونَ الصوت لا جهارته، وينتقل التبديل بتلاشٍ متقاطع دون طقطقة؛ ويتنقّل <strong>قارن بالصوت المسطّح (A)</strong> بين السماعة و«مسطّح» لمقارنة A/B. وهو للمراقبة فقط: ما تسمعه هنا لا يصل أبدًا إلى تصدير أو دمج (bounce) أو ماستر، وكل تشغيل للتطبيق يبدأ مسطّحًا. وكل سماعة تقريبٌ لنوع من السماعات، لا قياسٌ لأي منتج أبدًا.","docs.cdc6504729ef":"يُفحص كل ماستر مُصدَّر أيضًا كما تعزفه سماعة الهاتف ومقصورة السيارة: كم يبقى من الباص في الهاتف، وما يضيع في المونو، ومدى عرض المنطقة المنخفضة، وهل تتراكم عند 80–150 Hz أو 200–400 Hz في السيارة، ومع كلٍّ منها ما يمكن فعله حيالها.","docs.85148526c29c":"درج الجهارة","docs.2472106bcd5c":"يقيس <strong>درج الجهارة</strong> كل قسم من الأغنية، من علامة إلى التالية، وحده، مقابل درجة تخص نوعه (المقدمة أو المقطع أو ما قبل اللازمة أو اللازمة أو الجسر أو الخاتمة) ضمن هامش تسامح، ويتحقق من أن كل لازمة ترتفع فوق المقطع الذي قبلها بالهامش المحدد في <strong>اللازمة فوق المقطع</strong>. سمِّ العلامات بالإنجليزية ليُعرف نوعها. ويرسم <strong>قِس المزيج</strong> الدرجات فوق جهارة الأغنية، مع كل رقم في جدول. وتُحفظ الأهداف على هذا الحاسوب، لا في المشروع.","docs.e4f52faad73b":"فحص المواصفات","docs.966ff4263e47":"يتحقق <strong>فحص المواصفات</strong> من ملف مُصدَّر، أحدِ نسخ الماستر أو أي ملف عبر <strong>افحص ملفًا…</strong>، مقابل هدف تسليم: البث التدفقي، مرتفعًا أو هادئًا؛ أو البث الإذاعي، EBU R 128 أو الولايات المتحدة (ATSC A/85)؛ أو ماستر القرص المضغوط؛ أو ملف WAV للموزّع؛ أو هدفك الخاص. وتغطي قواعده الثلاث عشرة الجهارةَ، وأعلى 3 ثوانٍ وأعلى 400 ms، ومدى الجهارة، والذروة الحقيقية وذروة العيّنات، ومعدل العيّنات، وعمق البت، والقنوات، والطول، والصمت عند كل طرف، والعيّنات المقصوصة المتتالية؛ وتعطي كلٌّ منها ما قيس، والهامش، وأبسط إصلاح. وحيث يستوفي تغييرٌ واحد في الكسب كل قواعد المستوى يقول بكم، وحيث لا يستطيع ذلك أي تغيير يقول هذا بدلًا منه.","docs.565f3cb18dc4":"يمكن تعديل الهدف وختمه بـ<strong>علّمه كمُتحقَّق منه اليوم</strong>؛ والهدف الذي لم يُتحقَّق منه منذ 180 يومًا يُعرض على أنه غير مُتحقَّق منه. ويُحفظ التقرير بصيغة HTML أو JSON أو PDF. والنجاح يعني أن الملف استوفى قواعد الهدف الذي اخترته، ولا يعني أبدًا أن خدمةً ستقبله.","docs.4d70c96652da":"امزجه من أجلي","docs.80cd4454f137":"يضبط <strong>امزجه من أجلي</strong>، بجانب <strong>تصدير نسخ الماستر</strong>، المزيج كله للوجهة الأولى المعلَّمة: بطاقات المؤثرات لكل جزء غير مقفل وغير مكتوم على اقتراحها (انظر <a href=\"#devices\">اقتراح</a>)، ومستوى كل جزء بحسب ماهيته، وعلى الرئيسي True-Peak Limiter يوصله إلى جهارة الصف تحت سقفه. وتُترك المسارات المقفلة والمكتومة كما هي، وكذلك المنزلق الذي عليه أتمتة لمستوى الصوت؛ وإذا كان الحُبيبي في الرئيسي مفعّلًا يُطفأ، لأنه يعمل بعد المحدِّد. ويقول التقرير ما فعله.","docs.8df50e56ff44":"إنه خطوة تراجع واحدة: التراجع يعيد المزيج كله. ويصيّر كل جزء خارج الزمن الحقيقي ليقيسه، لذا يستغرق بعض الوقت في الجلسة الكبيرة.","docs.5371ad5444f6":"<kbd>Ctrl</kbd>+<kbd>,</kbd>. كل تغيير يُطبَّق فورًا ويبقى محفوظًا لكل جهاز. لا يوجد زر <em>تطبيق</em>، لأن نافذة إعدادات فيها زر كهذا هي نافذة إعدادات قد تخطئ في ما هو سارٍ فعلًا.","docs.d7af9297a0b1":"تمتد أقسامها الثلاثة عشر على الجانب. ويضم <strong>التسجيل</strong> العدّ التمهيدي، والاختصار العام لـ Oscillate Retro Record وأيقونته في علبة النظام، وكلاهما معطّل حتى تفعّله؛ انظر <a href=\"#retro-record\">Oscillate Retro Record</a>.","docs.bc1b88907d3b":"الصوت","docs.40710b1c4ea7":"اختر جهاز الإخراج وكم تأخذ من الجهاز. على Windows يمكنك طلب الوضع <strong>الحصري</strong>، الذي يمنحك أدنى تأخير يستطيعه العتاد ويُسكت كل تطبيق آخر. ويخبرك Oscillate <strong>بالوضع الذي حصلت عليه فعلًا وسببه</strong> — إما <em>فُتح التدفق حصريًا</em> أو <em>هذا الجهاز لم يفتح تدفقًا حصريًا، لذا ما زال الجهاز مشتركًا</em>. لا خفض صامتًا أبدًا.","docs.dfe87d5e5bba":"المظهر واللغة","docs.ca2a0f41ebc8":"السمتان كلتاهما، وثماني عشرة لغة، والاختيار الذي تقوم به يتغلب على اختيار الجهاز عند التشغيل التالي. والكتابة من اليمين إلى اليسار حقيقية، لا مجرد محاذاة للنص. وبجانبهما <strong>سرعة الحركة</strong> و<strong>تقليل الحركة</strong>: <em>سريعة</em> يدير العنوان بضعف السرعة، و<em>تقليل</em> يوقف كل حركة أيًّا كان إعداد النظام.","docs.56205fc54fb3":"<strong>الإعدادات ▸ التحديثات.</strong> يبحث Oscillate عن تحديث <strong>فقط</strong> حين تضغط <em>ابحث عن تحديثات</em>، أو عند التشغيل إذا فعّلت ذلك — وهو <strong>معطّل افتراضيًا</strong>.","docs.shot.updates":"الإعدادات وقسم التحديثات محدَّد: زر «ابحث عن تحديثات» داخل إطار أحمر يحمل الرقم 1، ومفتاح «الفحص عند بدء تشغيل Oscillate» داخل إطار يحمل الرقم 2 وهو في وضع الإيقاف.","docs.983c1169fe58":"1 يفحص مرة واحدة، الآن. و2 هو الفحص عند التشغيل، ويبقى معطّلًا حتى تفعّله. وتطبع اللوحة العنوان الدقيق الذي سيُتّصل به وآخر مرة اتُّصل به فعلًا.","docs.3ce9192c8c94":"يطلب الفحص ملفًّا ثابتًا واحدًا ولا يرسل شيئًا عنك ولا عن هذا الجهاز ولا عن مشاريعك. وحين يُعثر على تحديث تُعرض عليك النسخة والتاريخ وسجل التغييرات والحجم، وأنت تختار. كل ملف إصدار موقَّع؛ والملف الذي لا يُتحقَّق من توقيعه يُرفض مع خطأ بدل أن يُثبَّت.","docs.eb0eedb56328":"مع تعطيل الفحص عند التشغيل لا يُتّصل بشيء ولا تعرض اللوحة أي نتيجة على الإطلاق — يبقى <em>آخر فحص</em> على <em>أبدًا</em>. ولا ترسم أبدًا «أنت على آخر إصدار» فوق فحص لم يحدث، لأنهما حقيقتان مختلفتان ولن تكون إلا إحداهما صحيحة.","docs.855dbb09047b":"كل واحد من هذه يمكن تغييره في <strong>الإعدادات ▸ الاختصارات</strong>، والتركيبة المحجوزة سلفًا تقول أي إجراء يملكها. على macOS اقرأ <kbd>Ctrl</kbd> على أنه <kbd>Cmd</kbd>.","docs.456bb0100878":"التركيبة","docs.64cff1319d2f":"الإجراء","docs.a78afaff2fda":"تشغيل أو إيقاف مؤقت","docs.4b627c7915d2":"حفظ Oscillate Retro Record — آخر دقائق من مدخلك، محفوظة بعد حدوثها","docs.a41eb2bf7245":"مشروع جديد","docs.c4c61e4f9081":"فتح مشروع","docs.1509f561f241":"حفظ","docs.60af8a30e5e6":"حفظ باسم","docs.c0d170d865e7":"تراجع — عن تغييرك أنت، دائمًا","docs.74273989b096":"إعادة","docs.26c31b40dc4c":"بطاقة الجلسة","docs.e91f3b2dc496":"إظهار مستعرض الملفات أو إخفاؤه","docs.3eeec874b1d1":"إظهار رف الأنماط أو إخفاؤه","docs.56f9e52baa67":"إظهار لوحة أو إخفاؤها — المحرّر، المازج، الغرفة","docs.83e175e68d99":"إظهار المسرح أو إخفاؤه","docs.1d966b73a9ca":"إظهار لوحة النوتات أو إخفاؤها","docs.ef1800cc8809":"إظهار لوحة الدروس أو إخفاؤها","docs.30da360ea376":"إظهار نافذة الفحص النهائي أو إخفاؤها","docs.bed27fa10d73":"فتح إحدى الأوراق التسع الأولى، و1 هو المدونة الكاملة، ما دامت لوحة النوتات ظاهرة؛ والمفتاح نفسه مرة أخرى يعيدك","docs.2f965c221f2d":"العودة من الورقة المفتوحة، في لوحة النوتات","docs.ef86faf16227":"التنقّل بين عروض المسرح، إلى الأمام أو إلى الخلف، حين يكون التركيز على المسرح","docs.598372c72bff":"تقديم منظر المنصة أو إرجاعه، من أي مكان ما دامت المنصة ظاهرة","docs.0bb673ee3069":"النصل / المؤشر","docs.ce13b797313a":"أداة الرسم؛ وفي المحرر، وضع الرسم (القلم)","docs.5689a46a3b2a":"أداة الرسم المتكرر — المقطع المختار يُرسم على طول المسار","docs.ae568d1cdc7a":"أداة المسح","docs.2e45e8cb5822":"أداة الكتم","docs.2914595ae6ab":"أداة إزاحة المحتوى — ينزلق محتوى المقطع؛ وعلى الحافة تتحرك الحافة معه","docs.d9e17187d41a":"أداة الاستماع — المقطع المضغوط يُسمع وحده","docs.8bda3a715fdf":"نسخ المقاطع المحددة","docs.6a9097f78c98":"لصق المقاطع عند رأس التشغيل","docs.5d4232ecd8df":"في البيانو رول: نسخ النوتات المختارة وقصّها ولصقها","docs.c216e4b5e616":"العلامة السابقة / العلامة التالية","docs.63195e7ab017":"المازورة 1 / نهاية التوزيع","docs.308ea67cd57c":"تحديد كل شيء","docs.ef8b2814c03b":"مسح التحديد","docs.3eea5fab03b2":"حذف المحدَّد","docs.324d77bb489d":"التكميم","docs.caa2871b6c07":"الأنسنة","docs.c9b32288f886":"ليجاتو","docs.2e5b4c5eaf16":"عكس النوتات","docs.349dbacd897e":"نقل النوتات إلى المقام","docs.dee3dab5b567":"تكرار بعدها","docs.a5239b85e5fb":"إزاحة","docs.f87e04909851":"نصف درجة؛ ومع <kbd>Shift</kbd>، أوكتاف","docs.715210114589":"طيّ اللفّة إلى المقام","docs.71d26d2e1ebf":"النوتات الشبحية — بقية النمط، خلف هذه","docs.c4b80c8b8af1":"مسار الشدة","docs.6bea7121b291":"مسار الاحتمال — كم مرة تُعزف كل نوتة","docs.12beabce3af4":"مسار مدى الشدة — إلى أي حدّ تتجوّل كل نوتة","docs.0c319deafe8d":"لا يحتاج Oscillate إلى حساب، ولا يجمع أي قياس عن بُعد، ولا يرسل مشاريعك أو صوتك أو أي شيء عنك أو عن جهازك إلى أي مكان لم ترسله إليه بنفسك. التسجيل والتحرير والتشغيل والمزج والتصدير كلها محلية بالكامل.","docs.080502306d57":"هناك أربع مناسبات بالضبط يستعمل فيها الشبكة:","docs.7b291aa666a0":"<strong>جلسة تعاون فتحتها أو انضممت إليها.</strong> مباشرة إلى الأشخاص الآخرين فيها، من جهاز إلى جهاز، بلا خادم في المنتصف.","docs.19e4e946fae3":"<strong>استعلام STUN</strong>، فقط أثناء إنشاء الغرفة، لاكتشاف عنوانك العام. يُعرض الخادم الذي يُتّصل به في الإعدادات ويمكن استبداله بخادمك — أو إطفاؤه كليًا، ما يعني أن الغرفة لا تتصل بأحد على الإطلاق.","docs.e19cbd5438b8":"<strong>فحص التحديثات</strong>، فقط حين تضغط الزر أو تفعّل الفحص عند التشغيل. معطّل افتراضيًا. انظر <a href=\"#updates\">التحديثات</a>.","docs.3a3b41351317":"<strong>MixSir، ما دمت ترسل إلى هاتفك.</strong> يقدّم Oscillate الأغنية التي أرسلتها للأجهزة الموجودة على شبكتك أنت، على المنفذ 7434، حتى توقف الإرسال؛ ولا يتصل هو بأي شيء، ولا يأخذ شيئًا من الهاتف. انظر <a href=\"#phone\">MixSir</a>.","docs.0d97a43de208":"هذا مفروض ببوابة بناء لا بوعد: لا يمكن الوصول إلى أي عميل HTTP من أي جزء من Oscillate إلا من مكوّنَي التعاون والتحديث المذكورين أعلاه، والبوابة تثبت ذلك بالمشي في رسم الاعتماديات لا بالبحث عن الأسماء. تُكتب تقارير الأعطال على قرصك، وتُعرض عليك كاملة، ولا تغادر الجهاز إلا إذا اخترت إرسال أحدها.","docs.64a02f31ce7f":"<strong>الاستماع الحي.</strong> حين يستمع إليك درس، أو تستعمل الموالف أو تعاير مدخلك، يسمع Oscillate مدخل جهاز الصوت المختار في <strong>الإعدادات ▸ الصوت</strong>، وفقط ما دام ضوء الاستماع مضاءً. وما يسمعه يُحلَّل على حاسوبك لحظة وصوله، إلى نوتات وتآلفات وضربات طبول ومقاطع لفظية وتوقيت، ثم يُترك. لا يُصنع أي تسجيل، ولا يُكتب أي صوت على القرص، ولا يُرسل شيء إلى أي مكان.","docs.8d1a762df8c1":"الشيء الوحيد الذي يحتفظ به الاستماع ملف إعدادات صغير، <code>listen.json</code>، في مجلد بيانات Oscillate على هذا الحاسوب: المدخل الذي اخترته، وضبط A4 لديك، والدورات التي تستمع، ومفتاح المراقبة لكل دورة، والكمون المقيس لكل مدخل بالمللي ثانية. هذه أرقام وأسماء، لا صوت أبدًا. والمراقبة، المعطّلة افتراضيًا، تعزف مدخلك عبر مسار الدرس الخاص لتسمع نفسك؛ ولا تسجّل شيئًا هي أيضًا. وتفشل بوابة بناء إذا مدّ كود الاستماع يده إلى أي ملف غير ذلك الملف، ويشغّل اختبارٌ جلسة استماع كاملة فلا يجد شيئًا آخر متروكًا خلفها.","docs.caf7b4929a7d":"<strong>Oscillate Retro Record.</strong> ما دام <strong>الالتقاط</strong> مفعّلًا، يحتفظ Retro Record بمدخل الصوت لديك ولوحة مفاتيح MIDI في ذاكرة هذا الحاسوب، من 30 ثانية إلى ساعة منها، والأحدث يحلّ محل الأقدم. ولا يُكتب أي صوت على القرص حتى تضغط <strong>حفظ</strong>، ولا يُرسل شيء منه إلى أي مكان أبدًا. والحفظ كمقطع يكتب صوته ملفَّ WAV في مجلد <code>Takes</code> الخاص بـ Oscillate، كما تُكتب أي لقطة مسجّلة؛ والحفظ كملف WAV يكتبه، مع ملف MIDI إن كنت قد عزفت نوتات، في مجلد <code>Retro Record</code> داخل مجلد بيانات Oscillate. ويُصنع كل ملف جديدًا باسم لا يحمله أي ملف آخر، فلا يكتب الحفظ فوق أي ملف من ملفاتك أبدًا، والحفظ الذي يفشل في منتصفه لا يترك أيًّا من ملفاته خلفه.","docs.e5be57430ab7":"يُصفّر <strong>مسح كل شيء</strong> ما يحتفظ به Retro Record، ومعه الثواني القليلة التي ما زالت في طريقها من خيط الصوت، ويعيد الذاكرة؛ وتغيير مدته أو صيغته أو مدخله، أو سحب موافقتك، يفعل الشيء نفسه، والخروج من التطبيق يعيد الذاكرة إلى نظام التشغيل. وملفه الآخر الوحيد هو <code>retro.json</code>: موافقتك، ومدته وصيغته ومدخله، ومفتاح القدم، ومفتاحا التبديل الخاصان بالاختصار العام وعلبة النظام، ولا صوت أبدًا. ولا يصل إليه الدمج (bounce) أو التصدير أبدًا، ويُلزمه اختبارٌ بمصدر تغذية واحد، هو المدخل الحي.","docs.5a3b48d48644":"يحتفظ <strong>البحث عن المتشابه</strong> بملف واحد، <code>find-similar.index</code>، في مجلد بيانات Oscillate. ولكل ملف WAV أو MIDI تحت مجلدات مستعرض الملفات وحزم الإيقاع المرفقة، يحفظ مسار الملف الكامل وحجمه وتاريخه، وبصمات (hashes) لبايتاته ولصوته أو نوتاته، وقياسات تقريبية: جهارة الصوت وطيفه، أو إيقاع الحلقة وسرعتها وأدنى نوتة في كل ضربة. لا يُحفظ فيه أي صوت، ولا يُرسل إلى أي مكان؛ وحذفه لا يكلّف إلا قراءة أخرى لمجلداتك. أما <strong>مطابقة الركلة والباص</strong> فلا تحتفظ بشيء على الإطلاق.","docs.c474edeb7ac4":"<strong>أربعة منتجين في الغرفة</strong>، لأن كل مشارك يرسل إلى كل مشارك آخر، والاتصال الخامس هو النقطة التي ينفد عندها رفع منزلي عادي.","docs.d92b90c2dcd3":"<strong>نحو واحد من كل عشرة اتصالات لن ينعقد</strong> دون مُرحِّل، وOscillate لا يأتي بمُرحِّل — فالمُرحِّل يكلّف نطاقًا تردديًا إلى الأبد، وهذه فاتورة مستمرة لا يستطيع تطبيق مجاني تحمّلها.","docs.12e311704eeb":"<strong>العيّنات لا تعبر الشبكة أبدًا.</strong> اللقطة التي سجّلتها تعبر؛ والعيّنة التي اشتريتها لا تعبر.","docs.311b8222a5fd":"<strong>ستة أجهزة مسمّاة ورمادية بلا عناصر تحكم</strong>، لكل منها سبب مكتوب لا مجرد هزّة كتف.","docs.5aae84a23e5e":"<strong>نص الدروس بالإنجليزية</strong> حتى النسخة التجريبية. أما كل عنصر تحكم حوله فبلغتك.","docs.414bff17d593":"<strong>المقطع الصوتي المنقولة طبقته أو الممدَّد يُرسم كملفه.</strong> فالموجة تُظهر التسجيل، لا الصوت الذي يُعزف.","docs.822c3066dfa6":"<strong>لا يمكن تصيير مُعايِن عيّنات بلا ملف إلى صوت.</strong> تحويل نمط على مسار مُعايِن العيّنات فيه فارغ يُرفض باسمه بدل أن يُعاد صمتًا.","docs.a638c9f1f04c":"<strong>يسمع الهاتف الأغنية كما أُرسلت.</strong> والتعديل بعد <strong>أرسل إلى هاتفي</strong> يحتاج إلى إرسال آخر، ويُخدَم الهاتف عبر HTTP عادي على شبكتك أنت، دون تشفير.","docs.c446742f8d3c":"<strong>الغرفة ترفض تغيير التوزيع الكبير جدًا.</strong> يُرفض في الغرفة التبديل أو الدمج أو التوزيع الجديد أو النسخ أو الحذف الذي من شأنه أن يرسل أكثر من 1024 تغييرًا دفعة واحدة، أي نحو 500 مقطع؛ وحين تعمل وحدك، ينجح أي حجم.","docs.601ee4a78c6d":"<strong>قيمتا Mod X وMod Y الخاصتان بالنوتة تصلان إلى آلتين.</strong> يسمع Oscillate Grain Layers كلتيهما نوتةً نوتة، ويسمع Oscillate Siren قيمة Mod Y؛ أما كل آلة أخرى وإضافاتك فتسمعهما للمسار كله. ولا تسمع الإضافات بان النوتة ولا ضبطها الدقيق للطبقة.","docs.7ddad12c5802":"<strong>الانزلاق يثني المسار كله.</strong> فهو يحرّك عجلة ثني النغمة للمسار، فتنثني معه كل نوتة تصدح فيه.","docs.687899918ed2":"<strong>مسار CC يُرسم ويُحفظ، ولا يُعزف.</strong> لا تقرؤه أي آلة بعد، ومن ذلك المذبذب منخفض التردد (LFO) المكتوب فيه.","docs.9596113825be":"<strong>مشاركة الشاشة على Windows وLinux.</strong> لا يملك macOS طريقًا لالتقاط الشاشة من داخل عرض ويب مضمَّن لا يحتاج إلى واجهة برمجية خاصة في ملف تنفيذي موثَّق، لذا الزر غائب هناك ويقول السبب.","docs.00cc76804476":"<strong>لا يُكتشف المشارك الذي انقطع بعد.</strong> إذا انقطعت شبكة أحدهم، تبقى قائمة الحاضرين تُظهره.","docs.c8fe28a31074":"لا يوجد صوت","docs.90409e8554a3":"تحقّق من <strong>الإعدادات ▸ الصوت</strong> أولًا: الجهاز، والوضع الذي حصلت عليه فعلًا. إذا كان تطبيق آخر يمسك الواجهة الصوتية في الوضع الحصري، فلا يستطيع Oscillate فتحها ويقول ذلك. والمسار الصامت بينما غيره ليس صامتًا يكون عادةً بسبب إفراد في مكان آخر، أو هو مكتوم، أو خانة آلته فارغة.","docs.15d94cccd4a0":"إضافة لا تظهر","docs.b2298073a265":"<strong>الإعدادات ▸ الإضافات</strong> تسرد المجلدات التي يُجرى فحصها وما وُجد فيها. والإضافة التي فشل تحميلها تُسرد محظورة مع السبب، ويمكن إلغاء حظرها لإعادة المحاولة. يستضيف Oscillate إضافات VST3 وCLAP؛ ولا يستضيف VST2 ولا AU.","docs.2ac89ed8e9e1":"الغرفة لا تتصل","docs.dde8792e71cd":"اقرأ السبب الذي يذكره — هناك تسعة أسباب وهي مشكلات مختلفة. <em>شبكتك تعطي كل خادم عنوانًا مختلفًا</em> تعني أنك تحتاج إلى مُرحِّل، ومكانه في <strong>الإعدادات ▸ التعاون</strong>. وتحقّق أن الرمز الذي لصقته هو الرمز كاملًا: فالرموز طويلة، وتطبيق الدردشة الذي يقسم أحدها على أسطر يكون قد أفسده.","docs.79993d75b6ac":"حدث عطل","docs.f6ceafb1fe98":"يُكتب تقرير على جهازك تلقائيًا. <strong>الإعدادات ▸ عام</strong> تسمّي أحدث تقرير وتفتح المجلد. يحتوي التقرير على النسخة ونظام التشغيل وجهاز الصوت وقائمة الإضافات بأسمائها — لا مشروعك أبدًا، ولا مسارًا من قرصك أبدًا، ولا رمز غرفة أبدًا. ولا يغادر حاسوبك إلا إذا اخترت إرساله.","docs.9031c748abd6":"لوحة أصبحت فارغة لكن الموسيقى استمرت","docs.0f28d0790cf5":"هذا عطل مختلف عن الانهيار، وهو العطل الذي لا يبلّغ عنه معظم الناس. خيط الصوت لا يشغّل شيئًا من شيفرة الواجهة، فيستمر التشغيل ويبقى مشروعك سليمًا. ومع ذلك كُتب تقرير؛ وستسمّيه الإعدادات.","kit.skip":"الانتقال إلى المحتوى","kit.nav.site":"الموقع","kit.nav.home":"الرئيسية","kit.nav.features":"الميزات","kit.nav.documentation":"التوثيق","kit.nav.changelog":"سجل التغييرات","kit.nav.language":"اللغة","kit.nav.allApps":"كل تطبيقات Freally","kit.badge.progress":"v0.17.0 منجز · v0.18.0 هو التالي","kit.cta.features":"شاهد كل الميزات","kit.cta.docs":"اقرأ التوثيق","kit.price":"Freally Oscillate مجاني اليوم، لكنه قد لا يبقى مجانيًا إلى الأبد: قد تُباع الإصدارات المستقبلية.","kit.noDownloads":"لا توجد تنزيلات بعد، والشفرة المصدرية خاصة.","kit.label.overview":"نظرة عامة","kit.label.inside":"في الداخل","kit.label.roadmap":"خارطة الطريق","kit.ladder.done":"منجز","kit.ladder.planned":"مخطط له","kit.ladder.goal":"الهدف","kit.label.honesty":"الصراحة","kit.family.label":"عائلة Freally","kit.family.title":"<span class=\"hl-muted\">عائلة واحدة.</span> <span class=\"hl-bright\">عشرة تطبيقات.</span>","kit.cta.label":"ما الذي تغيّر","kit.cta.title":"<span class=\"hl-muted\">كل إصدار،</span> <span class=\"hl-bright\">مدوَّن.</span>","kit.cta.lede":"يسرد سجل التغييرات كل ما تغيّر في Freally Oscillate، إصدارًا بعد إصدار، بثماني عشرة لغة.","kit.cta.changelog":"اقرأ سجل التغييرات","kit.footer.thisApp":"هذا التطبيق","kit.footer.family":"عائلة Freally","kit.status.devVersion":"قيد التطوير · v0.17.0","kit.head.features":"<span class=\"hl-muted\">كل ما يفعله،</span> <span class=\"hl-bright\">جنبًا إلى جنب.</span>","kit.label.numbers":"بالأرقام","kit.label.free":"مجاني اليوم","kit.label.compare":"مقارنة","kit.label.principles":"المبادئ","kit.label.limits":"الحدود","kit.states.title":"ماذا تعني الحالات","kit.states.done":"مبنيّ وموسوم، لكنه ليس تنزيلًا على هذا الموقع","kit.states.planned":"لم يُبنَ بعد","kit.states.goal":"الإصدار الذي يقود إليه الطريق","kit.states.ladder":"شاهد كل درجة على الطريق","kit.head.documentation":"<span class=\"hl-muted\">كيف يعمل،</span> <span class=\"hl-bright\">خطوة بخطوة.</span>","kit.search.placeholder":"ابحث في التوثيق","kit.docs.contents":"المحتويات","kit.head.changelog":"<span class=\"hl-muted\">كل تغيير،</span> <span class=\"hl-bright\">إصدارًا بعد إصدار.</span>","kit.changelog.lede":"الأحدث أولًا: كل ما تغيّر في Freally Oscillate، بكل لغة يتحدث بها هذا الموقع.","kit.changelog.versions":"الإصدارات","kit.search.none":"لا شيء في هذا الموقع يطابق ذلك.","kit.zoom.close":"إغلاق","changelog.9fd9a60c9a98":"<span class=\"release__meta\"><span class=\"release__ver\">v0.17.0</span><time class=\"release__date\" datetime=\"2026-11-12\">2026-11-12</time></span>","changelog.c4015d81ec0c":"<strong>الترددات المنخفضة، زوجًا — لا توجد تنزيلات بعد.</strong> جهازان جديدان صُنعا ليعملا معًا: يضع Oscillate Sub جهيرًا عميقًا تحت ما تعزفه، ويوسّع Oscillate Width ما فوقه دون أن يُرقّق المجموع الأحادي أبدًا. اربطهما، على مسار واحد أو عبر مسارين، فيتشاركان نقطة فصل واحدة، فلا يُوسَّع شيء تحتها أبدًا. ويكسب مزيج الهاتف مفتاح توليد لـ MIDI Master المرفق، وصارت الإضافة المستضافة تسمع تعبير كل نوتة الخاص بها.","changelog.6b02e0d363a4":"أُضيف","changelog.a86d93475bf6":"<strong>Oscillate Sub: جهير عميق تحت الباص.</strong> يتبع جهير 1 طبقة ما يدخل إليه ويعزف تحتها موجة جيبية، تُعرض بالهرتز أو اسمَ نوتة، وله زمن الهجوم والتلاشي والانزلاق الخاصة به؛ وتُبقيه محاذاة الطور في طور المصدر نفسه، فلا يلغي أحدهما الآخر أبدًا. ويخفض جهير 2 نطاقًا من المصدر أوكتافًا أو اثنين (أو بأنصاف الدرجات) بجودة Best أو Balanced أو Light، أحاديًّا أو ستيريو، ويُبقي التنعيم عند 0 هجمة الكيك. وتضيف النغمة توافقيات كي تبقى المنطقة المنخفضة مسموعة على الهاتف: Tube أو Tape أو Transistor أو Rectifier، مع إفراط في العينات بأربعة أضعاف إن أردت. ويسوّي الثبات خط باص يقفز مستواه، نطاقًا بنطاق تحت 150 Hz، ويزيل كتم الترددات المنخفضة المنطقة المنخفضة الخاصة بالمصدر تحت نقطة الفصل. وتعرض الواجهة الطبقة التي يسمعها، ومستوى كل جهير، ومحلّلًا للمنطقة المنخفضة بثلاث درجات من الدقة. وخمسون إعدادًا مسبقًا من المصنع.","changelog.6dcbf76fb98e":"<strong>Oscillate Width: أعرض، ولا يرقّ في الأحادي أبدًا.</strong> ثلاثة نطاقات، تفصل بينها في البداية 400 Hz و4 kHz، ويُوسَّع كلٌّ منها من 0 إلى 200 % ويبقى المجموع الأحادي كما كان تمامًا؛ وتحدد القوة مدى إبعاد الجانبين أحدهما عن الآخر. أفرِد نطاقًا، أو اسمع ما أُضيف فقط (Side)، أو أثبت أن الوسط لم يتحرك أبدًا (Mid). وتُبقي مطابقة المستوى المصدر الأحادي الموسَّع بالعلوّ الذي كان عليه، ويُدخل مفعّل الجهاز ويُخرجه دون نقرة، ويعرض مقياس ترابط ومقياس زوايا (goniometer) المجال الستيريو. بلا تأخير. وخمسون إعدادًا مسبقًا من المصنع.","changelog.56f07800a4bc":"<strong>الزوج.</strong> في المستعرض، يضع <em>إدراج الزوج</em> Sub ثم Width على مسار، مرتبطَين. وما داما مرتبطين، على مسار واحد أو عبر مسارين، يتشاركان نقطة فصل واحدة: حرّكها في أيٍّ من الواجهتين فتتحرك في كلتيهما. ولا يوسّع Width ما تحتها أبدًا؛ وتظلّل واجهة Width النطاق الذي يصنعه Sub، وتُعلِّم واجهة Sub نقطة فصل Width. واثنا عشر إعدادًا مسبقًا للزوج تضبطهما معًا. <strong>خمسة وثمانون من الواحد والتسعين مبنية</strong> الآن.","changelog.ed4b1f0cb640":"<strong>التوليد من هاتفك.</strong> حين يكون لـ MIDI Master الذي تستضيفه باب أوامره (في إصدار قادم من MIDI Master)، تعرض صفحة المزيج على الهاتف مفتاح توليد: اضغطه فيصنع MIDI Master لقطة جديدة عند المكتب، وتنفتح نافذته، ويمكن التراجع عن اللقطة في سجله الخاص كأي لقطة أخرى. وحتى ذلك الحين لا تذكر الصفحة شيئًا عن التوليد.","changelog.c14badf75253":"<strong>يصل تعبير كل نوتة الخاص بها إلى إضافاتك.</strong> ضغط النوتة وجرسها الخاصان بها (Mod Y وMod X لكل نوتة في لفّة البيانو)، وثنيها الخاص، والضبط الدقيق للطبقة والبان لخطوةٍ ما، تصل كلها، على تلك النوتة وحدها، إلى إضافة CLAP مستضافة تعبيراتِ نوتات، وإلى VST 3 أحداثَ تعبير النوتة (والضغطُ ضغطًا متعدد الأصوات). والإضافة التي لا تأخذ أيًّا منها تسمع ما كانت تسمعه من قبل؛ وإضافة CLAP التي لا تقرأ إلا MIDI تتلقى ضغط النوتة لمسةً لاحقة متعددة الأصوات.","changelog.2a6141e43be0":"تغيّر","changelog.0f032151ad10":"<strong>تسميات الأجهزة بالهولندية والعربية والأوكرانية والروسية</strong> قُرئت مقابل ما يفعله كل عنصر تحكم فعلًا، وأُعيدت كتابتها حيث كانت حرفية، أو حيث كان عنصرا تحكم يتشاركان كلمة واحدة.","changelog.f016cddec88d":"<strong>لقطة شاشة البداية</strong> تُظهر التخطيط الجديد.","changelog.8f6fb4eb7f42":"الأمان","changelog.32e5a43f5672":"<strong>لدى MixSir مسار واحد له أثر عند المكتب</strong>: توليد الهاتف. ويحتاج إلى مفتاح الاقتران كأي مسار آخر، وما دام MIDI Master بلا باب يُرفض كما يُرفض مسار غير موجود.","changelog.79508d88a5b7":"<span class=\"release__meta\"><span class=\"release__ver\">v0.16.0</span><time class=\"release__date\" datetime=\"2026-11-09\">2026-11-09</time></span>","changelog.83d578f4962d":"<strong>مزيجك على هاتف، ومظهر جديد، وعشرة أجهزة جديدة — لا توجد تنزيلات بعد.</strong> أرسل المزيج وكل جزء إلى هاتف على شبكة Wi-Fi لديك عبر رمز QR، لتمزجها هناك وتحفظها عليه ملفات. وأُعيد تخطيط كل لوحة، لكلٍّ منها زر رئيسي واحد، وأيقونات صغيرة وقوائم منسدلة ومفاتيح تبديل لما سواه. ويكسب التوزيع الرسم المتكرر للأنماط، وشريط تكبير فوق الخط الزمني، ومفتاحًا لكل أداة، وعدة توزيعات في مشروع واحد، ومُطلِق مقاطع بمشاهد؛ وتكسب لفّة البيانو أدوات الرسم المتتابع والكتم والتقطيع، ونوتات تنزلق وتنساب، واختيارًا زمنيًا خاصًا بها. ويعزف المسرح عدة أجزاء معًا، بيدين تتجنبان التقاطع. وتصل عشرة أجهزة على دفعتين، من كيك يحفر مكانه في الباص إلى عاصفة مرسومة على خريطة. ويحتفظ Oscillate Retro Record بالدقائق الأخيرة مما تعزفه، فيظل ممكنًا حفظ لقطة لم تضغط زر التسجيل لها قط، ويرتّب البحث عن المتشابه أشباه الصوت عبر مجلداتك. هذا الإصدار وحده يُتمّ أربع درجات من السلّم، من 0.13.0 إلى 0.16.0، تحت وسم واحد؛ وليس للإصدارات 0.13.0 و0.14.0 و0.15.0 وسم خاص بها.","changelog.98037fc94f72":"<strong>MixSir: مزيجك على هاتفك.</strong> اضغط في لوحة الغرفة الهاتف ▸ <em>أرسل إلى هاتفي</em> فيُصيَّر المزيج وكل مسار عليه مقاطع، وإضافاتك ضمنها، ويظهر رمز QR ما إن تصبح الحالة <em>جاهز على شبكتك</em>. امسحه بهاتف على شبكة Wi-Fi نفسها فيُفتح المزيج في متصفحه، دون أن تثبّت شيئًا. ويُحمَّل كل جزء على الهاتف لحظة فتح الصفحة، فيظل يعزف والشبكة مطفأة ما دامت الصفحة مفتوحة. ولمازج الهاتف شريط للمزيج وشريط لكل جزء، مع الكسب والبان والكتم والإفراد (يعزف زر التشغيل المزيج؛ المس جزءًا، أو اكتم المزيج، فتُعزف الأجزاء بدلًا منه، كما توازنها أنت، دون أن يضاعفها المزيج أبدًا)؛ ويُحفظ أي جزء على الهاتف ملفَّ WAV بكسبه وبانه، أو ملفَّ MP3 بمعدل 192 kbps يُجلب من المكتب. ويعزف <em>الاستماع عند المكتب</em> المزيجَ، متدفقًا بصيغة Opus، ولا يحفظ شيئًا. ويسمع الهاتف الأغنية كما كانت حين ضغطت: والتعديل بعد ذلك يحتاج إلى إرسال آخر. أغانٍ حتى عشر دقائق، مع ما يصل إلى 127 مسارًا فيها شيء. ويُنهيه <em>الإيقاف</em>، أو الاقتران من جديد، أو إغلاق النافذة الرئيسية، أو الخروج من التطبيق.","changelog.0d29b6c8fb39":"<strong>مظهر جديد في كل لوحة.</strong> أُعيد تخطيط كل لوحة وكل نافذة بأسلوب واحد: غرافيت غير لامع، وعناصر تحكم مثبّتة في تجاويف غائرة، وتسميات محفورة، ونقاط مضيئة، وأشرطة عرض للأرقام. وتحتفظ كل لوحة بإجرائها الرئيسي الوحيد زرًّا مُصيَّرًا (ولا يحتفظ المحرّر بأي زر، ليفسح المجال للّفة)؛ وكل ما عدا ذلك أيقونة صغيرة يسمّيها تلميحها ويذكر اختصارها، أو قائمة منسدلة حيث يُختار واحد من كثير (مع مربعات اختيار حيث يمكن اختيار عدة)، أو مفتاح متعدد الأجزاء، أو مفتاح تبديل رمادي حين يكون معطّلًا، وأبيض تحت المؤشر، وأخضر حين يكون مفعّلًا. والمقابض والمنزلقات ومسارات الأتمتة كما كانت، وكل كلمة متاحة بكل اللغات الثماني عشرة، ومن اليمين إلى اليسار في العربية.","changelog.5260ed9a395d":"<strong>الفحص النهائي، بتخطيط جديد.</strong> تبويباته هي النسخ النهائية والسماعات ودرج الجهارة وفحص المواصفات، والنسخ النهائية أولًا. والوجهات قائمة منسدلة واحدة بمربع اختيار لكلٍّ منها (ومعها <em>الكل</em>)، ولكلٍّ منها جهارتها وسقفها بجانبها، ولا يُظهر الجدول إلا الصفوف التي علّمتها. و<em>استمع كأنه</em> قائمة منسدلة أولها «مسطّح»، وما زال التبديل فيها بلا طقطقة، مع مفتاح تبديل للمقارنة A/B بالصوت المسطّح (A). و<strong>تصدير نسخ الماستر</strong> هو زر النافذة الوحيد، وحين لا يكون شيء معلَّمًا يطلب منك تعليم وجهة.","changelog.cf2a1447c43c":"<strong>لفّة البيانو تأخذ المساحة.</strong> صار شريط أدوات المحرّر صفًّا واحدًا من الأيقونات بعد أن كان ثلاثة صفوف من الأزرار، ويُفتح المقطع وارتفاع صفوفه 18 px (وكان 14)، وتجلس مسارات الشدة والاحتمال وCC والأتمتة واللقطات تحت فاصل واحد تسحبه، ويُحفظ موضعه على هذا الحاسوب. وتُفتح نافذة المحرّر أول مرة بمقاس 1360 × 928. ومحرّر رف الأنماط هو اللفّة نفسها ويأخذ المساحة نفسها.","changelog.4f61c7339338":"<strong>ارسم وحدّد وامحُ دون تغيير الأداة.</strong> أيًّا كانت الأداة، تمحو النقرة اليمنى أو السحب بالزر الأيمن ما يعبره، ويرسم Ctrl+سحب مربعًا، وShift يضيف إليه. والنقرة على شبكة فارغة ترسم نوتة بطول المحاذاة (ومع وجود نوتات مختارة تلغي الاختيار بدلًا من ذلك، إلا مع «رسم»، الذي يرسم دائمًا). والسحب على نوتة يحرّكها، وحافتاها، المعلَّمتان بـ <code>[</code> و<code>]</code> تحت المؤشر، تطيلانها وتقصّرانها؛ ومع «محو» و«كتم» و«تقطيع» يؤدي الضغط على نوتة عمل تلك الأداة ما لم تضغط Ctrl. والأداة، وهي إحدى «تحديد» و«رسم» و«رسم متتابع» و«محو» و«كتم» و«تقطيع»، تختار ما يفعله السحب العادي على شبكة فارغة. وما دامت النوتة تُسحب، تتحرك معها أعمدة شدتها واحتمالها وانحرافها.","changelog.c016b8f11128":"<strong>الشبكة تُظهر المحاذاة.</strong> ترسم اللفّة خطًا عند كل خطوة محاذاة تبعد 6 px أو أكثر، والثلاثيات ثلاثياتٍ، مع تظليل المازورات بالتناوب (أو النبضات بالتناوب عند التكبير). وتتبع مازوراتها موازين الأغنية، فللمازورة من 3/4 ثلاث نبضات، وللمازورة من 7/8 سبعة أثمان.","changelog.6de419fe1b5c":"<strong>لوحة الدروس، بتخطيط جديد.</strong> قائمة منسدلة للدورات وشريط بالدورات الخمس عشرة، لكلٍّ منها ضوء تقدّم من عشرة أجزاء، والأيام التي اجتزتها، وما الذي تبدأ بعده إن لم تكن قد بدأتها؛ ثم أيام الدورة المفتوحة على خط واحد، مجمّعةً حسب الأسبوع تحت أقسامها. ويتميّز كل يوم بشكله إلى جانب لونه (مجتاز، أو حيث أنت، أو مراجعة، أو نقطة تحقق، أو لم تبلغه بعد)، وتتنقّل مفاتيح الأسهم على طول الخط، و<em>متابعة</em> هو زر اللوحة الوحيد.","changelog.ad7c3a66767e":"<strong>الإعدادات على الجانب، وقوائم مستعرض الملفات بلوحة المفاتيح.</strong> تمتد أقسام الإعدادات الثلاثة عشر على الجانب. وفي مستعرض الملفات، تقبل قائمة الآلات وأصواتي ← و→ للتنقل بين إجراءات الصف، إلى جانب ↑ و↓ للتنقل والعزف (وعلى اسم الآلة، يظل ← و→ يعزفانها إلى الخلف وإلى الأمام)، مع Home وEnd وCtrl+Home وCtrl+End؛ وكل قائمة محطة واحدة لمفتاح Tab. ومرشّحا العائلة والدور قائمتان منسدلتان بمربعات اختيار.","changelog.143667e7f56b":"<strong>المسرح يعزف عدة أجزاء معًا.</strong> صار <em>تتبّع</em> الآن قائمة منسدلة بمسارات MIDI في المشروع، بمربع اختيار لكلٍّ منها، و<em>الكل</em> معلَّم افتراضيًا، ويقودها المسار الذي تحدده. وعلى البيانو، تُعزف حتى أربعة أجزاء معًا، يُعرف كلٌّ منها باسم مساره (لحن، تآلفات، باص، لحن مقابل) أو بموقعه إن لم يُعرف بالاسم: فيميل الباص والتآلفات إلى اليد اليسرى، واللحن واللحن المقابل إلى اليمنى. ويعزف الغيتار الجزء الواحد المختار في <em>يعزف</em>، ويعزف الباص خط الباص، ولا ينضم مسار الطبول إلى الفرقة أبدًا. وما هو معلَّم يدوم طوال الجلسة.","changelog.eb52194f9ce6":"<strong>يدان لا تتقاطعان.</strong> صارت يدا البيانو لا تتقاطعان إلا حين لا توجد طريقة بلا تقاطع لعزف الفقرة الموسيقية، واليد التي ليس لديها ما تعزفه تستريح في جانبها هي من الأخرى.","changelog.02db47470aef":"<strong>ارسم الأنماط رسمًا متكررًا في التوزيع.</strong> يسرد المنتقي الذي بجانب المسارات أنماط رف الأنماط، وأنماط MIDI، والمقاطع الصوتية، والحالي منها مضاء؛ والضغطة تنتقي أحدها وتختار أداة الرسم المتكرر. والنقرة على مسار فارغ تضعه في موضع المحاذاة، والسحب يرسم نسخًا متلاصقة حول المقاطع الموجودة، والنقرة اليمنى أو السحب بالزر الأيمن يزيلها؛ وكل سحبة خطوة تراجع واحدة. وتبقى النسخ مرتبطة بنمطها، كما كان النمط الموضوع دائمًا. والضغط على مقطع بأداة المؤشر أو الرسم أو الرسم المتكرر يجعل نمطه هو الحالي، ويرشّح المنتقي حسب النوع، ويُظهر غير المستخدم فقط، ويرتّب، ويعزف النمط الذي تقف عليه بـ <em>استمع إليه</em>.","changelog.e25983ec7ed8":"<strong>شريط التكبير فوق التوزيع.</strong> ينتقل شريط التمرير إلى ما فوق المسطرة: اسحب الجزء المنزلق منه للتمرير، واسحب أيًّا من طرفيه للتكبير حول الطرف الآخر، وانقر عليه نقرًا مزدوجًا لملاءمة الأغنية؛ وحين يكون التركيز على الشريط، تمرّر مفاتيح الأسهم ويغيّر Ctrl+الأسهم التكبير. وتحت الجزء المنزلق صورة صغيرة للأغنية كلها، مقاطع كل مسار فيها بلونه. وتحرّكه مفاتيح التكبير وCtrl+العجلة أيضًا. والعجلة فوقه تكبّر وتصغّر، وShift+العجلة تمرّره.","changelog.037c5be5d7bc":"<strong>مفتاح لكل أداة.</strong> في التوزيع، <strong>P</strong> يرسم، و<strong>B</strong> يرسم رسمًا متكررًا، و<strong>D</strong> يمسح، و<strong>T</strong> يكتم، و<strong>S</strong> يُزيح المحتوى، و<strong>C</strong> يقطع بالنصل، و<strong>V</strong> يحدد، و<strong>Y</strong> يستمع: الحروف التي يتوقعها المنتج الموسيقي. وتستجيب ما دام التركيز على التوزيع، فتحتفظ لوحة مفاتيح الحاسوب بنوتاتها ويحتفظ المحرّر بمفاتيحه الخاصة في غيره. وينسخ Ctrl+C المقاطع المحددة ويلصقها Ctrl+V عند رأس التشغيل، وينتقل Alt+← وAlt+→ إلى العلامة السابقة والتالية. ويمكن تغيير كلٍّ منها في الإعدادات ▸ الاختصارات.","changelog.169c9a143cc7":"<strong>أدوات جديدة في التوزيع.</strong> تكتم أداة الكتم كل مقطع تعبره سحبة أو تلغي كتمه؛ وتُزلق أداة إزاحة المحتوى ما يُعزف داخل المقطع، وعلى الحافة تحرّك تلك الحافة وينزلق معها ما يُعزف داخله، وتُترك المقاطع الأخرى حيث هي؛ وتعزف أداة الاستماع المقطع المضغوط وحده عبر المعاينة، لا عبر شريط النقل أبدًا. وAlt مع حافة مقطع صوتي يمدّده، مع الحفاظ على طبقته، من ربع طوله إلى أربعة أضعافه (لا المقطع المعكوس أو المكرَّر). ويعيد <em>الاسم واللون…</em> في قائمة المقطع تسمية المقطع وتلوينه. ⚠ المقطع الذي تستمع إليه يُسمع دون مؤثرات مساره، والممدَّد بسرعة ملفه الأصلية.","changelog.25abbe4e8d33":"<strong>قائمة «ترتيب»، مكتملة.</strong> التقطيع عند كل خط من الشبكة، أو عند نقاط الهجوم في الصوت المحدد، أو عند نقاط الإشارة (cue) والمناطق التي يحملها ملفه؛ ودمج مقاطع الأنماط المحددة في المسار في نمط واحد؛ وتجميع المقاطع لتتحرك وتُكتم وتُحذف كوحدة واحدة، أو فك تجميعها؛ وتحديد كل نسخة من مقطع، أو المكتومة، أو المتداخلة، أو المكدّسة، أو عكس التحديد؛ والنسخ واللصق؛ وكتم التحديد وإلغاء كتمه؛ ومحاذاة البدايات على الشبكة؛ وإدراج امتداد الحلقة من الوقت أو حذفه؛ وجعل كل المسارات صغيرة أو متوسطة أو كبيرة؛ واستنساخ مسار بأجهزته وأتمتته ومقاطعه، أو تسميته باسم أول مقطع فيه، أو نقله إلى الأعلى أو الأسفل؛ والتكبير إلى التحديد. وكل ما يغيّر الأغنية منها خطوة تراجع واحدة؛ أما الاختيار والنسخ والتكبير فليست كذلك. وتكسب المحاذاة 1/32، وسدس الخطوة، و<em>حواف المقاطع</em>. ⚠ حذف امتداد من الوقت يترك المقطع الذي يعبر حافته حيث كان.","changelog.c27e0439c34e":"<strong>علامات تفعل شيئًا.</strong> انقر بالزر الأيمن على علامة في المسطرة واختر ما تفعله: تبدأ الأغنية عندها حين تعزف من البداية (وتغلب أبكر علامة من هذا النوع)، أو تعود إليها من العلامة التالية، أو تقفز إلى العلامة التالية، أو تتوقف عندها. والنقرة اليمنى على المسطرة تغيّر أيضًا الميزان بدءًا من أي مازورة، أو تزيل تغييرًا.","changelog.40f1052de714":"<strong>عدة توزيعات في مشروع واحد.</strong> تبدّل قائمة منسدلة في شريط أدوات التوزيع بينها، وتصنع قائمتها توزيعًا جديدًا، أو تنسخ، أو تعيد التسمية، أو تحذف، أو تدمج توزيعًا آخر في التوزيع الظاهر على الشاشة. ولكلٍّ منها مقاطعه وعلاماته وخطوات تراجعه الخاصة فوق المسارات والأنماط والمازج التي تتقاسمها، والتشغيل والدمج (bounce) والتصدير تعزف التوزيع الظاهر على الشاشة. والتبديل إلى توزيع وإنشاؤه ونسخه ليست خطوات تراجع أبدًا. والمشروع السابق يُفتح توزيعًا واحدًا، كما كان. ⚠ في الغرفة، يُرفض تغيير التوزيع الذي من شأنه أن يرسل أكثر من 1,024 تغييرًا دفعة واحدة (تبديل، أو دمج، أو توزيع جديد، أو نسخ، أو حذف، أي نحو 500 مقطع)، بجملة تقول ذلك؛ وحين تعمل وحدك، ينجح أي حجم.","changelog.327140a0572b":"<strong>مُطلِق المقاطع والمشاهد.</strong> يُظهر زر المُطلِق في شريط أدوات التوزيع شبكةً فوق الخط الزمني، فيها عمود لكل مسار صوت ومسار MIDI، وصف لكل مشهد. وتُطلق الخانة مقطعها، متكررًا، عند المازورة التالية أو النبضة التالية أو فورًا (بعد نبضة واحدة ما دامت الأغنية تعزف)، مقطعًا واحدًا لكل مسار، والإطلاق والأغنية متوقفة يبدأ تشغيلها؛ ويُطلق المشهد صفّه كله؛ وأوقف مسارًا واحدًا، أو أوقف كل المسارات، أو اختر <em>العودة إلى التوزيع</em>. وتقول الخانة التي تعزف <em>يعزف</em> والتي تنتظر <em>في الانتظار</em>، وتعمل عليها مفاتيح الأسهم وEnter. ويأخذ المشهد الجديد المقاطع التي تحت رأس التشغيل، ويمكن لكل مشهد أن يتابع بعد 1 إلى 64 مازورة إلى المشهد التالي أو السابق أو الأول، أو أي مشهد آخر عشوائيًا، أو أن يوقف كل شيء. والإطلاق ليس خطوة تراجع أبدًا؛ ويكتب <em>سجّل الأداء</em> ما أطلقته في التوزيع حيث عُزف، بدل ما كان لتلك المسارات هناك، في خطوة تراجع واحدة، ويترك المسار المقفل كما كان.","changelog.228b76751682":"<strong>أدوات لفّة البيانو الجديدة.</strong> يضع <strong>رسم متتابع</strong> نوتة في كل خطوة محاذاة يعبرها السحب ولا نوتة فيها، ويكتم <strong>كتم</strong> النوتات أو يلغي كتمها (وتُرسم مجوّفة)، ويقطع <strong>تقطيع</strong> كل نوتة يعبرها السحب. وترسم قائمة <strong>الختم</strong> تآلفًا مع كل نقرة؛ وستة عشر لونًا للنوتات، واسم كل نوتة مكتوب عليها حيث يتسع، ولوحة المفاتيح على اليسار تختار كل نوتة من طبقة المفتاح. وتقص قائمة <strong>تحرير</strong> وتنسخ وتلصق (Ctrl+X وC وV في اللفّة)، وتدوّر النوتات خطوة، وتعكس الاختيار، وتختار النوتات المكتومة أو التي خارج النبضة؛ وتضبط <strong>أدوات أخرى</strong> الأطوال إلى 25 أو 50 أو 75 أو 150 %، وتجعل كل نوتة بطول خطوة واحدة، وتحاذي النهايات على الشبكة، وتكمّم إلى النصف أو مع التأرجح، وتحصر النوتات ضمن أوكتافين، وتغيّر الشدة بنسب. وتلائم قائمة <strong>التكبير</strong> كل النوتات أو المختارة منها، ويمرّ رأس التشغيل عبر اللفّة، ويكسب <em>إضافة مسار</em> البان والضبط الدقيق للطبقة، اللذين تسمعهما آلات Oscillate نفسها التي تعزف العيّنات ولا تسمعهما إضافاتك.","changelog.699aad0e2319":"<strong>نوتات تنزلق وتنساب وتُفلَت.</strong> يعطي مسار الإفلات كل نوتة السرعة التي تُترك بها، فتطول رنّة One-Shot Sampler وMultisampler وDrum Machine وGrain Layers وSiren مع الإفلات البطيء وتقصر مع السريع؛ وتُبلَّغ إضافاتك بها أيضًا. ونوتة الانزلاق لا تضرب شيئًا وتثني المسار إلى طبقتها؛ ونوتة الانسياب تُضرب انطلاقًا من النوتة التي قبلها ثم تنساب إلى موضعها على امتداد نوتة من السادس عشر، أو على امتداد طولها هي إن كان أقصر. وترسل مسارات Mod X وMod Y عجلة التعديل والضغط الخاصين بكل نوتة لحظة ضربها. وانقر نقرًا مزدوجًا على نوتة لترى خصائصها: كل أرقام النوتات المختارة، مكتوبة، و<em>مختلطة</em> حيث تختلف. ⚠ يحرّك الانزلاق عجلة ثني النغمة للمسار، فتنثني معه كل نوتة تصدح على ذلك المسار، ولا تتبعه الإضافة بدقة إلا ضمن مدى الثني الخاص بها. ويسمع Grain Layers قيمتَي Mod X وMod Y نوتةً نوتة، ويسمع Siren قيمة Mod Y؛ أما كل آلة أخرى وإضافاتك فتسمعهما للمسار كله. ولا تسمع سرعة الإفلات إلا هذه الآلات الخمس: أما الآلات المبنية على محرّك التركيب الصوتي المشترك فلا تأخذ منها شيئًا بعد.","changelog.9fc979239544":"<strong>الوقت في لفّة البيانو.</strong> للّفة مسطرة خاصة بها: يختار Alt+سحب فيها امتدادًا من الوقت، ثم تُدرج قائمة «تحرير» فراغًا بطوله (فيطول النمط)، أو تقطع وتُدرج، أو تحذفه (فيقصر النمط، دون أن يتجاوز آخر نوتة فيه أبدًا)، أو تقتطع إليه، أو تُلغيه. اسحب في المسطرة لتسمع النوتات، وفعّل <em>تتبّع مؤشر التشغيل</em>، وشاهد علامات الأغنية في اللفّة (والنقر المزدوج على المسطرة يضع علامة). ويمكن تجميع النوتات لتتحرك وتُحذف كوحدة واحدة، وتكسب المحاذاة خطوات أدق، وحواف النوتات والعلامات، ويمكن لمسار CC أن يكتب مذبذب LFO (جيبيًّا أو مثلثيًّا أو مربعًا أو منشاريًّا، من مازورة إلى نوتة من السادس عشر، ومن 25 إلى 100 %) في خطوة تراجع واحدة. ⚠ لا يزال مسار CC يُرسم ويُحفظ لكنه لا يُعزف: لا تقرؤه أي آلة بعد، فلا يُسمع المذبذب.","changelog.5af822d7568e":"<strong>Oscillate Kick Carve:</strong> يُخفض الباص في شريحة المنطقة المنخفضة التي يصدح فيها الكيك فقط، وفقط ما دام يرنّ هناك؛ ولا تتحرك توافقيات الباص التي فوقها أبدًا. اختر الكيك في <em>‏Sidechain من</em>. يقسم <em>Spectrum</em> المنطقة المنخفضة إلى 24 نطاقًا، ويتبع <em>Bell</em> طبقة الكيك نفسها بقطع واحد؛ والعمق حتى 24 dB، والضبط، وعرض Q، والتتبّع، والإمساك، والمدى، والوسط فقط، وحتى 5 ms من الاستباق، مع تعويض تأخيره عبر المزيج كله. وعند عمق صفر يمرّ الباص كما هو بتًّا ببت، متأخرًا بقدر ذلك الاستباق فقط. وثمانية إعدادات مسبقة.","changelog.6e9e3eb32420":"<strong>Oscillate Bass Unison:</strong> موجة منشارية أو 808 تتحول إلى باص reese متحرّك، من صوتين إلى ثمانية أصوات مُزاحة الضبط حتى 35 سنتًا وتدور عبر مراحل all-pass، منتشرةً على اتساع، بينما يبقى كل ما تحت نقطة الفصل (40–300 Hz) أحاديًّا ودون مساس، فيسمعه كله مكبّر الترددات المنخفضة (sub) الأحادي في النادي وسماعة الهاتف الوحيدة. والعرض حتى 150 %، والثقل، والمزج؛ وثمانية إعدادات مسبقة، من Classic Reese إلى Extreme Phase. ويُبلغ عن تأخير نحو 15 ms.","changelog.2f0e26ac5223":"<strong>مطابقة الركلة والباص، في مستعرض الملفات.</strong> في مجلد أصوات، اختر ركلة واضغط <em>رتّب أصوات الباص</em>: يُعطى كل ملف WAV آخر في المجلد درجة من 100 بحسب الفاصل والخشونة والتداخل في المنطقة المنخفضة وتوافق التلاشي، مع إعادة الضبط بالسنتات التي تضع الركلة على أساس الباص أو خامسته أو أوكتافه. ويعزف <em>استمع</em> مازورة من أربع ركلات، بعد إعادة ضبطها، فوق الباص بسرعة 120 BPM. إنها قياس، بلا نموذج، ولا يُحفظ شيء. ⚠ ملفات WAV فقط، وأول أربع ثوانٍ من كلٍّ منها، و2,000 صوت باص على الأكثر.","changelog.2bbf8a9cbdb7":"<strong>Oscillate Groove، وأربعون إحساسًا:</strong> جهاز نوتات ينقل الطبول التي تُعزف إليه إلى إحساس مسمّى، من <em>Grid Tight</em> و<em>Laid-Back Backbeat</em> إلى <em>Loose Drummer</em>. امزج إحساسين، واضبط العمق (حتى 200 %) وإزاحة كل مسار وعمقه الخاصين، بالاستيفاء أو بالالتقاط. وحين يكون أولًا على المسار، يقرأ نوتات المقطع مسبقًا، فلا تحتاج النوتة المقدَّمة إلى أي تأخير مضاف؛ أما المفتاح المعزوف حيًّا، أو Groove يأتي لاحقًا في السلسلة، فينتظر بمقدار الاستباق لديه. احفظ أحاسيس من صنعك واستدعها، واطبع المقطع المفتوح في المحرّر بإحساس ما، مقطعَ MIDI جديدًا بجانبه. و<strong>Oscillate Groove Kit</strong> آلته الشريكة، اثنا عشر طبلًا مُركَّبًا صوتيًا تعزف أنماطها بإحساس ما. والأحاسيس الأربعون مكتوبة هنا، كل رقم فيها باليد؛ ولم يؤخذ أيٌّ منها من أي مكان.","changelog.92a1c80a9eba":"<strong>Oscillate Chord Trigger:</strong> مفتاح واحد يعزف تآلفًا كاملًا مع باصه، بقيادة أصوات تجعله يتحرك بأقل قدر ممكن. ثلاث مناطق (الباص والتآلفات ومفاتيح التحكم)، و27 شكلًا للتآلفات وثمانية من صنعك تُبنى على شبكة من ثلاثة أوكتافات، والقلوب، والإمساك، والخربشة (strum) حتى 60 ms، واثنا عشر إعدادًا مسبقًا. ووسائده كبيرة (64 px، أو 96 مع <em>أهداف أكبر</em>)، ويعزف صف الأرقام التآلفات، ويمكن العزف عليه بالمسح بالمُبدِّل، بمُبدِّل واحد أو اثنين (مفتاح، أو نوتة MIDI أو متحكّم تعلّمه إياه). ⚠ تعزف الوسائد المسار المجهَّز، وتدوم إعدادات المسح طوال الجلسة.","changelog.53a6da7d9287":"<strong>Oscillate Glide:</strong> انزلاقات لخطوط 808. سبع قواعد تختار أي النوتات تنزلق (كل نوتة، أو النوتات خارج النبضة، أو نوتة كل بضع نوتات، أو القصيرة، أو القفزات، أو المعلَّمة في مساره، أو لا شيء)، على زمن انزلاق من 5 ms إلى 2 s أو متزامن مع الإيقاع، وعلى أحد ستة منحنيات، مع مسار من «انزلاق» و«إمساك» و«تخطٍّ» يصل طوله إلى أربع مازورات مرسوم على واجهته. ويثني بخطوات من 14 بت، ويُبلغ إضافاتك بمدى الانحناء لديه (ولا تحتاج آلات Oscillate نفسها إليه)، ويقيّد الانزلاق الذي يتجاوزه أو يقسمه. ويغذّيه باص Chord Trigger. واثنا عشر إعدادًا مسبقًا.","changelog.f839647ae043":"<strong>Oscillate Siren:</strong> صفارات الشرطة النائحة، وصفارات الغارات الجوية، والصفارات ثنائية النغمة، وصفارات الدَّب، على دوّار يدور ويصنع تباطؤه، من 0.2 إلى 12 ثانية، الصعودَ والهبوط؛ واثنا عشر نموذجًا للدوّار، وغلاف للطبقة، وانسياب، ومذبذب LFO من 0.01 إلى 40 Hz، وMono وLegato وPoly 8 وLatch، ونمط إنذار من 16 إلى 32 خطوة، وغلافان، وثلاثة مذبذبات LFO، وتسلسل من 16 خطوة، ومصفوفة من اثنتي عشرة خانة. واثنان وستون إعدادًا مسبقًا: صفارات، ودَب، وضربات ريف، وطلقات ليزر، ونوابض. وتعمل مذبذباته بمعدل 4× افتراضيًا، حيث يكون التشوّه الطيفي (aliasing) فيها دون −80 dB. ⚠ وعند 1× يكون أعلى بكثير.","changelog.3a01cdff8bdc":"<strong>Oscillate Dispersion Delay:</strong> حتى 512 مرحلة all-pass تنشر الضربة عبر تردداتها فتحوّلها إلى طلقة ليزر (على خط، أو لكل أوكتاف، أو على هيئة جرس، فتتأخر المنخفضات أو المرتفعات)، مع تغذية راجعة محدودة داخل حلقتها، وجانب أيمن مُزاح عن الأيسر؛ ثم صدى شريطي من 1 ms إلى 2 s مع التموّج والارتجاف (wow وflutter)، والإعتام، والتشبع، ونتوء الرأس. وترسم واجهته التأخير الذي تصنعه المراحل فعلًا، ترددًا بترددٍ، والمجال الاستريو. ولا يضيف أي تأخير في المعالجة (latency).","changelog.ff6ae697f032":"<strong>Oscillate Grain Layers:</strong> حتى ثماني عيّنات من عيّناتك مكدّسة كطبقات صخرية يقرؤها مثقاب يختار عمقُه ما يصدح؛ فالتعرية تُبلي العمود، والطي يثنيه، والصدع يشقّه. ستة عشر صوتًا، وأربعة مذبذبات LFO، وغلافان، ومصفوفة من ست عشرة خانة، ببذرة ثابتة فيخرج التصيير متطابقًا في كل مرة، واثنا عشر إعدادًا مسبقًا من المصنع طبقاتها مُركَّبة صوتيًا بالشيفرة. ضع ملفًا، أو الملف الذي استمعت إليه في مستعرض الملفات، على طبقة؛ ويحمل <em>احتفظ بصوت هذه الطبقة داخل المشروع</em> الصوتَ في ملف المشروع، ويبحث <em>ابحث عن هذا الملف مجددًا في مجلداتك</em> عن ملف نُقل. وتُعرض الذاكرة التي تأخذها طبقاته، حتى 1 GiB. ويُرسم مقطعه العرضي حيًّا على Windows، ويبقى ثابتًا مع تفعيل تقليل الحركة، وعلى macOS وLinux. وتحرّك قيمة Mod X للنوتة مثقابه، وتذهب قيمة Mod Y إلى حيث يقول <em>الضغط إلى</em>. ⚠ حد الحبيبات فيه من 16 إلى 64 (و48 افتراضيًا)، أقل مما خُطط له أولًا، كي تبقى أدق درجاته ضمن حصته من خيط الصوت.","changelog.d13b6a8a420c":"<strong>Oscillate Storm:</strong> مطر ورعد ورياح مصنوعة من فيزيائها، فلا شيء يتكرر ولا تُستعمل أي عيّنة. يسقط المطر على ثمانية أسطح (سقف من الصفيح، ونافذة، ومظلة، وسطح خشبي، وأوراق الشجر، وخرسانة، وبُقعة ماء، وبِركة)، ويصل الرعد متأخرًا بقدر بُعد برقه. وعلى خريطة العاصفة تضع المستمع، وما يصل إلى ثماني مناطق مطر، وما يصل إلى أربعة بروق ترسمها. ومقبضا ماكرو، المطر والعاصفة. والمفتاح عند التقسيم أو فوقه يشغّل الطقس ويُسقط قطرة بطبقته؛ والمفتاح تحته يُطلق برقًا. وتجلب عجلة التعديل العاصفة، وCC 11 المطر، وCC 74 الرياح، وتقرّب عجلة ثني النغمة المستمع أو تبعده. واثنان وستون إعدادًا مسبقًا، وثلاث درجات للجودة (Draft وNormal وUltra)، ويكتب <em>صيّر الطبقات الثلاث</em> المطر والرعد والرياح في ثلاثة ملفات WAV يساوي مجموعها المسار. ستيريو فقط. <strong>ثلاثة وثمانون من التسعة والثمانين مبنية</strong> الآن، ومعها اثنان وثلاثون مؤثرًا أساسيًا وكل أجهزة النوتات التسعة عشر.","changelog.d26614725630":"<strong>Oscillate Retro Record: الدقائق الأخيرة، دائمًا.</strong> يحتفظ النقل ▸ Oscillate Retro Record… بمدخل الصوت لديك (مدخل واحد أو زوج ستيريو) ولوحة مفاتيح MIDI في الذاكرة: من 30 ثانية إلى ساعة (خمس دقائق افتراضيًا)، بدقة 24 بت أو 16 بت أو فاصلة عائمة 32 بت، مع عرض الذاكرة التي تأخذها كل مدة قبل أن تختارها؛ <em>دائمًا</em> أو <em>أثناء التشغيل</em> أو <em>عند تجهيز مسار</em>. وتُظهر موجة حيّة ما يحتفظ به، والأحدث على اليمين؛ اسحب عبرها لتختار. ويُنزل <em>حفظ</em>، أو Ctrl+Shift+R في أي نافذة من نوافذ Oscillate، اللقطةَ مقطعًا، الصوت على مسار الصوت المجهَّز والنوتات على مسار MIDI المجهَّز (أو على مسار جديد)، عند المازورة التي عزفتها فيها، أو عند رأس التشغيل إن كانت الأغنية متوقفة؛ أو ملفَّ WAV مختومًا بالتاريخ والوقت، وبجانبه ملف MIDI. وتحفظ الضغطة الواحدة كل ما يحتفظ به، أو آخر امتداد تختاره فقط؛ ويقصّر <em>تخطي الصمت</em> فترات الهدوء الطويلة، وعتبته مضبوطة أعلى من الغرفة بمقدار 9 dB عبر <em>قياس الغرفة</em>. ويحفظ مفتاح قدم MIDI أيضًا (دواسة الاستدامة أو مفتاح يتعلّمه، معطّل حتى تختاره)، وتضيف الإعدادات ▸ التسجيل اختصارًا عامًا وأيقونة في علبة النظام، وكلاهما معطّل حتى تفعّله.","changelog.3faf581791d2":"<strong>Retro Record يسأل أولًا، ويُظهر نفسه دائمًا.</strong> لا يحتفظ بشيء حتى توافق، مرة واحدة، ولا يبدأ إلا حين تضغط <em>الالتقاط</em>. وما دام يلتقط أو يحتفظ بأي شيء، يبقى ظاهرًا في المقدمة في كل نافذة من نوافذ Oscillate ضوءٌ بكلمة حالته، والوقت المحفوظ والذاكرة التي يأخذها، ولا شيء يخفيه. ويمحو <em>مسح كل شيء</em> ما يحتفظ به فورًا. ولا يصل إليه الدمج (bounce) أو التصدير أبدًا، وإن كان المدخل صامتًا مدة ثانية ونصف يقول كيف قد يحجب Windows أو macOS أو Linux الميكروفون.","changelog.5d6f51c7a959":"<strong>البحث عن المتشابه، في مستعرض الملفات.</strong> اختر صوتًا أو حلقة MIDI في المجلد الذي أنت فيه واضغط <em>ابحث عن المتشابه</em>: يُرتَّب كل ملف مشابه في مجلدات مستعرض الملفات وحزم الإيقاع المرفقة بدرجة من 100، كلٌّ منها مع سببه بالكلمات (الملف نفسه، أو إعادة حفظ، أو تغيير في الكسب، أو قصّ، أو تغيير في الطبقة، أو تمديد، أو نبرة مختلفة، أو الإيقاع نفسه). ويعزف <em>استماع</em> المرجع، أو الملف المشابه، أو الاثنين معًا متحاذيين في التوقيت. وتُقرأ المجلدات في الخلفية حين تُفتح اللوحة أول مرة في الجلسة، ولا يُقرأ من جديد إلا ما هو جديد أو معدّل. إنه قياس، بلا نموذج. ⚠ ملفات WAV وMIDI فقط؛ ولا وعد بتغييرات الطبقة التي تتجاوز ثلاثة أنصاف درجة ولا بالتمديد الذي يتجاوز 12 %.","changelog.62790887f365":"<strong>النصل الآن هو C</strong>، بعد أن كان B، الذي صار للرسم المتكرر؛ وأداته هي <em>قص</em>. ولا تستجيب حروف أدوات التوزيع إلا ما دام التركيز على التوزيع: فلم يعد <strong>V</strong> و<strong>C</strong> يعملان من أي مكان آخر، و<strong>P</strong> هو قلم المحرّر في كل مكان خارج التوزيع.","changelog.9d2ea7559799":"<strong>على macOS، يذكر طلب إذن الميكروفون Retro Record</strong> بين ما قد يستمع إلى مدخلك.","changelog.981dec5c13f5":"<strong>لا يعمل خادم MixSir إلا ما دمت ترسل إلى هاتفك.</strong> إنه عملية مستقلة، <code>oscillate-mixsir</code>، يبدؤها <em>أرسل إلى هاتفي</em> ويُنهيها <em>الإيقاف</em>، أو الاقتران من جديد، أو إغلاق Oscillate. ويستمع على المنفذ 7434 لأي جهاز يستطيع الوصول إلى هذا الحاسوب. ويحمل عنوان رمز QR مفتاحًا من 32 بايتًا عشوائيًا صُنع لذلك الاقتران وحده: ومن دونه تُرفض قائمة الأجزاء وكل ملف والتدفق بجواب واحد لا يذكر السبب أبدًا، وخمسة طلبات بمفتاح خاطئ أو من دون مفتاح تُنهي الاقتران. ولا يأخذ شيئًا من الهاتف، ولا يقرأ أي ملف، ولا يكتب شيئًا على القرص. ⚠ الاتصال HTTP عادي، غير مشفّر: كل من يرى الرمز، أو يراقب حركة البيانات على شبكة Wi-Fi لديك، يستطيع سماع الأغنية حتى ينتهي الاقتران، فعامله كما تعامل رمز الغرفة، وأرسل إلى هاتفك على شبكة تثق بها.","changelog.0118b7065892":"<strong>يحتفظ Retro Record بما يسمعه في الذاكرة، لا على القرص أبدًا، حتى تحفظ.</strong> ولا يُرسل شيء منه إلى أي مكان أبدًا. وملف إعداداته، <code>retro.json</code>، يحفظ اختياراتك ولا يحفظ صوتًا أبدًا. ويُصفّر <em>مسح كل شيء</em> الدقائق التي يحتفظ بها ويعيد الذاكرة. ويسجّل الاختصار العام مفتاحًا واحدًا لدى نظام التشغيل، ما دام مفتاح تبديله مفعّلًا فقط؛ ولا يُقرأ أي مفتاح آخر تكتبه.","changelog.9f3a2f272e06":"<strong>فهرس البحث عن المتشابه يحفظ ما هو الصوت، لا الصوت نفسه أبدًا.</strong> إنه ملف واحد في مجلد بيانات Oscillate: لكل صوت مساره الكامل وحجمه وتاريخه، وبصمات (hashes) لبايتاته ولصوته، وقياسات تقريبية لجهارته وطيفه؛ ولكل حلقة إيقاعها وسرعتها وأدنى نوتة في كل ضربة. لا يُحفظ فيه أي صوت، ويُقرأ عند استرجاعه على أنه غير موثوق، مع التحقق من كل طول قبل حجز أي ذاكرة. والبحث والاستماع و<em>ضع على هذه الطبقة الملف الذي استمعت إليه في المستكشف</em> في Grain Layers لا تفتح أبدًا إلا ملفًا تحت المجلدات التي أضفتها.","changelog.915d977e99d5":"<strong>صار المشروع يستطيع حمل صوت طبقة، ويُفحص لأجل ذلك.</strong> طبقة Grain Layers المحفوظة <em>داخل المشروع</em> تُكتب في ملف المشروع؛ وفتح المشروع يقرأ ذلك الصوت من الملف نفسه لا من أي مكان آخر، والجزء الذي يدّعي أكثر مما يحويه يُرفض قبل حجز أي ذاكرة. وتخضع توزيعات المشروع ومشاهده للحدود نفسها التي تخضع لها مقاطعه.","changelog.1246fc93bca0":"أُصلح","changelog.8cbf5609dedb":"<strong>عنصر التحكم المعطّل لا يفعل شيئًا.</strong> في 0.12.0 كان الزر الرمادي لا يزال يرتفع وينخفض ويتوهّج تحت المؤشر. أما الآن فلا يُظهر عنصر التحكم المعطّل أي أثر للتمرير فوقه أو للضغط عليه، ولا يُبلغ أي شيء مما كان سيفعله، في أي مكان من التطبيق.","changelog.2263c6fa5d22":"<strong>تُفتح نافذة اللوحة من جديد بالحجم الذي تركتها عليه.</strong> بين حين وآخر كان المازج يعود في المكان الصحيح لكن أطول بمقدار 100 px؛ أما الآن فتُفتح النوافذ من جديد واحدة تلو الأخرى، والنافذة التي تكبر بعد وضعها تُعاد إلى حجمها.","changelog.04b1306d704e":"<strong>لم تعد قائمة المقطع مقطوعة.</strong> كانت حركة المسح التي تُفتح بها اللوحة تترك قناعها قائمًا بعد أن تنفتح، ما قد يقطع قائمة المقطع في التوزيع نفسه.","changelog.29675e838f56":"<strong>لم تعد قيمة خاطئة واحدة تعيد ضبط كل إعدادات التصدير.</strong> كان إعداد من النوع الخطأ في الملف الذي تحفظ فيه الإعدادات ▸ التصدير قيمها يعيد المجلد والصيغة والعمق والبقية إلى قيمها الافتراضية؛ أما الآن فلا يعود إلا ذلك الإعداد وحده.","changelog.3a479cc9ddc2":"<strong>فتح يوم آخر ينقلك إلى تبويب «اليوم».</strong> حين يكون يومٌ مفتوحًا بالفعل، كان فتح يوم آخر من الدورة يبقى حيث كان.","changelog.a95437716e5e":"**في مستعرض الملفات، لم يعد <em>لأعلى</em> واحدًا من الملفات.** كان يقع داخل قائمة الملفات، فكانت لوحة المفاتيح وقارئ الشاشة يعدّانه ملفًا منها؛ أما الآن فهو منفصل عنها.","changelog.ea34e6ae8231":"<span class=\"release__meta\"><span class=\"release__ver\">v0.12.0</span><time class=\"release__date\" datetime=\"2026-11-04\">2026-11-04</time></span>","changelog.329cfec3b9c7":"<strong>الدروس وأدوات الاستوديو الخاصة — لا توجد تنزيلات بعد.</strong> صارت خمس عشرة دورة تُدرِّس داخل Oscillate، يومًا بيوم، في لوحة خاصة هي لوحة الدروس: يُريك المسرح الطريقة، ثم يستمع إليك الدرس وأنت تعزف، على لوحة مفاتيح MIDI أو عبر مدخل الصوت لديك، بينما ينتظر مشروعك جانبًا في أمان. وإلى جانبها تأتي نقلات الطبقة والتمديد الذي يحفظ الطبقة على مقاطع الصوت، وكل بطاقة مؤثر مرسومة حيّة، ومُضاعِف وخافض، ومقبض حُبيبي وضاغط على كل شريط في الخلّاط، واقتراح على كل بطاقة، ونافذة الفحص النهائي التي تصنع ماسترًا لكل وجهة وتتيح لك سماع المزج كما يُسمع في هاتف أو سيارة. هذا الإصدار وحده يُتمّ درجتين من السلّم، 0.11.0 و0.12.0.","changelog.ac2db52dddb9":"<strong>لوحة الدروس، من Freally Handscore.</strong> عرض ▸ الدروس (Ctrl+8)، أو زرها الذي يحمل قبعة التخرّج في شريط العنوان، يفتح عمودًا خاصًا بجانب التوزيع فيه خمس عشرة دورة: البيانو، وقراءة النوتة، والإيقاع، وتدريب الأذن، والنظرية للمنتجين، وكتابة الأغاني، وكتابة الكلمات، والراب والتدفق، وتوزيع الأغنية، والمزج، وقرع الطبول بالأصابع، وطقم الطبول، والغيتار، والغيتار الكلاسيكي، والباص. كل دورة خريطة من الأقسام والأسابيع والأيام مع الوقت الذي تدرّبت فيه، و<em>متابعة</em> تستأنف من الخطوة نفسها التي توقفت عندها. وتبويبات اللوحة هي الدورات واليوم والسجل والكلاسيكيات. الدروس نفسها مكتوبة بالإنجليزية حاليًا؛ أما كل زر وتسمية ورسالة حولها فبكل اللغات الثماني عشرة، ومن اليمين إلى اليسار في العربية.","changelog.37b4f7453a04":"<strong>يُوضع مشروعك جانبًا أثناء تعلّمك.</strong> يعمل الدرس في مشروع خاص به، بمسارات حقيقية على آلات Oscillate نفسه يعزفها شريط النقل ويتبعها المسرح. أما مشروعك وتغييراته غير المحفوظة وسجل التراجع فيه فتُوضع جانبًا دون أن تُمس، وشريط يمتد عبر اللوحة يقول ذلك؛ و<em>العودة إلى مشروعي</em> تعيده تمامًا كما كان، وكذلك يعيده إنشاء مشروع جديد، وفتح مشروع، ودخول غرفة، والخروج من التطبيق. وينتظر الدرس ما دمت تشارك في غرفة.","changelog.953ff1f65d1e":"<strong>اليوم، مشغّل الأيام.</strong> تُعزف خطوات اليوم على المسرح: راقب اليدين، ثم اعزف المفاتيح التي يضيئها على لوحة مفاتيح MIDI بينما ينتظرك؛ و<em>على الإيقاع</em> يعدّ لك مازورة قبل البدء ويحكم على لقطتك مازورةً بمازورة؛ و<em>اعزف كاملًا</em> يطلب المقطوعة من أولها إلى آخرها؛ وتمارين الأذن والنظرية تسأل وأنت تجيب على المفاتيح. تدرّب على يد واحدة بينما يعزف المسرح الأخرى، وكرّر أي مازورات تشاء، واصعد سلّم السرعة حتى سرعة اليوم؛ ثلاث محاولات ناجحة متتالية تُنجح اليوم، وما تعلّمته يعود إليك حين يحين وقت مراجعته. ويضيء المسرح المفاتيح، أو زند الغيتار، أو لوحات الطبول التي يطلبها الدرس.","changelog.316226b27a80":"<strong>أرني.</strong> يعزف <em>أرني</em> الخطوة على المسرح قبل أن تجرّبها، واليدان عن قرب، بنصف السرعة أو بثلاثة أرباعها أو كاملة، مكرّرًا المازورات التي تختارها، ولا يستمع إلى شيء؛ و<em>العودة إلى الخطوة</em> تعيدك إليها.","changelog.67a53511787c":"<strong>القراءة بصوت عالٍ.</strong> يقرأ الدرس نفسه لك بأصوات حاسوبك نفسه، إذ لا يأتي أي صوت مع Oscillate، ويضيء كل كلمة وهو يقرؤها. في شريط القارئ ترجيع، وتشغيل وإيقاف مؤقت، وإيقاف، وتقديم سريع، وسرعة من 0.5× إلى 2×، واختيار الصوت، وساعة للقراءة، ويعمل Space وShift+← أو Shift+→ ما دام التركيز في اللوحة. وهي معطّلة حتى تفعّلها، ويُحفظ اختيارك؛ وعلى حاسوب لا صوت مثبّتًا فيه، يقول الشريط ذلك.","changelog.2de5fcb18e84":"<strong>دورات الإنتاج تفتح أدوات Oscillate نفسه.</strong> تعمل كتابة الأغاني وكتابة الكلمات والراب والتدفق وتوزيع الأغنية والمزج في مشروع الدرس: الأغنية في التوزيع وأقسامها علامات، والكلمات على مسار الكلمات وشبكة الإيقاع الخاصة به، والحلقة على خلّاط Oscillate نفسه، والدفتر صفحةً في لوحة الدروس. وتأتي أغانيها وحلقاتها الأولى مع التطبيق، صنعها محرّك Freally MIDI Master مرة واحدة؛ ولا يُولَّد شيء أثناء تعلّمك. وأهداف خطوة المزج (القمة، والجهارة، والقمة الحقيقية، وجهارة الصوت الرئيسي نفسه) تُقاس على مزجها بعد تصييره، و<em>أدِّ الراب</em> في الراب والتدفق يسمع لقطة راب عبر مدخلك، دون أن يسجّلها، ويقيس توقيت كل مقطع لفظي مقابل الموضع الذي وضعته فيه.","changelog.e562f651546c":"<strong>دروس تستمع.</strong> فعّل <em>الاستماع</em> في دورة فيسمعك الدرس عبر المدخل الذي يسجّل منه Oscillate، على جهاز الصوت المختار في الإعدادات ▸ الصوت، مدخلًا واحدًا أو زوج ستيريو، ويحكم على ما يسمعه: النغمات وتوقيتها، والأكوردات، وضربات طقم الطبول، ومقاطع الراب، مميَّزةً عن نقرات المترونوم نفسه. واللقطة المسموعة بهذه الطريقة تقول إنها <em>قُيِّمت بالأذن</em>. و<em>المدخل…</em> في شريط الدرس يُظهر المدخل ومستواه والكورد الذي يسمعه وموالفًا ومعايرة زمن الاستجابة، ويُضاء ضوء طوال استماع أي شيء، وفي ذلك الوقت فقط.","changelog.8065bd36868b":"<strong>موالف ومعايرة لزمن الاستجابة.</strong> يُظهر الموالف النغمة التي تعزفها وكم سنتًا تنحرف، مقابل A4 من 415 إلى 466 Hz، مع أقرب وتر مطلق في الغيتار أو الباص. وتعزف المعايرة ثماني نقرات وتستمع إليها، مُعادةً عبر كابل، أو من سماعاتك إلى الميكروفون، أو بالتصفيق معها، وتحتفظ بالتأخير الذي قاسته لذلك المدخل وحده، فيقع ما تعزفه حيث عزفته؛ وحتى ذلك الحين، يستخدم الدرس تقدير Oscillate نفسه.","changelog.8652ebf2415a":"<strong>المراقبة.</strong> مفتاح <em>المراقبة</em> في شريط الدرس يتيح لك سماع نفسك أثناء استماع الدرس، والغيتار أو الباص عبر Guitar Amp. وهو معطّل افتراضيًا، كي لا يرتدّ صوت الميكروفون عبر سماعاتك، ويُحفظ لكل دورة؛ وهو يغيّر مشروع الدرس، لا مشروعك أبدًا.","changelog.c89ae4f5ac3a":"<strong>لا يُحفظ شيء مما تعزفه.</strong> يحدث الاستماع على هذا الحاسوب، وفقط ما دام الضوء مضاءً: لا يُسجَّل أي صوت ولا يُحفظ ولا يُرسل. وكل ما يحتفظ به ملف إعدادات صغير: المدخل الذي اخترته، وA4 وأوتار الموالف لديك، ومفتاحا <em>الاستماع</em> و<em>المراقبة</em> لكل دورة، ومعايرة كل مدخل.","changelog.f735c56f78c4":"<strong>ملاحظات تقول ما يجب إصلاحه.</strong> بعد كل لقطة يذكر الدرس ثلاثة أمور على الأكثر، الأعلى كلفةً أولًا، ولكلٍّ منها مازورته ونبضته وطريقة إصلاحه، بلغتك. وفي دورات الإنتاج، يمكن تعليم هدف أخطأته عمدًا بأنه <em>مقصود</em> فيتوقف احتسابه.","changelog.0a8fd7218c37":"<strong>السجل وملف الأعمال.</strong> يُظهر السجل تقدّمك ووقت تدرّبك والأغنية التي تعمل عليها عبر الدروس: نسخها المسمّاة مع ما تغيّر بينها (واستعادة إحداها خطوة تراجع واحدة)، وكل صفحة من الدفتر، تفتح كلٌّ منها يومَها عند خطوتها، وورقة اللحن الخاصة بها، التي تُفتح في لوحة النوتات وبصيغة PDF. ويُحفظ كل ذلك في مجلد بيانات Oscillate نفسه. وإذا كان Freally Handscore على هذا الحاسوب، يُنقل تقدّمك وملف أعمالك والكلمات التي احتفظت بها في قاموس الكلمات فيه في المرة الأولى، مرة واحدة فقط، ويقول Oscillate ذلك؛ ولا تُغيَّر ملفات Handscore نفسه أبدًا.","changelog.68b193b60b2e":"<strong>الكلاسيكيات والمقاطع.</strong> يضم تبويب الكلاسيكيات أغاني Handscore الـ62 من الملك العام، مع اعتماداتها، ومقاطعه، ويمكن البحث فيها مع علامات الحروف أو بدونها. افتح إحداها مادةً للدرس على المسرح، أو مساراتٍ في مشروعك أنت في خطوة تراجع واحدة. ولا يمكن أن يغادر Oscillate من الأغنية الكلاسيكية سوى أكورداتها: فكل سحب إلى الخارج (مقبض المسار، ومقبض التوزيع، ومقبض شريط النوتات، و<em>اسحب الكل</em>) يرفض لحنها ولحنها المقابل وخط الباص ويقول السبب، وتبقى العلامة مع تلك المسارات عبر إعادة التسمية والتراجع والحفظ.","changelog.0f01b6fe1544":"<strong>نقلات الطبقة على مقاطع الصوت.</strong> في محرّر الصوت، اسحب عبر جزء من الشكل الموجي، واضبط أنصاف النغمات (من −12 إلى +12) والسنتات (من −50 إلى +50) واضغط <em>انقل الطبقة</em>: تنتقل النغمة المغنّاة درجةً كاملة دون أن تصير كصوت السنجاب، لأن فورمانتاتها محفوظة، ويحتفظ المقطع الاستريو بصورته. يُحسب النقل في الخلفية مع شريط تقدّم، ثم يحلّ خطوةَ تراجع واحدة؛ ويُرسم شريطًا تحت الشكل الموجي، و<em>امسح نقلات الطبقة</em> تزيلها كلها، ولا يتغيّر التسجيل نفسه أبدًا. ويسمعه التشغيل وكل تصدير وكل من في الغرفة. ويظل الشكل الموجي يرسم المقطع كما سُجِّل.","changelog.0e16fde64d9e":"<strong>تمديد يحفظ الطبقة.</strong> صار <em>ملاءمة الإيقاع ▸ تمديد (يحفظ الطبقة)</em>، الذي كان معطّلًا حتى الآن، يعمل: يتبع المقطع إيقاع علامات الالتواء الزمني فيه دون أن تتحرك طبقته، الطبول والأكوردات كما الصوت المنفرد. يُصنع في الخلفية بمجرد أن تختاره أو تغيّر مازوراته، ويُحفظ ويُشارَك ويُسمع في كل تصدير كأي تعديل؛ والمقطع المعكوس أو المتكرر يقول لماذا لا يمكن تمديده.","changelog.1f1daa435d8e":"<strong>كل بطاقة مؤثر مرسومة حيّة.</strong> ما دامت البطاقة على الشاشة فهي ترسم ما يفعله جهازها بالصوت المارّ عبره: منحنى EQ فوق طيف الصوت الداخل والخارج؛ ومنحنى المستوى للضاغط أو المحدِّد أو البوابة والصوت يسير عليه، وخفض الكسب فيه يتمرّر، وإبرة حيّة؛ ونقطة المُشبِّع على منحناه؛ والمجال الاستريو للمضاعِف والكورس والغسلة الحُبيبية؛ وأصداء التأخير وذيل الريفيرب مع اضمحلاله المقيس؛ وخفض الخافض الآتي من مفتاحه. والمحلّل وإبرة خفض الكسب، اللذان كانا يقولان <em>ليس حيًّا بعد</em>، يتحركان الآن. والبطاقة المخفية لا تكلّف خيط الصوت شيئًا يُذكر، ولا شيء مما تصدّره يرسم في بطاقة. ومع تقليل الحركة تتحدّث القراءات ولا يتمرّر شيء.","changelog.93c41d273176":"<strong>Oscillate Doubler، من Freally Handscore:</strong> جزء يُغنّى أو يُعزف من جديد بما يصل إلى أربعة أصوات تأتي خلفه بقليل، كلٌّ منها منحرف ببضعة سنتات وبضعة أجزاء من ألف من الثانية وينجرف على طريقته البطيئة، موزّعةً عبر المجال الاستريو. وبذرة الانجراف مأخوذة من المشروع، فيكون التصدير الملف نفسه في كل مرة، ومقبض البذرة يمنح مضاعِفَين في أغنية واحدة انجرافًا مختلفًا لكلٍّ منهما. والمزج عند الصفر يترك الصوت تمامًا كما كان. أربعة إعدادات مسبقة: Tape Double وWide Double وStack وSubtle.","changelog.3d6134de7c78":"<strong>Oscillate Ducker، من Freally Handscore:</strong> مسار يُخفَض صوته ما دام مسار آخر يعزف، كأن يفسح الباص المجال للكيك. اختر المفتاح في <em>‏Sidechain من</em> على بطاقته: يُؤخذ بعد أجهزة ذلك المسار وقبل منزلقه، فالكيك المكتوم يظل يُطلقه، ويصل متزامنًا مع الباص مهما أضافت أجهزة أيٍّ من المسارين من تأخير. العمق والعتبة والهجوم والإمساك والتحرير ومرشح تمرير مرتفع على المفتاح؛ وثلاثة إعدادات مسبقة: Kick Pump وGentle Duck وVoice Over. أعد تسمية مسار المفتاح فيبقى المفتاح؛ واحذفه فتقول البطاقة إن المفتاح قد ذهب، ويعزف الباص دون أن يُمس حتى تختار غيره. <strong>ثلاثة وسبعون من التسعة والسبعين مبنية</strong> الآن، ومعها اثنان وثلاثون مؤثرًا أساسيًا.","changelog.00ebccea7a17":"<strong>مقبض حُبيبي وضاغط على كل شريط.</strong> يكسب كل شريط في الخلّاط مقبض حُبيبي من Freally Handscore وضاغط الشريط الخاص به، بجانب منخفض ومتوسط ومرتفع وغرفة وصدى وحرارة وتعديل الطبقة. حُبيبي عند 0 % يترك الصوت تمامًا كما كان، ويبعثر كل شريط على طريقته، ويُصيَّر متطابقًا في كل مرة. والضاغط خارج مسار الإشارة حتى تضغط زره <em>C</em>، ثم تكون له العتبة والنسبة والهجوم والتحرير والتعويض، مع ضوء يُضاء عند نصف ديسيبل من خفض الكسب. وكل مقبض يُحفظ، ويقبل الأتمتة، وتغييره خطوة تراجع واحدة، وزر المقابض في الخلّاط يطويها مع البقية. ومقبض الماستر الوحيد هو حُبيبي.","changelog.1750f070ec46":"<strong>نافذة الفحص النهائي.</strong> عرض ▸ الفحص النهائي (Ctrl+9)، أو زرها في شريط العنوان، يفتح نافذة خاصة بها، مثل الخلّاط؛ ويثبّتها ⇲ تحت الخلّاط. تسرد النافذة الوجهات (Spotify وApple Music وYouTube وAmazon Music وTidal وDeezer وSoundCloud وCD ونادٍ ليلي وEBU R 128 وATSC A/85)، ولكلٍّ منها جهارتها وسقفها وملفها، وهل الرقم من الخدمة نفسها أم هو الافتراضي في Oscillate حيث لا تنشر الخدمة رقمًا، وأين ومتى قُرئ. علّم ما تريده منها (ويُحفظ اختيارك على هذا الحاسوب) فيصنع <em>تصدير نسخ الماستر</em> ماسترًا لكلٍّ منها من المزج نفسه، في مجلد خاص بها داخل مجلد الإعدادات ▸ التصدير: كلٌّ منها يقع ضمن 0.5 LU من هدفه وتحت سقفه عبر True-Peak Limiter، مقيسًا من ملفه. ولا شيء يَعِد بأن خدمةً ما ستقبل ملفًا.","changelog.dcc02d2a0030":"<strong>فحصا السيارة والهاتف، و«استمع كأنه».</strong> يُفحص كل ماستر كما سيعزفه مكبّر صوت الهاتف ومقصورة السيارة (الباص الذي تحمله توافقياته، والمزج بالأحادي، وعرض الترددات المنخفضة، والطنين وتراكم الترددات المتوسطة المنخفضة) فإما أن يصمد أو يقول ما يجب تغييره. وفي تبويب السماعات، يُسمعك <em>استمع كأنه</em> ما يصل إلى سماعات المراقبة كما يسمعه هاتف أو سيارة أو حاسوب محمول أو سماعة صغيرة أو سماعات أذن داخلية، كلٌّ منها بمستوى مُعادَل ومع انتقال متداخل، ومعها <em>مسطّح</em> للمقارنة A/B. وهو لأذنيك وحدك: لا شيء مما يُسمع عبره يصل إلى تصدير أو دمج أو ماستر، وكل تشغيل للتطبيق يبدأ مسطّحًا.","changelog.a9218b2ebd52":"<strong>درج الجهارة.</strong> سمِّ علاماتك Intro أو Verse أو Pre-chorus أو Chorus أو Bridge أو Outro (بالإنجليزية)، فيقيس تبويب درج الجهارة كل قسم، من علامة إلى التالية، وحده مقابل درجته، بهدف وسماحية، ويقيس كل لازمة مقابل المقطع الذي يسبقها بهامش تحدده أنت. ويرسم الدرجات فوق الجهارة قصيرة المدى للأغنية مع كل رقم في جدول؛ وتُحفظ أهدافه على هذا الحاسوب.","changelog.d4c91aa1d3a3":"<strong>فحص المواصفات.</strong> يفحص تبويب فحص المواصفات ماسترًا، أو أي ملف تختاره، مقابل هدف تسليم (بث رقمي بجهارة عالية أو هادئة، أو EBU R 128، أو البث الإذاعي الأمريكي، أو CD، أو ملف WAV لموزّع، أو هدفك الخاص) وفق ثلاث عشرة قاعدة، من الجهارة المتكاملة والقمة الحقيقية إلى معدل العينات، والصمت في كل طرف، والعينات المقصوصة المتتالية. وكل قاعدة إما تنجح أو تفشل أو تحذّر، مع هامشها وأبسط إصلاح لها، ويُعرض تغيير واحد في الكسب يستوفي كل قواعد المستوى، أو يقول الفحص إنه لا يوجد تغيير كهذا. والأهداف قابلة للتعديل ومؤرَّخة (<em>علّمه كمُتحقَّق منه اليوم</em>)، وتُعرض بأنها غير متحقَّق منها بعد 180 يومًا، ويُحفظ التقرير بصيغة HTML أو JSON أو PDF.","changelog.ab8c6b35f5a4":"<strong>اقتراح على كل بطاقة مؤثر.</strong> يستمع <em>اقتراح</em> على كل بطاقة من بطاقات مؤثرات Oscillate نفسه إلى ما يصل إلى البطاقة (المسار وحده، حتى تلك البطاقة) ويقترح إعدادات في جمل مكتوبة، قارئًا دور الجزء من اسم المسار: فالـ EQ يسوّي رنينًا أو يزيل الهدير أو العكارة، والضاغط يأخذ مقدار الخفض المناسب للدور، وDe-Esser يتمركز على الصفير المقيس، والتأخير أو الغرفة يتزامنان مع الأغنية، وGain and Width يبقى آمنًا بالأحادي. و<em>تطبيق</em> يضبط ذلك كله في خطوة تراجع واحدة. والأجهزة التي عملها مسألة ذوق تقول ذلك ولا تقترح شيئًا، ولمقابض منخفض ومرتفع والضاغط في الشريط زر <em>اقتراح</em> خاص بها أعلى رف المسار المحدد؛ أما الإضافات المستضافة فلا اقتراح لها. ويعمل بالقياس وبقواعد مكتوبة، دون ذكاء اصطناعي، فيحصل المزج نفسه على الاقتراح نفسه في كل مرة.","changelog.0c3173aff29d":"<strong>امزجه من أجلي.</strong> في نافذة الفحص النهائي، يضبط <em>امزجه من أجلي</em> بطاقات كل جزء غير مقفل وغير مكتوم على اقتراحها ومستواه بحسب دوره، ثم يُنزل الماستر على أول وجهة معلَّمة عبر True-Peak Limiter في نهاية سلسلة الماستر نفسها؛ وتراجع واحد يعيد المزج كله. وتُترك المسارات المقفلة والمكتومة كما هي، ويُطفأ مقبض حُبيبي في الماستر إن كان مفعّلًا، ويقول التقرير ما فعله. وليس لسلسلة الماستر رف خاص بها بعد: يظهر محدِّدها في التقرير ويزول بالتراجع أو بـ<em>امزجه من أجلي</em> مرة أخرى.","changelog.e2c4c3ac3a03":"<strong>النوافذ تُفتح من جديد كما تركتها.</strong> نوافذ الخلّاط ومستكشف الملفات والمحرّر والغرفة والفحص النهائي التي كانت مفتوحة عند الخروج تعود في التشغيل التالي، حيث تركتها، بمجرد ظهور النافذة الرئيسية؛ والنافذة التي تُركت على شاشة لم تعد موجودة تُفتح على شاشة موجودة. ويُحفظ هذا السجل كلما فُتحت نافذة أو أُغلقت، فيصمد أمام الانهيار.","changelog.1b5c3133a037":"<strong>تصدير بأي طول.</strong> يكتب ملف ▸ تصدير مجلد مرافق… مزجه ومساراته المنفصلة، ويكتب الفحص النهائي كل ماستر، إلى القرص أثناء تصييرها، فتُصدَّر الأغنية التي تتجاوز عشر دقائق كاملةً. ويبقى حد العشر دقائق للسحب إلى الخارج، وتتوقف ملفات WAV وAIFF عند 4 GB.","changelog.1a96cd093f4f":"<strong>واحد من كل نوع، والأفضل في داخله.</strong> حيث كان لدى كلٍّ من Oscillate وFreally Handscore مؤثر من النوع نفسه، قيس الاثنان جنبًا إلى جنب، واحتفظ كل جهاز باسمه وواجهته وإعداداته المسبقة مع الصوت الأفضل في داخله. يرسم Precision EQ وFour-Band EQ المنحنيات نفسها، والمقبض الذي يُحرَّك أثناء عزف الصوت ينساب الآن على مدى 30 ms بدل أن يقفز، فلا يتشظّى المسح بعد الآن؛ ويَنساب عرض Gain and Width أيضًا، ويمرّ وسط الصورة دون أن يُمس. ومقياس الجهارة في الخلّاط والفحص النهائي ونسخ الماستر صارت تقرأ مقياسًا واحدًا، ضمن 0.02 LU من إشارات اختبار EBU.","changelog.2ca6b9df7119":"<strong>الجلسات المزدحمة تعزف بحمل أخف، والتصدير ينتهي أسرع.</strong> صارت المسارات المجمِّعة ومسارات الإرجاع تُصيَّر الآن عبر أنوية معالجك بجانب المسارات، والمسار الذي عليه خافض يبدأ ما يسبقه بالتوازي مع مفتاحه، وDigital Delay يؤدي جزءًا من عمله فقط ما دام زمنه ثابتًا. وعلى أكثر جلسة ازدحامًا نختبرها، يجري تصدير المزج أسرع بأكثر من أربع مرات، ونسخ الماستر أسرع بنحو ست مرات، وكلاهما موزّع على الأنوية ومتطابق مع التصيير على نواة واحدة.","changelog.e1eb319dfd66":"<strong>الآلات المشتركة مع Freally MIDI Master تنتقل إلى أحدث إصدار منه.</strong> يَنفتح مرشّح Bright Reed قليلًا، كما في MIDI Master، والأغنية المسحوبة من MIDI Master على الإصدار نفسه يحطّ كل جزء منها على الصوت نفسه الذي عزفه هناك.","changelog.a086436bf07c":"<strong>السحب إلى الخارج على Linux.</strong> صار MIDI المسار أو صوته يُسحب الآن خارج Oscillate على Linux أيضًا، من كل مقبض سحب، كما على Windows وmacOS؛ وما يُسحب ينتظر في مجلد لا يقرؤه أحد غيرك.","changelog.4a30a62f9b42":"<strong>الكورد الذي يُضرب مجددًا لحظة انتهائه يُعزف كاملًا.</strong> حين كان كورد يُترك ويُضرب من جديد على التكّة نفسها، كانت نغمة قد تُضرب قبل تحريرها فتنقطع في الحال؛ أما الآن فتأتي عمليات التحرير أولًا، ثم يُضرب الكورد من أدنى نغمة صعودًا، في التشغيل وفي وضع الأنماط وفي التصدير. ونغمتان من مجموعة خنق واحدة تُضربان معًا تتركان الأعلى منهما مسموعة، في كل مرة.","changelog.a4ae782328a5":"<strong>True-Peak Limiter يحافظ على سقفه.</strong> عند ضبطه على −1 dBTP، كان يُمرّر قممًا تصل إلى −0.91 dBTP؛ أما الآن فيقرأ القمة الحقيقية بفرط التعيين الخاص بمقياس الجهارة نفسه ويستهدف 0.02 dB داخل السقف، فيستقر عند −1.02 dBTP بـ 4× و8×، ولا يضيف زمن استجابة سوى نظرته المسبقة.","changelog.8fb884be103d":"<strong>سلسلة مؤثرات الماستر نفسها تعزف.</strong> كل مشروع كان يحتفظ بسلسلة مؤثرات للماستر، ولم يكن شيء يعزفها؛ أما الآن فتعزف بعد مجموع الماستر وقبل منزلقه. والمشروع الذي صُنع قبل هذا الإصدار فيه سلسلة فارغة ويبدو صوته كما كان.","changelog.e18d492281be":"<strong>الخروج يُغلق كل النوافذ.</strong> كانت نافذة خلّاط أو مستكشف ملفات أو محرّر أو غرفة مخفية تُبقي Oscillate يعمل دون أن يُرى بعد إغلاق نافذته الرئيسية، فلا يفعل التشغيل التالي شيئًا. أما الآن فإغلاق النافذة الرئيسية يحفظ موضع كل نافذة ويغلقها جميعًا.","changelog.569c159e4ed3":"<strong>سطر الكلمات يحتفظ بكلماتك غير المُرسَلة.</strong> حين يُنقل السطر الذي تحرّره بفعل شخص آخر في الغرفة، أو بالتراجع، أو بالاستيراد، يتبعه المحرّر الآن بكلماتك؛ وحين يُحذف، تُحفظ كلماتك، والتراجع الذي يعيد السطر يفتحه من جديد بها. وفي السابق كان المحرّر يُغلق وتضيع الكلمات.","changelog.208739ca3b60":"<strong>يرفع الكسب التلقائي في Precision EQ القطعَ 24 ديسيبل على الأكثر.</strong> مع تشغيل Auto Gain، كان مرشّح القطع العالي أو المنخفض يعوّض ما أزاله بما يصل إلى 37 ديسيبل (قطع عالٍ عند 100 هرتز)، وهو صوت عالٍ بما يكفي ليؤذي؛ يتوقف التعويض الآن عند 24 ديسيبل، ويبقى مقبض Output يصل إلى ما يقوله تمامًا.","changelog.043185ecadf0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.10.0</span><time class=\"release__date\" datetime=\"2026-11-02\">2026-11-02</time></span>","changelog.34fbbfb4cefd":"<strong>النوتات — لا توجد تنزيلات بعد.</strong> صار أي مسار MIDI يُقرأ الآن نوتةً موسيقية مدوَّنة في لوحة خاصة هي لوحة النوتات، مع تدوين TAB للغيتارات والباصات، وبيان اليد أو القدم لكل ضربة في الطبول، وكلمات مسار الكلمات تحت النوتات، وتُصدَّر الأغنية كلها ملفَّ PDF أو تُطبع. وإلى جانبها يأتي محرّر كلمات بقاموس وقوافٍ ونبر وإيقاع، وقفل على كل مسار، وتوازن الصوت ↔ MIDI، ورف أنماط مصقول كما صُقل نظيره في FL Studio، ونافذة رئيسية تُفتح نظيفة.","changelog.8db786d68913":"<strong>لوحة النوتات.</strong> عرض ▸ النوتات (Ctrl+7)، أو زرها الخاص في شريط العنوان، يُظهر لوحة تحت المسرح تدوّن أي مسار MIDI نوتةً موسيقية: مدرج بمفتاح صول أو بمفتاح فا أو مدرج مزدوج يُختار بحسب مدى المسار، والميزان والمقام يتغيّران حيث يتغيّران في المشروع، وعلامة تمرين عند كل علامة قسم، وسكتات متعددة المازورات للمازورات الصامتة، وصفحات كالورق تحمل اسم المشروع و<em>صفحة n من N</em>. الورقة عرضٌ لمسارها: تعدّل النوتات في لفّة البيانو فتتبعها الورقة. تُدوَّن مئتا مازورة في نحو ربع ثانية، ولا يُحمَّل شيء من محرّك التدوين حتى تُعرض أول ورقة.","changelog.c333a04570c9":"<strong>تدوين TAB وأوراق الطبول.</strong> يُدوَّن مسار الغيتار بمفتاح صول منخفضًا أوكتافًا فوق TAB بستة أسطر، مع مخططات الأكوردات وأسهم الضرب على الأوتار؛ والباص فوق TAB بأربعة أسطر، أو بخمسة على باص بخمسة أوتار. والدساتين هي نفسها التي تعزف عليها أيدي المسرح. ويكتب مسار الطبول R أو L أو RF أو LF تحت كل ضربة.","changelog.904679c05d35":"<strong>الكلمات تحت النوتات.</strong> تُدوَّن كلمات مسار الكلمات تحت نوتاتها، والمقطع الممدود بـ <code>_</code> يرسم خط امتداده.","changelog.81d8f60280bd":"<strong>شريط النوتات والطاولة.</strong> على طول أعلى لوحة النوتات، تأتي شارة المدونة الكاملة أولًا، ثم شارة لكل مسار MIDI فيه نوتات، بترتيب التوزيع. كل شارة تفتح ورقتها، وتكتم مسارها وتُفرده كما يفعل المازج، وتقفله، ولها على Windows وmacOS مقبض سحب يُخرج MIDI المسار من Oscillate؛ ومقبض المدونة الكاملة، <em>اسحب الكل</em>، يسحب مسار كل ورقة. وتحت الشريط، تعرض الطاولة الصفحة الأولى من كل ورقة: انقر على إحداها لتقرأها.","changelog.8c17b512f72a":"<strong>القارئ.</strong> ما دامت لوحة النوتات ظاهرة، تفتح المفاتيح من 1 إلى 9 الأوراق التسع الأولى بكامل العرض، و1 هو المدونة الكاملة، والمفتاح نفسه مرة أخرى أو Esc يعيدك. تنقلب الصفحات من تلقاء نفسها أثناء عزف الأغنية، والنوتات المضاءة هي دائمًا المسموعة (المسار المكتوم لا يضيء شيئًا)، وقائمة أقسام تقفز إلى كل قسم. ويمكن تغيير كل مفتاح في الإعدادات ▸ الاختصارات.","changelog.fa43705c3059":"<strong>النوتات بصيغة PDF، أو مطبوعة.</strong> ملف ▸ تصدير النوتات بصيغة PDF…، أو زر PDF في شريط النوتات، يحفظ ملف PDF واحدًا بمقاس A4 حيث تختار: صفحة غلاف، والاعتمادات، وورقة كل مسار، والمدونة الكاملة. تذكر صفحة الغلاف المقام والإيقاع والميزان (كل تغيير مع مازورته)، والمازورات والنوتات، إجمالًا ولكل مسار. وتسمّي الاعتمادات الكتّاب والمنتجين من سجل المشروع نفسه، بالأسماء المضبوطة في الإعدادات ▸ التعاون ▸ <em>اسمك داخل الغرفة</em>. وملف ▸ طباعة النوتات…، أو زر طباعة، يرسل الصفحات نفسها إلى مربع حوار الطباعة في نظامك، على ورق A4 أبيض في أيٍّ من السمتين.","changelog.34db14f3968c":"<strong>حامل النوتة في المسرح يعرض الورقة</strong> الخاصة بالمسار الذي يتبعه المسرح، فيقلب صفحاتها بنفسه ويضيء النوتة التي تعزفها اليدان.","changelog.eedc16f5e0ac":"<strong>الكلمات مع قاموس.</strong> يُكمل محرّر الأسطر في مسار الكلمات الكلماتِ من قاموس إنجليزي يضم 327,000 كلمة بمفتاح Tab، ويُبقي Shift+Tab أو ✓ الكلمة كما كتبتها، على هذا الحاسوب. ومفتاح تبديل <strong>التهجئة</strong> يصحّح الكلمة المكتوبة خطأً عند انتهائها، وBackspace مباشرة بعد ذلك يعيدها. وهو مفعّل افتراضيًا في الإنجليزية ومعطّل في اللغات الأخرى.","changelog.84697cddb821":"<strong>المقاطع على نوتاتها.</strong> <code>-</code> يقسم الكلمة إلى مقاطع و<code>_</code> يمدّ مقطعًا على النوتة التالية، و<em>قسّم</em> يضع كل مقطع على نوتته. ويُظهر كل سطر مدى ملاءمته لنوتاته (4/4، +2، −1)، والسطر الأطول من نوتاته يقول ذلك بدل أن يُقسَّم.","changelog.1a063c6e681b":"<strong>النبر والقوافي والإيقاع.</strong> تُعلِّم <em>علامات النبر</em> المقطع المنبور في كل كلمة، ويكتبه الملقّن بخط عريض. وتلوّن <em>القوافي</em> نهايات الأسطر بحسب القافية، وتعطي كل سطر حرفه في نظام قوافي قسمه (AABB، ABAB…)، وتَسِم العبارات المستهلكة بأنها شائعة. وتضع <em>شبكة الإيقاع</em> مقاطع كل مازورة على السادس عشر مع العدّ ومدى الانضباط والعَروض، ويقيس <em>أدِّ الراب</em> توقيت لقطة مسجّلة تحددها مقابل المقاطع الموضوعة، معلِّمًا كل مقطع بأنه مبكر أو متأخر.","changelog.0439610e6f48":"<strong>ورقة اللحن.</strong> زر في مسار الكلمات يفتح لحن المسار وكلماته ورموز الأكوردات في قارئ لوحة النوتات.","changelog.72e16178296c":"<strong>اقفل مسارًا.</strong> قفل على رأس كل مسار صوت وMIDI، وعلى شريطه في المازج، وعلى شارة ورقته. وما دام المسار مقفلًا، يُرفض كل تغيير على نوتاته ومقاطعه بجملة تسمّيه، أيًّا كان مصدره: لفّة البيانو، أو شبكة الإيقاع، أو الرف، أو التوزيع، أو ملف مُفلَت، أو التسجيل، أو التراجع؛ أما اللقطة التي كانت قيد التسجيل حين يأتي القفل فتصل مع ذلك. ويبقى مزجه حرًّا. ويُحفظ القفل مع المشروع، وهو خطوة تراجع واحدة، وفي الغرفة يصل إلى الجميع، فتُرفض من ذلك الحين التغييرات التي يجريها كل منهم بنفسه على المسار.","changelog.3f6496b8d90e":"<strong>توازن الصوت ↔ MIDI.</strong> منزلق في شريط النوتات يمزج مسارات الصوت في المشروع مقابل مسارات MIDI فيه: اليسار يعزف الصوت وحده، واليمين MIDI وحده، والوسط كليهما كاملين. ينساب دون طقطقات، ويُحفظ مع المشروع، ولا يحرّك منزلق أي مسار أبدًا؛ والتصدير والمسارات المنفصلة وتجميد المسارات تتجاهله. والنقر المزدوج يعيده إلى الوسط.","changelog.463a355353fb":"<strong>صار البان والضبط الدقيق للنغمة لكل خطوة مسموعين</strong> على Drum Machine وOne-Shot Sampler وMultisampler وPercussion Sampler، أثناء العزف وفي التصدير. أما Modelled Synth، الذي يعزف آلات المكتبة، وSection Player وLayer Rack فلا تعزفهما بعد، والإضافة تسمع كل خطوة في الوسط وبنغمتها الصحيحة.","changelog.b8ba10151223":"<strong>غيّر منظر المنصة من أي مكان.</strong> ما دامت المنصة ظاهرة، ينقلك Alt+V إلى منظرها التالي و Alt+Shift+V إلى السابق، أينما كنت تعمل.","changelog.51aa144b34b1":"<strong>عازف الطبول ينتعل حذاءً حقيقيًا.</strong> حذاء رياضي عالي الرقبة برباط، من قماش أسود على نعل مطاطي أبيض ومقدمة بيضاء، وأربطة بيضاء عبر عُرى معدنية حتى العقدة، فوق جوارب بيضاء، بدل حذاء داكن بسيط كان يضيع على السجادة.","changelog.a19019b8fb76":"<strong>النافذة الرئيسية تُفتح نظيفة:</strong> شريط النقل، ورف الأنماط مثبّتًا فوق التوزيع وبينهما فاصل، والتوزيع. يُظهر الرفَّ ويخفيه زرُّه في شريط العنوان، وعرض ▸ رف الأنماط، وCtrl+2؛ ولم يعد يحلّ محل التوزيع، واختفى زر التوزيع من شريط العنوان.","changelog.44f584847313":"<strong>المازج ومستعرض الملفات والمحرّر والغرفة تعيش في نوافذ خاصة بها،</strong> مخفيةً حتى يفتحها زرها في شريط العنوان، أو بندها في قائمة عرض، أو Ctrl مع رقمها. يُخفي ✕ النافذة، ويثبّت ⇲ اللوحة داخل النافذة الرئيسية، ويُخرج ⇱ اللوحة المثبّتة من جديد؛ ويُحفظ مكان كل لوحة على هذا الحاسوب. تُفتح نافذة اللوحة أول مرة بجانب النافذة الرئيسية، ثم تُفتح من جديد حيث تركتها. وتُفتح نافذة المحرّر أول مرة كبيرةً بما يكفي لشريط أدوات لفّة البيانو وأوكتافين ومسار الأتمتة ومساري لقطات. والتثبيت السابق للإصدار 0.10.0 ينتقل إلى هذا التخطيط مرة واحدة، محتفظًا بأحجام لوحاته، والجولة الإرشادية تُدخل مستعرض الملفات والمحرّر إلى النافذة الرئيسية ما دامت تشير إليهما.","changelog.14ef80e49e29":"<strong>رف الأنماط، مصقولًا كما صُقل نظيره في FL Studio.</strong> كل صف سطر واحد: ضوؤه (كتم المسار)، ومقبضا البان ومستوى الصوت (بان المسار ومنزلقه في المازج نفسه)، والوجهة التي يعزف إليها، واسمه وS، مع تحرير ووضع وتحريك لأعلى وإزالة أزرارًا صغيرة في نهايته. تأتي الخطوات في مجموعات من أربع، تتناوب في تظليلها، وكل خطوة مضاءة ساطعة بقدر شدّتها. والخطوات الواقعة بعد نهاية النمط باهتة: اضغط عليها أو اسحب عبرها، أو اسحب المقبض على الخطوة الأخيرة، أو استعمل − و+ بجانب <em>الخطوات</em> لتغيير الطول، حتى 256 خطوة و16 مازورة. واللحن المكتوب في لفّة البيانو خارج شبكة الخطوات يظهر في صفه لفّةَ بيانو صغيرة؛ انقر عليه نقرًا مزدوجًا لتفتحه. انقر على اسم صف لترى رسمًا بيانيًا لشدة كل خطوة وبانها وضبطها الدقيق للنغمة واحتمالها ومدى شدتها، يُرسم أو يُكتب، وكل مسحة خطوة تراجع واحدة. ويضيف <strong>+</strong> في أسفل اليسار صف آلة جديدًا: مسار MIDI جديدًا بالآلة التي تختارها من رفوف المستعرض، في خطوة تراجع واحدة.","changelog.a46684dcbb1e":"<strong>الجودة التلقائية في المسرح تحكم بأبطأ إطاراتها</strong> لا بمتوسطها، فلا تخفّض التفاصيل إلا حيث يتعثّر الجهاز فعلًا، ولم تعد تخفّضها عند 52 إطارًا ثابتًا في الثانية.","changelog.d72c41d7cffa":"<strong>المسرح يعزف على macOS.</strong> يرسم جهاز Mac الأبعاد الثلاثية على بطاقة رسوميات حقيقية، فيعزف المسرح هناك مع الأغنية كما يفعل على Windows. أما على Linux فما زال ثابتًا، يرسم إطارًا لكل تغيير، ويقول السبب.","changelog.18c24a81e339":"<strong>سحب الأغنية كاملةً من Freally MIDI Master يمكنه أن يحمل صوت كل جزء.</strong> صار Oscillate يقرأ الإعداد المسبق الذي يحمله كل جزء حين تُسحب أغنية إليه من MIDI Master. وسيبدأ MIDI Master بكتابته في إصدار قادم؛ وحتى ذلك الحين تعزف أجزاء الأغنية المُفلَتة الأصواتَ الرئيسية لآلاتها، كما في السابق.","changelog.0440f7958ce1":"<strong>لا لوحة مفاتيح فوق طقم الطبول.</strong> افتح المنصة مباشرة على مسار طبول فيظهر الطقم وحده، دون لوحة مفاتيح بيانو عارية تطفو فوق الطبل الصغير.","changelog.1d9fe93e55f4":"<strong>عازف الطبول يمسك العصيّ.</strong> تُطبق كل يد على عصاها بكل أصابعها، والعصا ممتدة عبر راحة اليد كما يمسكها عازف الطبول، بدل أن يقرصها بين الإبهام والسبابة وبقية الأصابع مفتوحة.","changelog.6dbc52a85080":"<strong>الأصابع التي لا تعزف شيئًا تستقر على المفاتيح.</strong> بجانب الكورد، لم تعد الأصابع الخاملة في اليد ترتفع فوق المفاتيح أو تقف على مفتاح أسود أو تقفز مع كل نبضة.","changelog.845917250ea2":"<strong>لم يعد ثني طقم مزدحم يقطع الصوت.</strong> حين تثني عجلة طبقة الصوت إيقاعًا مزدحمًا في Drum Machine أو كوردًا كبيرًا في سامبلر، تتلاشى أهدأ الأصوات بعد الـ 32، كما في السامبلر الحقيقي، فلا ينقطع الصوت أبدًا.","changelog.420f580c3422":"<strong>منصة قصيرة تُظهر البيانو كله.</strong> اجعل المنصة قصيرة فتتراجع الكاميرا حتى تظهر لوحة المفاتيح واليدان وحامل النوتة كلها، في المنتصف.","changelog.88dda7027d59":"<strong>مسار Drums في المشروع الجديد مسار طبول:</strong> تقف عليه المنصة بطقم الطبول، لا ببيانو.","changelog.09d0ea47cefd":"<strong>يبقى شريط أدوات الترتيب ظاهرًا</strong> حين تجعل المنصةُ الترتيبَ قصيرًا، وتقع أيقونة مفتاح الكلمات في منتصف مفتاحها.","changelog.6de570ed34e4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.9.0</span><time class=\"release__date\" datetime=\"2026-10-31\">2026-10-31</time></span>","changelog.846db83f9221":"<strong>المسرح — لا توجد تنزيلات بعد.</strong> مسرح 3D تحت التوزيع يعزف أي مسار MIDI بأيدٍ على البيانو والغيتار والباص والطبول. وإلى جانبه تأتي آلة طبول، ومضخّم غيتار، ومستعرض الآلات بكل آلاته البالغة 1,648، ورف أنماط يعمل كما يعمل نظيره في FL Studio، وعجلات لوحة مفاتيح MIDI على كل آلة، ومقابض جديدة.","changelog.f5738fc842ef":"<strong>المسرح، من Freally Handscore.</strong> عرض ▸ المسرح (Ctrl+6) يفتح مسرحًا 3D تحت التوزيع. اختر مسار MIDI، أو دعه يتبع المسار المحدد، فتعزف أيادٍ نوتاته على آلته متزامنةً مع النقل: عبر تغيّرات الإيقاع، وحول التكرار، وأينما سحبت رأس التشغيل. التمرير فوق مسطرة الخط الزمني يعرض معاينة صغيرة للمسرح في تلك اللحظة. لا يُحمَّل المسرح إلا في أول مرة تفتحه، فيبدأ Oscillate بالسرعة نفسها كما كان. على macOS وLinux ينتقل المسرح إلى كل موضع جديد حين توقف التشغيل أو تقفز إلى موضع آخر أو تغيّر العرض، بدل أن يعزف مع الموسيقى، ويقول ذلك.","changelog.00de69a4fa5a":"<strong>أربعة بيانوهات على المسرح:</strong> آلات المصنع Grand Piano وAcoustic Piano وUpright Piano وHonky-Tonk Piano يظهر كلٌّ منها بهيئته، وأي آلة أخرى تُعزف على Grand Piano. يمكنك اختيار بيانو آخر من أجل المظهر. ويمكن تسمية المفاتيح (المفاتيح البيضاء، أو كل المفاتيح، أو لا شيء)، وترقيم الأصابع 1–5.","changelog.29f8c7f4c6b7":"<strong>غيتارات وآلات باص على المسرح.</strong> آلات المصنع Guitar وNylon Guitar وElectric Guitar وMuted Guitar، وPluck Bass وSlap Bass وUpright Bass، يظهر كلٌّ منها بهيئته، بيدين تضربان الأوتار وتنقرانها، مع الانزلاقات والطرق على الأوتار وسحبها (hammer-on وpull-off). وElectric Guitar الموصول بـGuitar Amp يظهر غيتارَ روك. اختر ما يعزفه الغيتار (الأكوردات، أو اللحن، أو اللحن المضاد)، و4 أو 5 أوتار للباص، وأسلاك الدساتين، وعازفًا أعسر. ينتقل خط الباص أوكتافًا للأعلى أو للأسفل حيث تحتاج الرقبة ذلك. <em>المرافقة</em> تُفرد المسار المتتبَّع أو تدع المسارات الأخرى تعزف معه. ويمكنك إظهار أي آلة من هذه الآلات لأي مسار، من أجل المظهر.","changelog.7a3b1c31c7b1":"<strong>الطبول على المسرح.</strong> يظهر مسار Drum Machine على هيئة وحدة تحكم من 16 وسادة تعزفها أيادٍ تقرع بالأصابع، وتضيء وساداتها حين تُضرب. وأي مسار طبول آخر يظهر على هيئة طقم استوديو يُعزف بالعصي والقدمين، لعازف أيمن أو أعسر. على المسار المجهَّز، انقر وسادة لتعزفها.","changelog.893ee50f0701":"<strong>كاميرات المسرح.</strong> انظر من الأمام أو من الأعلى أو من الجانب، أو اقترب من يد: اليسرى أو اليمنى على البيانو، ويد الدساتين أو يد النقر على الغيتار، واليدين على الوسادات، ويدَي عازف الطقم وقدميه. حين يكون التركيز على المسرح، ينتقل V إلى العرض التالي وShift+V إلى السابق، بانزلاق سلس بينها (أو بقطع مباشر إن طلب نظامك تقليل الحركة). يمكن أن تكون الجودة تلقائية، فتخفضها لتبقى الصورة سلسة، أو عالية أو متوسطة أو منخفضة، وتأتي الأيدي بستة ألوان للبشرة.","changelog.586b2ef349d2":"<strong>المسرح للجميع.</strong> كل عنصر تحكم على المسرح يمكن بلوغه من لوحة المفاتيح، وله اسم يقرؤه قارئ الشاشة. يقول المسرح ما الذي يظهر عليه وما الذي يتبعه، ومع تقليل الحركة تنتقل الكاميرا بقطع مباشر بدل الانزلاق، بينما تواصل الأيدي العزف.","changelog.e502dae2a32f":"<strong>اعزف على بيانو المسرح.</strong> على المسار المجهَّز، انقر مفاتيحه 3D لتعزفها، وما تعزفه على لوحة مفاتيح الحاسوب أو على لوحة مفاتيح MIDI يظهر على مفاتيحه. وما دامت عجلة الطبقة أو عجلة التعديل أو الضغط في لوحة مفاتيح MIDI بعيدة عن وضع السكون، تعرضها قراءة صغيرة.","changelog.52f0b0e83617":"<strong>مستعرض الآلات يكبر.</strong> الآلات الـ1,648 كلها في مجلدات عائلات على كل رف، والقائمة تتمرّر بسلاسة مهما طالت، والنجمة على أي صف تضعه في مكان جديد هو <strong>المميّزة بنجمة</strong>. ومع تحديد مسار MIDI، يعزف إبقاء المؤشر فوق آلة نوتاتِ ذلك المسار نفسه عبرها. <strong>أصواتي</strong> يحتفظ بالآلات التي تحفظها، باسمها ومجلدها، جاهزةً لتضعها على مسار.","changelog.ed2da6e473fb":"<strong>PACK:</strong> اختر حتى 25 ضربة مفردة من أي آلات، واعزفها، واستبدل كلًّا منها بأداء آخر للآلة نفسها، وصدّرها ملفاتِ WAV إلى مجلد تختاره. ولا يكتب التصدير أبدًا فوق ملف موجود.","changelog.f8948f1e3897":"<strong>مضخّم غيتار، من Freally Handscore</strong>، جهازًا على أي مسار: طابعا الصوت crunch والكسب العالي اللذان كانت غيتارات الروك في Handscore تعزف من خلالهما، مع مستويي الدخل والخرج.","changelog.1f5a90f43722":"<strong>غيتارات روك، جاهزة للعزف:</strong> رف جديد هو <strong>السلاسل</strong> في المتصفح يضم <em>Overdriven Guitar</em> و<em>Distortion Guitar</em>. كلٌّ منهما هو Electric Guitar موصولًا بـGuitar Amp، يليه صدى وتردّد غرفة صغيرة، مضبوطًا مستواه ليجلس حيث كان الغيتار الجاف. حمّل أحدهما على مسار MIDI فيحلّ محل رف المسار في خطوة تراجع واحدة. ويُظهر المسرح أيًّا منهما غيتارَ روك.","changelog.2c1bdb1a5144":"<strong>Granular Wash، من Freally Handscore:</strong> مقبض واحد يحوّل الصوت إلى سحابة من الحبيبات، يحتفظ بالنوتة ويضيف الأوكتافين فوقها وتحتها، مع صدى يمدّه لثوانٍ.","changelog.456b255a9204":"<strong>أغلفة على كل آلة.</strong> صار لكل آلة من الآلات الـ1,648 أربعة أغلفة يمكنك تشغيلها: مستوى الصوت، والمرشّح، وحدّة النغمة، والتوزيع. يبدأ كلٌّ منها من شكل (Init، أو نقر، أو بساط، أو تصاعد، أو بوابة، أو ارتداد)، أو ترسم شكلك الخاص بما يصل إلى 16 نقطة إضافية. ويمكن لكلٍّ منها أن يتكرر ما دام المفتاح مضغوطًا، وأن يُقفل على الإيقاع، وأن يتبع قوة الضغط والمفتاح، وأن يبدأ من جديد مع كل مازورة، وأن يمزج بين شكلين. يُحفظ الشكل المرسوم في المشروع وفي ملفات الرف، لا في سطر إعدادات ملصوق. ومع إطفاء كل الأغلفة، تصدح كل آلة تمامًا كما كانت. <strong>واحد وسبعون من السبعة والسبعين مبنية</strong> الآن، ومعها ثلاثون مؤثرًا أساسيًا.","changelog.3c490686a380":"<strong>Drum Machine، من Freally Handscore</strong>، يحلّ محل Pad Grid: 16 وسادة تعزف أطقم Handscore الأربعة المركّبة (Sub وFloor وNeon وWire)، وكل ضربة تُختار من ثلاث طبقات بحسب قوة عزفك وتتناوب بين أداءين، فلا تكرّر دحرجة الطبل نفسها تمامًا أبدًا. لكل وسادة دوزنتها، ومسح طبقتها، وغلافها، وتوزيعها، ومرشّحها، ومجموعة الخنق الخاصة بها، وحتى أربع طبقات يمكنك عكسها أو تطبيعها. وأصوات الطقم وحزم الإيقاع الـ11 مسرودة بجانب الوسادات، لتسمعها ولتضعها على وسادة. والأغاني التي استخدمت Pad Grid تُفتح على Drum Machine مع الاحتفاظ بمستوياتها ومجموعات الخنق فيها.","changelog.a73196fdefd8":"<strong>رف الأنماط يعمل كما يعمل نظيره في FL Studio.</strong> لكل صف جزؤه الخاص منذ البداية، فيفتحه <em>تحرير</em> في لفّة البيانو (أو شبكة الإيقاع) ويضعه <em>وضع</em> في الأغنية فورًا؛ لا شيء يجب أن يكون موجودًا في التوزيع أولًا.","changelog.accec80b1ae2":"انقر الخطوات داخل الرف مباشرة. ينفتح مسار الطبول إلى صف من الخطوات لكل صوت من أصواته، وخطوات الصف اللحني تعزف نوتته. السحب يرسم سلسلة من الخطوات أو يمحوها في خطوة تراجع واحدة، والخطوة التي تشغّلها تعزف صوتها.","changelog.115e9acfd86e":"<strong>وضع النمط</strong> يضع كل صف على مساره الخاص عند رأس التشغيل في خطوة تراجع واحدة، مرتبطًا بالنمط، فتعديل النمط يغيّر كل نسخة موضوعة منه.","changelog.75ba3144030f":"للنمط طوله الخاص (حتى 16 مازورة)، وشبكته (من 1/4 إلى 1/32)، وسوينغه.","changelog.afc2281ee72b":"<strong>النمط / الأغنية</strong>، بجانب النقل: في وضع <em>النمط</em>، يكرّر التشغيلُ النمطَ المفتوح على آلات مساراته وسلاسلها وخلّاطها، بإيقاع الأغنية، دون أن يمسّ التوزيع. الخطوة التي تشغّلها أثناء العزف تُسمع في الدورة التالية، ويُظهر الرف الخطوة التي تُعزف. و<em>الأغنية</em> يعيد رأس التشغيل إلى حيث كان.","changelog.f7997e06e1f4":"أيقونة مفتاح <em>نمط جديد</em> صارت الآن بجانب اسمه، وكذلك أيقونة كل مفتاح.","changelog.2ac99e3c60b4":"<strong>شبكة الإيقاع مُتسلسِل خطوات أيضًا:</strong>","changelog.19331c466587":"شدّة ضغط كل ضربة تُرسم عمودًا، ويمكن رسم شدّات ضغط الصف في مسار تحته؛","changelog.0efc86543f52":"السوينغ من 50 إلى 75 %؛","changelog.e59c0853bb61":"الضربة الواقعة خارج الشبكة تُعلَّم مبكرة أو متأخرة؛","changelog.6a44598b8b11":"السحب بالزر الأيمن يمحو مستطيلًا؛","changelog.4ba33e04b552":"يمكن إفراد كل صف كما يمكن كتمه.","changelog.7946b0544401":"على مسار Drum Machine تُسمّى الصفوف بأسماء وساداته، ومجموعة الخنق للصف هي مجموعة خنق الوسادة.","changelog.72e1521ec764":"<strong>خريطة الطبول:</strong> الطبول المستوردة بتخطيط طقم آخر (Toontrack وAddictive Drums وSuperior وغيرها) تعزف القطعة الصحيحة من طقمك. يمكن توجيه كل صف إلى قطعة، أو إلى خط باص 808، أو تركه خارج الطقم، دون تغيير نوتة واحدة: أطفئ الخريطة فيُعزف الجزء كما جاء. التشغيل والتصدير والسحب والمسرح كلها تتبعها.","changelog.a24945cd87a3":"<strong>تعلُّم وحدة التحكم بالوسادات لديك</strong> (الإعدادات ▸ MIDI ▸ وحدة تحكم بالوسادات): اضرب كل وسادة من الوسادات الـ16 حين يُطلب منك، فتعزف وحدة التحكم لديك وسادات Drum Machine بالتخطيط وتوزيع الأصابع اللذين تختارهما.","changelog.d9fbc164eaf0":"<strong>عجلات لوحة مفاتيح MIDI تصل إلى كل آلة.</strong> عجلة الطبقة تثني النوتات الممسوكة، والنوتات التي تُضرب وهي مُزاحة تبدأ مثنيّة. عجلة التعديل وضغط القناة يُدخلان الفيبراتو في الآلات. والثلاثة كلها تصل إلى إضافات VST3 وCLAP المستضافة كما تصل في أي DAW آخر.","changelog.b74af77e2ad7":"<strong>الإعدادات ▸ MIDI ▸ طريقة العزف:</strong> تحويل الطبقة، ومدى الثني (±2 افتراضيًا، حتى أربعة أوكتافات)، ومنحنى قوة ضغط ناعم أو قاسٍ، و<strong>الكوردات</strong>، الذي يعزف من كل مفتاح كوردًا في سُلّم المشروع.","changelog.c6232c384873":"<strong>تُصيَّر المسارات عبر أنوية حاسوبك.</strong> حين تكون الأغنية ثقيلة، تعزف مساراتِها المستقلة حتى سبعة خيوط مساعدة في آنٍ واحد، فتستغرق الجلسة المزدحمة نحو خُمس الوقت الذي كانت تستغرقه. الصوت هو نفسه حتى آخر بت. والجلسة الخفيفة أو النقل المتوقف لا يوقظان الخيوط المساعدة أصلًا.","changelog.862476a841b8":"<strong>قسم Section Player يجهز في أقل بكثير من ثانية</strong>، بعد أن كان يستغرق نحو عشرين. ومسارات Modelled Synth وLayer Rack تجهز أسرع أيضًا.","changelog.0eeb8bf8931a":"<strong>مقابض جديدة.</strong> كل مقبض الآن مقبض غرافيتي داكن بإضاءة حافة ناعمة ومؤشر أخضر رفيع واحد، المقبض نفسه في المظهر الفاتح والداكن، مع قوس قيمة أرفع حوله.","changelog.b74912e85473":"<strong>One-Shot Sampler وMultisampler وPercussion Sampler وGranular Player تعزف ملفاتك أنت.</strong> لم تكن هناك طريقة لإعطائها ملفًا داخل التطبيق، فلم تكن تُصدر أي صوت. <em>أضف عيّنات…</em> على كلٍّ منها، وعلى وسادات Drum Machine، يختار الآن ملفات لتعزفها. والضربة المفردة من حزمة تذهب إلى وسادة بنقرة واحدة.","changelog.a1d18eba0405":"<strong>إضافة CLAP لا تسمع عجلات MIDI إلا على منفذ يعلن أنه يفهم MIDI</strong>، كما يطلب معيار CLAP؛ والمنفذ الذي لا يتحدث إلا بأحداث النوتات الخاصة بـCLAP لم يعد يُرسل إليه MIDI لم يطلبه.","changelog.76148bf374f1":"<strong>ملف الصوت ذو العيّنات المعطوبة (قيم ليست أرقامًا أو قيم لانهائية) يعزف صمتًا في مواضعها</strong> بدل أن يرسلها إلى المزيج.","changelog.d14ed914a63c":"<strong>أغلفة مُعايِنات العيّنات تحافظ على أزمنتها.</strong> كان الهجوم بطول 10 ms يستغرق 18 ms، والهجوم بطول 100 ms لم يكن يبلغ المستوى الكامل أبدًا. وقراءة العيّنة صارت أيضًا أرخص بنحو مئة مرة، فالطقم المزدحم لم يعد يكلّف أكثر مما يملكه الحاسوب.","changelog.dcc387d30b9e":"<strong>Amp Head لم يعد يضيف أزيزًا خافتًا</strong> لم يكن في الموسيقى. تشوّه التقاطع في مرحلته من الفئة AB، حين تُقاد بالكسب الافتراضي، صار الآن أدنى من الموسيقى بنحو 20 dB إضافية، ويستهلك الرأس من CPU أقل بنحو الخُمس.","changelog.de63c4379a3e":"<strong>التوزيع يُبقي مسطرته وشريط أدواته على الشاشة.</strong> عجلة الفأرة فوق المسارات أو فوق أسمائها تمرّر المسارات وحدها، ويظهر شريط تمرير رفيع بجانبها حين لا تتسع كلها، ويلتفّ شريط الأدوات بدل أن يدفع التوزيع جانبًا في نافذة ضيقة.","changelog.b00b534eb987":"<strong>شبكة الإيقاع تعمل من لوحة المفاتيح.</strong> Enter أو Space يقلب حالة الخلية، وكل عمود شدّة منزلق تحرّكه مفاتيح الأسهم. والسحب بالزر الأيمن الذي ينتهي خارج الشبكة لم يعد يفتح قائمة النقر الأيمن الخاصة بالنافذة (رجوع، تحديث، طباعة)، واللمسة التي تتحول إلى تمرير لم تعد تضع ضربة.","changelog.a95781e19fc6":"<strong>في الغرفة، يبقى تعديل المتعاون سريعًا على جزء كبير أو إضافة ثقيلة.</strong> كان كل تغيير في نوتة أو مقبض ينسخ الجزء أو المسار الذي لمسه بأكمله، بحالة الإضافة وكل شيء، فكان السحب على مسار يحمل إضافة كبيرة قد يستغرق ثواني حتى يصل.","changelog.71e443e94c1d":"<strong>الإضافة التي يستبدلها متعاون بأخرى ثم يعيدها تعود بصوتها الخاص</strong>، لا بإعداداتها الافتراضية.","changelog.f7cfe2b155f7":"<strong>لم تعد الغرفة تنقسم</strong> حين يزيل شخص صوتًا يضعه آخر على وسادات الطبول في اللحظة نفسها؛ كل جهاز ينتهي بالأغنية نفسها.","changelog.6a3c703c203f":"سياسة المحتوى في النافذة تسمح الآن للصفحة بقراءة عناوين <code>blob:</code> التي أنشأتها بنفسها، فتظهر خامات نماذج المسرح. ولا يُسمح بدخول أي شيء من خارج التطبيق.","changelog.b2ad26c2005b":"<strong>حالة إضافة المتعاون لا تصل أبدًا إلى إضافة مختلفة.</strong> عندما يبدّل متعاون جهازًا إلى إضافة باسم آخر، تبدأ بإعداداتها الافتراضية بدل أن تُسلَّم حالة الإضافة القديمة، و<em>إعادة التحميل</em> على جهاز صار إضافة أخرى يشغّل الإضافة الصحيحة.","changelog.37b7bf5a7781":"<strong>فحوص الغرفة لم تعد تتباطأ كلما كبرت الأغنية.</strong> إزالة متعاون لأصوات كثيرة، أو مسار كامل يُكتب دفعة واحدة، يُفحص في زمن يكبر بقدر ما أُرسل لا بقدر كل ما في الأغنية.","changelog.0777d6b7566d":"<strong>في الغرفة، يُرفض التعديل الواحد الذي يضم أكثر من 1,024 تغييرًا، مع ملاحظة تطلب تنفيذه على أجزاء أصغر.</strong> أجهزة المتعاونين ترفض تعديلًا بهذا الحجم، وكانت تحسبه على من أرسله. والتراجع والإعادة يخضعان للحد نفسه.","changelog.f930a12d52df":"<span class=\"release__meta\"><span class=\"release__ver\">v0.8.0</span><time class=\"release__date\" datetime=\"2026-10-30\">2026-10-30</time></span>","changelog.176a21a2f44e":"<strong>MIDI Master وFlipcopy وTakelight ضمن الحزمة — لا توجد تنزيلات بعد.</strong> صار مثبّت Oscillate يجلب معه ثلاث إضافات من Freally بوصفها إضافاته المرفقة: Freally MIDI Master لكتابة الأجزاء والأغاني الكاملة، وFreally Flipcopy لنسخ الصوت إلى MIDI والعكس، وFreally Takelight للغناء.","changelog.506992d57adc":"<strong>ثلاث إضافات من Freally تأتي مع Oscillate</strong>، مدرجة بوصفها مرفقة تحت الإضافات في المتصفح، دون حاجة إلى فحص. يضعها المثبّت في مجلدَي VST3 وCLAP في النظام، فتجدها كذلك كل برامج DAW على الحاسوب، ويُبقيها إلغاء تثبيت Oscillate في مكانها. ولا يستبدل أبدًا نسخة أحدث، ولا نسخة ثبّتّها بنفسك.","changelog.f26b74a62345":"<strong>دليل تعليمي</strong>، تحت مساعدة، يرشدك عبر الإضافات الثلاث في سبع خطوات، كل منها تشير إلى عنصر التحكم الحقيقي: إضافة MIDI Master إلى مسار MIDI، وسحب أغنية منه إلى التوزيع، والنسخ بـFlipcopy، ووضع Takelight على غناء. وهو يتحدث لغات Oscillate الثماني عشرة كلها.","changelog.af2f024f12a2":"<strong>أفلِت أغنية كاملة من Song Mode في MIDI Master</strong> على مساحة فارغة، فتصل مسارًا لكل جزء، مع تغيّرات الإيقاع في الأغنية وعلامة لكل قسم. وتراجع واحد يعيد كل ذلك.","changelog.352062423c22":"<strong>استيراد كأجزاء.</strong> ملف صوتي أو ملف <code>.mid</code> (من المتصفح، أو من منتقي الملفات، أو من قائمة المقطع الصوتي نفسه) يدخل بوصفه مسارات MIDI: اللحن والتآلفات والباص، دون الطبول.","changelog.3677012c1215":"<strong>جاهزية النجاح</strong>، تحت عرض: درجة من A إلى F لأي توزيع، تُقرأ من علامات أقسامه، مع نصائح حول مواضع إسقاط بعض الأجزاء قبل اللازمة. ويمكن تسمية الأقسام بأي لغة من لغات Oscillate الثماني عشرة.","changelog.16d08660e013":"<strong>اسحب المسارات خارج Oscillate</strong>، من المقبض في رأس كل مسار، إلى مجلد أو برنامج DAW آخر: بصيغة MIDI (ملف لكل جزء، أو ملف واحد مع Ctrl) أو بصيغة صوت (مسار منفصل لكل مسار مع إضافاته، أو المزيج مع Ctrl).","changelog.b4fc9a1d1d3f":"<strong>سلسلة جانبية إلى إضافة.</strong> الإضافة التي لها مدخل سلسلة جانبية، مثل Takelight، تحصل على خيار <em>Sidechain من</em> في بطاقتها، لتسمع مسارًا آخر (مسار الإيقاع، من أجل Auto Key في Takelight).","changelog.1b0e0cbf5f82":"<strong>المثبّت صار على مستوى الجهاز</strong>: مطالبة UAC واحدة، وOscillate في Program Files. ويُستبدل الإصدار <code>0.7.0</code> المثبّت لكل مستخدم.","changelog.be6892914a86":"<strong>التصدير يحمل كل إضافة تستخدمها.</strong> صار كلٌّ من التثبيت إلى صوت والمسار المنفصل والماستر يشغّل كل إضافة مستضافة تشغيلًا غير متصل، فلا يصمت أبدًا في الملف جزءٌ تعزفه إضافة. والإضافة المفقودة أو التي تفشل تُذكر باسمها في ملاحظات التصدير.","changelog.884818bbcd38":"<strong>كل إعداد مسبق مصنعي، لا الصوت الرئيسي لكل آلة فحسب</strong>، صار قابلًا للتحميل، فيصل الجزء القادم من MIDI Master على الصوت نفسه الذي كُتب به.","changelog.bc05f9aa575a":"<strong>إعدادات Wavetable المسبقة تعزف الفيبراتو الخاص بها</strong>، كما في MIDI Master. كان مقبض طبقة الصوت عند الصفر يطفئه.","changelog.b69c8ebb18bf":"<strong>«تحويل إلى MIDI» على مقطع لا يبدأ عند النبضة الأولى</strong> يضع النوتات على النبضة؛ كانت تقع مبكرًا من قبل.","changelog.2633e1dc8bb9":"<strong>الإضافة التي تعزف نوتات، مثل MIDI Master، تُصدر صوتًا في Oscillate</strong>، والأجزاء التي تعزفها تُسجَّل على النبضة لا متأخرة بكتلة واحدة.","changelog.0b2b3be5c0d7":"<strong>الإضافة التي تغيّر تأخيرها</strong> (Takelight حين يبدّل سلسلته) تبقى متزامنة مع المسارات الأخرى.","changelog.da4c4e9ff002":"<strong>الإضافة المفقودة تُبقي مسارها في توقيته.</strong> المسار الذي كانت إضافته مفقودة كان يُعزف مبكرًا بمقدار تأخير تلك الإضافة.","changelog.274f7feb38d5":"<strong>التعديلات في محرّر الصوت ولفّة البيانو تعيد رسم الخط الزمني فورًا.</strong>","changelog.6c69e876d1d2":"<strong>Esc في قائمة النقر بالزر الأيمن يغلق القائمة</strong> ولم يعد يمسح معها ما كنت قد حددته على الخط الزمني.","changelog.eff8a20b3835":"<strong>تصدير MIDI من مشروع فيه منحدر إيقاع يحافظ على توقيت المنحدر</strong>، فتقع كل نوتة في برنامج DAW آخر حيث يعزفها Oscillate. كان المنحدر يصل سابقًا قفزةً واحدة، وكانت كل نوتة بعده متأخرة.","changelog.ae7d802659fb":"<strong>التصدير إلى FLAC أو OGG أو MP3 على قرص ممتلئ</strong> يُبلغ بأنه فشل، بدلًا من أن يترك ملفًا مبتورًا ويُبلغ بأنه كُتب.","changelog.71eaab782086":"<strong>المثبّت لا يتبع أبدًا رابطًا مزروعًا في مجلدات الإضافات في النظام.</strong> فحيث يستطيع أي مستخدم الكتابة في تلك المجلدات، كان من الممكن لرابط مزروع أن يوجّه المثبّت، الذي يعمل بصلاحيات المسؤول، إلى كتابة ملفات أو حذفها في مكان آخر.","changelog.1d5cbd1d6bbd":"<strong>ملف MIDI المُفلَت على التوزيع يُرفض إذا تجاوز 4 MB</strong>، أو حالما يحمل نوتات أو علامات أو تغيّرات إيقاع أكثر مما يتسع له المشروع، قبل أن يملأ ذاكرة الحاسوب.","changelog.33ee0c5ec252":"<span class=\"release__meta\"><span class=\"release__ver\">v0.7.0</span><time class=\"release__date\" datetime=\"2026-10-28\">2026-10-28</time></span>","changelog.6380b0daebc4":"<strong>محرّك واحد — لا توجد تنزيلات بعد.</strong> برنامج DAW نفسه، مبنيّ الآن على المحرّك المشترك لعائلة Freally بدلًا من نسخ منه. الإصدار <code>1.0.0</code> أدناه بُني للاختبار ووُضع جانبًا: يكبر Oscillate ليصبح DAW أكبر، درجةً بعد درجة، وهذه أولى الدرجات الجديدة.","changelog.f8f3a7bd4b47":"<strong>الآلات تأتي من المكتبة المشتركة لعائلة Freally</strong>، المكتبة نفسها التي يعزف بها Freally MIDI Master، مثبّتة على إصدار واحد بدلًا من نسخها. كل صوت مصنعي يُصيَّر تمامًا كما كان: نتائج التصيير الاختبارية البالغة 4,983 كلها متطابقة بايتًا ببايت.","changelog.94126c8f7ee2":"<strong>مؤشر Freally:</strong> حلقة في قلبها نقطة. النقطة هي موضع النقر، والحلقة تتبعها؛ تكبر فوق كل ما يمكن ضغطه وتصغر أثناء ضغطك. أما المؤشرات التي تعني شيئًا، مثل مؤشرات حواف القص في المقطع والفواصل والنص، فما زالت مؤشرات نظامك.","changelog.ef160105ff0d":"<strong>مفاتيح التبديل تُقرأ بنظرة واحدة:</strong> رمادية حين تكون مطفأة، وبيضاء حين تكون مطفأة وتحت المؤشر، وبأخضر Freally حين تكون مشغّلة.","changelog.ae7560701556":"<strong>«تحويل إلى MIDI» يعمل بالفأرة.</strong> اختياره بنقرة من قائمة المقطع لم يكن يفعل شيئًا؛ لوحة المفاتيح وحدها كانت تعمل. ويُرسم المقطع المحوَّل الآن فورًا، لا بعد التمرير التالي.","changelog.a63a6cbcf25f":"<strong>التراجع والإعادة وفتح مشروع تعيد رسم مقاطعها فورًا.</strong> كان الرد السريع قد يترك الخط الزمني يعرض المقاطع في أماكنها السابقة.","changelog.664eefc3eae5":"<strong>النقر بالزر الأيمن على قائمة مقطع مفتوحة</strong> لم يعد يفتح فوقها قائمة المتصفح الخاصة.","changelog.336a4fd289a9":"<strong>إطار عمل التطبيق والمكتبات الكامنة وراء فحص التحديثات صارت محدَّثة</strong>، تلبيةً لثمانية تنبيهات أمنية نُشرت هذا الشهر بشأنها (<code>rustls</code> و<code>zip</code>).","changelog.77d42d7c2487":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-10-09\">2026-10-09</time></span>","changelog.e0b00ac11c8b":"<strong>الإصدار 1.0.0، مبنيّ للاختبار — لا توجد تنزيلات بعد.</strong> كل ما في الإصدار المرشّح أدناه، والعيوب التي وجدتها مراجعته، وإعدادان موجودان في كل تطبيقات Freally.","changelog.ab16cb9401f9":"<strong>سرعة الحركة وتقليل الحركة</strong> في الإعدادات ▸ المظهر، الثنائي نفسه في كل تطبيقات Freally. <em>سريعة</em> يدير العنوان بضعف السرعة؛ و<em>تقليل</em> يوقف كل حركة — بما فيها شاشة البداية — ويُبقي العنوان مستويًا، أيًّا كان إعداد النظام.","changelog.ac49a12e1f61":"<strong>أرسل تقريرًا بالبريد.</strong> حين تواجه الواجهة مشكلة، يفتح <em>أرسله بالبريد</em> برنامج البريد لديك والتقرير موجّه إلى freallyproducts@gmail.com، وينسخ التقرير كاملًا أيضًا. ويحلّ محلّ رابط إلى صفحة لم تكن موجودة.","changelog.e088f2f8847a":"<strong>مؤثرات شريط القناة تتلاشى بهدوء.</strong> إعادة آخر مقبض في الشريط إلى الصفر لم تعد تقطع ذيل غرفة أو صدى ولا تُحدث نقرة؛ والمقبض الذي يُرفع أثناء التشغيل ينزلق تدريجيًا؛ ولم تعد تكرارات صدى اللاحقة تضيع؛ ولمسة من حرارة لم تعد تُخمد الحِدّة؛ وتشغيل غرفة أو صدى لم يعد يهدد بانقطاع عند معدلات العينة العالية.","changelog.3c2767adacb5":"<strong>التصدير يتبع أتمتة الشريط</strong> بالدقة نفسها التي يتبعها التشغيل، فتظهر رمية سريعة لـصدى أو حرارة في الملف المصدَّر.","changelog.4abd4bab9fc5":"<strong>تتحرك اللوحات بقدر طول صوتها تمامًا</strong>: 320 ms عند الظهور و280 ms عند الإخفاء.","changelog.3882af1c3146":"<strong>المقاييس والمقابض والمفاتيح:</strong> يبقى ضوء الذروة مضاءً فوق 0 dBFS؛ ويعرض المقبض قيمته أثناء تدويره من لوحة المفاتيح أو العجلة؛ ولم يعد المفتاح يبقى مضغوطًا حين ينتقل التركيز عنه.","changelog.dea443b9c7d5":"<strong>قارئات الشاشة</strong> تسمع مجددًا تحذير رمز الغرفة في بطاقة الجلسة وشرح قفل السلّم.","changelog.7ba875906742":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0-rc</span><time class=\"release__date\" datetime=\"2026-09-25\">2026-09-25</time></span>","changelog.508d2f7ec832":"<strong>مراجعة المرشّح للإصدار في 24–25 سبتمبر 2026</strong> في الأعلى: ميزة جديدة واحدة، والعيوب التي وجدتها المراجعة، وما يبدو الآن مختلفًا في مشروع محفوظ. وتحتها إصلاحات 19 سبتمبر، ثم <strong>آلية النسخة التجريبية</strong> (المرحلة 11)، ثم <strong>الواجهات والأصوات والأدوار والنسب</strong> (المرحلة 9.5)، ثم <strong>الغرفة</strong> (المرحلة 9)، ثم <strong>أدوات الكتابة</strong> (المرحلة 8)، و<strong>أجهزة Oscillate الخاصة</strong> (المرحلة 7)، و<strong>استضافة الإضافات</strong> (المرحلة 6)، و<strong>المحرّرات</strong> (المرحلة 5)، و<strong>عرض التوزيع والمشروع الذي تحته</strong> (المرحلتان 3 و4، درجة <code>v0.2.0</code> كلها).","changelog.b1f634b002e5":"تغيير — أدوات التحكم والمظهر والأصوات لعائلة Freally (2026-10-06)","changelog.cce1ebda3172":"<strong>مجموعة عتاد Blender، وعرض واحد للمفاتيح.</strong> كل مقبض ومنزلق ومفتاح تشغيل وإيقاف ومفتاح ومفتاح تبديل هو الآن من تصميم Blender في كتيب Freally، بالوضعين الداكن والفاتح، وهي الملفات نفسها التي يستخدمها Freally Flipcopy. كل زر كان له وجه زر أصبح مفتاحًا، بعرض واحد يتسع لكل تسمية في اللغات الثماني عشرة؛ أما الأزرار المرسومة كنص وأزرار النقل فبقيت كما كانت. والمقبض هو نفسه، بلونه الفضي المصقول، في السمتين.","changelog.be6f318c395c":"<strong>طقم واجهة Freally.</strong> الألوان واللوحات البارزة والحوارات والقوائم الزجاجية وشعار الاسم تأتي من الطقم المشترك. أخضر Freally تعبئة وتوهج؛ والكلمات والخطوط الخضراء تستخدم حبره. وما زال خيار «النظام» يتبع نظام التشغيل.","changelog.00660e46fb29":"<strong>أصوات الواجهة.</strong> تصدر الحوارات واللوحات والنوافذ المنفصلة صوت العائلة لكل حركة، عبر مخرج الصوت ولا تدخل أبدًا في التصدير. ويوقفها الإعدادات ▸ عام ▸ أصوات الواجهة.","changelog.6fae69200b7e":"<strong>شريط قنوات Freally Flipcopy في المازج</strong>: شبكة مقابض، ومنزلق طويل رفيع بجانب مقياس LED، ثم Solo وMute، والقناة الرئيسية في أقصى الطرف. مقابضه السبعة مؤثرات حقيقية — Low وMid وHigh وRoom وEcho وHeat وPitch Mod — تُحفظ وتُلغى وتُشارك في الغرفة وتقبل الأتمتة؛ وعند الصفر لا تغيّر شيئًا. وتُطوى شبكة المقابض حتى يُظهرها مفتاح <strong>المقابض</strong> في المازج، ويدير رف الصوت فوق لوحة مفاتيح محرر النوتات غرفة وصدى وحرارة وتعديل الطبقة نفسها.","changelog.0e780ad471b9":"<strong>في كل مكان آخر، وفي MixSir.</strong> إعدادات التشغيل والإيقاف هي المفتاح المرسوم، ومفاتيح التشغيل الصغيرة مفاتيح تبديل، ومازج الهاتف يستخدم المجموعة نفسها.","changelog.dc28fa7b5e37":"<strong>البيانوهات الصوتية</strong> هي التي أعاد Freally MIDI Master بناءها. ⚠ صوتها أخفض بمقدار 10–12 dB، والمشروع المحفوظ يحتفظ بالبيانو القديم حتى يُختار من جديد.","changelog.7a5d4f56ddd0":"أُضيف — لوحة مفاتيح MIDI حقيقية تعزف وتسجّل","changelog.e63d48df6d81":"⛔⛔ <strong>لم يفتح أي شيء في Oscillate منفذ MIDI قط.</strong> شيفرة المشغّل بُنيت واختُبرت ولم يستدعها شيء، بينما كان README وخارطة الطريق وقصة التشغيل الأول تقول كلها <em>«اعزف على لوحة مفاتيح MIDI ← صوت»</em>، وكانت الإعدادات ▸ MIDI تقول إن الميزة غير موجودة بعد. إنها موجودة الآن.","changelog.dcc8ae17c873":"<strong>الإعدادات ▸ MIDI تسرد مداخلك. اختر واحدًا</strong> فيعزف المسار المجهَّز تمامًا كما تفعل لوحة المفاتيح على الشاشة، ويسجّل في اللقطات بالطريقة نفسها. تضيء نقطة حين تصل النوتات، ويقول القسم ذلك حين لا يكون أي مسار مجهَّزًا.","changelog.fdebbbb5e13c":"<strong>ما الذي يحمله:</strong> النوتات بشدتها، ودوّاسة الاستدامة، ورسائل الطوارئ (<em>All Notes Off</em> و<em>All Sound Off</em>)، فيوقف زرّ الطوارئ في لوحة المفاتيح كل شيء.","changelog.fe2865a6e325":"⚠ <strong>الدوّاسة يمسكها Oscillate لا الآلة.</strong> لا توجد هنا آلة تقرأ الدوّاسة، فيحتجز Oscillate رسائل إيقاف النوتات حتى تُرفع الدوّاسة. وهذا يعمل بالطريقة نفسها على كل آلة، واللقطة المسجّلة تحتفظ بكل نوتة طوال المدة التي سُمعت فيها، لا طوال ضغط المفتاح فقط.","changelog.c6abb9b19ac3":"⛔ <strong>ما لا يُحمل بعد، ولا يُزيَّف:</strong> ثني الطبقة، وعجلة التعديل وغيرها من وحدات التحكم، وضغط القناة، واللمسة اللاحقة متعددة الأصوات، وتغيير البرنامج. الآلات تستطيع استقبال الثني والضغط؛ أما المسار الحيّ من لوحة المفاتيح إليها فلا يستطيع بعد. ثني الطبقة وعجلة التعديل والضغط ستأتي بعد 1.0.","changelog.f17d5e0822ce":"<strong>افصلها في منتصف نوتة فتتوقف النوتة.</strong> مكتبة MIDI لا تُبلغ عن أحداث التوصيل أو الفصل، لذا يفحص Oscillate مرة كل ثانية ما دام منفذ مختارًا: لوحة المفاتيح التي اختفت تُطلق كل نوتة كانت تمسكها ويقول القسم <em>غير موصولة</em>. أعد توصيلها فتتصل من جديد بالاسم.","changelog.4e160f9c55ef":"<strong>الاختيار يُحفظ</strong> في <code>midi.json</code> بجانب <code>audio.json</code>، ويُعاد فتح المنفذ عند بدء التشغيل قبل ظهور النافذة. وإذا بدأ ولوحة المفاتيح مفصولة، يُفتح Oscillate كالمعتاد ويقول ذلك.","changelog.315f68af9cc8":"<strong>المنفذ الذي يمسكه تطبيق آخر يقول ذلك</strong>، <em>تعذّر فتحه</em>، مع السبب الذي يذكره المشغّل نفسه، ويتصل ما إن يتحرر المنفذ.","changelog.34f38d764f89":"⚠ <strong>حدّ معروف:</strong> الفصل وإعادة التوصيل داخل فحص الثانية الواحدة نفسه قد يترك المنفذ يُظهر <em>متصل</em> بينما لا يصدر أي صوت. اختيار المنفذ مرة أخرى يصلح ذلك.","changelog.942c6cb85fad":"<strong>عيبان في لوحة المفاتيح على الشاشة، أُصلحا في الطريق</strong> لأن نوعَي لوحة المفاتيح يتشاركان الآن مسارًا واحدًا:","changelog.d2f0b8c7936a":"<strong>تجهيز مسار آخر أثناء الضغط على مفتاح كان يرسل الإطلاق إلى المسار الجديد</strong>، فتظل النوتة على المسار القديم تصدح حتى يُعاد تشغيل Oscillate. الآن تُطلق النوتة على المسار الذي عُزفت عليه.","changelog.7634f305d478":"***إيقاف كل النوتات<em> كان يُفرغ طابور النوتات كله</em>*، فيرمي معه الإطلاقات المعلّقة الخاصة بلوحة المفاتيح الأخرى.","changelog.19562cee5d4a":"أُصلح — مراجعة المرشّح للإصدار","changelog.9705daf96914":"▶ <strong><code>/simplify</code> و<code>/code-review</code> و<code>/security-review</code> على الشجرة كلها مرة أخرى، ثم نحو اثنتي عشرة جولة إصلاح.</strong> أُصلحت مئات العيوب، لكل منها اختبار رُئي يفشل أولًا حيثما سمحت الأدوات. الأسوأ أولًا. وقسم <em>تغيّر</em>، في الأسفل، يسرد ما يبدو الآن أو يتصرف مختلفًا في مشروع لديك من قبل.","changelog.9cfb8a7fe85a":"<strong>أسوأ ما فيها</strong>","changelog.c3b3b0310b60":"⛔⛔ <strong>في التطبيق الذي تثبّته، لم تصل مقاطع التوزيع ومقاطع MIDI والأتمتة إلى المحرّك قط، ولم تصل منذ 27 أغسطس.</strong> كان <code>main.rs</code> يستدعي <code>Builder::setup</code> في Tauri مرتين، والاستدعاء الثاني <strong>يستبدل</strong> الأول بدل أن يضيف إليه. الأول كان يشغّل عامل التشغيل ورادار الحجب ومقياس الجهارة، فلم يعمل أيٌّ من الثلاثة. ونجحت كل الاختبارات، لأن أي اختبار لم يشغّل الباني. هناك الآن إعداد واحد، وبوابة (<code>the_builder_has_one_setup.rs</code>) ترفض إعدادًا ثانيًا.","changelog.57f0db8ea734":"⛔⛔ <strong>كل تصدير كان يعزف النوتات التي في بداية الأغنية فقط.</strong> التصيير غير المتصل لم يحرّك نقله الخاص قط. وتصدير المجلد المرافق كان يحمل النوتات عند النبضة الأولى بلا رسائل إيقاف، وأتمتة مستوى الصوت فيه متجمدة، وأجهزته المتزامنة مع الإيقاع تعمل على 120. تعزف الصادرات الآن الأغنية كلها بخريطة إيقاعها وأتمتة مستوى صوتها، ولم تعد المقاطع الصوتية تجفّ في منتصف الطريق.","changelog.88021b53a47d":"⛔⛔ <strong>إعادة فتح مشروع كانت تترك كل إضافة VST 3 وCLAP صامتة، ولم تُحفظ إعدادات الإضافة الخاصة قط.</strong> كانت الإضافات المستضافة لا تُحمَّل إلا حين تضيف واحدة أو تفتح نافذتها. أما الآن فتُحمَّل بعد كل فتح وتراجع وإعادة وتحميل لإعداد سلسلة وتحديث من مشارك. وتُلتقط حالة كل إضافة قبل كل حفظ وتُستعاد حين يُفتح المشروع.","changelog.cc2f0645818b":"⛔ <strong>كانت المؤثرات تُعاد من البداية خمسين مرة في الثانية أثناء دوران النقل.</strong> كان عامل التشغيل يعيد بناء خطة التصيير كلها كل 20 ms سواء تغيّر شيء أم لا، وكل إعادة بناء كانت تعيد ضبط كل جهاز مرفق. فتُقطع ذيول الصدى، وتبدأ الضواغط من جديد، وتسقط الأصوات الممسوكة، ويعود كل جهاز منزلقًا من إعداداته الافتراضية. الآن لا تُعاد الخطة إلا حين يتغيّر فيها شيء، وإعادة البناء تنقل الأجهزة العاملة بدل أن تستبدلها.","changelog.b8a809519ca1":"⛔ <strong>منطقة التكرار لم تكرّر قط.</strong> كانت المسطرة ترسمها والمشروع يحفظها، لكن شيئًا لم يُخبر النقل. يلتف التشغيل الآن عند نهاية التكرار، ولم يعد صوت المقاطع يتجاوز نهاية التكرار ثم يُعزف متأخرًا.","changelog.8e4359696cb2":"⛔ <strong>التراجع والإعادة وفتح مشروع وتعديل مشارك لم تكن تعيد رسم النوافذ الأخرى.</strong> ظلت لفّة البيانو ومحرّر الصوت ولوحة الجهاز المفتوحة وكل نافذة منفصلة تُظهر الحالة السابقة، وقصٌّ ثانٍ محسوب من عرض قديم كان يمكن أن يكتب فوق الأول. كل تغيير الآن يحرّك عدّادًا واحدًا تستمع إليه كل النوافذ.","changelog.991a518ad40a":"⛔ <strong>بعد ملف ▸ فتح، لم يظهر عرض الاستعادة من العطل قط، وكان الحفظ التالي يحذف السجل الذي كان سيعرضه.</strong> يُعرض الآن كلما فُتح مشروع، ويحتفظ الحفظ بالسجل حتى تجيب.","changelog.72fcf1110d6e":"⛔ <strong>الثغرات الأمنية</strong>، تاليًا.","changelog.bbc74b04e065":"<strong>الأمان</strong>","changelog.1b1ab848b297":"<strong>كان تعديل حيّ من مشارك قادرًا على تسمية ملف على جهازك</strong>، فيفتحه Oscillate بعد ذلك. كانت اللقطات الكاملة من المشارك تُنظَّف عند دخولها؛ أما التعديلات المفردة فلا. كل تعديل وارد الآن تُنزع منه مسارات الملفات وحالة الإضافات، تمامًا كما كان يحدث دائمًا للتعديلات الصادرة.","changelog.db067cb38cfa":"<strong>مسار شبكي في ملف مشروع أو في تعديل مشارك كان يمكن أن يُسرّب بصمة تسجيل دخولك إلى Windows</strong> حين تستضيف غرفة أو تقرأ لقطة، لأن Windows يسجّل الدخول إلى مشاركة الشبكة من تلقاء نفسه. كل قارئ الآن يتحقق من أن المسار ملف على قرص محلي <strong>قبل</strong> أي استدعاء لنظام الملفات، ويرفض مشاركات الشبكة ومسارات الأجهزة رفضًا قاطعًا.","changelog.a26ae554ba1a":"<strong>كان عضو في الغرفة قادرًا على انتحال هوية عضو آخر</strong> بتمرير عرض اتصال باسمه، ومعها نسبه والمسارات المسلَّمة إليه وموازيره في الكوميتي. هذا مرفوض الآن في الصفحة ومرة أخرى في عملية الغرفة.","changelog.2819dc6c2317":"<strong>كان المشروع المفتوح، أو اللقطة الكاملة من مشارك، يصل إلى خيط الصوت دون تحقّق.</strong> قيمة أتمتة 1000 كانت تعني +60 dB، وكسب 1000 dB كان يصير لانهاية. كلاهما يُتحقَّق منه الآن عند الوصول. الضرر الذي لا يمكن إصلاحه يُرفض، والأرقام الخارجة عن المدى تُحصر، ويُقال لك ما الذي تغيّر.","changelog.52903827c85e":"<strong>كل مشارك الآن يعرّف بنفسه مباشرة</strong> حين يُفتح رابط، وهذا ما يتيح للمبارزة أن تُجلس الجميع. هذا التعريف يربط الرابط مرة واحدة، ولا يعيد تسميته أبدًا، ولا يستطيع ادّعاء شخص يتحدث باسمه رابط آخر.","changelog.caedde91f452":"<strong>طلب الدمج من نسخة متفرعة لم يعد يعمل على جهاز البناء Windows المستضاف ذاتيًا</strong>، الذي يحمل مفتاح توقيع المحدِّث.","changelog.bb6bf121bbd4":"<strong>التشغيل والمحرّك</strong>","changelog.b8040300e667":"<strong>نوتات عالقة عند الإيقاف، وعند قفزة رأس التشغيل، وعند التفاف التكرار.</strong> تُطلق كل النوتات الآن عند كل واحدة من هذه، ومسار الطبول الذي يُكتم أثناء صدح نوتة لم يعد يتركها ممسوكة.","changelog.60710aea2474":"<strong>تأخير جهاز النوتات نفسه لم يكن يُعوَّض</strong>، فكان الجزء المارّ عبر Tread يُعزف متأخرًا بمقدار ذلك التأخير بالضبط.","changelog.af5806634af3":"<strong>كان رأس التشغيل ينجرف عن الصوت عبر منحدر الإيقاع</strong>، الذي كان يُحسب متأخرًا بمقطع واحد. وكان التحديد القصير للموضع يحرّك رأس التشغيل ويترك الصوت مكانه.","changelog.6c68d7fa128a":"<strong>المقاطع المعادة الطبقة كانت تُطقطق</strong> حيث يُقرأ الملف على دفعات. <strong>والمقاطع المعكوسة كانت تتلعثم</strong> بعد نهاية ملفها. وكان التلاشي الخارج يُقاس خطأً عبر تغيير في الإيقاع. والقص قبل المازورة 1، أو على مقطع معاد الطبقة، كان يقرأ الجزء الخطأ من الملف، وذيل الانقسام كان يُقرأ من رأس اللقطة.","changelog.6187aee593ac":"<strong>خانة المازج المعاد استعمالها كانت تعزف بقايا المسار السابق.</strong>","changelog.7f42837dfb17":"<strong>المقاييس والجهارة كانت تقرأ القناة اليسرى فقط.</strong> المسار الموجَّه بالكامل إلى اليمين لم يُظهر شيئًا، وأرقام الجهارة تجاهلت الجانب الأيمن. الجانبان يُقاسان الآن.","changelog.75dc4a3bc8cb":"<strong>الأعداد دون الطبيعية تُصفَّر الآن</strong> على الخيوط التي تُصيّر، الحيّة وغير المتصلة، فلم يعد الخفوت الطويل المتلاشي نحو الصمت قادرًا على رفع حمل المعالج فجأة. ⚠ احتاج ذلك إلى موضع <code>unsafe</code> جديد واحد، <code>denormal.rs</code>، راجعه المالك ووافق عليه؛ ويسرده <code>SECURITY.md</code>.","changelog.3b1cc767fb75":"<strong>كانت المعاينة الثانية قد تبدأ من منتصفها، أو لا تبدأ أبدًا.</strong>","changelog.2e44dc9f2c04":"<strong>التصدير</strong>","changelog.aa4e4757d0fd":"<strong>المسارات المكتومة كانت تتسرّب إلى مزيج الماستر.</strong>","changelog.dca6958b82dc":"<strong>بعد حذف مسار أو إعادة ترتيبه، كانت الأجزاء المصدَّرة تقع على القنوات الخطأ.</strong>","changelog.0c77d58d7aa5":"<strong>كان التصدير يشوّش على التشغيل الحيّ.</strong> كان يستعمل تدفقات الصوت الخاصة بالجلسة، فقد تحمل المسارات المنفصلة صوتًا حيًّا، ويبدأ التشغيل بعد ذلك من المكان الخطأ. التصدير الآن يُصيّر من تدفقات خاصة به.","changelog.927038d08ab5":"<strong>معدل العيّنات الذي اخترته كان يُتجاهَل.</strong> كل شيء كان يُصيَّر ويُكتب بـ 48 kHz؛ والآن يُصيَّر بالمعدل المختار.","changelog.7a5894bfd40f":"<strong>ملفات AIFF كانت تدّعي ضعف معدل عيّناتها</strong>، فتعزفها البرامج الأخرى أعلى بأوكتاف. ملفات AIFF-C العائمة تحمل الآن ترويسة كاملة.","changelog.b85e29446f98":"<strong>كان FLAC بعمق 24 بت يُحجَّم ويُضاف إليه التشويش المقصود على نحو خاطئ.</strong>","changelog.81c39a6550b6":"<strong>ملفات <code>.mid</code> المصدَّرة كانت تقطع النوتات المكررة في برامج DAW الأخرى.</strong> كانت بداية النوتة تُكتب قبل نهاية النوتة السابقة على النبضة نفسها.","changelog.f92853678a37":"⚠ <strong>ما زالت الصادرات تُصيَّر دون إضافات VST 3 وCLAP.</strong> انظر <em>ما زال مفتوحًا</em>.","changelog.cdb5aaa35ee1":"<strong>التسجيل</strong>","changelog.cd64252ce063":"<strong>كان دخل بتردد 44.1 kHz تحت خرج بتردد 48 kHz يسجّل بفجوات</strong>، فنحو 8% من اللقطة صامت. يُفتح الدخل الآن بمعدل الخرج، أو يُحوَّل.","changelog.0c4683ccfd2e":"<strong>كان تأخير اللقطة يتفاوت</strong> بحسب المدة التي ظل فيها الدخل مفتوحًا.","changelog.18dc0df95ce2":"<strong>لقطات العدّ التمهيدي والإدخال الفوري كانت تقع متأخرة حتى مخزن مؤقت كامل</strong>، وكانت الكتلة عند نقطة الخروج تسقط. وكان إدخال MIDI الفوري يحتفظ بنوتات عُزفت قبل نقطة الدخول.","changelog.b39ca3f1ef37":"**الملف المُفلَت الذي فشل نسخه كان يترك ملفًّا ناقصًا في <em>Imports</em>.**","changelog.f489fa7c6c3b":"كانت الفجوة الدنيا بين النوتات في كشف البدايات أطول بخطوة تحليل واحدة.","changelog.585177b8005b":"<strong>الإضافات</strong>","changelog.9ea91ef0792f":"<strong>تحريك المقابض في نافذة إضافة VST 3 الخاصة لم يصل إلى الصوت قط</strong>، وتغييرات المعاملات بعد 512 في كتلة واحدة كانت تسقط.","changelog.27e989498bde":"<strong>التراجع عن إزالة جهاز يعيد صوته كما كان.</strong>","changelog.27732aa68c31":"<strong>إزالة مسار تغلق عمليات إضافاته</strong>، والمشروع الجديد أو المفتوح يحرّر عمليات المشروع السابق.","changelog.3db09f2ff76a":"<strong>كانت الإضافة المنهارة أو المعلّقة قادرة على تجميد التطبيق.</strong> الإضافة المعطوبة تُوقف الآن قبل أن ينتظرها Oscillate، ولا يُمسك أي قفل أثناء بدء إحداها. ويُبلَّغ الآن عن العطل في اتصال التحكم الخاص بالإضافة.","changelog.d5b5750c16ca":"<strong>الإضافة التي حدّدت مكانها يدويًا لم تكن تُضاف إلى الفهرس قط</strong>، وإعادة الفحص كانت تلغي فكّ الحظر والإضافات المحدَّد مكانها التي أُضيفت أثناء عملها.","changelog.8d834fbea6c9":"<strong>الإضافة التي تغيّر تأخيرها بنفسها</strong> تحصل الآن على خطة جديدة معوَّضة.","changelog.750a21151bde":"<strong>كانت نوافذ الملفات تعمل على الخيط الرئيسي</strong> (الفتح، والحفظ، والحفظ باسم، وإعدادات السلاسل، و<em>تحديد الموقع…</em>، وإضافة مجلد إضافات، واختيار مجلد معاينة، واستيراد الكلمات والصوت) وكان يمكن أن توقع النافذة في جمود. كلها تعمل خارجه الآن.","changelog.78ee198e26b6":"<strong>المحرّرات</strong>","changelog.2b57535746ad":"<strong>سحب الحافة الطرفية لنوتة يغيّر طولها الآن</strong>، وسحب بدايتها يحرّك البداية ويُبقي النهاية، في خطوة تراجع واحدة.","changelog.eb080b94fcd5":"<strong>سحب النوتة القطري، والسحب القطري للنسخ، كلٌّ منهما خطوة تراجع واحدة</strong>، والسحب مع <code>Ctrl</code>/<code>Alt</code> ينسخ بدل أن ينقل.","changelog.33cf4310ae9b":"<strong>مسار الأتمتة تحت مقطع لا يبدأ عند المازورة 1 كان يرسم نقاطه ويكتبها عند المازورة 1.</strong> يعمل الآن في المكان الحقيقي للمقطع. وتحت طقم طبول لم يعد يتبع تمرير لفّة البيانو المخفية، و<em>حفظ ككاتا</em> و<em>اطبع</em> يغطيان امتداد المقطع نفسه.","changelog.a75d2252b98e":"<strong>إسكات امتداد داخل غلاف كسب هادئ كان يضخّم الصوت من حوله.</strong> تقسيم مقطع أو قطعه أو قصّه من اليسار يُبقي الآن غلاف كسبه حيث يكون الصوت.","changelog.b4c012d3b380":"<strong>علامات العابرات على مقطع مقسوم أو مقصوص كانت تُظهر ضربات لا يعزفها المقطع.</strong> والقص من محرّر الصوت يحتفظ بإزاحة القص السابق، في نافذة المحرّر المنفصلة أيضًا. ولم يعد محرّر الصوت يرسم نافذة قديمة بعد التكبير، ولا مقطعًا معكوسًا إلى الأمام عند التكبير على مستوى العيّنة.","changelog.14e60b4dae34":"<strong>في التوزيع</strong>، كان المقطع المحدد الذي خرج من مجال الرؤية بالتمرير يُفلَت في المكان الخطأ عند النقل أو النسخ، وكان القص من اليسار قادرًا على تجاوز بداية الصوت وسحبه مبكرًا. وكان القص أو التلاشي يعاين التحديد كله بينما لا يتغير إلا المقطع الممسوك؛ والمعاينة تُظهر الآن بالضبط ما يفعله الإفلات. والحركة التي ألغاها نظام التشغيل كانت تُعتمد بدل أن تُترك.","changelog.3e8ed6000a39":"<strong>النقر والسحب في شبكة الإيقاع كانا يعملان في متصفح الاختبار فقط</strong>، ولم يعد النقر بالزر الأيمن يقلب حالة الخلية.","changelog.c83a3388d770":"<strong>كتابة قيمة في مقبض</strong>: 6 dB تعني الآن 6 dB، لا المدى الكامل، و50 في خانة البان لم تعد تعني R100.","changelog.ca7b3b7fb67d":"<strong>لوحة المفاتيح على الشاشة واختصار على الحرف نفسه كانا ينطلقان معًا.</strong> ومفاتيح الأسهم في قائمة المتصفح وعلى المسطرة كانت تنفذ إلى إزاحة التوزيع.","changelog.4ecad0ceceaa":"<strong>النقل ▸ Home وEnd والمؤشر والنصل لم تكن تفعل شيئًا.</strong>","changelog.8872f6e3c7a1":"<strong>الخروج من سطر كلمات بمفتاح Tab كان يمحو توقيت مقاطعه اللفظية.</strong> ولم يعد يُرفض سطر الكلمات المُفلَت تمامًا على بداية سطر آخر.","changelog.c967a14cb0d7":"<strong>رف الأنماط</strong> يتحدّث بعد التراجع والإعادة وتعديل المشارك، ومنتقي الأنماط يُفتح على النمط الحالي.","changelog.9b72ff0fe3e8":"<strong>العربية</strong>: شريط التمرير والفاصل ومسار الكلمات وبطاقة الجلسة كانت معكوسة خطأً.","changelog.0af10661d846":"<strong>كل جملة فيها رقم لها صيغ جمع</strong> في اللغات الثماني عشرة كلها.","changelog.b58312a40a18":"<strong>أصغر منها:</strong> رأس تشغيل معاينة <code>.mid</code> كان يسير بضعف السرعة؛ وملف <code>.mid</code> المُفلَت الذي تقع أول نوتة فيه عند الصفر كان يقع متأخرًا بنبضة واحدة؛ وسحب مسار CC كان يتعرّج؛ ومقبض التلاشي بطول صفري لم يكن ممكنًا إمساكه؛ وسحب ارتفاع المسار كان يبقى منحرفًا بعد رفض؛ وملفات WAV بأعداد صحيحة 32 بت، والصوت بعمق 24 بت في حاوية 32 بت، كانت تُرسم وتُعزف ضجيجًا بالمستوى الكامل.","changelog.ea7aa3c36986":"<strong>الأجهزة والآلات</strong>","changelog.d838f5d0cc47":"<strong>تدوير مقبض على آلة مصنعية (Cello وSub Bass وغيرهما) كان يحوّلها إلى مركِّب Wavetable افتراضي</strong>، ولم يكن التراجع يعيدها. الآلات المصنعية تفتح الآن لوحة، وتُظهر صف مقابض الصوت، وتنسخ وصفة تسمّيها.","changelog.618828dda056":"<strong>كان Chamber وVault غير مستقرّين في إعداداتهما الافتراضية.</strong> كان عنصر التحكم Low Decay فيهما قادرًا على جعل الصدى ينمو بلا حدود. أما <em>Freeze</em> فلم يعد يخفت ولا ينمو.","changelog.96ae9147c9a5":"<strong>مزيل الصفير Quench كان يعمل دائمًا</strong>، لا على أصوات السين فقط.","changelog.a33e5317a331":"<strong>تكرارات Relay كانت تنجرف متأخرة مع كل صدى</strong>، وكان Sparks يُطقطق في إعداداته الافتراضية، وGild يُطقطق بين الكتل، وCeiling يضبط كسبًا واحدًا لكل كتلة. وكان مُفرط الاعتيان المشترك يتعثر عند حدود الكتل بحجم المخزن المؤقت الافتراضي، وهذا مسّ كل جهاز دفع ومضخّم ومشبِّع.","changelog.0b69c04327da":"<strong>كانت التغذية الراجعة قادرة على الانفلات</strong> في Shoal وRelay فتقفل المسار في الصمت.","changelog.c9fc79327515":"<strong>عناصر تحكم لم تكن تفعل شيئًا أصبحت تفعل:</strong> Grid Bias في Guard، وDiffusion في Vault، وTension في Coil على مداه كله، وDriver Position في Foil، وMedium في Wear، وOversample في Ceiling.","changelog.f73ae6f614ed":"<strong>صُحّح أيضًا:</strong> Halve وFlush في Lantern، وRein عند زمن صدى صفري أو متحرك، وComb عند المرور بالصفر، وعتبة Strand، والإشارة الجافة في Cleave وStrand، التي لم تكن تُؤخَّر لتطابق الإشارة المعالَجة.","changelog.d3d9ad692654":"<strong>لا مزيد من النوتات العالقة</strong> من Scatter وTurn وHone وStack وApproach وHold وTread وRunner وRevoice، وأجهزة النوتات تعزف الآن بالطريقة نفسها أيًّا كان حجم مخزن الصوت المؤقت.","changelog.039ca12ebc31":"<strong>Hammer</strong> يُصدر صوتًا عند Hold 0 ولم يعد يضاعف مستواه عند إعادة القدح؛ و<strong>صوت مُعايِن العيّنات المسلوب يخفت</strong> بدل أن يُطقطق؛ وتصفيقة Skin تتبع الشدة؛ وFeedback في Sideband يعمل على الخوارزميات الثماني كلها؛ ولم يعد Armory ينهار فوق النوتة 127. وانزلاقات كل آلة أصبحت ناعمة أيًّا كان حجم المخزن المؤقت.","changelog.bf11fb10bbc6":"<strong>المنحنيات على بطاقات الأجهزة</strong> كانت تُقاس والجهاز ما زال ينزلق، فكانت خاطئة.","changelog.74b1e2eb3733":"<strong>الغرف والجلسات</strong>","changelog.a0322da52ba0":"<strong>مبارزة الكوميتي كانت موجودة على الجهاز الذي ضغط البدء فقط.</strong> مقاطع المشاركين في موازيرهم الخاصة كانت تسقط دون كلمة، وترتيب الأدوار قد يختلف بين الأجهزة. المبارزة الآن جزء من المشروع، يبدؤها المضيف ويوقفها، وهي نفسها على كل جهاز.","changelog.221c7bfd4bd2":"<strong>اللقطات:</strong> اللقطة التي تملكها سلفًا لم تعد تُحتسب على المضيف؛ واللقطات التي تصل معًا لم تعد تضيع؛ والنقل لم يعد يسبّب انقطاعات؛ وملف اللقطة المكتوب نصفه يُزال.","changelog.ca86740f15d8":"<strong>كل رسالة على رابط عرضه هذا الجهاز كانت تُعالَج مرتين.</strong>","changelog.97e5f228e6ba":"<strong>كان الميكروفون قادرًا على البقاء حيًّا بينما يقول زرّه إنه مطفأ</strong>، بعد إيقاف التقاط آخر. وكان الضغط للتحدث ينطلق أيضًا أثناء الكتابة في حقل نصي.","changelog.4a064c4a34ce":"<strong>إرجاع الجلسة</strong> كان يجمّد التطبيق أثناء إعادة التشغيل. <em>تراجع إلى هنا</em> كان يتراجع خطوة واحدة وصار الآن يتراجع حتى تلك النقطة؛ و<em>العودة إلى الآن</em> تستعيد التوزيع الحيّ؛ والفرع الذي يفشل يقول ذلك.","changelog.3d5138762144":"<strong>ورقة التوزيع</strong> تسمّي صفّك أنت، وتتحدّث حين ينضم مشارك آخر، ولم تعد تنسب الهيكل الجاهز للقالب إلى أحد.","changelog.c893c1638a99":"<strong>تعديلات كان يمكن أن تكسر الجلسة:</strong> كتابة ترتيب المسارات كله كانت قادرة على إسقاط مسارات؛ وحذف مسار أو مقطع كان يترك صفوف الأنماط تشير إلى لا شيء، فتُرفض كل حركة لاحقة في الرف على ذلك النمط؛ وكان يمكن حذف لقطة ما زالت مستعملة على مسار آخر؛ وكان يمكن أن يختلف جهازان إلى الأبد حين يعدّل أحدهما مسارًا كاملًا ويعدّل الآخر شيئًا داخله؛ والمقطع المنقول إلى مسار يمسكه شخص آخر كان يُفحص مقابل المسار الخطأ.","changelog.8dfa12545efa":"<strong>التعديل الذي يُجرى بعد الحفظ مباشرة لم يكن يعلّم المشروع غير محفوظ</strong>، والتعديل السريع كان قادرًا على الاندماج في تراجع أو إعادة.","changelog.5fe00713937b":"<strong>أجزاء الملف التي كتبها Oscillate أحدث تنجو الآن من الحفظ.</strong>","changelog.eb5b0a0ed3af":"<strong>إعادة الانضمام إلى غرفة</strong> لم تعد تُلحق بسجل الجلسة الأخيرة.","changelog.80a4afa3903d":"الفاصل الزمني لجلسة بدأت من قالب لم يعد يُفتح بفصل زائف <em>فُتحت الغرفة</em>؛ وفحص الاتصال لم يعد يُبلغ عن NAT متماثل غير موجود؛ ولم يعد بإمكان مشارك خامس أن ينضم.","changelog.bf9104f16adc":"<strong>النوافذ والإعدادات</strong>","changelog.f478b946c3ed":"<strong>النوافذ المنفصلة كانت تكتب فوق إعدادات بعضها.</strong> تُكتب الإعدادات الآن مفتاحًا مفتاحًا، تحت قفل واحد، وتعيد كل نافذة قراءتها.","changelog.0e7572903a98":"<strong>الخروج والنافذة مصغّرة كان يُضيّع موضعها وحجمها.</strong>","changelog.3d17c7fddadd":"<strong>تقريرا عطل كُتبا في اللحظة نفسها كان أحدهما يكتب فوق الآخر.</strong>","changelog.8ad92ece2e49":"<strong>يُفرَّغ سجل الاستعادة حين يُغلق Oscillate</strong>، وحين تتوقف، وحين تصل لقطة.","changelog.09d6b687a5b5":"كان <em>نعم، ابحث عند بدء التشغيل</em> في سؤال التشغيل الأول يُرفض بصمت، وكان التثبيت الفاشل للتحديث يختفي دون كلمة.","changelog.166249aead89":"ربط <code>Space</code> في الإعدادات ▸ الاختصارات كان يسرق التشغيل؛ وكانت شاشة خطأ تحلّ محل شريط العنوان فلا يمكن إغلاق النافذة؛ وكانت نافذة قد تبقى دون تحجيم بعد سحب انقطع في منتصفه.","changelog.42078e2a4ce9":"<strong>المحدِّث وأدوات الإصدار</strong>","changelog.079af0dc6c83":"<strong>لم يكن Windows ليحصل على بيان تحديث على الإطلاق.</strong> كان سكربت الإصدار يبحث عن أسماء مثبّتات لا ينتجها Tauri 2.","changelog.ec17b741d16a":"<strong>كان <code>1.0.0</code> سيطابق مثبّتات <code>1.0.0-rc</code></strong>، فكان بيان الإصدار النهائي قادرًا على الإشارة إلى المرشّح للإصدار إلى الأبد.","changelog.12c5a28c6a09":"<strong>وسم المرشّح للإصدار لم يكن يستطيع بناء مثبّته</strong>، لأن MSI يرفض نسخة ما قبل الإصدار. نسخة ما قبل الإصدار تبني الآن NSIS فقط.","changelog.df7f1b0ff2d6":"<strong>ملاحظات الإصدار كانت تُقتطع بمطابقة البادئة</strong>، فكان <code>1.0.0</code> سيأخذ ملاحظات المرشّح للإصدار، والملاحظات المفقودة لم تكن تُطلق إلا تحذيرًا. هي الآن قسم هذه النسخة بالضبط، وغيابها يُفشل الإصدار.","changelog.88312da3637b":"<strong>بوابات لم يكن ممكنًا أن تفشل، أو لم تكن تعمل في أي مكان:</strong> فحص التكافؤ في CI كان ينقصه هدف WebAssembly؛ وفحص التنزيل كان يُفشل كل إصدار خاص بـ Windows وحده؛ واختبارات طرف لطرف في ملفين لم يكن ممكنًا أن تفشل؛ وتشغيل اختبارات طرف لطرف كان يعيد كتابة لقطات شاشة التوثيق؛ وصفحة سجل التغييرات المنشورة كانت تحمل معرّفات أقسام مكررة. بوابة جديدة ترفض محارف التحكم في سجل التغييرات والتوثيق.","changelog.da13fe88f9b4":"<strong>ما وُجد بمراجعة الإصلاحات نفسها</strong>","changelog.d52c1048f2f9":"⚠ كل إصلاح أعلاه رُوجع مرة أخرى بعد دخوله. وجدت تلك المراجعات تراجعات حقيقية في الإصلاحات، وعدة عيوب أقدم فاتت الجولة الأولى. كلها مُصلحة هنا.","changelog.8f27c8f6a2dc":"⛔⛔ <strong>بعد إزالة مسار أو فتح مشروع، كانت لوحة المفاتيح على الشاشة ولوحة مفاتيح MIDI ومعاينة النوتات في لفّة البيانو تعزف المسار الخطأ أو لا شيء على الإطلاق، ولم يكن التسجيل يلتقط شيئًا.</strong> كانت النوتات الحيّة تُوجَّه بمعرّف القناة بينما يقرؤها المحرّك بموضعها، والاثنان لا يتفقان إلا حتى يُزال أول مسار. تجد النوتات الآن مسارها بالموضع، ويُعاد قراءته بعد كل تغيير، والمفتاح الممسوك أثناء إزالة مسار يُطلق على مساره.","changelog.0e5001be4975":"⛔ <strong>مع تفعيل التكرار، كانت نوتات MIDI عند بداية التكرار تسقط في كل تكرار بعد الأول.</strong> المقاطع الصوتية كانت سليمة. جدولة النوتات تعرف التكرار الآن.","changelog.4dd4a9484523":"⛔ <strong>تعديلات الغرفة التي تمسّ عدة أشياء دفعة واحدة كانت قادرة على أن تقع مختلفة على أجهزة مختلفة، إلى الأبد وبصمت</strong> (نقل مقطعين بينما يعيد أحدهم تلوين أحدهما، أو حذف مسار بينما يعدّل أحدهم نمطه). كل تعديل داخل العملية يُحسم الآن على حدة، وبوابة جديدة تعيد تشغيل ثلاثة أجهزة عبر كل ترتيب وصول ممكن.","changelog.73da74cfe8a0":"⛔ <strong>كان المشارك قادرًا على الاستيلاء على <code>Ctrl+Z</code> الخاص بك</strong> بإعادة استعمال معرّف آخر تعديل لك. المعرّف الذي يملكه شخص آخر سلفًا يُرفض الآن، ويكلّفه ذلك.","changelog.3496697e7b5b":"⛔ <strong>كان الحفظ قادرًا على إسقاط إضافة تتجاوز إعداداتها نحو 19 MB، وكل حفظ كان يخزّن نسخة كاملة أخرى من المسار في ملف المشروع</strong>، فتنمو الملفات بلا حدود. إعدادات الإضافات تنتقل الآن بايتات وتُحفظ مرة واحدة في الملف المحفوظ: لا في سجل التراجع أبدًا، ولا في الغرفة أبدًا.","changelog.f26a96f70549":"<strong>الإضافات:</strong>","changelog.6efbe93b609b":"الإضافة التي ترفض إعداداتها المحفوظة لم تعد تُحفظ قيمها الافتراضية فوق إعداداتك.","changelog.3d2817502593":"التأخير الذي تُبلغ عنه الإضافة لم يعد يعلّم المشروع متغيرًا، ولا يضيف خطوة تراجع، ولا يمحو إعدادات إضافات أحد المتعاونين.","changelog.c4b6e7b8714a":"الإضافة البطيئة مرة واحدة لم تعد تُعامَل كأنها انهارت، والتي تجيب فورًا لم تعد تُحسب خطأً عالقة فيُعاد تحميلها.","changelog.ae1ae60b6520":"التراجع والإعادة يعيدان الإضافات بالإعدادات التي كانت عليها، بما في ذلك حين حذف متعاون المسار ثم تراجع عن ذلك، وحين كانت الإضافة مفقودة في ذلك الوقت.","changelog.5dc3a7247bfd":"تغييرات إعدادات VST 3 المسبقة التي تحرّك أكثر من 128 معاملًا تصل كلها إلى الصوت، ولم تعد الإضافة تُعاد من البداية كل كتلة. وإعادة تشغيل VST 3 لم تعد ترمي التغييرات الأخرى التي أعلنتها الإضافة أثناءها.","changelog.1396f179afdf":"تتبع الإضافات معدل عيّنات جهاز الصوت.","changelog.39e285644bd7":"نوافذ الملفات تتبع النافذة الرئيسية وتُفتح واحدة تلو الأخرى. يرفض «حفظ باسم» إذا عُدّل المشروع أو استُبدل والنافذة مفتوحة، ولم يعد «فتح» يُرفض لأن متعاونًا عدّل في الأثناء.","changelog.ba3a925735d4":"<strong>التشغيل والتسجيل:</strong>","changelog.ac75155693e0":"فصل جهاز الصوت واستئنافه، أو تغيير الإيقاع أثناء التشغيل، لم يعد يترك الصوت غير متوافق مع رأس التشغيل.","changelog.cfe7e8319c5a":"المسارات المعوَّضة عن تأخير إضافة لم تعد تنقطع كلما أُعيد بناء المزيج أو التفّ التكرار.","changelog.99bca8f464be":"المفاتيح التي تمسكها لم تعد تُقطع حين يلتف التكرار أو يتحرك رأس التشغيل.","changelog.d98cd614c1dc":"النوتات المعزوفة أثناء العدّ التمهيدي لم تعد تتكدّس على النبضة الأولى للقطة. والنوتة المعزوفة قبيل النبضة القوية بقليل (ضمن كتلة أو 30 ms) تُحفظ وتقع عليها.","changelog.e786b3ffa54c":"استدعاء الدخل المتأخر قليلًا لم يعد يترك فجوات في التسجيل، ومراقبة الدخل لم تعد تنقطع بضع أجزاء من الثانية كلما قُلّص تراكم الدخل.","changelog.ee43b80e51fe":"النوتات ذات إعداد الاحتمال لم تعد تكرر النمط نفسه بعد تحريك رأس التشغيل كما كانت ستفعل الدورة التالية للتكرار.","changelog.ae9faf402cfe":"الواجهات الصوتية متعددة القنوات لم تعد تبدّل المداخل بعد فيض.","changelog.a28c78da2430":"المداخل ذات معدلات العيّنات العالية لم تعد تتشوّه بالتداخل الطيفي في جلسة ذات معدل أدنى.","changelog.66785b97f53f":"<strong>التصدير:</strong>","changelog.e230adbb4330":"كان MP3 فوق 48 kHz يفشل بعد أن تُصيَّر الأغنية كلها. يُكتب MP3 الآن بـ 48 kHz، والإعدادات ▸ التصدير تقول ذلك.","changelog.6e5025c21bdc":"التصدير المرفوض يخبرك الآن بالسبب تحت قائمة ملف؛ وكان من قبل يفشل بصمت.","changelog.1de1be9b8ded":"الجهاز ذو القراءة المسبقة لم يعد يجعل التصدير يبدأ متأخرًا ويفقد نهايته.","changelog.69d54e8f37b8":"لم يعد MIDI في التصدير ينجرف مبكرًا بعد تغيير في الإيقاع أو منحدر.","changelog.a4184301f89d":"<strong>مفتاح التشويش المقصود كان يُتجاهَل:</strong> كل تصدير بعمق 16 و24 بت كان يُضاف إليه التشويش المقصود حتى والمفتاح مطفأ. صار يُحترم الآن، والمسارات المنفصلة تحمل تشويشًا مستقلًا.","changelog.01060597d526":"الملفات المسحوبة من مجلد مؤقت لم تعد تترك نسخًا في Imports.","changelog.1181bbddc23a":"لوحة الجهارة لم تعد تصف كل رقم بأنه «ناقص» عند 88.2 kHz وما فوقها.","changelog.0f052d7de643":"<strong>الغرف والجلسات:</strong>","changelog.ce576eef99b0":"يستطيع أي أحد إنهاء مبارزة كوميتي، بما فيها مبارزة غادر مضيفها، ولا تُحفظ المبارزة في ملف المشروع أبدًا؛ وضغطتا بدء في اللحظة نفسها تُحسمان إلى مبارزة واحدة.","changelog.9a242815cb22":"الانضمام إلى غرفة على مشروع موجود لديك أيضًا على القرص لم يعد يحذف استعادة الأعطال لذلك المشروع.","changelog.e1a82a286154":"«تراجع إلى هنا» في الغرفة يرسل كل تراجع إلى المنتجين الآخرين، ويسترجع التغييرات التي أعدتها بعد تلك اللحظة.","changelog.152a9fa8944c":"اللقطة التي قطعها عطل تصل في المرة التالية التي تُرسل فيها.","changelog.b58ba06bb488":"استعادة الأعطال تحتفظ بسحب منزلق لمتعاون قاطعه تعديلك أنت.","changelog.db0e3ba74f7a":"فتح مشروع داخل غرفة لم يعد يسمح لتعديلات المشاركين الأقدم بالكتابة فوقه؛ وإعادة الانضمام إلى غرفة لم تعد تكلّفك مخالفة.","changelog.121c95328780":"تدويرتان منفصلتان للمقبض نفسه خطوتا تراجع، لا خطوة واحدة.","changelog.731cf5b68562":"النوافذ المنفصلة لم تعد تلغي أحجام لوحات بعضها أو اختصاراتها أو إعدادات تصديرها.","changelog.19fbc09eb565":"لم يعد ملف ▸ جديد يعرض استعادة الجلسة التي غادرتها للتو.","changelog.9e2773fb1867":"المقبض الذي تديره على جهاز يسحبه متعاون يحتفظ بقيمته على كل جهاز، والمنزلق أو المقبض الذي يُسحب بعيدًا ثم يُعاد إلى حيث بدأ يصل إلى الغرفة بدل أن يكلّفك مخالفة.","changelog.0541b65c1e83":"المسار أو اللقطة الذي يُحذف بينما يعيد متعاون تلوين أحد مقاطعه أو يضيف إليه تلاشيًا يختفي على كل جهاز، والتراجع عن حذف بينما يغيّر متعاون المقطع نفسه يعيده على كل جهاز.","changelog.d15a8772edef":"تثبيت عدة مقاطع MIDI إلى صوت دفعة واحدة يصل إلى المنتجين الآخرين، والنمط الذي عزف اثنين منها لم يعد يستمر في تسمية واحد.","changelog.622a2b984e68":"إنهاء مبارزة بدأها شخص آخر لم يعد يوقف عمل <code>Ctrl+Z</code>، ومغادرة ضيف للغرفة لم تعد تنهي مبارزة المضيف للجميع.","changelog.0603f0c1588b":"المنتج الذي يعيد الانضمام يحتفظ بالتعديلات التي أجراها أثناء إعادة الاتصال، ويعود اسمه ومقعده في المبارزة ما إن يذهب رابطه القديم، ولم يعد بإمكان شخص ثانٍ يدّعي هويته أن يستولي عليها.","changelog.f1a8d7a6d26e":"التعديل المرفوض من مشارك لم يعد يسمح لهذا الجهاز بإعادة استعمال ختمه، وقبول استعادة الأعطال داخل غرفة لم يعد يسمح لتعديلات المشاركين الأقدم بالكتابة فوق العمل المستعاد.","changelog.c8981d80a918":"<strong>المحرّرات:</strong>","changelog.e708a20db8e5":"أول سحب لمقبض على آلة في مشروع أقدم (Cello مصنعي مثلًا) خطوة تراجع واحدة، ولم يعد في الغرفة يكتب فوق تعديلات متعاون على ذلك المسار.","changelog.102d708d0039":"تحت شبكة الإيقاع، يصطف مسار الأتمتة مع الخطوات.","changelog.8febd9bab766":"سطر الكلمات المُفلَت تمامًا على بداية سطر آخر يوضع بعده، ولا يتحرك شيء آخر.","changelog.1a424e0ded88":"ملفات WAV التي تسمّي ترويسة صيغتها شيئًا غير PCM العادي أو العائم تُرفض برسالة بدل أن تُعزف ضجيجًا.","changelog.08c29531d3c4":"صف النمط الذي أُزيل مقطعه لا يُظهر أي مقطع، بدل مقطع بلا اسم لا يمكن فتحه.","changelog.3c2daf0d3e7f":"<strong>دخل MIDI:</strong> المفاتيح المعزوفة بينما المسار المجهَّز لا مكان له ليعزف فيه تُرفض بدل أن تُدّخر وتُعزف لاحقًا دفعة واحدة؛ ويمكن اختيار لوحتَي مفاتيح متطابقتين كلتيهما؛ ولم تعد الإعدادات ▸ MIDI تتعطل خلف مشغّل بطيء.","changelog.412206443be0":"تغيّر — ما يبدو مختلفًا في مشروع محفوظ","changelog.6459a83979a9":"⚠ <strong>المشروع المحفوظ قبل هذا البناء قد يبدو مختلفًا حين تفتحه.</strong> كل واحد من هذه تصحيح، وعدة منها تحرّك المستويات ببضعة ديسيبلات، فافحص أي مزيج يهمّك.","changelog.d2730738dfc9":"<strong>التسجيل يتجاهل التكرار.</strong> أثناء التسجيل يكون التكرار مطفأً، للصوت وMIDI على السواء، وتمضي اللقطة مباشرة متجاوزة نهاية التكرار. ويبقى التكرار مطبّقًا على التشغيل. ومن قبل، كانت كل دورة من تسجيل مكرَّر تُكتب متتالية، وكانت لقطة MIDI تخالف لقطة الصوت.","changelog.15f909e8e1c8":"<strong>يمكن أن يصل طول التصدير إلى عشر دقائق بأي معدل عيّنات.</strong> ويُرفض مسبقًا، مع سبب، إذا لم تكن لدى الجهاز الذاكرة الكافية لحمله. وقبل هذا البناء كان الحد عشر دقائق عند 48 kHz، وكانت الصادرات تتجاهل المعدل الذي اخترته.","changelog.3d3d8119cb3d":"<strong>تأخير Ceiling هو 100 عيّنة في إعداداته الافتراضية (وكان 72)</strong>، ومنتقي Oversample يغيّره الآن. ما يعلنه Ceiling هو قراءته المسبقة مضافًا إليها تأخير كاشفه الخاص، فيصطفّ بتعويض تأخير الإضافات.","changelog.18563098f694":"<strong>Comb:</strong> المرور بالصفر مفعّل افتراضيًا، ومركز المسح أدنى بخطوة Delay واحدة.","changelog.429dc9a41e0f":"<strong>Tension في Coil</strong> يحوّل الآن 0 إلى 1.92 (وكان 1.2) و1 إلى 0.75 (وكان 1.0)؛ و0.5 لم يتغير.","changelog.42ca15cb09d8":"<strong>Wear وSpool وOxide:</strong> المكوّن ذو 6 Hz يستجيب الآن لـ Flutter بدل Wow. وسيطا Vinyl وConverter في Wear صوتان جديدان؛ وTape لم يتغير.","changelog.9605e8d810a8":"<strong>Sparks:</strong> الحبيبات الآن نوافذ Hann نظيفة حين تكون السحابة متفرقة وفي الإعدادات الافتراضية، فيتغير شكل الحبيبة حتى لو لم تلمسه قط.","changelog.a2fb1a26818a":"<strong>Guard</strong> لا ينفتح إلا ضمن Grid Bias الخاص به من نوتة.","changelog.ee039b997faa":"<strong>Vise وWeld وParry وPeen وGuard:</strong> تُرشَّح السلسلة الجانبية قبل قياسها، فتتحرك العتبات الفعلية بعدة ديسيبلات.","changelog.4415b1af6ee9":"<strong>Quench</strong> يزيل الصفير بمقادير مختلفة.","changelog.2d621f5fc3be":"<strong>Edge:</strong> صار Attack وRelease أبطأ بأربع مرات، كما هو مكتوب عليهما.","changelog.c091d1c40cb7":"<strong>Triode وRasp وShear وFold:</strong> يتغير الباص والهبوط عند الإفراط العالي في الاعتيان. <strong>Furnace:</strong> يتغير توقيت الهبوط.","changelog.3875af7ad8a2":"<strong>Chamber وFoil وCoil وVault وBaffle:</strong> تتغير نقاط خرج الصدى، فيتحرك المستوى والصورة الستيريو. ومجال <strong>Vault</strong> المتأخر يبدأ الآن عند التأخير المسبق، وناشراته أقصر.","changelog.0a57881c2b36":"<strong>Shoal</strong> فيه تغذية راجعة أقل حين يكون Voices فوق 1. ودفع <strong>Rein</strong> يتدرج الآن في الظهور مع مقداره.","changelog.72f7c4662b6e":"<strong>تكرارات Relay</strong> تقع في وقتها، ولا يمر عبر محدِّد التغذية الراجعة الجديد فيه إلا الأصداء التي تدور مرة أخرى، فلا يُشبَّع الدخل الساخن. <strong>ورؤوس Spool الإضافية</strong> تكرر في الأزمنة المضبوطة عليها.","changelog.def90dbc42c4":"<strong>Sideband</strong> يفرط في الاعتيان الآن أربع مرات حقًّا ويعلن تأخيرًا قدره 24 عيّنة. ولم يعد <strong>Hammer</strong> يضاعف مستواه عند إعادة القدح، وتصفيقة <strong>Skin</strong> تتبع الشدة.","changelog.5d9cf4f7dd65":"<strong>قراءات LUFS المتكاملة</strong> تتغير: البوابة تستعمل الآن كتلًا بطول 400 ms بتداخل 75%، كما يقول المعيار.","changelog.85271e6ecd8c":"<strong>لم تعد الصادرات يُضاف إليها التشويش المقصود إلا إذا كان مفعّلًا.</strong> كان المفتاح يُتجاهَل من قبل، فالتصدير بعمق 16 أو 24 بت المصنوع ببناء سابق كان يحمل تشويشًا لم تطلبه.","changelog.d82014f95805":"<strong>التسجيل ومراقبة الدخل متأخران الآن بنحو 5 ms</strong> عند دورة صوت مدتها 10 ms. يحتفظ الدخل الآن بهامش صغير حتى لا يترك الاستدعاء المتأخر قليلًا فجوة في اللقطة؛ والتأخير ثابت.","changelog.ccde2b49c256":"ما زال مفتوحًا","changelog.2948905e9c03":"⚠ <strong>تُصيَّر الصادرات دون إضافات VST 3 وCLAP</strong>. ملف README في كل مجلد تصدير يقول ذلك. وإصلاحه يتطلب أن يحصل التصيير غير المتصل على نسخة إضافة خاصة به، وهذا قرار تصميم لا عيب.","changelog.0740065d75e1":"⚠ <strong>ثني الطبقة وعجلة التعديل والضغط في لوحة مفاتيح MIDI</strong> لا تُحمل بعد. أما النوتات والشدة ودوّاسة الاستدامة فتُحمل. والنوتة الآتية من العتاد تصدح عند بداية كتلة الصوت التي تستقبلها، واللقطات المسجّلة لا تُعوَّض بعد عن تأخير الدخل والخرج.","changelog.e4f8567eaca5":"⚠ <strong>تُخزَّن إعدادات الإضافات في ملف المشروع قائمةً من الأرقام</strong>، بنحو ثلاثة أضعاف ونصف حجمها، واستعادة الأعطال تعيدها كما كانت عند آخر حفظ.","changelog.94b3ea8fff75":"⚠ <strong>أربعة سباقات نادرة في الغرفة ما زالت قادرة على ترك الأجهزة مختلفة:</strong> مقطع يوضع على مسار في اللحظة ذاتها التي يحذف فيها متعاون ذلك المسار؛ وتعديل يُجرى في لحظة افتتاح مبارزة كوميتي، قبل أن يرى مرسله المبارزة؛ ومقبض على آلة أقدم يديره منتج فيصل إلى جهاز ثالث قبل أول تحريك للمقبض هيّأه؛ ومقطع يُتراجع عن حذفه بينما يعيد متعاون تلوينه، فيعود في كل مكان لكن قد يبقى التلوين الجديد على بعض الأجهزة فقط.","changelog.7f22bd522c65":"أُضيف — النمط يستطيع أخيرًا الوصول إلى الخط الزمني","changelog.0cc9d8e73e75":"⛔⛔ **كان <code>ClipContent::Midi</code> مرجعًا حيًّا منذ v0.2.0 — <em>«تحرير المصدر يغيّر كل موضع وُضع فيه، وهذا هو النمط بالضبط»</em> — ولم يكن في الصفحة أي شيء يستطيع وضع أي شيء مرة ثانية.** <code>ArrangementEdit::PlacePattern</code> لم يكن يحمل مصدرًا، ومعالجه كان يستدعي <code>MidiSource::empty</code> دون شرط، فكان كل وضع نمطًا فارغًا جديدًا تمامًا. كان المنتج يستطيع بناء نمط في الرف ولا يملك أي طريقة على الإطلاق لوضعه في الأغنية. النموذج كان قادرًا على ذلك؛ والمنتج لم يكن، وهذا هو التمييز الذي دفع هذا المشروع ثمنه مرة من قبل في سجل العمليات.","changelog.894247c903fd":"<strong><code>PlacePattern</code> يأخذ <code>source</code> اختياريًا.</strong> متغيّر واحد لا اثنان: فشقيق مثل <code>PlaceExistingPattern</code> سيكون عيب البابين المفتوحين على حقل واحد الذي حُذف بسببه <code>ArrangementEdit::SetClipLoop</code> في 2026-09-17. <code>None</code> هو السلوك القديم بالضبط، والنقر المزدوج على خط زمني فارغ يقول ذلك الآن.","changelog.a278c0f6d9cf":"<strong>الرف يضع نمط الصف عند رأس التشغيل</strong>، آخذًا طول المقطع نفسه لا مازورة مخمّنة، ويُسمّى المقطع باسم النمط، فيُقرأ وضعان لـ <em>Verse</em> على أنهما <em>Verse</em> مرتين بدل غريبين.","changelog.bad0be6b218c":"⚠ <strong>زرّ، لا سحب.</strong> يسلّم WebView2 في Tauri كل سحب HTML5 إلى معالج إفلات الملفات في نظام التشغيل قبل أن تراه الصفحة، فيكون <code>draggable</code> + <code>onDragStart</code> أخضر تحت Playwright — إذ لا توجد طبقة Tauri تحت Chromium — وميتًا في التطبيق المشحون. والزر أيضًا هو ما تحصل عليه لوحة المفاتيح وقارئ الشاشة مجانًا.","changelog.b2a11a0200e5":"⛔ <strong>الوضع يكشف التوزيع.</strong> الرف والخط الزمني هما خانة الوسط نفسها، فمن داخل الرف لم يكن الوضع الناجح يغيّر شيئًا على الشاشة — المشكلة نفسها «يبدو كأنه لا يفعل شيئًا» التي يصلحها هذا الإصدار أيضًا في <em>نمط جديد</em>، والوضع الذي لا يراه المنتج وضعٌ سيضغطه مرة أخرى.","changelog.d996223bdc2c":"⛔⛔ <strong>البوابة هي المرجع الحيّ نفسه</strong>: ضع نمطًا واحدًا مرتين، وحرّر النوتات مرة واحدة، وتحقّق من أن الموضعين <strong>كليهما</strong> تغيّرا — ثم <em>جعله مستقلًا</em> على أحدهما وتحقّق من أن الآخر لم يتغير. ⚠ أي شيء أقل من ذلك ينجح مع تنفيذ ينسخ عند الوضع، يبدو مطابقًا على الشاشة يوم شحنه ولا يمكن فكّه بعد ذلك. ثبت ذلك بكتابة ذلك التنفيذ ومشاهدة هذا الاختبار، وهذا الاختبار وحده، يتحول إلى الأحمر.","changelog.4e4c1e91df18":"أُصلح — <em>نمط جديد</em> كان يبدو كأنه لا يفعل شيئًا","changelog.bb60005cf453":"⛔ <strong>المالك، 2026-09-19.</strong> كان التعديل يقع في كل مرة. <code>refreshPatternRack</code> يحتفظ بالنمط المفتوح <em>ما دام موجودًا</em>، وبعد الإضافة يكون السابق موجودًا دائمًا — فلم يتحرك التحديد قط، ولم يتغير جسم اللوحة قط، وكان الدليل الوحيد على النجاح مدخلًا إضافيًا في قائمة منسدلة مغلقة.","changelog.cb9e75e7d0bf":"<strong>النمط الجديد هو المفتوح الآن</strong>، ويُعثر عليه بفرق المجموعات لا بالموضع: <code>patterns.at(-1)</code> سيكون ادّعاءً ثانيًا غير مُعلن عن الترتيب الذي يعيد به النموذج الأنماط، صحيحًا اليوم وصامتًا حين يكفّ عن أن يكون.","changelog.fe911c060ae2":"<strong>النمط الجديد لم يعد يأخذ اسمًا مأخوذًا.</strong> كان الرقم يأتي من العدد، فمع <em>نمط 1 / 2 / 3</em> وقد حُذف <em>نمط 2</em> كان التالي <em>نمط 3</em> ثانيًا — بينما كان التعليق المجاور يدّعي أن هذا الشكل هو ما يمنع ذلك بالضبط. والمنتقي يسرد الأنماط بأسمائها، فنمطان يتشاركان اسمًا لا يمكن التمييز بينهما في المكان الوحيد الذي يختار فيه المنتج بينهما.","changelog.37c6b44b957f":"⚠ **الاختبار الموجود كان يتحقق من أن التعديل <em>أُرسل</em>.** وقد أُرسل فعلًا. كانت كل البوابات خضراء فوق زر أبلغ المالك أنه ميت — الفخ 8 حرفيًّا تقريبًا: غطّت الاختبارات القطع ولم تغطِّ الوصلة بينها قط. الاختبار الجديد يسأل عمّا ينظر إليه المنتج بعد ذلك.","changelog.8bc07e14cb41":"تغيّر — حزمة المركِّب لحقت بمصدرها الأصلي","changelog.b60fde70b9bf":"▶ <strong>يُستورد <code>synth/</code> من <code>Freally MIDI Master</code>، ولا يُحرَّر هنا أبدًا</strong>، و<code>tests/the_synth_is_not_forked.rs</code> يقارن الاثنين بايتًا ببايت على أي جهاز سُحب عليه الاثنان. وكان قد صار أحمر: هذه النسخة كانت متأخرة بإيداع واحد.","changelog.973b9db56f9d":"<strong>أُعيد استيراده عند <code>ff99972c</code></strong>، وهي مراجعة مدفوعة لا شجرة عمل، فلا يمكن لما نُسخ أن يتحرك تحت النسخة. أُخذ <code>src</code> كله لا الملفات الثلاثة التي اختلفت فقط، وهذا أيضًا ما يثبت أن شيئًا آخر لم ينجرف — إذ يُبلغ <code>git</code> عن هذه الثلاثة بالضبط، إضافة إلى الترويسة.","changelog.d0edfd8085ba":"<strong>ما جاء معه ميزة واحدة</strong>: تحكم بالنبرة ثلاثي النطاقات على خرج كل جزء، بعد مرحلة الدفع. مسطّح افتراضيًا، و<code>is_flat()</code> يتخطى المرحلة كلها بدل تشغيل ثلاثة مرشّحات biquad عند الوحدة.","changelog.563488a64458":"⚠ <strong>لم يتحرك أي صوت مصنعي، وهذا مقيس لا مُجادَل فيه.</strong> أُخذت بصمة كل الضربات الأحادية المخبوزة البالغة <strong>1,648</strong> قبل الاستيراد وأُعيد خبزها بعده: كلها مطابقة بايتًا ببايت. التجاوز دقيق.","changelog.719cec9783d3":"⛔ <strong>ظلت ترويسة الحزمة نفسها تدّعي طوال أربعة إيداعات أنها «مطابقة باستثناء التفاف أسطر rustfmt» للاستيراد الأصلي.</strong> توقف ذلك عن كونه صحيحًا في <code>b6149993</code> وبقي على الصفحة حتى <code>0e36a6ab</code>. الآن تسمّي الإيداعات الأربعة التي حرّكتها. وكانت بوابة هذا المنتج قد ربطت تحققًا بالجملة المتقاعدة، فانتقلت البوابة إلى الجملة التي حلّت محلها — فالترويسة التي لم تعد تقول إن الحزمة مستوردة تبقى إخفاقًا، وعلى جهاز لا توجد عليه نسخة الشقيق تكون هي الشيء <em>الوحيد</em> الذي يتحقق.","changelog.69b25eeb0c5b":"<strong>ثلاث عشرة بوابة لم تكن لدى المصدر الأصلي.</strong> شُحن التحكم بالنبرة بلا اختبار في أيٍّ من المنتجين، و<em>«كل حقل في قيمته الافتراضية تجاوز تام»</em> أمر تحمل عليه 372,600 صوت هناك و1,648 هنا — وكان يستند إلى تعليق. ثبت أن كل واحدة تفشل أمام العيب الذي تسمّيه. والتي تستحق مكانها:","changelog.b94bccab9f9e":"<strong>الرقعة الافتراضية تُصيَّر مطابقة بتًّا ببت لرقعة ذات ترددات نطاقات عبثية وكل الكسوب عند الصفر</strong> — فلا يستطيع المعادل المسطّح أن يُسرّب تردداته المركزية إلى الخرج.","changelog.5e207e72d810":"<strong>النطاق الذي يُحرَّك مسموع.</strong> ⚠ بدون هذا، كان اختبار التجاوز أعلاه سينجح بالسعادة نفسها على معادل غير موصول بأي شيء على الإطلاق، وهذا أكثر العيوب تسجيلًا في هذا المشروع.","changelog.185db1f5eda0":"<strong>كل نطاق يفعل ما يقوله اسمه، مقيسًا استجابةَ مقدار بالديسيبل.</strong> ⛔ الاختبار الذي يتحقق فقط من أن الخرج <em>تغيّر</em> ينجح على معادل موصول بالمقلوب. الرفّ المنخفض يرفع 50 Hz بمقدار 12 dB ويحرّك 12 kHz بأقل من نصف ديسيبل؛ والذروة الوسطى تحرّك مركزها وتترك الطرفين؛ وQ يحدد العرض حقًّا. وكل نطاق عند 0 dB وحدة — <code>resonator.rs</code> يحذّر بكلماته الخاصة من أن رفًّا وذروة من اشتقاقين مختلفين لن يُجمعا مسطّحين، وتجاوز المحرّك هو ما سيخفي ذلك.","changelog.561660be824d":"<strong>الرقعة التي تحمل <code>NaN</code> وحقولًا لانهائية ما زالت تُصيّر صوتًا منتهيًا.</strong> ⛔ الكسوب غير صفرية عن قصد، فلا يستطيع التجاوز المسطّح إنقاذها ويجب أن يقوم الحصر بالعمل. وحذف الحصر يضع فعلًا عيّنات غير منتهية في ناقل الخرج — فالرقعة تصل من ملف مشروع أو إعداد مسبق أو كتلة جلسة، فتأتي تلك الأرقام من القرص.","changelog.cf7a53067d45":"<strong>الرقعة المحفوظة قبل وجود الحقل ما زالت تُحمَّل، وتُحمَّل مسطّحة</strong>، وهذا كل ملف مشروع لدى المنتج من قبل. ⚠ يتحقق الاختبار من العثور على المفتاح <code>eq</code> قبل حذفه، فلا تستطيع إعادة تسمية أن تترك الاختبار يحمّل بهدوء مستندًا حديثًا ويُبلغ عن نجاح.","changelog.5cfdbb31fdb6":"<strong><code>reset</code> يمسح ذاكرة التحكم بالنبرة</strong>، وهو المسار الذي تسلكه الضربات الأحادية المخبوزة الـ 1,648 كلها، واحدة تلو الأخرى، عبر محرّك واحد.","changelog.8db9ed06330a":"<strong>المعاملات تتبع تغيير معدل العيّنات</strong> — انظر أدناه.","changelog.844ddc7e034e":"⚠ <strong>لا يمكن الوصول إلى التحكم بالنبرة من Oscillate</strong>، وهذه هي الحالة الصادقة لا سهو. لا شيء هنا يكتب <code>patch.fx.eq</code>، والآلة لا تكشف أي عنصر تحكم له — إنه ميزة في اللوحة الأمامية لـ <code>Freally MIDI Master</code>، وصل لأن الحزمة تصل كاملة. لذا هو مسطّح إلى الأبد هنا، أي متجاوَز إلى الأبد. البوابات أعلاه موجودة كي يكون الوعد الذي استُورد عليه محفوظًا سلفًا في اليوم الذي <em>يكشفه</em> فيه Oscillate.","changelog.04a45d3f4f5f":"⛔ <strong>وعيبان وُجدا بكتابتها، كلاهما أُصلح في المصدر الأصلي وأُعيد استيراده.</strong> كان <code>SynthEngine::set_sample_rate</code> يعيد بناء الأصوات والتأخير الصدوي والصدى لكن لا التحكم بالنبرة — كانت إعادة البناء مشروطة بتغيّر <em>المعاملات</em>، ومعدل العيّنات ليس منها، فالمضيف الذي ينتقل من 48 kHz → 96 kHz كان يُبقي معاملات مبنية لـ 48 kHz ويضع كل نطاق أخفض بأوكتاف، فيعمل رفّ 6 kHz عند 3 kHz. ▶ <strong>حيّ في المنتج الآخر، لا نظري</strong>: إضافته تستدعي <code>set_sample_rate</code> عند التهيئة، فالمشروع المفتوح بمعدل آخر كان سيُشحن بذلك بالضبط.","changelog.164f095fad5b":"⚠ النظر في الحارس الخاص بذلك الإصلاح كشف عيبًا ثانيًا: كان يسجّل المعاملات <strong>المحصورة</strong> ويقارنها بالرقعة <strong>غير المحصورة</strong>، فأي رقعة تحمل رقمًا واحدًا خارج المدى لم تكن تتطابق أبدًا وكانت تُعيد البناء في كل كتلة — ثلاث دوال متسامية لكل نطاق لكل قناة، على خيط الصوت، طوال عمر النوتة. هذه هي الكلفة التي وُجد الحارس لتجنّبها، مدفوعة بالكامل.","changelog.10064bd5014c":"▶ كلاهما مُصلح في <code>ff99972c</code> وهذه الحزمة تحمل الإصلاح. ⛔ <strong>لم يُرقَّع أيٌّ منهما هنا</strong> — فـ <code>tests/the_synth_is_not_forked.rs</code> هي هذه القاعدة بالضبط، والعيب في حزمة مستوردة يُبلَّغ عنه إلى مصدرها الأصلي ويعود عبر إعادة استيراد.","changelog.763976c39a5e":"⚠ <strong>لم يكن Oscillate قادرًا على بلوغ أيٍّ منهما</strong>: <code>prepare</code> يعيد إنشاء المحرّك بدل تعديل معدله، ولا شيء هنا يستدعي <code>set_sample_rate</code> على مركِّب أصلًا، ولا شيء يكتب <code>patch.fx.eq</code>، فتُتخطى المرحلة كليًا. ومع ذلك يُحتفظ بالاختبار — ففي اليوم الذي يكشف فيه هذا المنتج عنصر التحكم، لن يتذكر أحد أن الحزمة أخطأت في هذا يومًا.","changelog.748d76268df9":"أُصلح — بوابة كانت تقيس الجهاز","changelog.907c2f2fd645":"<strong>كانت بوابة كلفة الحفظ في <code>the_profile</code> متقلّبة، وأرقامها نفسها تدحض رسالتها.</strong> قرأت 1.007 µs لكل عملية عند 1 000 مدخل، و<strong>4.399</strong> عند 10 000، و2.030 عند 40 000، ثم فشلت قائلة <em>«الكلفة لكل عملية تتصاعد مع السجل»</em>. ⛔ الكلفة التي تتصاعد لا تعود فتنخفض — فأكبر عيّنة كانت أقل من نصف التي فشلت. القراءة الوسطى كانت توقفًا مؤقتًا، أُخذت بينما جعل <code>cargo-test-parallel</code> هذا الملف التنفيذي يتقاسم الجهاز مع جار يستغرق 265 s وآخر 198 s.","changelog.f740ca8afb55":"⚠ <strong>ثلاثة قياسات الآن، يُحتفظ بأصغرها، والحد لم يُمسّ.</strong> ضجيج المجدوِل وخطأ الصفحة والمخصِّص الذي يوسّع ساحته لا يمكنها إلا أن <em>تضيف</em> وقتًا، فالحد الأدنى هو أقرب قراءة للكلفة الحقيقية. ▶ والدليل على أن هذا قياس أفضل لا أرخى: يعيد <strong>0.484 µs لكل عملية</strong>، وهو <em>«نحو نصف ميكروثانية»</em> الذي يوثّقه تعليق الاختبار نفسه منذ كتابته. والحد 2.0 يحتفظ بالهامش 4× الذي أُعطي له.","changelog.ee0e7470e12b":"⚠ <strong>أهمية ذلك أكبر حيث لا يكون مجانيًا</strong> — فالملف التنفيذي نفسه يعمل في مهمة macOS بمضاعف فوترة 10×، حيث يكلّف التقلّب مالًا وإعادة التشغيل إنسانٌ يقرر إنفاقه.","changelog.976e6e97f8a2":"أُصلح — المراجعتان، والعيوب الثلاثون التي وجدتاها","changelog.db1222c7163d":"▶ <strong><code>/code-review</code> و<code>/security-review</code> على الشجرة كلها، ثم مراجعة توصيل لكل عنصر تحكم.</strong> لم تجد المراجعة الأمنية شيئًا قابلًا للاستغلال. ووجدت الأخريان ثلاثين، والنمط فيها شيء واحد يُقال بثلاث طرق: آلية تعمل، ولا شيء يستدعيها.","changelog.7cf2cd2dae19":"<strong>الصوت</strong>","changelog.6b2f9047e7fb":"<strong>تقسيم مقطع صوتي كان يجعل النصفين يعزفان المازورات نفسها.</strong> كان <code>tail_of</code> يقدّم <code>content_offset_ticks</code> بينما يقرأ المحرّك <code>source_start_frame</code>، فقطع لقطة من ثماني مازورات عند المازورة الخامسة كان يعيد عزف المازورات من الأولى إلى الرابعة فوق الخامسة إلى الثامنة ويجعل النهاية الحقيقية للقطة بعيدة المنال. ⚠ المسار نفسه هو <em>القطع</em>، والتسجيل فوق لقطة، وسحب الحافة اليسرى لمقطع. و<code>clipwindow.rs</code> هو المكان الوحيد الذي يجمع الاثنين الآن.","changelog.2c8ea832888d":"<strong>إعادة الطبقة مع العكس كانت تمشي إلى ما بعد نهاية الملف فتقع في الصمت</strong>، وإعادة الطبقة مع التكرار كانت عملية صامتة لا تفعل شيئًا. لطالما عطّل المحرّر الوضع لكليهما؛ والمحرّك لم يتحقق قط.","changelog.776681ae58b6":"<strong>طقطقة بعد نحو 85 ms في كل مقطع معاد الطبقة</strong> يبدأ من أول ملفه — كان مُعيد الاعتيان يفترض مقدمة نواة لم تُعطَ له، ثم يقفز إلى الخلف بمقدارها عند حدّ الدفعة التالي.","changelog.025480518fc8":"<strong>زر M في مسار الطبول ومجموعة الخنق الخاصة به كانا يُحفظان ولا يُعزفان أبدًا.</strong> الهاي هات المكتوم كان يصدح رغم ذلك؛ وهاي هاتان في المجموعة 1 كانا يرنّان معًا. كلاهما من مسؤولية المجدوِل الآن، فالهاي هات المغلق يقطع المفتوح.","changelog.00a6999c8a9e":"<strong>عناصر تحكم لم تكن تصل إلى شيء</strong>","changelog.dcf104640213":"<strong>كل العناصر العشرة في الإعدادات ▸ التصدير.</strong> الصيغة والعمق والتشويش المقصود والمعدل وخانات <em>ما الذي يُكتب</em> الثلاث ونمط أسماء المسارات المنفصلة والمجلد وتوحيد المستوى والذيل كانت تُكتب في <code>preferences.json</code> ولا يقرؤها <strong>شيء</strong>: التصدير الوحيد في المنتج كان مثبّتًا على WAV بعمق 24 بت ويطلب مجلدًا في كل مرة. المنتج الذي اختار FLAC كان يحصل على WAV، ولا شيء يقول ذلك. ⚠ <em>توحيد المستوى</em> و<strong>ذيل</strong> الصدى منفّذان حديثًا لا مجرد موصولين، و<em>ما الذي يُكتب ← الماستر</em> يستطيع الآن إنتاج المزيج الذي كان يطلبه افتراضيًا دائمًا.","changelog.59d90c6cb919":"<strong>قائمة المقطع كانت عنصرًا واحدًا فوق واجهة خلفية تستطيع سبعة أشياء.</strong> <em>كتم هذا المقطع</em> — يحترم المحرّك <code>Clip::muted</code> منذ المرحلة 5 ولم يكن أي عنصر تحكم يستطيع ضبطه، فكان الكتم الوحيد هو كتم المسار كله. <em>جعله مستقلًا</em>، <em>مسح التركيب</em>. وهي تُفتح الآن على مقطع فارغ أيضًا.","changelog.e5b3cca1b7df":"<strong>كسب المقطع وتحرير الانزلاق</strong>، كلاهما في محرّر الصوت. الانزلاق هو أكثر تحريرات الصوت شيوعًا، ولم يكن لدى المنتج أي طريقة للقيام به.","changelog.6d771bdd8e51":"<strong>لم يكن ممكنًا إعادة تسمية مجموعة أجهزة قط</strong>، فكانت كل مجموعة تُسمّى <em>مجموعة جديدة</em> إلى الأبد. انقر نقرًا مزدوجًا على اسمها.","changelog.467d149679e8":"<strong>شبكة المحاذاة لم تكن تُحفظ قط.</strong> كانت تعود إلى <em>تكيّفية</em> عند كل إعادة تشغيل وتختلف بين النافذة الرئيسية وكل نافذة منفصلة. ⚠ هي الآن إعداد للمشروع، مخزّن <strong>وضعًا</strong> لا عددًا من النبضات — فـ <em>التكيّفية</em> قاعدة تتعلق بالتكبير، و<em>المازورة</em> و<em>الثلاثية</em> تتبعان الميزان، فلم يكن لرقم أن يحمل الجواب أبدًا.","changelog.a5d42a8ae7a9":"<strong>يمكن تصفير عدّاد الانقطاعات</strong> — اضغط عليه. فالعدد المتراكم منذ التشغيل لا يستطيع أن يخبر المنتج هل ساعد حجم المخزن المؤقت الذي غيّره للتو.","changelog.ba7c289f15f7":"<strong>يمكن إغلاق نافذة الإضافة المستضافة</strong>، لا فتحها فقط.","changelog.2cb47acac22e":"<strong>لم يكن <code>Ctrl</code>+<code>2</code> يفعل شيئًا.</strong> كان مسرودًا في الإعدادات، ومطبوعًا في تلميح زر الأنماط، ويقلب تفضيلًا توقف الإطار عن قراءته.","changelog.e50883a683a3":"<strong>كانت الإعدادات ▸ الاختصارات ترسم مفتاح ترجمة خامًا</strong> اسمًا لإجراء صف رف الأنماط، في اللغات الثماني عشرة كلها.","changelog.b14b86b1382f":"<strong>أشياء كانت ستفشل على جهاز شخص آخر</strong>","changelog.66c3c6c5267c":"<strong>كل بناء لـ macOS كان معطوبًا.</strong> كان <code>include_bytes!</code> يشير إلى صورة PNG لشاشة البداية حُذفت مع الحركة التي تنتمي إليها — خطأ ترجمة صريح على المنصة الوحيدة التي لا يترجم لها جهاز Windows أبدًا.","changelog.0baaabb3b598":"<strong>سير عمل الإصدار لم يكن يستطيع إنهاء مسودة قط.</strong> توقف عن البناء على ثلاثة مشغّلات بينما ظل بيان المحدِّث يطلب المنصات الأربع كلها، فكانت الخطوة تخرج بالرمز 1 في كل تشغيل. يعلن الإصدار الآن المنصات التي يغطيها، ويقول بأحرف كبيرة ما يتركه غير قابل للتحديث.","changelog.8427ce0ef17b":"<strong>بوابتا CI لم تكونا تعملان في أي مكان</strong> — فحص نوع المُرحِّل وفحص ترخيص المثبّت — بينما كانت ترويسة سير العمل نفسها تدّعي أن كل بوابة تعمل.","changelog.a778bef2ac7c":"<strong>الصدق بشأن ما لم يُبنَ</strong>","changelog.542fd1169d51":"<strong>مسار CC يقول إنه لا يُعزف.</strong> المنحنى يُرسم ويُعتمد ويُحفظ ويُقرأ من جديد، ولا آلة تقرؤه: <code>NoteMessage</code> ليس فيه متغيّر لوحدة تحكم، ولا جهاز فيه عنصر تحكم يُربط به. يبقى المسار يعمل محرّرًا ولم يعد يوحي بأنه مسموع.","changelog.19d2f3668484":"<strong>سؤال التحديث عند التشغيل الأول يحجب لوحة المفاتيح كما يحجب الفأرة.</strong> كان غطاؤه يوقف النقرات ولا شيء غيرها، فكان <code>Space</code> يشغّل النقل و<code>B</code> يختار النصل خلف نافذة حوار كان يُفترض أن تحجب النافذة.","changelog.4408a66cf4a7":"<strong>سحب المنزلقات والمقابض يرسل كتابة واحدة في كل مرة.</strong> كانت كل واحدة مهمة مستقلة بمعدل 60 إلى 120 في الثانية مقابل اعتماد غير ذرّي، فالسحب الذي يغيّر اتجاهه كان قادرًا على تطبيق قيمه <strong>بالمقلوب</strong> وترك المنزلق يُظهر قيمة مرّت بها اليد.","changelog.a76424b61990":"<strong>القيمة الافتراضية لـ <code>Writes</code> هي الثلاثة كلها.</strong> كانت الماستر وحده — كُتبت لنافذة تثبيت لم تُبنَ قط — بينما التصدير الوحيد الذي لدى هذا المنتج هو المجلد المرافق، الذي مواصفاته كلها مسارات منفصلة وMIDI.","changelog.4118fb4fed0e":"أُزيل","changelog.15b34653c2d8":"<code>ArrangementEdit::SetClipLoop</code>، باب وصلة ثانٍ على الحقل الذي كان <em>التكرار</em> في محرّر الصوت يملكه سلفًا. البابان على حقل واحد يمكن أن ينجرفا.","changelog.87ab637f8719":"خمسة أوامر مسجّلة لا شيء يستطيع بلوغها، منها مسار تسجيل ثانٍ كامل يكرر ترتيبًا يملكه <code>transport_toggle_record</code>.","changelog.840e2d665a01":"<code>InputRouting::midi_channel</code> — لا يُكتب ولا يُقرأ في أي مكان، والحقل في صيغة الملف يوحي بوجود ميزة.","changelog.68ff7b9f2a51":"نسخة ثانية ميتة من تنقّل متصفح الملفات، ونسخة مكررة بحجم 1.4 MB من شعار شريط الحالة لم يستوردها شيء.","changelog.5804894b279c":"أُضيف — خمس بوابات، ثبت أن كلًّا منها يفشل أمام العيب الذي كُتب من أجله","changelog.cbc111af658b":"▶ <strong>المراجعات وجدت العيوب؛ وهذه هي ما سيجد العيوب التالية.</strong>","changelog.0ced7e4acc29":"<strong>كل <code>#[tauri::command]</code> مسجّل يستدعيه شيء ما.</strong> البوابة الموجودة كانت تفحص المُعلَن↔المسجّل في الاتجاهين ولم تكن ترى الحالة التي وجدتها المراجعة فعلًا سبع مرات.","changelog.bfa23431d44f":"<strong>كل مسار <code>include_bytes!</code> في شجرة Rust يُحَلّ</strong> — يُقرأ نصًّا، فيرى الأسطر التي لا يترجمها بناء Windows أبدًا.","changelog.82c650a2453e":"<strong>كل بوابة يعرّفها <code>ci:local</code> تعمل في CI، أو تقول لماذا لا.</strong>","changelog.bbe1d90a6900":"<strong>كل مسار يسمّيه <code>tauri.conf.json</code> موجود</strong>، وصور المثبّت صور نقطية حقًّا.","changelog.35eba3face11":"<strong>القيم الافتراضية للتصدير هي الرقم نفسه في Rust وTypeScript.</strong> كان <code>preferences.ts</code> يدّعي أن بوابة تُبقيهما متوافقتين. لم يكن هناك اختبار كهذا، وكان الاثنان قد انجرفا سلفًا.","changelog.601f1c69bd48":"ترجمات الاختصارات الآن <strong>مشتقة من جدول الربط</strong> لا مسرودة يدويًا. القائمة المكتوبة يدويًا كانت متأخرة بثمانية عشر معرّفًا.","changelog.b9d982ea6bd7":"أُضيف — تسعة أشياء لم تكن لفّة البيانو تستطيعها","changelog.1f9c5a34c9d1":"▶ <strong>الفجوة بين لفّة Oscillate واللفّة التي يعرفها المنتج سلفًا.</strong> تسعة أشياء، وليس أيٌّ منها إعدادًا: كل واحد حركة إما موجودة وإما غير موجودة.","changelog.d5a043ed3427":"<strong>النوتات الشبحية.</strong> الأنماط الأخرى على الخط الزمني، مرسومة خلف النمط الذي تحرّره، فيمكن كتابة خط باص مقابل التآلفات التي يقع تحتها. ⚠ <strong>محاذاة بحسب الخط الزمني</strong>، لا من النبضة صفر إلى النبضة صفر: النوتة الشبحية تقع حيث تصدح فعلًا، فسحب مقطعها يحرّك ما تراه. تُرسم دون معرّفات نوتات فلا يمكن النقر عليها أو سحبها أو حذفها — فلا تستطيع تحرير النمط الخطأ بالمصادفة.","changelog.acb285536839":"<strong>احتمال لكل نوتة.</strong> النوتة ذات <code>chance: 60</code> تُعزف ست مرات من عشر. ⚠ اللفّة <strong>حتمية</strong> — النوتة نفسها في المكان نفسه تجيب بالطريقة نفسها في كل تصيير، فيبدو التثبيت مثل الاستماع التجريبي — والجواب يتغير في كل دورة حول <strong>قوس التكرار</strong>، وهكذا تسمعه.","changelog.91a46043d207":"<strong>انحراف الشدة لكل نوتة.</strong> نصف عرض حول شدة النوتة نفسها، فيتنفس خط الهاي هات دون إعادة رسمه. ولكلا الحقلين مساره الخاص في اللفّة، بجانب مسار الشدة.","changelog.ae227f69dad4":"<strong>تفكيك التآلف والخربشة والضربة المزدوجة والتقطيع</strong> — أربع أدوات تحوّل تحديدًا واحدًا إلى نوتات كثيرة. ⚠ <em>الخربشة</em> تحرّك كل بداية وتترك كل <strong>نهاية</strong>، فيبقى التآلف يقع معًا؛ أما <em>تفكيك التآلف</em> فيحرّك النوتة كلها.","changelog.7567510c9217":"<strong>ختم التآلف.</strong> ارسم نوتة واحدة، واحصل على التآلف. يحتفظ الأساس بهويته، فيتصرف التراجع وإعادة التحرير كما ينبغي؛ والفاصل الذي سيقع خارج لوحة المفاتيح يُسقط بدل أن يُلَفّ إلى الأوكتاف الخطأ.","changelog.a5716970627f":"<strong>اللصق.</strong> يصل النوتات ذات الطبقة نفسها التي تتلاقى فعلًا. لكل طبقة على حدة، ولا يتجاوز أبدًا الحدود الخارجية للتحديد.","changelog.6dca58299583":"<strong>الاستماع عند النقر.</strong> اضغط نوتة فتسمعها — ممسوكة ما دمت تمسك، و<strong>صامتة لحظة تبدأ سحبها</strong>، فتحريك نوتة ليس سيلًا من الطبقات. ⚠ تصدح على <strong>مسار المقطع نفسه</strong>، لا على المسار المجهَّز.","changelog.d436aec70d34":"<strong>تحرير عدة مقاطع.</strong> حدّد عدة مقاطع في التوزيع فتصل إليها كلها أداة اللفّة. ⛔ <strong>لكل نمط على حدة، لا على اتحادها أبدًا</strong> — فعكس مقطعين كامتداد واحد سيبادل محتوييهما بدل أن يعكس كلًّا منهما.","changelog.02c466c71f3d":"<strong>قفل المقام</strong> <em>(طلب المالك)</em>. مع تفعيله، لا يقع شيء خارج المقام: الرسم، والسحب، وكل تحويل، والنوتات المعزوفة من لوحة مفاتيح MIDI. ⚠ <strong>مسار الطبول مستثنى</strong>، لأن طبقات الطقم خانات لا نوتات. ملفات <code>.mid</code> المستوردة وتعديلات المشارك تُترك عن قصد — فالقفل يحرس ما تعزفه <em>أنت</em>، ولا يعيد كتابة ما أُعطي لك.","changelog.c0a758a4c2c8":"أُضيف — ثلاثة أخرى طلبها المالك أثناء بناء هذه","changelog.228a32503478":"<strong><code>[</code> و<code>]</code> على حواف المقطع.</strong> يقول المؤشر أي حافة أنت على وشك قصّها قبل أن تضغط، ويعود إلى مؤشر النقل في المنتصف.","changelog.67dab04fd1a6":"<strong>تثبيت التحديد إلى صوت.</strong> تصبح عدة مقاطع MIDI ملفات صوتية بضغطة واحدة، و<strong>تراجع واحد</strong> يعيدها كلها MIDI. ⚠ يحترم التصيير الاحتمال وانحراف الشدة، فالصوت هو ما سمعته.","changelog.e79c873347d5":"<strong>صفحة الاختصارات والتطبيق متفقان.</strong> يقارن اختبار الآن روابط التطبيق بجدول التوثيق في الاتجاهين، فالربط المضاف دون صفه — أو الصف المتروك بعد نقل ربط — يُفشل البناء بدل أن يصل إلى القارئ.","changelog.94af29dd35e5":"تغيّر — الآلات الأربع عشرة تقول ما هي","changelog.dba1519e23b3":"▶ <strong>المالك، 2026-09-16:</strong> <em>«غيّر كل أسماء إضافات المؤثرات الصوتية/MIDI لديّ إلى أسماء عادية، لكن ليست نفس أسماء Ableton/FL Studio، والأمر نفسه مع أي شيء آخر في تطبيقي له علاقة بـ 'Kiln' أو أي شيء من هذا القبيل.»</em>","changelog.da573c0bab5c":"أُعيدت تسمية المؤثرات الإحدى والستين في الدرجة السابقة؛ وتُركت الآلات بأسماء رمزية مستوحاة من الحدادة، وكان السؤال المفتوح هل ينبغي أن تلحق بها. وقد لحقت:","changelog.c973dfc231e6":"⚠ <strong>ثلاث منها ما زالت رمادية وتقول السبب</strong>، وتقوله بأسمائها الجديدة: <code>Hardware Instrument</code> يعزف عتادًا خارجيًا عبر منفذ MIDI وليس لدى Oscillate منفذ MIDI بعد؛ و<code>Track Replay</code> يحتاج إلى الخرج المسجّل لهذا المسار نفسه؛ و<code>Folder Kit</code> يحتاج إلى مكتبة عيّنات المنتج، وهذه مهمة مستعرض الملفات.","changelog.759ed41312d0":"⚠ <strong>مؤثر واحد انتقل أيضًا.</strong> صار <code>Strum</code> الآن <strong>Chord Strummer</strong>، لأن Live 12 يأتي بتحويل MIDI اسمه <em>Strum</em> بالضبط، وكانت التعليمات صريحة في ألا يكون أي اسم من أسمائهم.","changelog.5bce801ca6dd":"⛔ <strong>لم يتغير شيء مما يخزّنه ملف المشروع.</strong> تحرّك الاسم المعروض فقط؛ وكل <code>type_id</code> — <code>crucible</code> و<code>flint</code> و<code>hammer</code> والبقية — هو بالضبط ما كان عليه، لأن تلك السلسلة هي المفتاح الذي يحمله ملف <code>.oscillate</code> المحفوظ. المنتج الذي يفتح مشروع الأسبوع الماضي يجد كل جهاز حيث تركه، بإعداداته وأتمتته. ⚠ لذا فبقاء اسم رمزي في <code>type_id</code> ليس سهوًا يُرتَّب لاحقًا؛ ترتيبه هو العيب، و<code>every_device_name_says_what_it_is.rs</code> يثبّتها كلها، الخمسة عشر.","changelog.a4c30729338f":"⚠ <strong>تُرك «Kiln» عن قصد</strong>، ويستحق القول أين هو: ليس جهازًا على الإطلاق، بل <em>«Kiln Gong»</em>، إعداد مسبق واحد من بين 1,648 في المكتبة المصنعية المستوردة. تلك المكتبة تُقارن بايتًا ببايت بنسخة Freally MIDI Master، فإعادة التسمية داخلها تشقّ الاستيراد وتكسر الوعد بأن <code>PresetId</code> واحدًا يُصيّر الصوت نفسه في المنتجين.","changelog.388337669577":"أُضيف — استعادة الأعطال تصل إلى جلسة لم تُحفظ قط","changelog.4e88f60bb868":"⛔⛔ <strong>السجل يُسمّى باسم المشروع الذي ينتمي إليه، والجلسة التي لم تُحفظ قط ليس لها ملف مشروع يُعاد فتحه</strong> — فكان التشغيل التالي يصكّ مشروعًا جديدًا بمعرّف جديد ولا يبحث عنه أبدًا. كان العمل على القرص طوال الوقت ولم يعرض شيء إعادته، وهذا بالضبط حال المنتج الذي يعمل منذ الغداء دون أن يحفظ مرة واحدة.","changelog.e842b6131eed":"✅ يلتقط Oscillate الآن نقطة بداية الجلسة غير المحفوظة في سجلها عند أول تعديل، والتشغيل الذي لم يبدأ عملًا خاصًا به بعد يُعرض عليه أحدث سجل يتيم قابل للاستعادة. ⚠ تقول نافذة الحوار أي نوع من العروض هو: فاليتيم ليس له ملف محفوظ، فالطمأنة المعتادة — <em>«مشروعك المحفوظ لم يتغير»</em> — ستكون وصفًا لملف غير موجود.","changelog.7a6d58e08394":"⛔ <strong>السجل الذي ليس له لقطة كاملة خاصة به لا يُعرض أبدًا</strong>، لأنه لا يوجد مشروع محفوظ يُعاد تشغيله عليه، وستكون النتيجة مشروعًا لم يوجد قط. والعرض الذي قُبل أو رُفض سلفًا لا يعود.","changelog.e51b2a693d90":"حدّ معروف — الجلسة الطويلة تصنع ملف مشروع كبيرًا","changelog.7b7551a966b9":"⚠ <strong>يعيش سجل العمليات داخل <code>.oscillate</code>، عن قصد</strong>: هو ما يتيح للتراجع أن ينجو من الحفظ وإعادة التحميل، ومنه يُشتق كلٌّ من إرجاع الجلسة والفاصل الزمني للجلسة. لا شيء يقلّمه، فينمو الملف مع الجلسة — مقيسًا بـ <strong>29 MB بعد 100,000 عملية و58 MB بعد 200,000</strong>، أي نحو جلسة من ثماني ساعات، يُكتب في 67 ms.","changelog.2d5d351a5323":"▶ النمو <strong>خطي</strong> لا متراكب، والسقف موثَّق لا محدود: تقليم السجل سيزيل التراجع بعد إعادة التحميل وإرجاع الجلسة والفاصل الزمني معًا. ⛔ قرار المالك، 2026-09-15.","changelog.1bd930b6d7dc":"تغيّر — المتصفح يضيّق النطاق عند المصدر","changelog.ad56b31dd7dc":"⚠ <strong>فتح رفّ في المتصفح لم يعد يبني القائمة كلها أولًا.</strong> كل رفّ من الرفوف الخمسة — الآلات وتوسعات المصنع الأربع — كان يُسرد باستنساخ الآلات الـ 1,648 كلها ثم التخلص من الأخماس الأربعة التي تنتمي إلى الرفوف الأخرى، في كل سرد. وهو الآن يمشي في الرفّ المطلوب فقط: <strong>0.140 ms → 0.001 ms</strong> مقيسًا في بناء الإصدار للآلات، وما لا يقل عن 1,298 تخصيصًا للسلاسل لم تعد تحدث في كل مرة.","changelog.f69b8488a31f":"⛔ هذا هو العيب نفسه الذي أصلحه <code>Freally MIDI Master</code> في المصدر الأصلي في اليوم نفسه، وجاء تعليله مع الاستيراد: القائمة التي تُضيَّق بعد الواقعة تُبنى كاملة على <em>«الخيط الذي يرسم منه برنامج DAW نافذته»</em>.","changelog.46a40063d923":"أُصلح — ما وجدته مراجعات المرحلة 11","changelog.92c5375cd4da":"⛔ <strong>كانت شاشة البداية في macOS تؤخر التطبيق سبع ثوانٍ عند كل تشغيل.</strong> النافذة الأصلية ليس فيها صفحة، فلم يستدعِ شيء <code>splash_finished</code> قط — وصار المراقب ذو الثواني الأربع المكتوب لـ <em>«صفحة رمت استثناءً»</em> بصمت المسار العادي في macOS. تُسلّم شاشة البداية الأصلية الآن بعد مدة حركتها الخاصة، وتقرأ بوابة فرع macOS للتأكد من أن مراقب الصفحة لا يعود إليه أبدًا.","changelog.fcfe9625c96b":"⛔ <strong>وكانت تعرض قفزة مختلفة عن Windows وLinux.</strong> كانت نسخة Rust تحتوي على قطع مكافئ متماثل حيث تحتوي ورقة الأنماط على <code>51 − 17u − 78·sin(πu)</code>، بلا أي تحجيم، وإشارة الإزاحة العمودية معكوسة، ونافذة بنسبة 62 % من الشاشة بدل الشاشة كلها — فكان الشكل ينخفض بدل أن يقفز، ولا يقترب منك أبدًا، ويُقصّ على صندوق غير مرئي في وسط سطح المكتب. صُحّحت الأربعة كلها، وصار <code>splash_macos.rs</code> الآن <strong>يحلّل الإطارات المفتاحية في <code>window.css</code> نفسه</strong> ويفشل إذا اختلف التنفيذان عند أي من العيّنات الإحدى والعشرين.","changelog.9e463e8ee449":"⛔ <strong>كان موقع التوثيق يبقى على اللغة السابقة حين تختار الإنجليزية مرة أخرى.</strong> كل عقدة قابلة للترجمة تحمل نصها الإنجليزي في الترميز، وكان المبدِّل يقرأ ذلك على أنه «لا شيء يُفعل للإنجليزية» — فاختيار Français ثم English كان يترك صفحة فرنسية تحت <code>lang=&quot;en&quot;</code>. ومن العربية كان التخطيط يزول انعكاسه بينما يبقى النص عربيًا. الإنجليزية الآن فهرس كأي فهرس آخر، يُقرأ من الصفحة مرة واحدة قبل أن يكتب أي شيء فوقه.","changelog.704583748781":"⛔ <strong>كان تنزيل التحديث الفاشل يرمي العرض الذي راجعته للتو</strong>، فكانت إعادة المحاولة تعني طلبًا شبكيًا ثانيًا. ⚠ وكانت لوحة <em>التحديثات</em> تعلن أيضًا <em>«لم يُتّصل بشيء.»</em> نتيجةً حيّة في كل تثبيت جديد، تحت مفتاح يقول سلفًا <em>«مطفأ.»</em> — جملة عن شيء لم يفعله أحد.","changelog.058de0de8dea":"⚠ وأيضًا: <code>--verify</code> دون <code>--assets</code> كان يُبلغ عن كارثة § F-32 فوق بيان سليم؛ واستثناء في <code>deny.toml</code> كان قادرًا على إسقاط حظر GPL بصمت؛ و<code>|</code> داخل مقطع شيفرة كان يضيف عمودًا إلى جدول منشور؛ وثلاث بوابات كانت تقرأ <code>main.rs</code> ببحث يستطيع تعليق أن يجيب عنه، وتستطيع دالة مُزاحة أن تُرضيه، و— في حالة واحدة — بضابط مضاد للفراغ لم يصل قط إلى الفرع الذي كان يحرسه.","changelog.16ca0f9a8fbd":"⛔ تجميد الميزات — 11 سبتمبر 2026","changelog.ca13a48bad9c":"<strong>قائمة الميزات مغلقة حتى <code>v1.0.0</code> المستقر.</strong> من هنا لا يدخل إلا إصلاح العيوب والتقوية والتحسين والتوثيق والتعريب. والفكرة التي تصل أثناء النسخة التجريبية تحصل على رقم إصدار <em>بعد</em> 1.0 لا على مكان فيه — فالنسخة التجريبية التي تتحرك مجموعة ميزاتها ليست نسخة تجريبية، وتكفّ تقارير أخطائها عن أن تعني شيئًا.","changelog.73951f911f5c":"⚠ <strong>ثلاثة أشياء حُدّدت قبل الخط ما زالت قيد الإنهاء</strong> وتُحمل لا تُقطع: الفاصل الزمني للجلسة، وتسليم المسارات المنفصلة في MixSir، والإبلاغ عن المشارك الميت في الغرفة. حمل ميزة غير منتهية ليس كإضافة ميزة جديدة.","changelog.6293a41b4e75":"أُضيف — يستطيع تحديث نفسه، وهناك دليل","changelog.ac19bec2400d":"<strong>يستطيع Oscillate تحديث نفسه، ويسأل أولًا.</strong> تُظهر <em>الإعدادات ▸ التحديثات</em> النسخة التي تشغّلها، وزر <em>ابحث عن تحديثات</em>، والعنوان الدقيق الذي سيُتّصل به، وآخر مرة اتُّصل به فعلًا. ⛔ <strong>لا يحدث شيء حتى تضغط شيئًا.</strong> الفحص عند التشغيل مفتاح، وهو <strong>مطفأ</strong>؛ ومع إطفائه لا يُتّصل بشيء، ولا تُظهر اللوحة أي نتيجة على الإطلاق، ويبقى <em>آخر فحص</em> على <em>أبدًا</em>. ⛔ ولا ترسم أبدًا <em>«أنت على آخر إصدار»</em> فوق فحص لم يحدث — فهاتان حقيقتان مختلفتان ولن تكون إلا إحداهما صحيحة.","changelog.2d43b4efba6d":"⚠ <strong>ما يرسله الفحص: لا شيء.</strong> يطلب ملفًّا ثابتًا واحدًا ولا يحمل أي معلومات عنك أو عن هذا الجهاز أو عن مشاريعك. وحين يُعثر على تحديث تُعرض عليك النسخة والتاريخ وسجل التغييرات والحجم، وأنت تختار. ⛔ <strong>كل تحديث موقَّع</strong>، والتحديث الذي لا يُتحقَّق من توقيعه يُرفض مع خطأ بدل أن يُثبَّت — ولا يوجد طريق يتجاوز ذلك الفحص.","changelog.fc410aff2057":"⛔ <strong>صُحّحت جملتان بسببه، وكلتاهما كانت تُشحن سلفًا.</strong> كانت الإعدادات تقول <em>«لا حساب، لا قياس عن بُعد، لا اتصالات تلقائية من أي نوع»</em> بثماني عشرة لغة، وكانت الاتفاقية تقول الشيء نفسه. والفحص عند التشغيل الذي فعّلته <strong>هو</strong> اتصال تلقائي، فصارت الجملتان تقولان إن Oscillate <em>لا يُجري أي اتصال لم تطلبه</em> وتسمّيان المناسبات الثلاث التي يستعمل فيها الشبكة أصلًا.","changelog.459ef05e4504":"<strong>موقع توثيق بثماني عشرة لغة.</strong> الرئيسية، والدليل الكامل، وسجل التغييرات، وسلّم الإصدارات — بلا CDN، ولا تحليلات، ولا متتبّع، ولا خط مضمَّن، ولا سكربت لطرف ثالث في أي مكان منه، وهو الوعد نفسه الذي يقطعه التطبيق، وتفرضه بوابة بناء لا يُترك ادّعاءً. ⛔ <strong>لا تنزيلات عليه، ولا شيء حتى <code>v1.0.0</code>.</strong> صفحة التنزيل مبنية، وتقول بوضوح إنه لا شيء هناك بعد، وليست مرتبطة.","changelog.51a624b39021":"<strong>كل إجراء موثَّق مصوَّر بلقطة شاشة حقيقية من البناء الحقيقي</strong>، والشيء الذي يُطلب منك ضغطه محاط بإطار أحمر ومرقَّم — تُلتقط بتمريرة بلا واجهة على الواجهة الأمامية المبنية، لا تُرسم يدويًا أبدًا، وتُفحص في كل تشغيل فلا تنجو صورة لبناء لم يعد موجودًا.","changelog.84b4b10ce168":"<strong>شاشة بداية أصلية على macOS.</strong> هي الشكل نفسه والقفزة نفسها، يرسمهما AppKit بدل عرض ويب ثانٍ — وهذا ما أتاح التخلص من الواجهة البرمجية الخاصة الوحيدة من Apple التي كان هذا المنتج يستعملها. ⚠ الاستدعاء الخاص استدعاء تستطيع Apple إزالته في إصدار فرعي؛ ولو حدث ذلك أثناء النسخة التجريبية لرسم كل جهاز Mac مستطيلًا معتمًا فوق سطح المكتب. Windows وLinux لم يتغيرا.","changelog.4c1daaca8982":"⛔ **زر <em>افتح بلاغًا معبّأً مسبقًا على GitHub</em> داخل التطبيق لم يكن يؤدي إلى أي مكان.** كان يشير إلى المالك السابق للمستودع، فكل منتج استعمله — المسار الوحيد الذي وُجد مُبلِّغ الأعطال كله من أجل الوصول إليه — كان يحصل على 404، بعد كتابة التقرير. وكان مضيف الإضافات يعرّف نفسه لإضافات CLAP بالعنوان الميت نفسه.","changelog.fdc84a95e8eb":"⚠ <strong>كان <code>v0.4.5</code> مفقودًا من سلّم الإصدارات المنشور</strong>، ومن السلّم الخاص، مع أن المرحلة التي خلفه مبنية منذ 2026-09-04. يُولَّد السلّمان الآن من ملف واحد ويُقارنان في كل بناء.","changelog.70e390902fc1":"أُضيف — تستطيع أن تراهم، وتسمعهم، وتسلّمهم مسارًا، وتطبع من كتب ماذا","changelog.0ff6295aa3e0":"⛔⛔ <strong>الصوت والكاميرا ومشاركة الشاشة، في لوحة الغرفة.</strong> اضغط <em>تحدث</em> فيسمعك الآخرون؛ واضغط <em>الكاميرا</em> فيرونك. ويستطيع شخص واحد في كل مرة مشاركة شاشته. ⚠ <strong>الميكروفون والكاميرا مطفآن حتى تضغط شيئًا، وOscillate يرفضهما افتراضيًا</strong> — يحتفظ التطبيق بموافقته الخاصة، ولا يطلب عرض الويب من نظام التشغيل إلا بعد أن تقول نعم. إغلاق الغرفة أو إطفاء عنصر تحكم يوقف المسار، وهذا ما يطفئ ضوء العتاد.","changelog.58fe9d7d8f57":"⚠ <strong>لا شيء من الكاميرا أو الميكروفون يُسجَّل أو يُخزَّن مؤقتًا على القرص أو يُرسل إلى أي مكان سوى المشاركين في غرفتك.</strong> لا يوجد خادم في الطريق. ⚠ الشاشة المشارَكة تحمل <strong>الفيديو فقط</strong> — فكل ما يُعزف على سطح مكتبك، بما في ذلك موسيقى لم تكتبها، يبقى على جهازك.","changelog.3b3fa07d1428":"⛔ <strong>مشاركة الشاشة على Windows وLinux.</strong> لا يملك macOS طريقًا لالتقاط الشاشة من داخل عرض ويب مضمَّن لا يحتاج إلى واجهة برمجية خاصة في ملف تنفيذي موثَّق، لذا الزر غائب هناك ويقول السبب بدل أن يفشل عند الضغط.","changelog.8b18ea1e7eeb":"⛔⛔ <strong>التسليم — سلّم مسارًا واحدًا لشخص واستعده بمفتاح واحد.</strong> ما دام في يده فهو الكاتب <strong>الوحيد</strong> عليه، <em>بما في ذلك أنت</em>، فتُرفض تعديلاتك أنت على ذلك المسار حتى تستعيده. ⚠ والإمساك <strong>حاصر</strong> كما هو حصري: يستطيع أن يكتب ذلك المسار ولا شيء غيره. تسليم خط باص ليس تسليمًا للجلسة.","changelog.52c632003a26":"⚠ <strong>الاستعادة ختم، لا مفتاح.</strong> التعديل الذي أجراه قبل أن يكون قادرًا على المعرفة يبقى له ويقع؛ أما الذي أجراه بعد ذلك فلا. رفض كل ما هو في الطريق سيعاقب أحدًا على سرعة الضوء.","changelog.d460b43b1bf3":"⛔ <strong>الإمساك يُلزم فقط الجهاز الذي منحه</strong>، ويدوم بالضبط ما دام الاتصال. ومن ينقطع لا يمسك شيئًا — وإلا لكانت مغادرة الغرفة ستقفل عليك مسارك بقية الجلسة.","changelog.8d5007a0052a":"⛔⛔ <strong>الكوميتي — مبارزة إيقاعات يملك فيها كل دور موازيره الخاصة.</strong> يحصل كل دور على امتداد منفصل من الخط الزمني، يُحدَّد عند بدء المبارزة، فيكون <em>دور من هذا</em> و<em>داخل نطاقه</em> السؤال نفسه. ⚠ <strong>العدّ التنازلي على الشاشة لا يحجب شيئًا، وهذا مقصود</strong>: فالفحص الذي يستشير ساعة الحائط سيتيح لحاسوبين الوصول إلى جوابين متعاكسين عن التعديل نفسه ويترك المشروعين يتباعدان بصمت. تعطيل الساعة لا يكسب شيئًا، ولا يوجد دور يُطالَب به أو يُرفض التنازل عنه.","changelog.884f0b382cfc":"⚠ <strong>نوافذ المازورات تغطي وضع المقاطع.</strong> الأنماط والمسارات والأتمتة ومسارات CC والطبول تمتد بطبيعة بنائها على الخط الزمني كله وتبقى تحت قاعدة «الكاتب الأخير يفوز»؛ واللوحة تقول ذلك بدل أن تتركك تكتشفه.","changelog.a7e65a956e7d":"⛔⛔ <strong>ورقة التوزيع مُشتقة، والعمل الذي استرجعته لا يُحتسب.</strong> التراجع عملية عادية في السجل، فالعدّ الساذج كان سينسب إلى المنتج ثماني نوتات تراجع عنها — وينسبها إليه مرتين، مرة للعمل ومرة للتراجع. والإعادة محسومة أيضًا: العمل الذي تُراجع عنه ثم أُعيد يُنسب مرة أخرى. ⚠ لكل مؤلف: العمليات والنوتات والمقاطع والأجهزة والمسارات التي مسّها، والحصص مجموعها هو الإجمالي الذي هي أجزاء منه.","changelog.2b918a7903cf":"⚠ <strong>الحقيقة المشتقة لا يمكن كتابتها يدويًا.</strong> <code>Contribution</code> لا يحمل أي نص على الإطلاق — فقط معرّفات وأعداد صحيحة وطوابع زمنية — وليس له مُفكِّك تسلسل، فلا يمكن أن يصل أبدًا من ملف أو مشارك أو الصفحة. لا يمكن إلا أن يُحسب. تُحَلّ الأسماء عند الحافة، من المعرّفات، والمؤلف الذي ليس لهذا الجهاز قناة له يحتفظ بمعرّفه بدل أن يستعير اسم شخص آخر.","changelog.a0d3d98f71d7":"⚠ <strong>التصدير إلى Markdown وCSV وPDF لم يُبنَ بعد</strong>، ولا عمود النسب المئوية القابل للتحرير. ما يُشحن هو الاشتقاق، على الشاشة.","changelog.f4799f613685":"تغيّر — لا يستطيع المشارك أن يتكلم باسم غيره","changelog.d169d798cfa7":"⛔⛔ <strong>الهوية هي الاتصال، لا حقل في الرسالة.</strong> حتى هذا الإصدار كان مؤلف العملية سلسلة يختارها المرسل: الفحص القديم لم يكن يرفض إلا العملية التي تدّعي أنها <em>أنت</em>، ولم يفعل شيئًا حيال مشارك يختم هوية <strong>طرف ثالث</strong> على إحداها. وكان ذلك سيجعل المسار المسلَّم ودور المبارزة وسطر النسب قابلة للتزوير بسطر واحد لكل منها.","changelog.e345cf9eb7ad":"▶ الغرفة ليس فيها حسابات، ولا شيء يستطيع توقيع رسالة، لذا يستعمل Oscillate الشيء الوحيد الذي يمكنه معرفته: الاتصال الذي وصلت عليه البايتات فعليًا. أول رسالة على الاتصال تعرّف بمن يتكلم، وبعد ذلك <strong>لا يجوز أن يتغير أيٌّ من نصفَي هذا الزوج</strong> — فلا يستطيع الاتصال إعادة تسمية نفسه، ولا يستطيع اتصال جديد ادّعاء شخص يسمع منه Oscillate سلفًا. ⚠ الهوية التي لم تُرَ من قبل تُصدَّق في أول مرة تتكلم؛ فمع غياب الحسابات لا يوجد ما هو أفضل، والتظاهر بغير ذلك سيكون أسوأ من الحد.","changelog.e4feb5900f76":"⛔ <strong>الرفض لم يعد مخالفة.</strong> ثلاث حالات رفض تفصل المشارك، وكانت كل حالة رفض لصلاحية تُحتسب — فمن قال عدّه التنازلي إن الجرس لم يرنّ بعد، أو سُحبت منه صلاحية قبل لحظة، كان يجمع مخالفات لأنه تصرف تمامًا كما صُمّم. الآن لا يُحتسب إلا الرسالة المشوّهة أو المزوّرة، والتمييز خطأ ترجمة لا تعليق.","changelog.bdb9d0d768f8":"أُصلح — خمسة طرق مسدودة في لوحة الغرفة","changelog.c26c74c2acfa":"⛔⛔ <strong>يمكن فتح المنطقة المطويّة مرة أخرى.</strong> تخفي لوحة الغرفة نفسها تحت 1180 بكسل CSS، وكان زرّها في شريط العنوان <strong>معطّلًا</strong> — لكن حاسوبًا محمولًا بعرض 1280 بكسل بتحجيم العرض الذي يأتي به Windows يُبلغ عن نحو 853، فعلى جهاز عادي <strong>لم يكن هناك أي طريقة لفتح غرفة على الإطلاق</strong>. الطيّ الآن قيمة افتراضية يمكنك تجاوزها. الضيّق القابل للاستعمال يتفوق على الصحيح الذي لا يمكن بلوغه.","changelog.68ce629f09b9":"⛔ <strong>هناك طريق للعودة من غرفة نصف منشأة.</strong> المنتج الذي ضغط <em>إنشاء</em> ثم أراد الانضمام إلى غرفة صديق بدلًا من ذلك كان عالقًا: لا حقل انضمام، ولا <em>مغادرة</em>، ولا شيء يعيد اللوحة إلى البداية. كانت إعادة تشغيل التطبيق السبيل الوحيد للخروج.","changelog.9a716d44d5e3":"⛔ <strong>الإخفاق المسمّى صار تحته زر.</strong> حين يجمع الاتصال مرشّحيه بنجاح ثم لا ينفتح أبدًا، كانت اللوحة ترسم شرحًا دقيقًا لإخفاق دائم دون أي شيء يُضغط — <em>مؤشر انتظار دوّار بخطوات إضافية</em>.","changelog.e95b50b168e7":"⛔ <strong>الرمز الفارغ رفض، لا رمز.</strong> بلا واجهة خلفية كانت اللوحة ترسم صندوقًا فارغًا بزر <em>نسخ</em> حيّ وتحذير <em>عامله كأنه كلمة مرور</em> بجانبه.","changelog.2efd7314519c":"⚠ لم يعد <em>«يجري استلام المشروع…»</em> يجثم فوق لوحة خاملة، والمنضمّ الثاني والثالث يحصلان على صندوق لصق فارغ بدل نص السابق.","changelog.0294d79bbe62":"أُضيف — مفتاح واحد يحوّل الجلسة إلى شيء تستطيع نشره","changelog.2b19ee32f945":"⛔⛔ <strong>بطاقات الجلسة.</strong> اضغط <code>Ctrl/Cmd+Shift+C</code>، أو ملف ▸ <em>بطاقة الجلسة…</em>، فيرسم Oscillate صورة للجلسة بحجم 1200×630 — الإيقاع، والمفتاح الموسيقي، وعدد المسارات والمقاطع، وطولها، وشكل التوزيع، وشعار Oscillate. احفظها أو انسخها وانشرها.","changelog.789fdbc637f7":"⛔ <strong>رمز الغرفة مطفأ افتراضيًا</strong>، ومفتاحه يحمل التحذير بجانبه لا في تلميح: <strong>عامله كأنه كلمة مرور — كل من يراه يستطيع الانضمام.</strong> وحين لا تكون غرفة مفتوحة يقول المفتاح ذلك بدل أن يبقى رماديًا بلا تفسير.","changelog.70bf28ecdf8d":"⛔ <strong>البطاقة لا تستطيع تسريب جهازك، وهذه خاصية في التصميم لا مرشّح.</strong> الحقائق التي تُبنى منها البطاقة <strong>ليس فيها مكان لوضع نص</strong> — لا اسم مشروع، ولا اسم مسار، ولا اسم عيّنة، ولا مسار ملف. لا يوجد مُعقِّم يمكن أن يخطئ لأنه لا يوجد شيء يُعقَّم.","changelog.2ffea8d2ddec":"⚠ <strong>الحفظ هو الزر الذي يعمل دائمًا.</strong> هل تسمح هذه المنصة لـ Oscillate بوضع صورة في الحافظة؟ هذا ليس شيئًا نستطيع الوعد به، لذا يقول <em>نسخ</em> بوضوح حين لا يستطيع بدل أن يبدو كأنه نجح.","changelog.49b5e00378e0":"⚠ يُرسم الشكل من التوزيع كله، لا من الجزء الظاهر على الشاشة — فالجلسة نفسها تصنع البطاقة نفسها مرتين.","changelog.5eabaf9d3bff":"أُضيف — جلستك تُفتح بدون Oscillate","changelog.85583a70d607":"⛔⛔ <strong>ملف ▸ تصدير مجلد مرافق…</strong> يحوّل الجلسة إلى مجلد من الملفات العادية: مسار منفصل بالطول الكامل لكل مسار، وملف MIDI لكل جزء، وكل الأجزاء في ملف <code>.mid</code> واحد من النوع 1، وخريطة إيقاع، وملف README يشرح كل ذلك. <strong>ملفات المشاريع في كل مكان آخر احتجاز للرهائن.</strong> المتعاون الذي لا يملك Oscillate يُفلت المسارات المنفصلة عند المازورة 1 فتصطف.","changelog.b3048638cc00":"▶ <strong>كل مسار منفصل بطول الأغنية كلها</strong>، فلا شيء يحتاج إلى دفع إلى مكانه.","changelog.353e48b03b6b":"⛔ <strong>الجزء المكتوم يُصيَّر ويُسمّى، ولا يُسقط بهدوء أبدًا.</strong> تسليم أحدهم ملفًّا صامتًا صحيح الاسم وصحيح الطول هو أسوأ طريقة لإغفال مسار، لأنه يبدو صحيحًا — لذا يُصيّره Oscillate على أي حال ويسرده تحت <em>MUTED PARTS</em> في README، لتكتمه من جديد إن أردت ما كان يُعزف.","changelog.a9bc3aab7e27":"⛔ <strong>ويقول README أيضًا ما ليس في المجلد.</strong> يُصيّر Oscillate هذه المسارات المنفصلة دون أي VST 3 أو CLAP كان على الجلسة — أجهزة Oscillate الخاصة مشمولة، والإضافات لا — والمتعاون الذي يحصل على جزء لا يبدو صحيحًا يستحق أن يُقال له السبب بدل أن يُترك يخمّن. وهذا الحد مكتوب في الملف الذي ينتجه كل تصدير.","changelog.83bc1a94a3b0":"⚠ <strong>الجلسة الأطول من عشر دقائق لا يمكن تصديرها بهذه الطريقة بعد</strong>، وتقول ذلك بدل أن تنتج شيئًا مقطوعًا.","changelog.76f000611d9c":"أُضيف — الماستر يخبرك بما ستفعله به كل خدمة","changelog.c8f1227e67e3":"⛔⛔ <strong>قياس صادق للماستر.</strong> اضغط <strong>الجهارة</strong> في المازج فيُظهر Oscillate قيم LUFS المتكاملة وقصيرة المدى واللحظية للماستر، ومدى جهارته، و<strong>ذروته الحقيقية بوحدة dBTP</strong> — ثم، بجانب الهدف المنشور لكل خدمة، ما ستفعله تلك الخدمة فعلًا بهذا الماستر. الماستر عند −9.16 LUFS مقابل −14 لدى Spotify <strong>يُخفَض 4.84 dB</strong>، واللوحة تقول ذلك بهذه الكلمات.","changelog.fdb6d3d5fb12":"▶ <strong>الجميع لديهم LUFS. ولا أحد يخبرك بما يعنيه للمكان الذي يذهب إليه التسجيل.</strong> هذا الجدول هو الغاية من الميزة.","changelog.e3f75c74b59a":"⛔ <strong>الذروة الحقيقية ليست ذروة العيّنات، وحتى الآن لم يكن لدى Oscillate إلا الثانية.</strong> المحوِّل يعيد بناء الموجة <em>عبر</em> العيّنات، ويمكن لتلك الموجة أن ترتفع فوق أعلاها — فالمحدِّد المضبوط على ذروة العيّنات يقصّ عند التشغيل بينما يقرأ المقياس −0.1. يقيس Oscillate الآن بإفراط اعتيان 4×، كما يتطلب ITU-R BS.1770-4، ويُبلغ عنها بوحدة dBTP فتخبرك الوحدة نفسها بأي رقم تنظر إليه.","changelog.db653ea0e802":"⛔ <strong>الهدف ليس قاعدة، وكل صف يقول أيهما هو.</strong> معظم هذه تطبيع للتشغيل يستطيع المستمع إطفاءه؛ واثنان — EBU R 128 وATSC A/85 — مواصفات تسليم حقيقية. والملاحظة جزء من الصف، لا تلميح عليك البحث عنه. ⚠ يعيش الجدول في <code>data/loudness-targets.json</code> مع تاريخ آخر تحقّق منه، لأن هذه الأرقام تتغير.","changelog.721221e316a5":"⛔ <strong>منزلتان عشريتان دائمًا، والرقم الذي لم يقسه أحد شَرطة لا رقم.</strong> المقياس الذي يقرّب بطريقة تُجامل هو مقياس يكذب بأدب، و«−200.00 LUFS» ليست قياسًا لأي شيء.","changelog.b4bf7c9e9637":"⚠ <strong>مطفأ افتراضيًا، لأنه يكلّف وقت المعالج</strong>، والزر يقول ذلك.","changelog.b0bc2e5d54c5":"أُضيف — المازج يستطيع أن يخبرك أي مسارين يتنازعان","changelog.92a06653ecc1":"⛔⛔ <strong>رادار الحجب.</strong> اضغط <strong>الرادار</strong> في المازج فيسرد Oscillate أزواج المسارات التي تشغل الجزء نفسه من الطيف، الأسوأ أولًا، مسمّيًا النطاق الذي تلتقي فيه. انقر صفًّا فيأخذك إلى أحدهما.","changelog.2e33bd64d89d":"▶ <strong>إنه حساب، واللوحة تقول ذلك بصريح العبارة.</strong> يُختزل صوت كل مسار إلى طاقات واحد وثلاثين نطاقًا بعرض ثلث أوكتاف؛ ويحصل مساران على درجة عالية في نطاق حين تكون طاقاتهما <em>متشابهة</em> وكلاهما <em>حاضر فعلًا</em>، والتصادم زوج حافظ على ذلك ثانية ونصفًا. تتقاضى iZotope ثمنًا لمقياس الحجب وتتكئ على تعلّم الآلة؛ وهذا حساب تداخل يأتي في العلبة، والتلميح يخبرك بذلك بدل أن يوحي بغيره.","changelog.e7e45a4d31f7":"⛔ <strong>مطفأ افتراضيًا، لأنه يكلّف وقت المعالج</strong>، والزر يقول ذلك قبل أن تضغطه. إطفاؤه يحرّر المحلّلات ويوقف خيط الصوت عن الالتقاط — المطفأ مطفأ حقًّا.","changelog.0acfd6d0ea4c":"⛔ **الزوج الذي لم يسمعه Oscillate يُرسم <em>لم يُسمع بعد</em>، لا نظيفًا أبدًا.** مساران لم ينتجا صوتًا ليسا مسارين عادا نظيفين، واللوحة التي تُبلغ عن الثاني وهي تعني الأول ستطلق ادّعاءً لم يقسه أحد.","changelog.dd554854708c":"⚠ <strong>ما ليس موجودًا بعد، بوضوح.</strong> لا يوجد <em>اقتراح</em>: يخبرك الرادار أين التداخل ولا يقترح حركة معادل، والنقر على صف يحدد أحد المسارين بدل فتحهما كليهما. والجلسة التي فيها أكثر من اثنين وثلاثين مسارًا تُراقب حتى ذلك الحد فقط — واللوحة تقول ذلك بدل أن ترسم البقية نظيفة.","changelog.766ccc081745":"أُضيف — البناء يرفض الآن ميزة لا يستطيع التطبيق بلوغها","changelog.d340e8a8a795":"⛔⛔ <strong><code>check-commands.mjs</code>: كل <code>#[tauri::command]</code> يجب أن يكون في <code>generate_handler!</code>.</strong> هذه بوابة ضد <strong>العيب الذي شحنه هذا المشروع أكثر من أي عيب آخر</strong> — آلية عاشت أطول من مستدعيها الوحيد، سبع عشرة حالة مسجّلة. الأمر المفقود من تلك القائمة <strong>يُترجَم، وينجح في clippy، وينجح في <code>cargo test</code>، ولا وجود له بالنسبة إلى الصفحة</strong>: لا خطأ، ولا تحذير، ولا اختبار فاشل، مجرد ميزة غائبة بصمت عن التطبيق المشحون. كانت مرحلة كاملة يومًا بعيدة المنال بهذه الطريقة.","changelog.6a242e5b8d08":"▸ <strong>تفشل في الاتجاهين</strong> — أمر لم يسجّله أحد، واسم بقي في القائمة بعد أن أُعيدت تسمية دالته. ▸ <strong>لا تستطيع مطابقة نصها الخاص.</strong> النسخة البديهية من هذا الفحص تبحث عن اسم الأمر فتطابق تصريح <code>fn</code> نفسه، متجاوزة الشيء الذي كُتبت لالتقاطه بالضبط؛ أما هذه فتقارن <em>مجموعتين</em>، فلا يوجد بحث عن سلسلة فرعية يمكن خداعه. ▸ <strong>وترفض الإبلاغ عن مسح نظيف للا شيء</strong>: إذا أنتج تحليل أيٍّ من الجانبين أقل من مئة مدخل فالتحليل معطوب، فتفشل البوابة بدل أن تقول «نظيف». البوابة التي تنجح حين لم تجد شيئًا أسوأ من غياب البوابة، لأنها تُصدَّق.","changelog.368c3ca85aec":"⚠ تعمل في <code>npm run ci:local</code> وفي مهمة سلسلة الإمداد في CI. رُئيت تتحول إلى الأحمر في الاتجاهين قبل إيداعها، والشجرة التي تحرسها نظيفة حاليًا عند <strong>163 مُعلَنًا، و163 مسجّلًا</strong>.","changelog.c791e210b65a":"أُضيف — كلماتك على الخط الزمني، واللقطة تتذكر أيّها","changelog.f5e9ebab3d41":"⛔⛔ <strong>مسار الكلمات.</strong> اضغط زر الكلمات في شريط أدوات التوزيع فينفتح شريط تحت المسطرة وكلماتك مصفوفة على امتداد الأغنية. السطر الذي أنت عليه يُرسم بلون التمييز، والمقطع اللفظي الذي فوقه رأس التشغيل يضيء حين يمر — مقروءًا من <strong>النبضة نفسها التي يُرسم منها رأس التشغيل</strong>، ستين مرة في الثانية، لا من مؤقّت أبدًا. شاشة التلقين التي تتأخر عن النقل هي الشيء الوحيد الذي يجب ألا تفعله هذه الميزة أبدًا.","changelog.47d04dae6e96":"▸ <strong>استيراد <code>.txt</code> أو <code>.lrc</code>.</strong> يقع ملف <code>.lrc</code> الموقَّت على المازورات التي غُنّي عليها — تُحوَّل طوابعه <code>[mm:ss.xx]</code> عبر خريطة إيقاع مشروعك، فالأغنية التي تبطؤ عند المازورة التاسعة تبقى مصطفّة. والنص غير الموقَّت ينتشر على القسم وتدفع كل سطر إلى مكانه، مازورة في كل مرة، بضغطة تراجع واحدة لكلٍّ. ⚠ تُنسخ كلمات الملف إلى مشروعك؛ ولا يُشار إلى الملف نفسه مرة أخرى أبدًا، فالورقة التي سحبتها من مجلد التنزيلات لا تُفرغ نفسها الأسبوع القادم.","changelog.9ed712d8b53f":"▸ <strong>اللقطة تتذكر الكلمات التي غُنّيت عليها.</strong> حين يصل تسجيل يدوّن أي ورقة كانت على الشاشة، فالتركيبة المبنية من أربع لقطات تحمل المقطع الشعري الصحيح في كل منطقة. ⛔ <strong>وإعادة كتابة سطر لا تعيد كتابة التاريخ</strong>: أول تعديل بعد وصول لقطة يحتفظ بالكلمات القديمة لتلك اللقطة ويعطيك ورقة جديدة تعمل عليها. وحذف ورقة تشير إليها لقطات يسأل مرتين ويخبرك بعددها.","changelog.c7fbbc8b0881":"⚠ <strong>لم يُبنَ بعد</strong>: سحب سطر بالمؤشر (أزرار الإزاحة هي ما يحرّك السطر اليوم) وتقسيم سطر إلى مقاطع لفظية يدويًا.","changelog.eda939abbe78":"أُضيف — شاشة تلقين تستطيع قراءتها من الطرف الآخر للغرفة","changelog.9c8a4a093ca5":"⛔⛔ <strong>ثلاث طرق لرؤية الكلمات، ولا تحتاج أيٌّ منها إلى شاشة ثانية.</strong> رمز الكلمات في شريط أدوات التوزيع ما زال يفتحها <strong>ضمن السطر</strong> في المسار. وبجانب زر التسجيل الآن اثنتان أخريان: <strong>شاشة التلقين</strong>، التي ترفع شاشة تلقين عائمة كبيرة فوق الجلسة، و<strong>⇱</strong>، الذي ينقلها إلى <strong>نافذة خاصة بها</strong> لشاشة ثانية. الثلاث كلها ترسم الكلمات نفسها من النبضة نفسها — التي يُرسم منها رأس التشغيل — فلا يمكن أبدًا أن يختلف المسار وشاشة التلقين على السطر الذي أنت عليه.","changelog.162980882b3e":"▸ <strong>خط بحجم يناسب حامل الميكروفون، لا المكتب.</strong> أصغر حجم لشاشة التلقين يزيد على ثلاثة أضعاف حجم نص التطبيق الأساسي، والمنزلق لا يتحرك إلا صعودًا من هناك. هذا الحد الأدنى مفروض مرتين، في الشيفرة وفي ورقة الأنماط، و<em>يُقاس</em> في متصفح حقيقي بدل أن يُعلن — لأن الحجم المكتوب الذي لا يُطبَّق أبدًا يبدو تمامًا مثل حجم يعمل.","changelog.bc3bce45fb64":"▸ <strong>الانعكاس، لزجاج الملقّن.</strong> تخرج الكلمات معكوسة على الشاشة فيقلبها الزجاج إلى الاتجاه الصحيح للمغني. ⚠ عناصر التحكم لا تُعكس أبدًا: المنزلق الذي لا تستطيع توجيهه أسوأ من غياب المنزلق.","changelog.b5cab03de549":"▸ <strong>تباين عالٍ</strong> — أبيض على أسود في السمتين كلتيهما، 21:1، وهو أبعد بكثير من أشد معايير إمكانية الوصول صرامة. والمقطع اللفظي الذي أنت عليه يحتفظ بلون التمييز وبخطه السفلي.","changelog.09c361712c76":"▸ <strong>سرعة التمرير</strong>، وهي صادقة بشأن ما تفعله: النقل يقرر <em>متى</em> يصبح السطر حاليًا، فلا يغيّر عنصر التحكم إلا سرعة انتقال العمود إليه — من قطع فوري إلى انزلاق بطيء. لا شيء هنا تقوده ساعة.","changelog.03410a1b5d7b":"<code>Esc</code> يبعد شاشة التلقين العائمة. وزر ⇲ في النافذة المنفصلة يخفيها، فتعود تمامًا حيث تركتها وكما تركتها.","changelog.18c67528e236":"تغيّر — صفحة الشكر كفّت عن المبالغة فيما يُشحن","changelog.509f0435939b":"⛔⛔ <strong>كانت تقول «926 مكوّنًا». 360 منها أدوات بناء ليست في Oscillate على الإطلاق</strong> — المترجمات ومشغّلات الاختبار التي يُبنى بها المشروع، والتي لا تصل إلى جهازك أبدًا. تقول الإعدادات ← الشكر الآن الرقمين بوضوح: <strong>567 مكوّنًا تُشحن داخل Freally Oscillate</strong>، و360 أخرى لم تعمل إلا على الجهاز الذي بناه. هذه هي الصفحة الموجودة كي تتحقق بنفسك من ادّعاء «مجاني، وبلا ذكاء اصطناعي»، فالرقم الذي يجاملنا كان أسوأ ما يمكن أن تحمله.","changelog.5814ad801a5b":"▸ <strong>القائمة مجمّعة، وتستطيع أن ترى ما كل شيء.</strong> حزم تطوير الإضافات، وترميزات الصوت، وحزم Rust، ومجموعات الأيقونات، وحزم npm، والرسومات التي رسمها مالك Oscillate — ستة عناوين، لأن سؤال «أيّ هذه هو الترميز؟» لم يكن ممكنًا الإجابة عنه من قائمة مسطّحة من تسعمئة صف.","changelog.f9de56f9441e":"▸ <strong>كل مكوّن يسمّي مؤلفًا يُظهره الآن</strong>، وهذا ما يعنيه وعد صفحة الشكر فعلًا. ⚠ حزم npm لا تسمّي مؤلفيها في أي مكان يستطيع Oscillate قراءته دون سؤال خادم، وOscillate لا يسأل الخوادم، لذا لا تُظهر تلك الصفوف مؤلفًا بدل أن تُظهر تخمينًا.","changelog.3d0eb391f040":"▸ <strong>حزمة تطوير إضافات VST 3 مسرودة، مع إشعار حقوق النشر الخاص بها</strong> — ليست في أي ملف قفل، فلم يضعها شيء هناك قط، والترخيص يطلب هذا الشيء الواحد بالضبط.","changelog.7377a939c0c4":"أُضيف — اللقطة التي سجّلتها للتو تصل إلى المنتج الآخر","changelog.7fb3fbc8f280":"⛔⛔ <strong>التسجيل ينتقل؛ وحزمة العيّنات لا تنتقل.</strong> اللقطة هي الشيء الوحيد الذي تملكه دون لبس، فحين ينضم أحدهم إلى غرفتك تذهب اللقطات التي سجّلتها مع المشروع وتُعزف مقاطعهم. وكل ما اشتريته يبقى حيث هو، وقائمة ما يجب الذهاب لجلبه لم تتغير.","changelog.0e125500e568":"▶ <strong>يعرف Oscillate أن اللقطة لك لأنه هو من كتب الملف</strong>، في لحظة كتابته — لا بالتخمين من مسار. ولا يرسل إلا ملفًّا موجودًا فعلًا في مجلد Takes الخاص به، فالمشروع الذي يرسله إليك أحدهم بالبريد لا يستطيع أن يحوّل جهازك إلى وسيلة لتمرير ملفات <em>الآخرين</em>.","changelog.52dc23d22b34":"▸ <strong>اللقطة التي تصلك ليست لك لتمرّرها.</strong> كل جهاز لا يضمن إلا ما سجّله بنفسه. ⚠ كُتب هذا قاعدةً قبل أن يصبح صحيحًا: الشيفرة التي كان يُفترض أن تمحو العلامة لم تكن موجودة، فاللقطة من متعاون كانت ستُعرض على ثالث كأنك أنت من سجّلها. وهي مفروضة الآن، في الاتجاهين، وفوقها بوابة.","changelog.4976afdf942b":"▸ <strong>تقول اللوحة كم لقطة وصلت</strong>، بجانب قائمة العيّنات التي لم تصل. المقطع الذي يبدأ العزف بعد ثوانٍ من انضمامك هو الميزة وهي تعمل، ولم يكن على الشاشة ما يقول ذلك.","changelog.91203a1b805c":"أُصلح — عيّنة مستوردة كانت تُعلَّم على أنها تسجيلك أنت","changelog.bf40e3fa098c":"⛔⛔ <strong>كل ملف صوتي استوردته عبر التوزيع كان يُسجَّل في المشروع على أنه لقطة صنعها Oscillate.</strong> كان يتشارك مسار شيفرة واحدًا مع المسجّل، وكان المسار يضع العلامة دون شرط، مع تعليق يدّعي أن المسجّل وحده يصل إليه. ونتج عن ذلك أمران: لم يُخبَر المتعاون قط من أي حزمة جاءت إحدى عيّناتك المستوردة، فلم يستطع الذهاب لشرائها؛ وما إن بدأت اللقطات تنتقل حتى كانت العيّنة المشتراة ستنتقل معها. يُميَّز الآن بين الاستيراد والتسجيل بنظام الأنواع لا بتعليق.","changelog.8d484c32c666":"أُضيف — حزم عيّناتك تبقى لك","changelog.8f6475f914ce":"⛔⛔ <strong>Oscillate ليس وسيلة لنقل حزم العيّنات بين الحواسيب، وهو يفرض ذلك الآن بدل أن يعد به.</strong> حين تعمل مع أحدهم، ما يعبر هو <em>إشارة</em> المشروع إلى الصوت — لا الصوت أبدًا، ولا المسار الذي يعيش فيه على قرصك أبدًا.","changelog.f988bbb09929":"▶ <strong>إن كنتما تملكان الحزمة كلاكما، فهي تُعزف ببساطة.</strong> يتعرّف Oscillate على صوت متعاونك في مكتبتك من محتواه، فالحزمة نفسها تعمل أينما احتفظت بها وأيًّا كان الاسم الذي أعطيته للمجلد. لست مضطرًا لتحديد مكان أي شيء.","changelog.c8bdf1531d58":"▸ <strong>إن لم تكن تملكها، يخبرك Oscillate ما هي</strong> — الحزمة والملف — ويبقى المقطع صامتًا حتى تحصل عليها، من متعاونك عبر Discord أو بشرائها، كما كنت ستفعل على أي حال. ⚠ العيّنة لديك التي تحمل الاسم نفسه لكن بصوت مختلف يُبلَّغ عنها أنها مختلفة بدل أن توضع في مكانها بهدوء، لأن ذلك سيغيّر التسجيل دون إخبارك.","changelog.4649fcb81559":"⚠ <strong>هذا قائم أثناء عملك، لا عند الانضمام فقط.</strong> العيّنة المسحوبة إلى مسار في منتصف الجلسة تخرج ومسارها منزوع، مثل كل شيء آخر.","changelog.57f9f9dbb430":"أُضيف — علامة على الحزم التي تملكانها كلاكما","changelog.1c9cfe9ae3ee":"▸ <strong>يستطيع Oscillate الآن أن يخبرك أي حزم عيّناتك يملكها أيضًا من تعمل معهم</strong> — بايتًا ببايت، لا بالاسم. المجلد الذي تملكانه كلاكما يحصل على علامة بجانبه في المتصفح، فتعرف من نظرة أن الصوت الذي تمدّ يدك إليه صوت يستطيعون سماعه فعلًا.","changelog.3f47892c9684":"⚠ يقارن على خطوتين ليبقى سريعًا: أسماء الملفات وأحجامها أولًا، وهذا لا يقرأ شيئًا من قرصك، والفحص الكامل بايتًا ببايت فقط على الحزم التي تبيّن أن شخصًا آخر يملكها أيضًا. والحزمة التي تملكانها تحت اسمَي مجلدين مختلفين تتطابق مع ذلك.","changelog.7bec1b129e12":"⛔ <strong>يضع علامة، وهذا كل ما يفعله.</strong> لا يُرسل شيء — التطابق يخبرك أن الصوت مطابق، ولا يستطيع أبدًا أن يخبر أحدًا كيف حصل أيٌّ منكما عليه.","changelog.bb2db2d36be7":"أُصلح — لوحة الغرفة لم تكن على الشاشة أصلًا","changelog.55a9091211cb":"⛔⛔ <strong>كانت منطقة الغرفة ترسم عنوانها وزر فصلها ولا شيء غير ذلك.</strong> كل ما خلفها كان مبنيًا ولم يكن ممكنًا بلوغ أي شيء منه: لا زر يُضغط، ولا رمز يُنسخ. ⚠ وجده اختبار ينظر إلى الصفحة <em>المبنية</em> لا إلى مكوّن.","changelog.1ec729130651":"▸ ⚠ <strong>وشريط إظهار/إخفاء لوحة المفاتيح الافتراضية كان أصغر من أن يكون هدفًا مريحًا</strong> — بارتفاع 21 بكسل بينما ينبغي أن يكون كل ما يُضغط 24 على الأقل. لم يصبح ظاهرًا في كل مكان إلا في الإصدار الأخير، وعندها بدأ يهمّ.","changelog.57877c1f100c":"أُصلح — التراجع لم يكن يفعل شيئًا بعد فتح مشروع محفوظ","changelog.5243b35620d0":"⛔⛔ <strong>افتح مشروعًا، أجرِ تغييرًا، اضغط <code>Ctrl+Z</code> — ولا يحدث شيء.</strong> كان كل تشغيل يعطي هذا الحاسوب هوية جديدة، بينما يتذكر المشروع المحفوظ من كتبه، فبعد فتح ملف كانت تغييراتك تُسجَّل باسم شخص آخر ولا يجدها تراجعك. ⚠ لم يكن هناك خطأ: كان عنصر القائمة رماديًا ببساطة والاختصار لا يفعل شيئًا.","changelog.c356d2d80bd1":"▸ يحتفظ هذا الحاسوب الآن بهوية واحدة، فإعادة فتح مشروع الأمس تعيد أيضًا سجل التراجع الذي تركته فيه — وهذا ما صُمّم ملف المشروع لحمله دائمًا.","changelog.f0d11ed91957":"أُضيف — حوّل التسجيل إلى نوتات، والنمط إلى تسجيل","changelog.a7701541a706":"⛔⛔ <strong>انقر بالزر الأيمن على مقطع فيصبح من النوع الآخر.</strong> المقطع الصوتي يصبح نمطًا بجانبه؛ والنمط يصبح صوتًا بجانبه. ⚠ <strong>المقطع الذي بدأت منه لا يُستبدل أبدًا</strong> — طلبت النوع الآخر، لا أن يكفّ الأول عن الوجود — والتحويل كله <strong>ضغطة تراجع واحدة</strong>، بما في ذلك المسار الذي ينشئه لوضع النتيجة عليه.","changelog.2a5ddf2c998c":"▸ <strong>التسجيل يصبح نوتات</strong> بالإصغاء إلى حيث تبدأ كل نوتة وما طبقتها. ⚠ <strong>سيكون غير كامل، ويقول ذلك.</strong> حلقة الطبول تتحول إلى <strong>لا شيء على الإطلاق</strong>، وتخبرك كم ضربة لم تستطع قراءة طبقة منها — فاللحن الذي لا يحتويه تسجيلك أسوأ من رفض صادق.","changelog.59ed1e55e7ad":"▸ <strong>النمط يصبح صوتًا عبر كل ما على ذلك المسار</strong>: الآلة في خانتها، ثم كل مؤثر صوتي بعدها، بالترتيب، وكل واحد مسمّى في السطر الذي يظهر عند الانتهاء. ⚠ الجهاز الذي أطفأته بنقطته البنفسجية، أو المجموعة الكاملة التي أطفأتها، <strong>ليس</strong> في التصيير. ⚠ منزلق المسار والبان الخاص به <em>لا</em> يُخبزان فيه عن قصد — فالمقطع الجديد يُعزف عبرهما، وطبعهما فيه يعني تطبيقهما مرتين.","changelog.083ef45f5391":"▸ <strong>إن كانت خانة الآلة فارغة فهو يقول أي صوت استعمل بدلًا منها</strong>، ومُعايِن العيّنات الذي لم يُحمَّل فيه شيء <strong>يُرفض باسمه</strong> بدل أن يُعاد ثانيتين من الصمت.","changelog.79e200253532":"▸ <strong>التقدم رقم، لا مؤشر انتظار دوّار.</strong>","changelog.85981714a333":"أُضيف — الغرفة تُفتح، ولا أحد يشغّل خادمًا","changelog.4749e8ae03da":"⛔⛔ <strong>أربعة منتجين، جلسة واحدة، بلا خادم.</strong> اضغط <em>إنشاء رمز غرفة</em>، وأرسل الرمز إلى أحدهم، والصق الرمز الذي يرسله إليك، فتكونان متصلين. <strong>لا حساب، ولا تسجيل دخول، ولا شيء يجب إبقاؤه يعمل، ولا شيء يستطيع أحد إطفاءه.</strong>","changelog.40cbdaae0aa4":"▸ <strong>نصف المنضمّ موجود الآن.</strong> الصق رمزًا في لوحة الغرفة فيجيب Oscillate برمز خاص به لترسله — القطعة التي كانت مفقودة حين كان الإصدار السابق يستطيع إنشاء غرفة لا يستطيع أحد دخولها.","changelog.5417dcda779c":"▸ ⛔ <strong>الشخص الثالث والرابع يكلّف كلٌّ منهما تبادلًا واحدًا، لا ستة.</strong> ما إن يتصل شخصان حتى يحمل اتصالهما التعريفات لكل من سواهما: غرفة الأربعة أشخاص <strong>ثلاثة</strong> تبادلات بدل الستة التي كانت الشبكة المتشابكة ستحتاجها، والمشاركان الثالث والرابع لا يلصق أحدهما شيئًا للآخر أبدًا.","changelog.e32d5d96e2d3":"▸ <strong>تستطيع أن ترى من هنا.</strong> قائمة حاضرين بلون لكل شخص — اللون نفسه في كل مكان يظهر فيه ذلك الشخص — و<strong>مؤشره يتحرك على توزيعك</strong> أثناء عمله. ⚠ الأسماء يكتبها من يستعملها وقائمة الحاضرين تقول ذلك: لا يوجد حساب، فلا يوجد ما يمكنه التحقق من اسم.","changelog.309b2d70f417":"▸ <strong>دردشة، ما بقيت الغرفة.</strong> ⛔ لا تُكتب في أي مكان — لا على القرص، ولا في المشروع، ولا في إعداداتك.","changelog.63c63c2cdd7b":"▸ ⛔ <strong>تراجعك لك أنت.</strong> يسترجع <code>Ctrl+Z</code> آخر تغيير أجريته <strong>أنت</strong> ولا يسترجع تغيير غيرك أبدًا، حتى حين تقع تعديلاتهم بين تعديلاتك. وشخصان يعدّلان الشيء نفسه في اللحظة نفسها ينتهيان إلى رؤية النتيجة نفسها، دون أن يسأل أيٌّ من الجهازين شيئًا.","changelog.f28f76dbdb7c":"▸ ⚠ <strong>حين لا يتصل، يخبرك بالسبب.</strong> نحو زوج من كل عشرة لا يستطيع أحدهما بلوغ الآخر مباشرة، ويسمّي Oscillate السبب الفعلي — بما في ذلك <strong>قياس</strong> الحالة التي تعطي فيها شبكتك كل خادم عنوانًا مختلفًا، وهي الحالة التي لا يساعد فيها إلا مُرحِّل. ⛔ لا يوجد مؤشر انتظار يدور إلى الأبد.","changelog.17298de48df2":"▸ ⛔ <strong>يُقال لك بما سيتصل، وبما اتصل.</strong> فتح غرفة يسأل خادم STUN عامًا عن عنوانك — الخوادم التي سيجرّبها مسرودة على اللوحة قبل أن تضغط أي شيء، والتي أجابت فعلًا تظهر في الإعدادات ▸ التعاون بعد ذلك، والقائمة لك لتستبدلها، و<strong>لا تتصل بأي خادم</strong> يطفئ ذلك كليًا.","changelog.63cb58714c59":"▸ ⛔⛔ <strong>رمز الغرفة يحتوي على العنوان العام لحاسوبك</strong>، وهذا ما يجعل الغرفة بلا خادم ممكنة أصلًا. <em>«عامله كأنه كلمة مرور»</em> موجودة بجانب <strong>كل</strong> زر ينسخ رمزًا.","changelog.9191285a6277":"⚠ <strong>لا يبدأ شيء حتى تكون له حاجة</strong> — لا غرفة، ولا عملية، ولا طلب من جدار الحماية على جهاز لم يفتح عليه أحد غرفة قط.","changelog.e3b418ec5f75":"⚠ <strong>ما ليس هنا بعد:</strong> الشخص المنضمّ <strong>لا</strong> يستلم مشروعك. وحتى يصل ذلك، على الجهازين أن يفتحا ملف <code>.oscillate</code> نفسه قبل أن يصبح للتعديلات المعنى نفسه.","changelog.e9c85ff00dfa":"أُصلح — لم يكن شيء يقرأ موجات المجلد قط","changelog.d7b3c5728d91":"⛔⛔ <strong>إضافة مجلد تقرأ موجاته الآن.</strong> كان يُفترض أنها تفعل ذلك سلفًا: كانت هناك تمريرة وشريط تقدم وذاكرة مؤقتة، و<strong>لا شيء في البرنامج بدأ واحدة قط</strong>. كانت كل موجة تُرسم في أول مرة يصادف أن تنقر ذلك الملف، وهي اللحظة التي تكون فيها أقل رغبة في الانتظار. ⚠ الشريط بجانب قائمة المجلدات يتحرك الآن، وعليه عدد الملفات.","changelog.c5045ae52aa6":"أُضيف — الملفات تقع حيث تُفلتها، ولكل جهاز واجهته الخاصة","changelog.8aa7963ebacf":"⛔⛔ <strong>اسحب عيّنة من المستكشف إلى التوزيع.</strong> يقع الصوت على المسارات الصوتية وMIDI على مسارات MIDI؛ والنوع الخاطئ <strong>يُرفض بدل أن يُعطى مسارًا جديدًا بصمت</strong>، والهدف يقول ذلك قبل أن تُفلت. والأرض الفارغة تحت آخر مسار تصنع مسارًا من النوع الصحيح، مسمّى باسم الملف. ⚠ عدة ملفات دفعة واحدة تقع متتالية وتُحسب ضغطة تراجع <strong>واحدة</strong>، وملف <code>.mid</code> يصل نوتاتٍ على شبكة المشروع نفسه لا بالإيقاع الذي كُتب به.","changelog.e2a8868bca4e":"▶ <strong>لم يحتج هذا إلى صلاحية جديدة.</strong> يركب السحب القناة نفسها التي تركبها المقاييس؛ ومسارات الملفات لا تصل إلى الصفحة أصلًا.","changelog.c170e8e66577":"⛔⛔ <strong>المحدِّد لم يعد يبدو كمعادل.</strong> كل جهاز من الأجهزة الخمسة والسبعين يعلن واجهته الخاصة — ما يرسمه فوق عناصر تحكمه، وكم يريد أن يكون عرضه، وأي عناصر تحكمه هي التي تمدّ يدك إليها أولًا. المعادل يرسم استجابته؛ والضاغط يرسم ما ينتزعه، والرقم بجانب الشريط. ⚠ الواجهة التي لا يأخذ هذا البناء قياسها بعد ترسم <strong>لا شيء</strong> بدل شكل مختلق.","changelog.9913ddb063ed":"⛔⛔ <strong>جمّع الأجهزة، وأطفئ مجموعة كاملة بنقطة واحدة.</strong> حدّد بطاقتين أو أكثر في الرف، واضغط <em>تجميع</em>، فتتحرك معًا تحت ترويسة واحدة باسم وسهم طيّ ونقطة بنفسجية واحدة — ممتلئة حين تكون المجموعة مفعّلة، وجوفاء حين تكون مطفأة. ⚠ إطفاء مجموعة ثم تفعيلها مجددًا يعيد إليك بالضبط ما كان لديك، بما في ذلك الجهاز الواحد داخلها الذي تجاوزته عن قصد. ⛔ والمشروع الذي فيه مجموعات ما زال يُفتح على بناء لم يسمع بها قط.","changelog.7742cde966eb":"▸ <strong>لكل بطاقة جهاز تلك النقطة أيضًا</strong>، على أجهزة Oscillate الخاصة وعلى إضافات VST 3 وCLAP المستضافة على السواء.","changelog.70451f4cd15b":"▸ <strong>يمكن سحب الأجهزة من المتصفح إلى الرف</strong>، إلى الفجوة التي تختارها — والفجوات التي لا تقبلها تقول السبب قبل أن تُفلت.","changelog.e5e7c82e5751":"▸ <strong>صوت Windows الحصري، مدفوعًا بالأحداث.</strong> يذهب الجهاز إلى Oscillate وحده ويُتجاوز مسار المزج؛ وتُبلغ شاشة الإعدادات عمّا فُتح فعلًا لا عمّا طُلب. ⚠ أي شيء يرفضه الجهاز يعود إلى تدفق مشترك يعمل بدل الصمت.","changelog.9cc28e987ea4":"أُصلح — نوتات الإضافة نفسها لم يكن لها مكان تذهب إليه","changelog.e38c38ecdf91":"⛔ <strong>النوتات الصادرة عن إضافة مستضافة صار لها الآن بوابة على كل قفزة.</strong> كانت تُستخرج من الإضافة، وتُحمل عبر الأنبوب، وتُدفع إلى الكتلة — والاختبار الوحيد فوق ذلك السلك كان يجري رحلة ذهاب وعودة لقائمة أحداث <strong>فارغة</strong>، فلم يتحقق أي شيء قط من البايتات العشرين التي يشغلها الحدث.","changelog.14fc2e72aca1":"أُضيف — محرّرات الإضافات تُفتح، والمتصفح يعرف على أي مسار أنت","changelog.3a086a46c809":"⛔⛔ <strong>نافذة الإضافة المستضافة الخاصة تُفتح.</strong> يملك صندوق العزل نافذة حقيقية من المستوى الأعلى بمضخة رسائل، فيظهر محرّر VST 3 أو CLAP ويتحرك ويُغلق و<strong>يُعاد فتحه</strong> — ولم يعد إغلاق المحرّر يعني حذف البطاقة لاستعادته. ⚠ الإضافة التي ترفض عرض محرّر صارت تُميَّز عن الإضافة التي انهارت: الرفض لا يجعل شيئًا رماديًا.","changelog.1aed8953980f":"▸ <strong>فئة الإضافات تسرد ما وجده الفاحص</strong>، والإضافات تصل <strong>فور العثور عليها</strong> لا كلها في النهاية. ⚠ لم يعد الفحص يفتح نافذة طرفية لكل إضافة — فأول فحص لمكتبة حقيقية كان يومض بالعشرات منها.","changelog.84b095c699d5":"▸ <strong>ترويسة المسار تقول بكلمة واحدة هل هو MIDI أم صوت.</strong> كانت الشارة رمزًا صغيرًا خلف <code>aria-hidden</code>، لا يخبر قارئ الشاشة بشيء ولا يخبر المنتج الجديد إلا بالقليل؛ والسؤال الذي عليها الإجابة عنه هو <em>أيّ المؤثرات أستطيع وضعها هنا</em>.","changelog.dc9fc03cc83d":"▸ <strong>المتصفح يتبع المسار المحدد.</strong> المسار الصوتي لا يسرد إضافات الآلات أو مؤثرات النوتات، لأنه لا نوتات لديه ليعطيها إياها؛ والفئة المرفقة التي لا تناسب تقول ذلك بدل أن تفرغ. ومؤثرات Oscillate الصوتية الخاصة لا تُخفى أبدًا — فمكانها على نوعَي المسارات كليهما.","changelog.899b576b1610":"▸ <strong>الآلة الثانية تحل محل الأولى</strong>، كما يفعل كل DAW آخر، في حركة واحدة، فضغطة تراجع واحدة تعيد القديمة بإعداداتها.","changelog.ece91873bdd3":"أُصلح — الإضافات المتزامنة مع الإيقاع كانت تُعطى الوقت الخطأ","changelog.940e26b06d02":"⛔⛔ <strong>رأس التشغيل كان مطابقًا؛ والخط الزمني من حوله لم يكن.</strong> تُسلَّم الإضافة المستضافة نقلًا في كل كتلة. كان موضع النبضة فيها حقيقيًا دائمًا — أما الحقول الخمسة بجانبه فكانت ثوابت، و<strong>كلتا صيغتَي الإضافات أعلنتا أن تلك الحقول صالحة</strong>:","changelog.f753d55e9822":"⛔ <strong>موضع العيّنة في VST 3 كان عدّادًا يجري بحرية</strong>، لا رأس التشغيل. كان يتفق معه حتى أول تغيير للموضع ثم يختلف معه إلى الأبد، بمقدار المسافة المقفوزة بالضبط — فالإضافة التي تثق بالساعة الدقيقة على مستوى العيّنة كانت تنجرف عن الشبكة لحظة دخولك التكرار.","changelog.f49a399d635c":"⛔ كان الخط الزمني بالثواني <code>0</code>، بينما قيل لـ CLAP إنه صالح.","changelog.f6279218ddd3":"⛔ كان التكرار بطول صفري، بينما أعلن VST 3 أن حقول الدورة جديرة بالثقة.","changelog.17084eb56c2d":"⛔ كان الميزان دائمًا أربعة على أربعة، فكل ما يتزامن مع المازورات كان خاطئًا في 3/4 أو 7/8؛ وكانت المازورة تدّعي دائمًا أنها تبدأ من أول الأغنية؛ وكانت راية التسجيل دائمًا false.","changelog.9cdee9cc734d":"▸ الخمسة كلها تأتي الآن من النقل نفسه، وموضع العيّنة <strong>مشتق</strong> من رأس التشغيل بدل أن يُعدّ على حدة — الساعتان تتباعدان، والساعة الواحدة لا تستطيع.","changelog.77ad99f84eb0":"أُضيف — Windows يفتح تدفقًا منخفض التأخير، واللوحة تكفّ عن التخمين","changelog.a602943c1b8b":"⛔⛔ <strong>كان السلّم قادرًا على منح درجة لا شيء يستطيع فتحها.</strong> يسأل Oscillate نظام Windows منذ المرحلة 7 عن الدورة التي يعمل بها محرّك الصوت لديه؛ ما لم يكن يستطيعه هو فتح تدفق بتلك الدورة. <code>cpal</code> لا يُجري استدعاء <code>IAudioClient3::InitializeSharedAudioStream</code> ولا يمكن طلب ذلك منه، لذا وُجد <code>ModeReason::LowLatencyNotBuilt</code> ليقول ذلك بصدق بدل أن يعد بتأخير لا يستطيع المنتج تقديمه.","changelog.e7258ea8357b":"▸ <strong>هناك واجهة صوت خلفية ثانية الآن.</strong> <code>MMDeviceEnumerator</code> ▸ <code>IAudioClient3</code> ▸ <code>GetSharedModeEnginePeriod</code> ▸ <code>InitializeSharedAudioStream</code>، مدفوعة بالأحداث، بخيط تصيير خاص بها. على جهاز التطوير تجيب نقطتا النهاية كلتاهما بـ <strong>480 إطارًا عند 48 kHz</strong>. ⚠ كل إخفاق يعود إلى التدفق المشترك العادي ويبقى يُصدر صوتًا: Windows أقدم، أو مشغّل لا يقبل الدورة، أو صيغة مزج ليست عائمة 32 بت.","changelog.861accbc382a":"⛔ <strong>تغيّر معنى سلسلة السبب، فتغيّرت صياغتها في اللغات الثماني عشرة كلها.</strong> كان <code>lowLatencyNotBuilt</code> يعني <em>Oscillate لا يستطيع فعل هذا</em>. وصار يعني <em>هذا الجهاز لم يقبل</em>، وهنا موضع اللوم الصحيح.","changelog.6e9efa7f4ed8":"أُصلح — لوحة الصوت كانت تُبلغ عن تنبؤ بدل حقيقة","changelog.ea32534bf5d0":"⛔⛔ <strong>كانت الإعدادات ▸ الصوت تصف الجهاز بأنه «مشترك» بينما يُعزف عبره تدفق منخفض التأخير.</strong> يقرر السلّم بناءً على ما <em>يُعلنه</em> المشغّل: دورة دنيا من 128 إطارًا أو أفضل عند 48 kHz. ونقاط النهاية في جهاز التطوير تُعلن 480 — ومع ذلك يفتحها <code>InitializeSharedAudioStream</code>.","changelog.b78ee47f67e4":"▶ <strong>اللوحة لم تعد تتنبأ بشأن جهاز مفتوح.</strong> يسجّل المحرّك الدرجة التي أخذها فعلًا، وهي تفوز بلا منازع؛ ويحتفظ السلّم بمهمة صادقة واحدة، هي قول ما سيمنحه على الأرجح جهاز <strong>غير</strong> مفتوح. ⚠ كان إصلاح سابق قد صحّح التنبؤ من المحرّك بدلًا من ذلك، والتصحيح لا يستطيع إلا أن <em>يطرح</em> من تنبؤ لم يصنعه — فالتقط اتجاهًا واحدًا وكان أعمى عن الآخر.","changelog.8870524415ec":"⛔ <strong>والدورة على الشاشة هي الآن المقيسة.</strong> كانت <code>min_period_frames</code>، أي ما يدّعيه المشغّل، معروضة بجانب تدفق يعمل بما منحه <code>InitializeSharedAudioStream</code>. أما للجهاز غير المفتوح فيبقى الرقم المُعلن، حيث يكون تنبؤًا لا ادّعاءً بشأن شيء يعمل.","changelog.e255b62cecd9":"⛔ <strong>الرفض يحتفظ بسببه.</strong> المشغّل الذي لا يعمل بتلك السرعة، وWindows الأقدم من أن يدعم <code>IAudioClient3</code>، والجهاز الذي اختفى، كانت كلها تُختزل في جواب فارغ واحد، وكانت اللوحة تصف الثلاثة بـ <em>«هذا الجهاز لم يفتح تدفقًا منخفض التأخير»</em> — وهذا يرسل أحدهم لتحديث Windows بسبب إعداد في المشغّل.","changelog.5b21975b68bb":"أُصلح — لوحة الصوت كانت تُبلغ عن قرار بدل حقيقة","changelog.2718cbe5591b":"⛔⛔ <strong>بناء الواجهة الخلفية أعاد فتح الكذبة نفسها طابقًا أعلى.</strong> مع صيرورة التدفق منخفض التأخير حقيقيًا، يمنح السلّم تلك الدرجة لأي مشغّل سريع بما يكفي — وحين يفشل الفتح بعد ذلك، يعود المحرّك بهدوء بينما تبقى اللوحة تقرأ <em>«زمن استجابة منخفض، مشترك»</em>. ▸ تُبلغ الإعدادات ▸ الصوت الآن عمّا أخذه المحرّك العامل فعلًا، لا عمّا قُرّر له.","changelog.795cdd276d4e":"أُصلح — كتلة 10 ms مجدولة كأنها محرّر نصوص","changelog.ebec07e8645f":"⛔ <strong>خيط التصيير لم يكن مسجّلًا في MMCSS.</strong> طلب 480 إطارًا من المشغّل لا يشتري شيئًا إن كان الخيط الذي يملؤها قابلًا لأن يُستبق بسحب نافذة. وهو ينضم الآن إلى مهمة <strong>Pro Audio</strong>، وتقرأ بوابة أولوية خيط التصيير نفسه من داخل الاستدعاء — <strong>0 → 15</strong> — بدل أن تأخذها على الثقة.","changelog.c73668bfb50e":"أُضيف — إضافة مستضافة تُصدر صوتًا، لأول مرة","changelog.73ae63bbe1c7":"⛔⛔ <strong>لم تعالج أي إضافة VST 3 أو CLAP كتلة صوت واحدة في هذا المنتج قط.</strong> طوال المرحلتين 6 و7 كانت الإضافة تُفحص وتُحمَّل وتُفعَّل وتُبلغ عن تأخيرها وتكتب ذلك التأخير في المشروع وتفتح نافذة محرّرها — وكل خطوة من ذلك مسوّرة ببوابة وخضراء — بينما تمر الإشارة <strong>متجاوزة إياها مباشرة</strong>. ما كان المنتج يسمعه هو المسار دون إضافته، ونافذة الإضافة مفتوحة أمامه.","changelog.732aab71cf12":"▶ <strong>كان يجب أن تصح أربعة أشياء معًا</strong>: كان <code>DeviceRack</code> يمسك <code>Vec&lt;Box&lt;dyn StockDevice&gt;&gt;</code>؛ وكان الباب الوحيد لـ <code>GraphBuilder</code> هو <code>registry::build</code>؛ وكان <code>Channel::chain</code> مفهرسًا بـ <code>type_id</code> من السجل ليس لدى الإضافة؛ وكان <code>oscillate_app::mixer</code> يفتتح حلقة الإسقاط بـ <code>let DeviceKind::Stock { .. } else { continue }</code>. ⚠ <strong>المرة الثامنة التي يجد فيها هذا المشروع آلية كاملة لا شيء يستدعيها.</strong>","changelog.4d8fc1027169":"⚠ <strong>ما زال <code>oscillate-audio</code> لا يعتمد على <code>oscillate-host</code>، ويجب ألا يعتمد.</strong> يعلن المحرّك <em>شكلًا</em> — <code>rack::ForeignDevice</code> — ويوفّر <code>src-tauri</code>، الذي يعتمد على الاثنين سلفًا، واحدًا منه. ما زال المحرّك لا يستطيع فتح مكتبة مشتركة، وصار الآن يستطيع تشغيل ما فتحه شيء آخر.","changelog.f8700736d0be":"أُضيف — المسار يستطيع عزف خرج إضافة مسار آخر","changelog.3e316a37dda0":"ما يكتبه Live <strong>&quot;MIDI From → track → Plug-in Output&quot;</strong>، ويكتسب <code>InputRouting</code> الحقل <code>notes_from</code>. ⛔ <strong>كان هذا العيب المميِّز في أنقى صوره:</strong> خرج الإضافة المُصدِرة للنوتات كان يستخرجه CLAP، ويستخرجه VST 3، ويحمله <code>AudioMessage::events</code> عائدًا عبر الأنبوب، ويُدفع إلى قائمة المستدعي — خمس مراحل صحيحة — ثم <strong>يسقط</strong>، لأن المحرّك لم يكن فيه أي مكان لوضعه.","changelog.bcc00e454522":"⚠ التوجيه <strong>حافة ترتيب</strong> في تمريرة الترتيب الطوبولوجي نفسها التي ترتّب توجيه الصوت، فتكون النوتات نوتات هذه الكتلة لا السابقة، ومساران يشير كلٌّ منهما إلى الآخر يُرفضان بدل أن يُصيَّرا متأخرين بكتلة إلى الأبد.","changelog.2447de6a9358":"أُضيف — تسجيل MIDI، الذي لم يفعله Oscillate قط","changelog.0bba2bd8bed7":"<code>capture::NoteCapture</code> — بلا أقفال، وبلا تخصيص، ستة عشر ألف نوتة، و<strong>كل واحدة تحمل موضعها بالنبضات الفرعية</strong>، لأن حلقة من الرسائل المجردة كانت ستضع كل نوتات اللقطة على النبضة الأولى. ⛔ تُلتقط <strong>بعد</strong> انضمام النوتات الموجَّهة و<strong>قبل</strong> سلسلة النوتات الخاصة بالمسار، وهذا ما يسجّله كل DAW: الدخل، لا النتيجة بعد المؤثر. الالتقاط بعد السلسلة كان سيخبز المُفكِّك فيها، وإعادة عزف المقطع عبره كانت ستفكّك التفكيك.","changelog.71aaaf954cef":"⚠ تصل اللقطة <strong><code>Operation</code> واحدة</strong> تحمل تعديلين — النمط والمقطع الذي يضعه — فلا يترك التراجع نمطًا خلفه لا شيء يعزفه.","changelog.44edd735e062":"أُضيف — الإعدادات ▸ الصوت، والسلّم يقرر على أساس الحقيقة","changelog.26faed29b702":"⛔ <strong>رسم ذلك التبويب جسمًا فارغًا طوال ثماني مراحل</strong>، بينما كانت <code>device::enumerate</code> و<code>device::resolve</code> و<code>negotiate</code> و<code>Granted</code> و<code>ModeReason</code> جالسة في المحرّك <strong>بلا مستدعٍ في أي مكان خارج <code>device.rs</code></strong> — الحالة التاسعة من العيب نفسه. تسرد اللوحة المخارج، وتختار واحدًا، وتختار كم يُؤخذ من الجهاز، و<strong>تسمّي ما مُنح مع سببه</strong>، لأن المفاضلة بين التأخير ومشاركة الجهاز قرار المنتج.","changelog.3eff9d3dc578":"<code>engineperiod::smallest_period</code> يسأل <code>IAudioClient3::GetSharedModeEnginePeriod</code> عبر <code>windows-rs</code>، فيقرر السلّم بناءً على دورة المحرّك الحقيقية لا الحد الأدنى للمخزن المؤقت الذي يُعلنه المشغّل. ⛔ <strong>وجد ذلك عيبين حقيقيين</strong>: الصوت المدمج في هذا الجهاز يُعلن حدًّا أدنى هو <strong>صفر</strong>، فقرأه <code>negotiate</code> على أنه <code>0 &lt;= 128</code> ومنح درجة التأخير المنخفض بناءً عليه؛ وكانت اللوحة ستُبلغ عن <em>«زمن استجابة منخفض، مشترك»</em> فوق تدفق مشترك عادي، لأن <code>InitializeSharedAudioStream</code> غير مبني. كلاهما مُصلح، والثاني صار الآن <code>ModeReason::LowLatencyNotBuilt</code> — جوابًا صادقًا بدل كذبة على شاشة إعدادات المنتج نفسه.","changelog.db88097b77e2":"أُضيف — المستعرض، وخمس صيغ تصدير، ومعاينة المتصفح","changelog.409208576c1a":"مستعرض الملفات مع شريط نقل المعاينة، ومعاينات مقاطع MIDI، ووسوم الآلات على محورين، والتخزين المؤقت للموجات والفهرسة؛ والتصدير إلى WAV وAIFF وFLAC وOgg وMP3، للماستر والمسارات المنفصلة وMIDI، مع لوحة إعدادات وتقدّم صادق.","changelog.a7939e4436cb":"قِيس — قرار المضيّ أو عدمه في تطبيق الويب، قبل أوانه بأربع درجات","changelog.93f8bbf3e20c":"⛔ <strong>قُدّم من <code>v2.0.0</code> بناءً على حجة المالك</strong>، وكانت صحيحة: الاكتشاف عند <code>v2.0.0</code> يعني الاكتشاف بعد أن تكون كل ميزة قد صُمّمت مرتين. السؤالان كلاهما مُجابان في <code>web/spike/</code>.","changelog.799111b932af":"✅ <strong>تُترجَم معالجة الإشارة إلى <code>wasm32-unknown-unknown</code> من المحاولة الأولى</strong>، بلا أي تغيير في المصدر — بما في ذلك <code>oscillate-synth</code> والمكتبة المصنعية ذات الـ 248 آلة — وبيانو كبير واحد منمذج بتعدد الأصوات الكامل يكلّف نحو <strong>11% من كتلة بطول 128 إطارًا</strong>.","changelog.7ead2fc63ed7":"✅ <strong>تستطيع إضافة VST 3 بلوغ تبويب متصفح عبر الجسر الأصلي</strong>: رحلة الذهاب والعودة عبر الحلقة المحلية <strong>p99 0.049 ms</strong>، أي نحو 2% من كتلة.","changelog.1f8fdb6a96c2":"⛔ <strong>لكنها لا تبدو بالصوت نفسه.</strong> يختلف WASM والأصلي في الكتلة الأولى بمقدار 2.4e-5 ويستقران عند نحو <strong>−60 dBFS</strong>، لأن 551 استدعاءً لدوال متسامية في كل كتلة يحسبها منفذ <code>libm</code> الخاص بـ Rust على wasm ويحسبها MSVC CRT في الأصلي. ▶ العلاج محدود — حزمة <code>libm</code> على الجانبين — وهو يحرّك خرج سطح المكتب أيضًا، فهو قرار لا رقعة.","changelog.09954837c4f4":"⚠ <strong>دخلت المرحلتان 6 و7 كلتاهما إلى <code>main</code> في 2026-08-29</strong>، بإيداعَي الدمج <code>43785ad</code> و<code>7bb1ea1</code>. وهما معًا درجة <code>v0.3.0</code> — محطة عمل تستضيف إضافاتك <em>ولها</em> إضافاتها الخاصة — والدرجة <strong>لم تُوسم بعد</strong>: تريد <code>REL-0.3.0</code>، بناء الإصدار من طرف لطرف، أولًا. و<code>v0.2.0</code> و<code>v0.2.5</code> ما زالتا دون وسم خلفها.","changelog.9b1dcbd5fbd5":"أُضيف — الآلات الـ 248 كلها، وحزم الطبول، وFreally MixSir","changelog.52be750b9006":"⛔⛔ <strong>كانت القائمة 197، والسبب يستحق المعرفة.</strong> كانت <strong>تمشي</strong> في <code>Kind::ALL</code> الخاص بكل محرّك، فلم يكن بوسعها أبدًا أن ترى إلا الآلات التي <em>يسمّيها</em> محرّك منمذج. <code>SubBass</code> و<code>SawLead</code> و<code>WarmPad</code> و<code>Riser</code> و<code>VoxChop</code> وست وأربعون أخرى معرَّفة بـ <strong>رقعة</strong> لا بفهرس نوع — ولم يكن لأي مشي أن يبلغ واحدة منها. هذه هي الفجوة كلها بين 197 و248.","changelog.40218bb7cac0":"⛔ <strong>وفهرس النوع ليس صوتًا.</strong> تثبيت <code>(Bowed, 2)</code> كان يعطي الرقعة <em>الافتراضية</em> لمحرّك الأقواس مع اختيار <code>Cello</code> — لا الـ Cello الذي يسمعه المنتج في Freally MIDI Master، وهو <code>generator::generate</code> → <code>articulation::apply</code> → <code>tone::apply</code>. منتجان، الاسم نفسه، صوت مختلف، ولا شيء يفشل.","changelog.5e270075e2b0":"لذا فإن <code>factory/</code> هو الفهرس، <strong>مستوردًا</strong>: سبعة ملفات بايتًا ببايت من وحدة الإعدادات المسبقة الخاصة بالإضافة، إضافة إلى <code>preset.rs</code> مشتق من الشريحة في <code>mod.rs</code> الخاص بها التي لا تحمل تصريحات وحدات. وبوابة تشعّب تعيد اشتقاق تلك الشريحة وتفشل مسمّيةً السطر. أما <code>style_sound</code> و<code>palette</code> و<code>user</code> فبقيت خلفها — نصف الفنانين/المنتجين — واختبار رابع يفشل إن ظهر أحدها يومًا.","changelog.3de65c2ec7b1":"⚠ <strong>حُذفت نسختان محليتان مكررتان بدل إبقائهما بجانب الاستيراد.</strong> <code>natural_note</code> و<code>shape</code> لكل عائلة في خبّاز الضربات الأحادية كانا كلاهما نسختين أخشن من <code>audition_note()</code> و<code>render_time()</code>، اللتين يحملهما التصنيف سلفًا <strong>لكل آلة</strong>.","changelog.3a4683be12b7":"<strong>تعديل الطبقة، ولوحة المفاتيح، ورف الصوت.</strong> يمكن تعديل طبقة 91 من الـ 248 ولا يمكن ذلك في 157، والقسمة تقطع العائلات مباشرة — الإيقاعيات وحدها 11 مع و82 بدون — لذا <strong>يرشّح</strong> المتصفح بزر حبّة ولا يستعمل المجلدات أبدًا. وكلا نصفَي السؤال مُجاب: الحبّة للبحث، وعلامة SVG مضمّنة على كل صف للتصفح. (ليست <code>∿</code>، U+223F، الغائبة عن Noto Sans والتي تُرسم صندوقًا فارغًا.)","changelog.542c14231314":"مفاتيح لوحة المفاتيح الافتراضية موسومة بتباين البيانو الحقيقي — المفاتيح البيضاء تحمل وسومًا داكنة، والسوداء فاتحة — عبر <code>--color-text</code> لا عبر قيمة حرفية، وهذا ما يجعلها تصمد في السمتين كلتيهما. وهي محفوظة ومفتوحة افتراضيًا.","changelog.327f4ea52638":"يحمل رف الصوت فوقها كلمات الإضافة نفسها — <strong>غرفة، حرارة، صدى، كسب، توزيع، تعديل الطبقة</strong> — مأخوذة من فهارسها بلغاتها الثماني عشرة كلها، لأن <em>«برنامج DAW يسمّيه 'الدفع' بينما تسمّيه الإضافة 'حرارة' هو اسمان لعنصر تحكم واحد»</em>. ⛔ لا يُرسم على الإطلاق على آلة لا يمكن تعديل طبقتها. ⚠ «كسب» و«توزيع» هما عنصرا <strong>المسار</strong>، لا زوج ثانٍ.","changelog.9fde2df9f578":"<strong>حزم الطبول.</strong> أحد عشر طقمًا و407 ضربات أحادية بترخيص CC0، مضمّنة وقابلة للتصفح. ⛔ نُسخ الصوت ولم يُنسخ المولّد: <code>kitgen</code> يسحب كل عيّنة من تيار <strong>ChaCha8</strong> بينما <code>rng</code> في Oscillate هو <strong>SplitMix64</strong>، فالمولّد المنقول كان سيشحن مكتبة طبول مختلفة تحت الأسماء الأحد عشر نفسها.","changelog.36f9d92b4cee":"<strong>Freally MixSir</strong> — اقرن هاتفًا برمز QR، وأرسل إليه المشروع الموزَّع مسارات منفصلة، ووازنه بمقابض مرسومة، ونزّل المزيج أو أي مسار بصيغة WAV أو MP3. ⛔ كل ما بعد وصول المسارات المنفصلة محلي: المازج والتصدير يعملان والشبكة مطفأة، وهذا هو بيت القصيد — <em>«بيت صديقك شبكة مختلفة. البث الحيّ يموت عند الباب الأمامي. والملف لا يموت.»</em>","changelog.94365ba1d670":"⛔ <strong>سرّ الجلسة ليس اختياريًا.</strong> واحد لكل اقتران، ولا شيء يُحفظ، وخمس محاولات فاشلة تقتل الاقتران، ورفض واحد لا يقول شيئًا عن الجزء الخاطئ — لأن الرسالة التي تميّز بين «لا سر» و«سر خاطئ» تخبر المهاجم أيهما حقق.","changelog.083b2dd09b8a":"⛔ <strong>كانت كل بطاقة جهاز مرفق موسومة بمعرّفها.</strong> كان الرف يقرأ <code>whetstone</code> و<code>vise</code> و<code>factory.cello</code> — معرّف داخلي في المكان الوحيد الذي ينظر إليه المنتج ليرى ما على مساره.","changelog.6d162dd890d4":"⛔ <strong>الآلات الـ 248 لم تكن لتملك أي مقابض على بطاقاتها على الإطلاق.</strong> فهي ليست مدخلات في <code>registry::ALL</code> وتُحَلّ عبر بحث ثانٍ لم يكن مسار البطاقة يجريه.","changelog.8ac445d35eda":"⛔ <strong>مقبض على بطاقة كان يحرّك المعامل الخطأ.</strong> مقابض البطاقة تتخطى الخيارات، فموضع المقبض على البطاقة ليس فهرسه في قائمة الجهاز — وعلى أي جهاز تُفتح لوحته بمنتقي وضع، كان كل مقبض على البطاقة يحرّك عنصر التحكم الذي فوق العنصر الموسوم به. بصمت.","changelog.a56a71232f82":"⛔ <strong>كانت وصفة «المشروع ← مازج قابل للتصيير» مقسومة.</strong> الحلقة التي توصل كل قناة بخانة تدفقها كانت تعيش داخل أمر Tauri واحد ولا مكان غيره، فكل ما يبني مازجًا دون المرور به كان يُصيّر <strong>صمتًا</strong>.","changelog.7dfa8f74186b":"<strong>عرض التوزيع ينفصل في نافذة خاصة به.</strong> ⚠ الفصل والإخفاء شيئان مختلفان: إخفاؤه سيترك DAW بلا مكان يضع فيه مقطعًا، لذا ما زال بلا زر في شريط العنوان — لكن المنتج الذي لديه شاشتان يريد الخط الزمني على الكبيرة.","changelog.acbb6415e329":"<strong>انخفض <code>cargo test --workspace</code> من 417 s إلى 166 s</strong>، وخبز الضربات الأحادية من 168 s إلى 15 s، دون تخطي أي شيء ودون تقسيم.","changelog.27f0c63ca33a":"أُضيف — تستطيع سماع جهاز قبل أن تستعمله","changelog.9e4c221fc50d":"⛔⛔ <strong>لم يكن في Oscillate ما يستطيع إسماع جهاز ليس على مسار سلفًا.</strong> كان المتصفح يسرد خمسة وسبعين منها باسم موحٍ وسطر من الإنجليزية البسيطة، والاختيار بين <code>Crucible</code> و<code>Muster</code> كان يعني إضافة أحدهما إلى مسار، ورسم نوتة، والضغط على التشغيل، والاستماع، وحذفه، ثم فعل الشيء نفسه مع الآخر.","changelog.5804f25b08c9":"▶ <strong>مشغّل معاينة، تحت مستعرض الملفات.</strong> انقر أحد أجهزة Oscillate الخاصة فيعزف عرضه الخاص؛ واختر مجلدًا وانقر عيّنة فيعزفها. مشغّل واحد بدل شريط نقل لكل صف: صوت واحد فقط يمكن أن يكون قيد الاستماع في كل مرة، وللموجة مكان تعيش فيه.","changelog.40cbef0ecde9":"<strong>موجة، للآلات والعيّنات على السواء</strong> — الحد الأدنى والأقصى لكل عمود بدل كل عيّنة رقم N، فيصمد الحدّ العابر في ضربة الطبل عند رسمه. <strong>الأرضية خلف الجزء المعزوف يتغير لونها أثناء سيره</strong>، مع رأس تشغيل وقراءة <strong>الثواني المنقضية / الإجمالية</strong>.","changelog.f3f0517ac936":"<strong>تشغيل وإيقاف، وتكرار يمكن إطفاؤه مرة أخرى، و← / → للخلف والأمام.</strong> العكس هو الاتجاه الذي يمشي فيه فهرس المصدر، لا مخزن مؤقت ثانٍ ولا مسار شيفرة ثانٍ.","changelog.884d06fa9f2c":"<strong>نوتة وشدة وطول لكل آلة</strong>، مقيسة لا مخمّنة: <code>Crucible</code> و<code>Muster</code> يمسكان C3 أكثر من ثانيتين لأن رقعة جدول الموجات وفرقة من اثني عشر عازفًا تظلان في حركة عند الثانية الأولى؛ و<code>Skin</code> يُمسك 40 ms لأن الطبلة الكبيرة كلها ذيل؛ و<code>Sideband</code> يُضرب ويُطلق ويُترك ليرنّ.","changelog.8d682a63aee9":"⚠ <strong>خمس من الآلات الإحدى عشرة تقول لماذا لا تستطيع.</strong> <code>Flint</code> و<code>Armory</code> و<code>Bench</code> و<code>Hammer</code> و<code>Filings</code> مُعايِنات عيّنات تبقى صامتة حتى يُحمَّل فيها ملف، لذا تُظهر تلك الجملة بدل زر لا يعزف شيئًا. ⛔ وبوابة تحرس الخط: كل آلة مبنية إما تعلن استماعًا تجريبيًا وإما تعلن خانات عيّنات.","changelog.151407842cb1":"⚠ <strong>المشغّل صوت يُمزج بعد الرسم البياني</strong>، على نهج <code>click.rs</code>. يصدح والنقل متوقف، ولا يحتاج إلى إعادة بناء الرسم البياني، ولا يخصّص أبدًا — يُصيَّر المخزن المؤقت في التطبيق ويُسلَّم إلى الأسفل، والمخزن الذي يحل محله <strong>يُركن لخيط التطبيق بدل أن يُحرَّر</strong>، لأن التحرير توأم التخصيص. بوابة خيط الصوت تغطيه، ورُئيت تفشل مع <code>deallocations: 1</code>.","changelog.e7fc9384962d":"أُضيف — آلات Freally Secretarium، ومعاينات هي مجرد قراءة ملفات","changelog.356af9b34f95":"⛔⛔ <strong>كان المتصفح يسرد إحدى عشرة آلة مختلقة ولا شيء من الآلات الحقيقية.</strong> تعليمات المالك، قيلت أربع مرات: <em>«كان من المفترض أن تكون لديّ الآلات نفسها كلها التي في Freally MIDI Master»</em>، <em>«وFreally Secretarium»</em>، <em>«تلك الآلات، لا آلات مختلقة»</em>.","changelog.88620eb11d8a":"▶ **<code>synth/</code> في مساحة العمل هذه <em>هو</em> <code>havoc_dsp</code> الخاص بـ Secretarium<strong> — وحدةً وحدة — وكانت آلاته الـ </strong>197<strong> كلها مترجمة سلفًا داخل Oscillate. لم يكن شيء يسردها. كانت <code>Quiver</code> و<code>Muster</code> و<code>Crucible</code> تظهر حيث كان ينبغي أن تكون <code>Violin</code> و<code>Tuba</code> و<code>Grand Piano</code> و<code>Rhodes EP</code> و<code>Accordion</code> وأطقم 808/909/707/606. ⚠ </strong>الحالة السادسة في هذا المشروع لآلية صحيحة لا شيء يستدعيها**، وهي أكبرها بفارق كبير.","changelog.9d0068c6cd97":"⚠ <strong>الفهرس لا يثبّت أي اسم في الشيفرة.</strong> يمشي <code>oscillate_dsp::secretarium</code> في <code>Kind::ALL</code> الخاص بكل محرّك ويسأله عن <code>name()</code>، فهو <em>بحكم بنائه</em> قائمة Secretarium نفسها ولا يمكن أن ينجرف.","changelog.527bd770093f":"أُصلح — النقر على ▶ كان يجمّد التطبيق تسع ثوانٍ","changelog.7cfc5be2b1d8":"⛔⛔ <strong>مقيسًا، في بناء الإصدار، عند 48 kHz:</strong>","changelog.00ab2993d58b":"▶ <strong>كل <code>#[tauri::command]</code> في هذا التطبيق متزامن، والأمر المتزامن يعمل على خيط الواجهة.</strong> كان <code>preview_device</code> يبني آلة منمذجة كاملة ويُصيّر ثوانيَ من الصوت هناك، عند كل نقرة — فالنقر على <code>Muster</code> كان يجمّد التطبيق تسع ثوانٍ، والنقر مرة أخرى يضع تسعًا أخرى في الطابور. هذا سبب واحد لبلاغين من المالك: <em>«الآلات تُحمَّل ببطء شديد»</em> و<em>«أظل أنقر الزر لتشغيلها فينهار في النهاية»</em>.","changelog.f75de40a46cd":"⛔ <strong>الإصلاح هو تصميم المالك نفسه</strong>: <em>«يجب أن يحمّل مقطعًا صوتيًا للضربة الأحادية فقط، لا الآلة كلها إلا إذا أُضيفت إلى عرض التوزيع»</em>. يُصيّر <code>bake-oneshots</code> الـ 197 كلها وقت البناء — <strong>كلٌّ عند النوتة التي تصدح فيها تلك الآلة فعلًا</strong>، من مداها الحقيقي: <code>Tuba</code> عند C2، و<code>Piccolo</code> عند C6، و<code>Violin</code> عند G4، و<code>Double Bass</code> عند E2. والإيقاعيات غير محددة الطبقة تُعلَّم بذلك بدل أن تُعطى مفتاحًا زائفًا.","changelog.8d6da56f85ca":"<strong>197 مقطعًا، 22.6 MB، خُبزت في 110 s</strong> — أحادية القناة بعمق 16 بت، بمستوى موحّد عند −1 dBFS فتقارن المقارنة بين آلتين صوتيهما لا كسبيهما، ومقصوصة حيث يتوقف الصوت فعلًا لا عند ميزانية مخمّنة.","changelog.94c1bdbaa43a":"<strong>المعاينة الآن قراءة ملف: المتوسط 0.19 ms، والأسوأ 0.5 ms.</strong> في الملف التنفيذي المشحون عبر CDP: تظهر قائمة الـ 197 في <strong>134 ms</strong>، وتُعايَن <code>Violin</code> و<code>Tuba</code> و<code>Grand Piano</code> في <strong>75 / 45 / 51 ms</strong>.","changelog.2dc07d5f1557":"⚠ بوابتان تحرسانه: لكل آلة مقطع وليس أيٌّ منها صامتًا، وقراءة أحدها تبقى تحت 50 ms.","changelog.c5ee9fe2006c":"⛔ <strong>وكادت المقاطع تُشحن بعيدة المنال.</strong> تعريفها بـ <code>../assets/oneshots</code> وضع مجلدًا حرفيًا اسمه <strong><code>_up_</code></strong> في الشجرة المثبّتة — <code>Freally Oscillate\\_up_\\assets\\oneshots\\</code> — بينما كان التطبيق يحلّ <code>assets/oneshots</code>. نجح كل تشغيل تطويري، لأن بديلًا من مساحة العمل كان يجيب؛ أما البناء <em>المثبّت</em> فلم يكن ليجد شيئًا وكان سيعزف صمتًا للـ 197 كلها. ⚠ <strong>وُجد باستخراج MSI وتشغيل التخطيط المستخرج مع إخفاء نسخة المصدر</strong>، وهو الترتيب الوحيد الذي لا يستطيع فيه البديل إنقاذ الخطأ. يكتب الخبّاز الآن داخل <code>src-tauri/</code>، فلا دخل لأي <code>../</code>.","changelog.f4ddb6130986":"أُصلح — الضغط المتكرر على <em>إضافة</em> كان يُطلق عملية إضافة لكل نقرة","changelog.a8ec7142d4cc":"⛔ بلاغ المالك: <em>«إذا أضفت إضافة مرارًا وتكرارًا بسرعة كبيرة ينهار التطبيق، يجب ألا يحاول تحميلها 15 مرة بسرعة كبيرة في مسار الصوت/MIDI نفسه ثم ينهار»</em>. كل إضافة تبدأ صندوق عزل <code>oscillate-hostproc</code> وتنتظره؛ وخمس عشرة نقرة كانت خمس عشرة عملية تتسابق على خيط الواجهة. ⚠ <strong>تُسقط، لا توضع في طابور</strong> — فالمنتج الذي يتكئ على الزر يريد جهازًا إضافيًا واحدًا، لا خمسة عشر.","changelog.7dda4841cc1a":"أُضيف — حدّد آلة واعزفها بـ ← و→","changelog.82c24a2d7b61":"⚠ القائمة صندوق قائمة: النقر على اسم يحدده، و<strong>→ يعزفه إلى الأمام و← إلى الخلف</strong>. ⛔ يُضبط الاتجاه <em>قبل</em> تحميل المقطع — فالترتيب الآخر يعزف الضغطة الأولى إلى الأمام ولا يعكس إلا عند الثانية، وهذا يبدو كضغطة مفتاح ضائعة لا كخطأ.","changelog.fafc2a09973e":"أُضيف — مستعرض الملفات صار متصفحًا الآن، مرتّبًا كما يُرتَّب متصفح Ableton","changelog.edb9f6a2c94a":"⛔⛔ <strong>كان قائمة مسطّحة، والقائمة المسطّحة لخمسة وسبعين جهازًا جدار.</strong> تعليمات المالك: <em>«يجب أن تكون فيه قائمة مثل الإضافات، الآلات، ثم زر لإضافة مجلد … تمامًا كما هو مرتّب متصفح Ableton»</em>.","changelog.5e9e61c53217":"▶ <strong>شاشة رئيسية من الأماكن</strong>، لكلٍّ منها <code>›</code>: <strong>الآلات</strong>، <strong>مؤثرات صوتية</strong>، <strong>مؤثرات MIDI</strong>، <strong>الإضافات</strong>. انقر أحدها فيسرد ما فيه. وتحتها <strong>اختر مجلدًا</strong>، وتحت ذلك المجلدات التي أضفتها، <strong>بأسمائها فقط</strong> — انقر اسمًا فتحصل على شجرة ذلك المجلد: الجذر والمجلدات الفرعية والعيّنات وملفات MIDI.","changelog.099ce0f7d765":"<strong>← و→ فوق القائمة للتنقل</strong>، لا للتشغيل. الرجوع يعود إلى الفئات خطوة خطوة؛ والتقدم يعيد تتبّع المسار، أو — حين لا يكون شيء أمامك — يفتح المجلد الذي كنت فيه أخيرًا. ⚠ <strong>سجلّ، لا راية وضع</strong>: القيمة المنطقية <code>showingCategories</code> لا تستطيع الإجابة عن <em>«إلى الأمام نحو آخر مجلد كنت فيه»</em>، وهذا هو الغرض كله من السهم.","changelog.79957fde35e2":"<strong>المرشّح يبحث في كل ما تنظر إليه</strong>، ويبحث فيما <em>هو</em> الجهاز وفي اسمه أيضًا — <code>compressor</code> تجد <code>Vise</code>، الذي لا يقول اسمه شيئًا عنه.","changelog.e8b3a1a389e9":"<strong><code>Plugins</code> تعني إضافات شخص آخر</strong>، كما في Ableton. أجهزة Oscillate الخاصة الخمسة والسبعون موجودة في فهرس الفحص — وهذا ما جعل القائمة قابلة للبلوغ أصلًا — وتُرشَّح خارجًا هنا، وإلا لظهر كل واحد منها مرتين ولكانت <em>الإضافات</em> المكان الوحيد الذي يحتاجه أي أحد.","changelog.0047f4f33bdc":"<strong>مشغّل المعاينة يبقى مثبّتًا تحت المتصفح</strong>، كما طُلب.","changelog.4f2676f1a739":"أُصلح — ثلاثة عيوب أدخلتها إعادة كتابة المتصفح، كلها وُجدت بقيادة البناء","changelog.f49547b29542":"⛔ <strong>قيل لمُعايِن العيّنات إنه لا صوت له.</strong> كان <code>previewDevice</code> يختار رفضه من قائمة كانت اللوحة القديمة تجلبها عند التركيب؛ واللوحة المعادة كتابتها لم تجلبها، فبقيت القائمة فارغة وسقط كل مُعايِن عيّنات إلى <em>«هذا الجهاز ليس له صوت خاص به»</em>. ▶ <strong>المرة الرابعة في هذا المشروع التي تعيش فيها آلية أطول من مستدعيها الوحيد</strong>، والثالثة داخل هذه الميزة وحدها. الصف يحمل الجواب سلفًا، فصار الرفض يأتي من الصف ولا توجد قائمة ثانية يمكن أن تفقد التوافق.","changelog.662d079a371c":"⛔ <strong>صوّرت الجولة الإرشادية رفضًا تحت تعليق يعد بموجة.</strong> نقرت أول ▶ في القائمة، وهو <code>Armory</code> — مُعايِن عيّنات. ستة من الخمسة والسبعين تصدح دون مساعدة؛ والـ ▶ يقول الآن أيها هو في <code>data-can-hear</code>، والجولة الإرشادية تطلب واحدًا يصدح.","changelog.6d5cf6780d7a":"⛔ <strong>لم تكن هناك بوابة تحرس قاعدة المالك نفسه بشأن الطول.</strong> <em>«ليس كضربة أحادية من ثانية واحدة، بل كضربة أحادية من 2-4 ثوانٍ لتستطيع سماع الفرقة أو الكمان وهو يعزف»</em> — وكان الفحص الوحيد نطاق <code>400..=6_000</code> على رقم في السجل، يقبل بسعادة كمانًا مقطوعًا عند 400 ms، لأن المدة المُعلنة لا تقول شيئًا عمّا إذا كان <strong>الصوت</strong> قد انتهى. بوابتان تصغيان الآن بدلًا من ذلك:","changelog.67673c6c454c":"<code>no_instrument_is_cut_off_while_it_is_still_sounding</code> يُصيّر كل استماع تجريبي ويقيس العُشر الأخير مقابل ذروته الخاصة — نسبةً، لأن ثلاثة من هذه الستة تتباعد بعشرات الديسيبلات في المستوى المطلق، والعتبة المطلقة لن تفعل إلا إعادة قياس <em>ذلك</em> العيب. البقاء ضمن 30 dB من الذروة عند النهاية يعني أن المخزن المؤقت ينتهي في منتصف نوتة.","changelog.9dba8e1945f1":"<code>an_instrument_that_holds_a_note_demonstrates_for_at_least_two_seconds</code> يطلب من ثانيتين إلى أربع من أي جهاز يمسك نوتته ثانية — حالة الكمان والنحاسيات التي سمّاها المالك — بينما يترك الهاي هات المضروب قصيرًا. كلاهما رُئي يفشل: <code>crucible</code> المقطوع عند 1.5 s يُبلغ <em>«ما زال يصدح عند −27.9 dB تحت ذروته»</em>.","changelog.3ac136922655":"أُصلح — مسار من الصفحة بلغ القرص، والبوابة لم تستطع رؤيته","changelog.d83b8e757dd9":"⛔⛔ <strong>كان <code>preview_file</code> يأخذ مسارًا من عرض الويب ويفتحه</strong>، وبقيت <code>no_command_opens_a_path_from_the_page</code> <strong>خضراء</strong> فوقه. كان <code>Source::open(</code> في قائمة علامات تلك البوابة؛ والمعاينة تفكّ الترميز بمعدل الجلسة فتستدعي <strong><code>Source::open_at</code></strong>، الذي لم يطابقه المدخل.","changelog.f6e0367699b1":"▶ <strong>هذا بالضبط ما يتنبأ به تعليق القائمة نفسه</strong> حين يحصل استدعاء على اسم جديد ولا تُخبَر القائمة — وحدث مرتين في تغيير واحد، لأن <code>preview_browse</code> يبلغ <code>read_dir</code> عبر <code>listing_for</code> خاص ولم يكن يحتوي على علامة أيضًا. الشكل نفسه لـ <code>place_recording</code> قبله.","changelog.81f850dd8839":"⚠ صارت البوابة تعرف <code>Source::open_at(</code> و<code>read_dir(</code> و<code>listing_for(</code>، وتتحقق من أنها تختار <strong>خمسة</strong> أوامر تأخذ مسارات لا ثلاثة. رُئيت تفشل: إزالة الفحص تجعلها تقول <em>«القائمة ليست البوابة؛ الاستدعاء هو البوابة.»</em>","changelog.2d054f75b71a":"⛔ <strong>الفحص نفسه هو <code>oscillate_app::preview::Roots</code></strong> — المجلدات التي اختارها المنتج في <strong>نافذة حوار أصلية</strong>، لا تستطيع الصفحة فتحها ولا الاختيار فيها نيابة عن أحد. الحجة نفسها التي يقدّمها <code>Session::knows</code> بشأن المشروع. يوحّد المسارات قبل المقارنة، فالخروج بـ <code>../</code> من الشجرة، والرابط الرمزي إلى خارج الشجرة، والمجلد الشقيق الذي يتشارك بادئة الاسم، كلها مرفوضة، لكلٍّ منها اختبار.","changelog.eab49295e87c":"⚠ وُجد ولم يُصلح — أصوات الإيقاعيات المنمذجة غير معايَرة المستوى","changelog.1db39a57f0b2":"⛔ <strong>كان تصيير عرض توضيحي أول شيء في هذا المشروع يقيس مستوى خرج آلة</strong>، وثلاثة أجهزة منحرفة بشدة. في إعداداتها الافتراضية، عند 48 kHz:","changelog.8dbc3e72e325":"⚠ <strong>تعديلات <code>Level</code> مطبّقة وتعمل</strong> — <code>Skin</code> افتراضيه −6 dB و<code>Bronze</code> −9. الأصوات المنمذجة تحتها ببساطة غير معايَرة، لا مقابل المستوى الكامل ولا مقابل بعضها. على مسار يقصّ <code>Skin</code> بشدة ولا يُسمع <code>Sideband</code> بجانبه.","changelog.01769f9570bb":"⛔ <strong>لم يُصلح هنا عن قصد.</strong> إعادة ضبط ثلاثة أجهزة مشحونة تغيّر كل مشروع يستعملها سلفًا، فهو قرار المالك لا تغيير صامت يُجرى أثناء إضافة ميزة للمتصفح. المعاينات موحّدة المستوى — وهذا صحيح للمقارنة على أي حال، وهو ما تفعله كل مكتبة عيّنات — و<code>Rendered::raw_peak</code> يحتفظ بالرقم الحقيقي فيبقى العيب قابلًا للقياس. و<code>the_percussion_voices_are_not_level_calibrated_and_this_says_so</code> يتحقق من الحالة الراهنة ويفشل يوم يعايرها أحد، وهذا هو التذكير بتحديث هذا الجدول.","changelog.d14d01c626ec":"تغيّر — المولّدات هي مولّدات Freally MIDI Master، لا Oscillate (المرحلة 8)","changelog.dc81dfbc9b4f":"⛔ <strong>لا يحمل Oscillate أي شيفرة توليد، وحزمة <code>engine</code> اختفت.</strong> كانت عنصرًا نائبًا فارغًا في مساحة العمل منذ أول إيداع، تنتظر أن يملأها استيراد لن يحدث بعد الآن.","changelog.e3f68ceb379a":"▶ يُشحن Freally MIDI Master بدلًا من ذلك <strong>إضافةً مستضافة مرفقة</strong>، فتصل مولّداته عبر حدود الإضافات التي بنتها المرحلة 6 سلفًا — VST 3 وCLAP، خارج العملية.","changelog.7fc1c070e5b4":"⚠ <strong>لماذا يتفوق مصدر حقيقة واحد على بناء مكتفٍ بذاته هنا.</strong> كان ضمّ المحرّك سيعني نسخة بايتًا ببايت تُمسك في مكانها ببوابة تشعّب، وإعادة مزامنة كلما تحرك المصدر الأصلي، ومصدر منتج آخر يعيش في مستودعين. على المنتجين أن يتفقا — البذرة نفسها والأسلوب نفسه يجب أن يعطيا التوزيع نفسه في كليهما — والنسخة هي الشيء الذي يكفّ في النهاية عن الاتفاق.","changelog.2048fc009c6c":"أُضيف — أجهزة Oscillate الخاصة (المرحلة 7)","changelog.f5822af61c3c":"⛔⛔ <strong>تسعة وستون من الخمسة والسبعين مبنية</strong>، منها المؤثرات الأساسية الثمانية والعشرون كلها، وكل أجهزة النوتات الستة عشر، وتسع آلات. ⚠ ستة ما زالت مُعلنة فقط، وكل واحد منها معطّل بسبب وصلة لا بسبب معالجة الإشارة — وهي مسرودة بأسمائها تحت <em>ما لم يُبنَ</em> أدناه، مع ما ينتظره كلٌّ منها.","changelog.668c497ed943":"⛔ <strong>الأجهزة المبنية منذ آخر مرة قرأت فيها القائمة أربعة وخمسين</strong>، والوصلات التي فرضها كلٌّ منها:","changelog.8e557db4dbd0":"<strong><code>Filings</code></strong> — سحابة حبيبات من مقطع واحد، أربع وستون حبيبة من مجمّع مخصّص مسبقًا. وجدت بواباته عيبين قبل شحنه: كانت أغلفة الحبيبات المجموعة بارتفاع <code>Density × Grain Size</code>، فتكثيف السحابة من أربعين حبيبة في الثانية إلى مئتين كان يكسب 14 dB؛ والحبيبة المرشوشة بعد نهاية مصدرها كانت تصمت عند الغلاف الكامل، مقيسة أخفض بـ 23 dB.","changelog.50a4eea3576b":"<strong><code>Armory</code></strong> — ثماني مناطق من ثمانية تناوبات دائرية فوق جدول مسطّح 128×128 للمفتاح مقابل الشدة يُبنى خارج خيط الصوت، فتكلّف النوتة فهرسًا واحدًا بلا أي حساب. قدرة متساوية عند الوصلات، لأن منطقتين في عيّنة متعددة تسجيلان مختلفان، والتلاشي المتقاطع الخطي بين مصدرين غير مترابطين ينخفض 3 dB. واكتسب مجمّع الأصوات من أجله غلاف مرشّح حقيقيًا.","changelog.25ae013f0dd8":"<strong><code>Sift</code></strong> — إزالة ضجيج طيفية عند 4096/1024، وهذا عنى أن على <code>Stft</code> أن يأخذ طول إطاره عند الإنشاء لا من ثابت في الحزمة. طرح في مجال القدرة لا المقدار: النغمة التي تعلو القاع بـ 53 dB تفقد 0.12 dB في اتجاه وأقل من جزء من ألف من الديسيبل في الآخر.","changelog.99e2902c99af":"<strong><code>Yield</code></strong> — يُبقي جزءًا بعيدًا عن سجل مسار آخر. احتاج إلى وصلة لإشغال الطبقات عبر المسارات: صار <code>Context</code> يحمل <code>&amp;[PitchSet]</code>، وهو للقراءة فقط وبلا أقفال <em>بحكم نوعه</em> لا بالوعد، إضافة إلى ثلاثة آفاق للقراءة المسبقة فيكون لعنصر التحكم <code>Lookahead</code> معنى عند 0 و1 و2 نبضة.","changelog.cc6fff187e87":"<strong><code>Press</code></strong> — مشكّل MPE، الذي احتاج أن يحمل <code>NoteMessage</code> كلًّا من <code>Pressure</code> و<code>Timbre</code> و<code>Bend</code>. مفهرس بالنوتة لا بالقناة، لأن القناة العضو تفصيل نقل في MIDI 1.0. والنوتة السادسة عشرة المتزامنة تُرفض وتُحتسب، ولا تُسرق أبدًا.","changelog.267f52bbec0d":"<strong><code>Ply</code></strong> — مُنسِّق أصوات يتبع التآلف الذي يملكه التوزيع فعلًا. خرجت من بواباته ثلاثة عيوب: كان كاشف طبقة الدخل يقرأ أعلى خانة صوتًا، وهي في الحرف الصوتي المغنّى أيّ مكوّن تفضّله الصيغ الصوتية — فالصوت على دو الوسطى كان يُكشف أعلى بأوكتاف وخامسة؛ وكان تقريب الخانات يترك فجوات عند الإزاحة إلى الأعلى؛ ولم يكن المسار الجاف يُؤخَّر ليطابق المعالَج، فكان عند المزج الافتراضي مرشّح مشط كان الرسم البياني سيعوّض تأخيره المُعلن بسحب الجاف مبكرًا.","changelog.aadbc3dce93b":"<strong><code>Rein</code></strong> — مؤثر يؤديه مقطع MIDI لا LFO. احتاج إلى شدة وكثافة نوتات لكل مسار في فهرس التوزيع.","changelog.f7bd53ba1079":"<strong><code>Muster</code></strong> — جزء واحد تعزفه فرقة من اثني عشر عازفًا كحد أقصى، ولكل عازف توقيته وضبطه ومستواه وهجمته، تُسحب مرة واحدة من بذرة المشروع وتُثبَّت.","changelog.e4a1a80427f8":"<strong><code>Quiver</code></strong> — ثماني سلاسل تحت لوحة مفاتيح واحدة، مناطق نصف مفتوحة بتلاشٍ متساوي القدرة.","changelog.abefe55690b3":"⛔⛔ <strong>وأربع مخالفات لخيط الصوت لم تستطع بوابة التخصيص رؤيتها.</strong> كانت تمشي في كل جهاز مبني <strong>دون عيّنة محمّلة ودون نوتة تصدح</strong>، فلم يمرّ مسار القراءة في أي مُعايِن عيّنات ولا حلقة الأصوات في أي آلة تحت المخصِّص العدّاد مرة واحدة قط. صارت تحمّل مقطعًا في كل خانة وتضرب تآلفًا من ثماني نوتات مرتين، فوجدت أربعًا:","changelog.dd412aa63e27":"كان كلٌّ من <code>Skin</code> و<code>Bronze</code> و<code>Sideband</code> يقرأ <code>block.notes.to_owned()</code> — <code>Vec</code> يُخصَّص في استدعاء التصيير في كل كتلة تحمل نوتة.","changelog.1fe564b767bd":"كان <code>Crucible</code> يحمّل محرّكه من <code>process</code>، والمركِّب المستورد يبني الحالة المنمذجة للصوت في أول مرة يُطالَب فيها بذلك الصوت — فكانت النوتة المتزامنة التاسعة تخصّص في الاستدعاء.","changelog.1743b0d8b2c4":"▶ <strong>من قبل:</strong> المؤثرات الأساسية الثمانية والعشرون كلها، وأحد عشر من أجهزة النوتات الستة عشر، وأربع آلات، وأحد عشر من الأجهزة المميّزة السبعة عشر — أربعة وخمسون من الخمسة والسبعين. ▶ الثمانية والعشرون الأساسية هي كل ما تسميه المواصفات «كل ما يحتاجه المنتج لإنهاء تسجيل دون أن يمدّ يده إلى إضافة شخص آخر». القائمة 75، والرقم الصادق هو ما يجيب به <code>oscillate_dsp::registry::implemented_count()</code>؛ والرقمان كلاهما مُتحقَّق منهما في الشيفرة فلا يستطيع أيٌّ منهما الانجراف عن وثيقة. الواحد والعشرون الأخرى تظهر في المتصفح مسمّاة ورمادية، بلا أي عناصر تحكم — فقائمة عناصر تحكم دون معالجة الإشارة التي تعطي أرقامها معنى ستكون نطاقات مختلقة تبدو موثوقة.","changelog.afcfa380d255":"<strong>المعادلات:</strong> <code>Whetstone</code>، <code>Hilt</code>، <code>Temper</code>. <strong>الديناميكيات:</strong> <code>Vise</code>، <code>Weld</code>، <code>Strata</code>، <code>Parry</code>، <code>Ceiling</code>، <code>Peen</code>، <code>Quench</code>. <strong>الدفع والمضخّمات:</strong> <code>Shear</code>، <code>Triode</code>، <code>Rasp</code>، <code>Fold</code>، <code>Oxide</code>، <code>Furnace</code>، <code>Baffle</code>. <strong>التأخيرات:</strong> <code>Relay</code>، <code>Spool</code>، <code>Sparks</code>. <strong>الصدى:</strong> <code>Chamber</code>، <code>Foil</code>، <code>Coil</code>. <strong>التعديل والمرشّحات:</strong> <code>Shoal</code>، <code>Veer</code>، <code>Comb</code>، <code>Edge</code>. <strong>الأدوات المساعدة:</strong> <code>Stance</code>. <strong>الآلة:</strong> <code>Crucible</code>. <strong>أجهزة النوتات:</strong> <code>Runner</code>، <code>Stack</code>، <code>Hone</code>، <code>Weight</code>، <code>Hold</code>، <code>Scatter</code>، <code>Trail</code>، <code>Hand</code>، <code>Approach</code>، <code>Rake</code>، <code>Turn</code>. <strong>الإيقاعيات:</strong> <code>Skin</code>، <code>Bronze</code>، <code>Sideband</code>. <strong>المميّزة:</strong> <code>Waypoint</code>، <code>Guard</code>، <code>Lantern</code>، <code>Feint</code>، <code>Wear</code>، <code>Gild</code>، <code>Skywave</code>، <code>Toll</code>، <code>Vault</code>، <code>Cleave</code>، <code>Strand</code>.","changelog.5140cf1f25dd":"أُصلح — ثلاثة أشياء لم يكن يستطيع إظهارها إلا التطبيق المشحون","changelog.c5dfcf91c9c3":"⛔⛔ <strong>لم يكن <code>oscillate-hostproc.exe</code> في أي مثبّت، فلم يكن بوسع أي إضافة أن تُحمَّل أبدًا.</strong> لم يعلن <code>tauri.conf.json</code> مدخل <code>externalBin</code> ولا مدخل <code>bundle.resources</code>، ولم يحتوِ <code>target/release/</code> على الملف التنفيذي قط — فكانت كل إضافة VST 3 وكل CLAP تفشل في تطبيق <em>الإصدار</em> بالخطأ","changelog.07ff7d609df0":"▶ <strong>هذا هو الجواب عن «لم تُحمَّل أي إضافة به قط»: لم يكن بوسع أي منها ذلك.</strong> كان كل ما تسلّمه المرحلة 6 ميتًا في أي شيء يُبنى بـ <code>tauri build</code>، وكان سيبقى ميتًا في مثبّت يشغّله مختبِر. ونجح في كل مكان آخر لأن <code>cargo test</code> و<code>cargo run</code> و<code>scripts/host-conformance.mjs</code> كلها تعمل من <code>target/debug/</code>، حيث كان cargo قد وضع الملف التنفيذي بجانبها سلفًا. ⚠ أُصلح بـ <code>scripts/build-hostproc.mjs</code>، وتصريح <code>externalBin</code>، و<code>src-tauri/tests/the_bundle_carries_the_sandbox.rs</code> — الذي يفشل إن انفصل يومًا التصريح أو المسار أو خطوة البناء التي تنتج الملف. أُعيد بناء المثبّتَين كليهما وكبر كلٌّ منهما بالحجم المضغوط للملف التنفيذي.","changelog.006a47556b9e":"⛔⛔ <strong>كانت الأجهزة المرفقة التسعة والستون ما تزال بعيدة المنال من المتصفح</strong>، وهذه الحالة السادسة للشكل نفسه. يضع <code>PluginScan::index()</code> القائمة في البداية بشكل صحيح؛ أما <code>PluginScan::state()</code> فكان يستنسخ الفحص الخام <strong>في طبقة تحت ذلك الإصلاح</strong> — و<code>plugins_state</code> هو الأمر الوحيد الذي تستدعيه لوحة المتصفح. فكانت <code>device_rack</code> و<code>device_add</code> و<code>locate_for_load</code> كلها ترى القائمة، وخمس بوابات تستدعي <code>index()</code> وتنجح، بينما المنتج الذي يكتب <code>vise</code> في المرشّح لا يحصل على شيء. ⚠ كان اختبار سابق يتحقق من <code>state().index.plugins.len() == 1</code>، فأقفل العيب في مكانه. والبوابة الجديدة تمر عبر <code>state()</code> عن قصد: <strong>فتلك هي الدالة التي على طرفها الآخر مستخدم.</strong>","changelog.0cc1ca49a0e2":"⛔ <strong>كان وسم عنصر تحكم وتلميحه في شريط الحالة متبادلَين في الفهارس الثمانية عشر كلها.</strong> كان <code>arrangement.metre</code> يحمل الجملة و<code>hints.metre</code> يحمل الكلمة، فكان شريط أدوات التوزيع يرسم فقرة ملتفّة حيث مكان وسم من كلمة واحدة. كانت السلسلتان موجودتين ومترجمتين، فكانت بوابة التكافؤ — التي تقارن الفهارس ببعضها — خضراء فوق ثمانية عشر خطأً متطابقًا. هناك الآن بوابة على <em>الشكل</em>: كل وسم في شريط الأدوات يجب أن يكون أقصر من التلميح الذي يشرحه.","changelog.033773d6f964":"أُصلح — <code>Rein</code> كان يعرض <code>Off</code> عند الفهرس الثالث","changelog.3dbe0f12826c":"⚠ يجيب <code>Params::on</code> بـ <code>index &gt;= 1</code>، فعنصر التحكم الذي يعرض <code>Off</code> في أي موضع غير الأول يُقرأ <em>مفعّلًا</em> لدى كل جهاز يسأل. وكان <code>Target A</code> و<code>Target B</code> في <code>Rein</code> يسردانه أخيرًا. ⛔ التقطه <code>every_switch_in_the_crate_reads_off_then_on</code>، وهو ثابت على مستوى الحزمة كلها لا تفضيل في التسمية — وهو بالضبط نوع القاعدة التي لا تسدّد ثمنها إلا حين يضيف أحدهم الجهاز السبعين في الرابعة فجرًا.","changelog.176683ba65e2":"تغيّر — ثلاث بوابات كانت تعيد بناء الجهاز لكل إعداد، وإحداها كلّفت تسع عشرة دقيقة","changelog.7f6ca671bb48":"⚠ <strong>تسعة وستون جهازًا تكلّف أكثر من أربعة وخمسين، واثنان من الجدد يكلّفان أكثر بكثير.</strong> كلٌّ من <code>Sift</code> و<code>Ply</code> يُجري تحويلًا من 4 096 نقطة لكل قناة في كل قفزة؛ و<code>Muster</code> يستضيف حتى اثني عشر محرّك مركِّب و<code>Quiver</code> ثمانية، و<code>SynthEngine::new</code> يستغرق نحو ثانية. انتقلت مجموعة البوابات من ثلاث دقائق إلى <strong>أكثر من خمس وعشرين، حيث أُوقفت قسرًا بدل أن تنتهي</strong> — والمحاولتان الأوليان لجعلها في المتناول كانتا موجّهتين إلى الشيء الخطأ.","changelog.c76554d4e4d6":"⛔⛔ <strong>كان السبب الفعلي شكلًا واحدًا في ثلاثة أماكن: بوابة تبني جهازًا جديدًا لكل إعداد تختبره.</strong> لا علاقة لأي من الخصائص الثلاث بالإنشاء — <code>set_param</code> يبلغ كل إعداد، و<code>set_param</code> و<code>prepare</code> و<code>load_sample</code> كلها تعمل <strong>خارج</strong> خيط الصوت. كانت عمليات الإنشاء عبئًا خالصًا، ومع وجود آلات تحمل محرّكات في القائمة صارت هي وقت التشغيل كله:","changelog.8a13018ad9f4":"⛔ <strong>كان <code>silence_in_silence_out</code> وحده تسع عشرة دقيقة من تلك</strong>، وكان آخر اختبار ما زال يعمل حين أُوقفت المجموعة — ولهذا بدا الإصلاحان السابقان أدناه وكأنهما لم يحققا شيئًا.","changelog.6f7962d980c6":"⚠ <strong>لم يُضعَف شيء مما يُتحقَّق منه.</strong> ما زال كل إعداد يُزار، بالترتيب نفسه، عند كل حجم كتلة؛ ويُجرى <code>reset</code> لكلٍّ منها قبل أن يُصيّر؛ ويُعاد كل عنصر تحكم إلى قيمته الافتراضية قبل تحريك التالي، فتبقى كل تمريرة على بُعد عنصر تحكم واحد بالضبط من القيم الافتراضية — وهذا ما كان يعطيه بناء جهاز جديد. ⚠ بل إن بوابة الصمت صارت تفحص <em>بصرامة أكبر</em>: المحرّكات التي بناها إعداد سابق بكسل تبقى مبنية، فيعمل من الجهاز على اللاشيء أكثر مما كان من قبل.","changelog.a633f2f1182e":"⚠ <strong>تغييران على الأجهزة نفسها، كانا يستحقان الإجراء على أي حال ولم يشتريا وحدهما شيئًا يُذكر:</strong>","changelog.26dabe8bffb3":"<strong><code>Muster</code> لا يبني إلا العازفين الذين سيصدحون.</strong> كانت فرقة من أربعة تدفع ثمن اثني عشر، في المنتج وفي المجموعة على السواء؛ والبقية تُبنى حين يرتفع <code>Players</code>، في <code>set_param</code>، الذي لا يعمل أبدًا على خيط الصوت.","changelog.51e5d2b28182":"<strong><code>Quiver</code> لا يبني إلا السلاسل التي يمكن أن تصدح.</strong> سبع من ثمانٍ تُفتح صامتة بمنطقة فارغة، والسلسلة التي لا يمكن أن تصدح لا تحتاج إلى محرّك.","changelog.df19439598d0":"⚠ <strong>البوابة التي لا يستطيع أحد تحمّل كلفة تشغيلها بوابة تُتخطّى</strong>، وهذا كعدم وجودها — ولدى هذا المشروع سبعة عيوب مسجّلة ما كانت لتُلتقط إلا ببوابة شغّلها أحد فعلًا.","changelog.6e1b1bcf02c1":"أُصلح — تصريح الملحق كسر كل بناء بـ <code>cargo</code>، و<code>ci:local</code> كان أخضر فوقه","changelog.99a217744ea0":"⛔⛔ <strong>تصريح <code>externalBin</code> مُدخل بناء، لا مُدخل حزمة فقط.</strong> سكربت البناء في Tauri يرفض بناء <code>src-tauri</code> <strong>على الإطلاق</strong> ما لم يكن الملحق موجودًا لثلاثية المضيف — في <code>cargo clippy</code> أو <code>cargo test</code> العاديين، لا في <code>tauri build</code> وحده. فإصلاح <em>«لم يحمل أي مثبّت صندوق العزل»</em> كسر فورًا مهام <code>quality</code> الثلاث كلها بالخطأ","changelog.c5df1463b340":"⛔ <strong>وكان <code>npm run ci:local -- --slow</code> بنتيجة 18/18 بينما كان ذلك صحيحًا.</strong> الجهاز الذي أضاف التصريح كان عليه ملحق مُجهَّز من تشغيل يدوي سابق لسكربت البناء، فكان كل تشغيل محلي منذ ذلك الحين يعتمد بهدوء على ملف تركه أمر <em>آخر</em>. ⚠ المشغّل الذي يفعل ذلك لا يشغّل بيئة CI، وهي الشيء الوحيد الذي وُجد من أجله — وهذه المرة الثانية في هذا المشروع التي تجلس فيها مجموعة محلية خضراء فوق شجرة معطوبة.","changelog.18fb4b406b6c":"⚠ يجهّز سير العمل الآن الملحق <strong>قبل</strong> بوابات Rust لا بعدها؛ ويجهّز <code>ci-local.mjs</code> واحدًا بنفسه بوصفه أول بوابة؛ ويتحقق <code>ci_stages_the_sandbox_before_anything_that_builds_this_crate</code> من <strong>الترتيب</strong>، لأن خطوة التجهيز التي تعمل بعد البوابات هي بالضبط ما كان موجودًا وهي بالضبط ما فشل. ⚠ ويُستعمل <code>--debug</code>، لأنه لا شيء يُحزَم في تلك المهمة وسكربت البناء لا يتحقق إلا من وجود المسار.","changelog.4773f02d6a28":"⚠ <strong>نجحت مهام <code>release</code> طوال الوقت</strong>، لأن <code>npm run tauri:build</code> يشغّل سكربت التجهيز أولًا. ولم تتأثر إلا المهام التي تبني الحزمة دون حزمها — ولهذا لم يلتقطه أي شيء محلي.","changelog.6014a99b778f":"أُضيف — لم يسلّم أي شيء في المجموعة جهازًا كتلة أخيرة قصيرة قط","changelog.0565b063c7c7":"⛔⛔ <strong>كان كل عدد إطارات في مجموعة البوابات مضاعفًا تامًا لحجم كتلته.</strong> 1 024 إطارًا بكتلة 64، و4 096 بـ 2 048، و8 192 بـ 64 في بوابة الصمت — فعبر <strong>خمسة وسبعين جهازًا وأربعة أحجام كتل، لم يُطلب من جهاز واحد قط أن يعالج كتلة جزئية.</strong> الجهاز الذي يقرأ <code>block</code> حيث كان ينبغي أن يقرأ <code>frames.min(block)</code> كان سيكون أخضر في كل مكان هنا.","changelog.9fb238124783":"⚠ <strong>المحرّك الحقيقي ينتج كتلًا قصيرة باستمرار</strong>: نهاية امتداد، وحدّ تكرار، وتعويض التأخير الخاص بالجهاز. وُجد هذا أثناء تقليص وقت تشغيل المجموعة، لا بسبب إخفاق — وهذا هو الجزء المزعج، لأنه لم يكن هناك شيء سيجده بطريقة أخرى.","changelog.1ee0368d2be0":"⚠ صار <code>frames_for</code> يطرح نصف كتلة، فـ <strong>كل حجم كتلة ينتهي بكتلة جزئية</strong>، و<code>every_block_size_ends_on_a_short_block</code> يتحقق من هذه الخاصية في الدالة المساعدة بدل أن يثق بتعليق — وإلا فإن حجم كتلة يُضاف إلى <code>BLOCKS</code> ويصادف أن يقسم بالتساوي سيعيد المجموعة إلى حيث كانت، بصمت. ⚠ وهو أيضًا <em>أرخص</em> بنحو الخُمس، وهذا اتجاه نادر لإصلاح تغطية.","changelog.b032786ec60c":"⚠ <strong>بوابة التخصيص هي الصف الثالث في ذلك الجدول</strong>، وهي التي جعلت الشكل مرئيًا: تعليمها تحميل عيّنة وضرب تآلف نقلها من عشرين ثانية إلى أكثر من عشرين دقيقة في إيداع واحد. تُبنى الآن مرة واحدة لكل جهاز، مع زيارة كل إعداد بالترتيب نفسه وبقاء كل كتلة إحماء في مكانها — <strong>64 ثانية، وما زالت حمراء حين يُعاد <code>Vec</code> إلى <code>process</code>.</strong>","changelog.e90a16ca644f":"أُضيف — يمكن إعادة رمي البذرة، وستة أجهزة استيقظت","changelog.3f0ff3b92998":"⛔⛔ <strong>لم يكن لـ <code>ops::reroll_seed</code> مستدعٍ، وهذه المرة السابعة.</strong> بذرة المشروع موجودة في النموذج منذ المرحلة 3؛ تركب مع فهرس التوزيع وتصل إلى <code>Context::seed</code>؛ وستة أجهزة تسحب منها كل قرار عشوائي. <strong>لم يكن في الواجهة ما يستطيع تغييرها</strong>، فكان لكلٍّ من تلك الستة سلوك واحد بالضبط طوال عمر المشروع — وكانت كل بوابة تصنع <code>Context</code> يدويًا خضراء فوق ذلك، لأن السياق المصنوع يدويًا يستطيع حمل أي بذرة يشاء.","changelog.96d0a4ae4376":"⚠ هناك الآن <strong>زر ⚄ في شريط أدوات التوزيع</strong>، بجانب الإيقاع، لأن البذرة خاصية للأغنية لا للجهاز. يولّد المستدعي الرقم الجديد ويمرّره إلى العملية، فيبدو المشروع المعاد فتحه مثل الذي حُفظ: العملية التي ترمي عشوائيتها بنفسها لن تُعاد كما هي.","changelog.aaf264952da8":"تغيّر — النافذة المشروطة تموّه الجلسة خلفها","changelog.109a1280400d":"⚠ تعليمات المالك: <em>«حين تظهر أي نافذة مشروطة فوق الـ DAW، يجب أن تكون أجزاء الـ DAW في الخلفية مموّهة ولا يظهر إلا تلك النافذة.»</em> الغطاء وحده يترك كل منزلق ومقطع مقروءًا خلفه. <code>backdrop-filter</code> على الغطاء لا مرشّح على جذر التطبيق — فالمرشّح ينطبق على شجرة فرعية كاملة وكان سيموّه نافذة الحوار أيضًا. ⚠ مقيسًا على الملف التنفيذي المشحون: تنخفض الطاقة عالية التردد في مستعرض الملفات من 7.18 إلى 3.94 ونافذة الحوار مفتوحة.","changelog.b509ead0e07f":"أُضيف — كل عنصر تحكم، بكل لغة (المرحلة 7)","changelog.3fdf63211c68":"⛔⛔ <strong>اللوحات تتحدث اللغات الثماني عشرة كلها.</strong> 482 وسمًا مميّزًا لعناصر التحكم عبر الأجهزة الـ 69 المبنية، مترجمة إلى كل فهرس يشحنه Oscillate — آخر شيء في المرحلة 7 كان ما يزال بالإنجليزية في كل مكان.","changelog.9b5cef558932":"⚠ <strong>كان وسم وتلميحه في شريط الحالة متبادلَين في الفهارس الثمانية عشر كلها.</strong> كان <code>arrangement.metre</code> يحمل الجملة <em>«ميزان المشروع — كم نبضة في المازورة، وكم تساوي النبضة.»</em> و<code>hints.metre</code> يحمل الكلمة <em>«الميزان»</em>، فكان شريط أدوات التوزيع يرسم فقرة ملتفّة حيث مكان وسم من كلمة واحدة. لم يكن لشيء أن يلتقطه: السلسلتان موجودتان ومترجمتان، وبوابة التكافؤ تقارن الفهارس ببعضها — وكانت كلها خاطئة بالطريقة نفسها. هناك الآن بوابة على <em>الشكل</em>: الوسم كلمة، والتلميح جملة.","changelog.e4e709b8830c":"▶ <strong>أعراف الصناعة، وهي ليست مثل ترجمة كل شيء.</strong> تبقى <code>Gain</code> و<code>Attack</code> و<code>Release</code> و<code>Threshold</code> و<code>Ratio</code> و<code>Low Cut</code> كما هي في الألمانية والفرنسية والإسبانية والإيطالية والهولندية والبقية، لأن هذا ما يقرؤه المنتج في كل DAW آخر فتحه — Cubase وStudio One يشحنان لوحات ألمانية تقول هذه الكلمات بالضبط. وتحويلها إلى <code>Verstärkung</code> و<code>Ansprechzeit</code> و<code>Schwellwert</code> ألمانية صحيحة و<strong>أكثر</strong> غرابة لا أقل. ⚠ أما المفردات الوصفية الواضحة — <code>Frequency</code> و<code>Level</code> و<code>Width</code> و<code>Length</code> و<code>Size</code> و<code>Noise</code> و<code>Material</code> — فمترجمة في كل مكان.","changelog.7983ad8fb373":"⚠ <strong>اليابانية والكورية والصينية والروسية والأوكرانية والعربية والهندية لا تُبقي أي نص لاتيني على الإطلاق</strong>، لأن برامج DAW الخاصة بها لا تفعل: الكاتاكانا <code>アタック</code>، والهانغول <code>어택</code>، و<code>起音</code>، و<code>Атака</code>. إنه العرف نفسه يعطي جوابًا مختلفًا، و<strong>لا تظهر أيٌّ من تلك اللغات السبع في قائمة الكلمات الإنجليزية المُبقاة</strong> — والـ 319 كلها مفحوصة في السبع كلها.","changelog.b7c89628b394":"⛔ <strong>يُحسب المفتاح في Rust، من الوسم.</strong> <code>Gain</code> سلسلة <strong>واحدة</strong> للقائمة كلها بدل الإحدى عشرة التي كانت ستكون لو فُهرست لكل جهاز، وعنصر التحكم المعاد تسميته ينتج مفتاحًا تسمّيه بوابة اللغات مفقودًا بدل لوحة تعود بهدوء إلى الإنجليزية وكل اختبار ما زال أخضر.","changelog.15e32938dfa3":"⚠ <strong>الشبكة مركّبة من نمط لكل لغة، لا مكتوبة ستين مرة.</strong> <code>Band 1 Frequency</code> … <code>Band 4 Shape</code> وشبكة الديناميكيات رباعية النطاقات لا تختلف إلا في رقم أو نطاق، فتذكر كل لغة ترتيب كلماتها مرة واحدة. ⛔ استعملت المحاولة الأولى صيغة واحدة لكل نطاق وأنتجت <code>Hoch Ratio Up</code> و<code>Высокие Соотношение вверх</code> و<code>Tief Decay</code> — كلها خاطئة نحويًا. كلمة النطاق التي تقف وحدها على تحكم بالنبرة ليست الكلمة التي تصف اسمًا آخر: الألمانية تحتاج <code>Höhen-</code> وشَرطة، والروسية والأوكرانية تحتاجان <strong>حالة الإضافة</strong> وتأتيان <em>بعد</em> المصطلح. الصيغتان تُعطيان الآن منفصلتين.","changelog.94784bd56e51":"⚠ <strong>كان <code>Look Ahead</code> و<code>Lookahead</code> عنصر التحكم نفسه مكتوبًا بطريقتين</strong> — ثلاثة أجهزة تقول الأولى، واثنان يقولان الأخرى. وُحّدا على <code>Lookahead</code>، وهو ما استعملته الأغلبية وما تطبعه المحدِّدات الحديثة. هذه ترجمة مكررة أقل في ثماني عشرة لغة، وبوابة ترفض الآن وسمين لا يختلفان إلا في المسافات أو حالة الأحرف.","changelog.99966156003c":"أُضيف — أربع آليات صحيحة لا شيء يستدعيها (المرحلة 7)","changelog.f9e8e0604480":"⛔⛔ <strong>لم يكن Oscillate يستطيع إصدار نوتة.</strong> لا من لوحة مفاتيح افتراضية، ولا من لوحة عتاد. وحدة <code>midi</code> في <code>oscillate-audio</code> — <code>ports()</code> و<code>Input::open()</code> و<code>EventQueue</code> و<code>Filter</code> و<code>decode()</code> — كانت مبنية ومختبرة و<strong>لا تشير إليها أي حزمة خارج حزمتها</strong>؛ وكان <code>NoteBank</code> لا يملؤه إلا عامل التشغيل، من المقاطع. فكانت كل آلة في القائمة قابلة للإضافة إلى مسار ولا يمكن عزف أيٍّ منها. <code>live.rs</code> هو المسار المفقود، وهو طابور <strong>واحد</strong> لأن لوحة المفاتيح الافتراضية ومنفذ MIDI هما الحدث نفسه يصل من بابين مختلفين — والمساران سيكونان جوابين عن معنى الشدة، وقاعدتين لإيقاف كل النوتات، وقرارين بشأن ما يحدث أثناء دوران النقل، والأقل استعمالًا سيكون الخاطئ.","changelog.dccd39d3b268":"⛔⛔ <strong>كانت <code>Waypoint</code> و<code>Guard</code> و<code>Lantern</code> تقرأ <code>next_section_ticks: None</code> في كل كتلة، إلى الأبد.</strong> القراءة المسبقة هي الادّعاء الرئيسي لهذه المرحلة — <em>الإضافة تُخبَر أين رأس التشغيل ولا تُخبَر أبدًا بما أمامه</em> — وكان <code>graph.rs</code> يبني <code>Context</code> الخاص به بـ <code>..Context::default()</code>. فكانت ثلاثة أجهزة مميّزة مجرد ضاغط وبوابة وتأخير صدوي عاديين بعنصر Lookahead ميت. ⚠ <strong>بقيت كل بوابة خضراء لأن كل بوابة كانت تبني <code>Lookahead</code> خاصًا بها وتمرّره.</strong> كلها سألت هل <em>يستجيب</em> الجهاز لواحد؛ ولم يسأل أيٌّ منها هل <em>يستلم</em> واحدًا قط. الشكل نفسه لكون القائمة بعيدة المنال من المتصفح، والسؤال نفسه يجده: <em>ما الذي سيضغطه المنتج فعلًا؟</em> تُحسب بنية التوزيع الآن خارج خيط الصوت وتُسلَّم إلى الأسفل نبضاتٍ نسبية.","changelog.022bbad0846a":"⛔ <strong>وصلة العيّنات، وصوت واحد خلف كل جهاز يعزف ملفًّا.</strong> كانت سبع آلات <code>Declared</code> لحاجتها إلى هذا ولا شيء غيره. يُبنى الجهاز من <code>type_id</code> وقائمة من <code>f64</code>، والمسار ليس أيًّا منهما — <code>ParamSpec</code> يحمل أرقامًا لأن خيط الصوت لا يجوز أن يرى <code>String</code> — فلم يكن بوسع العيّنة أن تصل عنصرَ تحكم. تصل بدلًا من ذلك تبديلًا لـ <code>Arc&lt;SampleData&gt;</code>، يُفكّ ترميزه على عامل. ⚠ <strong>الإسقاط هو الفخ</strong>: إطلاق آخر <code>Arc</code> يحرّر على أي خيط تركه، لذا يعيد خيط الصوت القديم بدل أن يُسقطه. ⚠ رأس القراءة موجود في <code>delay::sinc_read</code> منذ AM-A1، موثَّقًا بأنه <em>«الخاص بمُعايِن العيّنات»</em> — مكتوب ومختبر ولا يبلغه أي مُعايِن عيّنات، لأنه لم يكن ممكنًا كتابة أي مُعايِن عيّنات. صوت واحد يخدمها كلها: مُجمَّع عند <code>prepare</code>، ولا يخصّص بعده أبدًا، ويُسرق الأهدأ ثم الأقدم و<strong>يخفت بدل أن يُقطع</strong>، لأن القطع الحاد عند عيّنة عشوائية طقطقة بالمستوى الكامل، وتقع بالضبط حين يعزف المنتج.","changelog.47a37733c964":"▶ <strong>القائمة 63 من 75، صعودًا من 54.</strong> خرجت تسعة أجهزة من قائمة المعطّلين: <code>Sift</code>؛ وأجهزة النوتات <code>Weave</code> و<code>Tread</code> و<code>Revoice</code>؛ ومُعايِنات العيّنات <code>Flint</code> و<code>Armory</code> و<code>Bench</code> و<code>Hammer</code> و<code>Filings</code>. ⚠ <strong>كانت المؤثرات الأساسية الثمانية والعشرون كلها مبنية سلفًا</strong> — كل واحد من هذه كان معطّلًا بسبب وصلة لا بسبب وقت أحد، ولهذا حرّك إغلاق ثلاث وصلات تسعة أجهزة.","changelog.5a6a1d227692":"أُضيف — مشاركة ما صنعته (المرحلة 7)","changelog.dbcd3e927b1f":"⛔⛔ <strong>إعدادات الجهاز تُكتب في سطر واحد تستطيع لصقه في دردشة.</strong> لا ملف، ولا رفع، ولا حساب — وهكذا يتبادل المجتمع الأصوات فعلًا.","changelog.f0988a917537":"▶ <strong>كل سطر يصل يُعامَل على أنه عدائي</strong>، لأنه جاء من غريب عبر نافذة دردشة. يُفحص الطول <strong>قبل تخصيص أي شيء</strong>؛ والجهاز المجهول يُرفض باسمه بدل أن يُخمَّن؛ وكل قيمة تُفحص مقابل نطاق عنصر التحكم الخاص بها، والسطر الخارج عنه <strong>يُرفض بدل أن يُحصر</strong> — فالحصر يحوّل سطرًا تالفًا إلى جهاز يبدو صحيحًا ويصدح خطأً، وهذا الإخفاق الذي لا يستطيع المنتج تشخيصه. و<code>NaN</code> يُحلَّل رقمًا ويُرفض كذلك: فلو بلغ حالة مرشّح لأسكت المسار بقية الجلسة دون أي شيء على اللوحة يقول السبب.","changelog.94eaa1442544":"⛔ <strong>لا يُطبَّق شيء حتى تقرأ ما الذي سيتغير.</strong> تسرد اللوحة عناصر التحكم التي تتحرك، من وإلى، بمنسِّق معالجة الإشارة نفسه — فلا تستطيع المعاينة أن تقول رقمًا يناقضه المقبض بعد ذلك — ولا تعرض تطبيقه إلا بعد ذلك، بوصفه <strong>خطوة تراجع واحدة</strong>. ⚠ اللصق حقل نصي لا قراءة من الحافظة: <code>readText()</code> يطلب من نظام التشغيل آخر ما نسخته أيًّا كان، والحقل لا يطلب شيئًا.","changelog.ac55cb626b91":"⚠ <strong>لا يحمل السطر أي ضغط deflate</strong>، الذي اقترحه مخطط § F-18. كان الهدف أقل من 200 محرف، والقائمة كلها تقيس أقل من نصف ذلك بكثير دون ضغط، فالضغط كان سيشتري محارف لا يعدّها أحد مقابل اعتماديتين على شجرة تُفشل بوابة تراخيصها البناء. وبايت الإصدار موجود كي يحصل عليه جهاز مستقبلي يحتاجه.","changelog.504a5ab9a3c1":"⛔⛔ <strong>ويُحفظ رف كامل ملفًّا.</strong> <em>«هل نستطيع حفظ مجموعات من VST3 وإعداداتها كإعدادات مسبقة — أو مجموعات من الإضافات المرفقة؟»</em> — نعم، كلاهما، بالترتيب، مع عناصر تحكم كل جهاز وحالة تجاوزه وحالة إضافته المعتمة الخاصة. إنه <em>Audio Effect Rack</em> في Ableton و<em>mixer state</em> في FL، ولم يكن شيء يغطيه: سلسلة الوصفة جهاز <strong>واحد</strong>، وسلسلة غنائية من أربعة لم يكن لها أي طريقة لتُحفظ.","changelog.f81450b45e4f":"<strong>ملف، لا سطر، والتمييز جوهري.</strong> حالة الجهاز المرفق حفنة أرقام. أما حالة الإضافة المستضافة فكتلة معتمة من المورّد، كثيرًا ما تبلغ ميغابايتات؛ والمُسلسِل الذي يحاول جعلها قابلة للصق إما سيقتطعها وإما سيُخرج شيئًا لا يستطيع أحد إرساله.","changelog.a3f286b4c94a":"⛔ <strong>الإعداد المسبق الذي يسمّي إضافة لا تملكها ما زال يُحمَّل</strong> — محتفظًا بإعداداتها وحالتها وموضعها في السلسلة، مرسومًا عنصرًا نائبًا يعرض <em>تحديد الموقع…</em>. رفض الإعداد المسبق كله لأن جهازًا واحدًا مفقود هو الطريقة التي يصبح بها الإعداد المشارَك عديم الفائدة.","changelog.9acecd496795":"⚠ <strong>يدوّن ما لا يستطيع الوعد به.</strong> يحمل الإعداد المسبق نسخة الإضافة التي حُفظ بها، واستدعاؤه على نسخة مختلفة يستعيد الحالة و<strong>يقول ذلك</strong> — فالمورّد حر في تغيير معنى الحالة بين الإصدارات، وتحميل حالة مشوّهة بصمت أسوأ من تحذير.","changelog.359fe5e52aef":"⛔ <strong>الإعداد المسبق لا يحمل رقم تأخير أبدًا.</strong> التأخير هو ما <em>يُبلغ</em> عنه الجهاز حين يُحمَّل؛ والملف القادر على ضبطه سيتيح لإعداد مسبق من غريب أن يُفسد محاذاة كل مسار في مشروعك، وستسمع ذلك كأن توقيتك أنت يخطئ.","changelog.c7548c290126":"إنه <strong>الحاوية نفسها التي يستعملها <code>.oscillate</code></strong>، عن قصد — الرقم السحري، ورفض الإصدار، وعدد الكتل المفحوص قبل حجز الدليل، والحساب المفحوص على كل إزاحة، كلها صحيحة هناك سلفًا، والنسخة الثانية من كل ذلك هي التي ستُكتب خطأً.","changelog.12b0585e2328":"أُضيف — مجموعة البوابات، على القائمة كلها (المرحلة 7)","changelog.27da05681148":"⛔⛔ <strong>لا يخصّص أي جهاز مرفق أثناء المعالجة، مقيسًا لا مفترضًا.</strong> كل جهاز مبني، عند كل طرف أقصى لكل معامل ومع كل عناصر تحكمه في أقصاها معًا، يمر عبر <strong>مخصِّص عام عدّاد</strong> — يعيش في مجموعة خيط الصوت في <code>oscillate-audio</code> لأن العملية تحصل على واحد بالضبط وذلك الواحد موجود هناك سلفًا. ⚠ رُئي يفشل أمام جهاز مخرَّب ليخصّص ثمانية أعداد عائمة. ▶ القسم 3 من فلسفة البناء يقول لا تخصيص على خيط الصوت؛ وحتى هذا كانت تلك قاعدة خلفها مراجعة لا قياس.","changelog.c1dd75c564d7":"⛔⛔ <strong>مجموعة واحدة، تمشي في السجل لا في قائمة يحافظ عليها أحد</strong> — فالجهاز المضاف غدًا يكون في كل بوابة دون أن يتذكر أحد إضافته. أربع عشرة بوابة: لا تخصيص عند أربعة أحجام كتل وكل طرف أقصى لكل معامل، والتأخير المُعلن مقابل المقيس، والصمت يدخل فيخرج صمتًا، والحتمية لكل بذرة، وأجهزة النوتات التي تُبلغ عن الفيض بدل إسقاط تآلف، ولا نوتات عالقة بعد إيقاف الكل، والمنحنى المرسوم مقابل الصوت، والميزة البنيوية، ولا استجابة نبضية ملتقطة في أي مكان من الشجرة.","changelog.ef1f383d949f":"▶ <strong>أربع منها تتحقق من غياب، وكلٌّ منها مقرون بتحقق من حضور</strong> — لأن البوابة التي تتحقق من غياب تنجح ببساطة أمام جهاز لا يفعل شيئًا. يجب أولًا إثبات أن المجموعة عملت على قائمة حقيقية، وغيّرت إشارة حقيقية، وملأت مخزن نوتات حقيقيًا.","changelog.a1f70e07df67":"<strong>ثلاثة عيوب حقيقية، وُجدت بكتابتها:</strong>","changelog.9c3286495065":"⛔ <strong>رسم <code>Furnace</code> كومة نبرته وأغفل مرحلتين من مسار صوته الخاص</strong> — مكثّف السطوع عبر عنصر تحكم الكسب، وانحدار محوّل الخرج — وكان <strong>منحرفًا بـ 2.9 dB عند 4 kHz</strong> عمّا يفعله فعلًا. المنحنى الذي تنقصه مرحلة زخرفة للجهاز لا قياس له. أُصلح، والمنحنى يتتبع الصوت الآن إلى عُشر الديسيبل.","changelog.fc2768b6fb8d":"⛔ <strong>بدا <code>Lantern</code> كأنه يتجاهل التوزيع</strong> ولم يكن كذلك: كان تصيير البوابة بطول 8 192 عيّنة وتأخيره 12 000، فلم يكن شيء قد عاد بعد. البوابة التي تقيس ذيلًا يجب أن تعمل إلى ما بعده.","changelog.44daac3f8f13":"⛔ <strong>«التأخير المُعلن هو حيث تبلغ النبضة ذروتها» خطأ</strong>، وجهازان يثبتان ذلك في اتجاهين متعاكسين. <code>Toll</code> يعلن صفرًا ويبلغ ذروته عند 1 332 — فهو رنّان، ورنينه يتراكم بعد نبضة مرت مباشرة. ونافذة <code>Strand</code> ترنّ 517 عيّنة <em>قبل</em> ذروتها. كلا الإعلانين صادق؛ أما القياس فلم يكن. تقيس البوابة الآن حيث <strong>تبدأ</strong> الاستجابة وحيث <strong>تبلغ ذروتها</strong>، وتتحقق مما يستطيع كلٌّ منهما إثباته: لا شيء يجوز أن يصل متأخرًا عمّا أُعلن، ولا شيء يجوز أن يبلغ ذروته مبكرًا.","changelog.9e568642d580":"⚠ <strong>الاستجابة الترددية كمية للإشارات الصغيرة، وجهازان احتاجا إلى قول ذلك بصوت عالٍ.</strong> يجيب <code>Furnace</code> بـ −7.97 dB عند 80 Hz لنغمة −20 dBFS وبـ −0.01 dB لنغمة هادئة، لأن الأولى تُضغط. وتأرجح <code>Oxide</code> ورجفته يحرّكان موضع القراءة، وهذا تعديل ترددي — فنغمة 4 kHz ثابتة تفقد 3 dB في نطاقات جانبية لن يرسمها أي منحنى مقدار. تُثبّت البوابة التعديل وتقيس بهدوء، وتقول السبب في الموضعين.","changelog.ae6713aae737":"أُضيف — الأجهزة التي لا يمكن لأي إضافة أن تكونها (المرحلة 7، AM-C)","changelog.ccec0b2bb36e":"⛔⛔ <strong>ثلاثة منها تقرأ التوزيع، وهذا ليس مخزنًا مؤقتًا أطول.</strong>","changelog.525a54a16b01":"▶ قراءة مازورتين من <em>الصوت</em> مسبقًا تأخير يدفع ثمنه كل منتج في الجلسة. أما قراءة <em>بنية</em> التوزيع قبل مازورتين فلا تكلّف <strong>شيئًا</strong> — اللازمة عند المازورة 33 سواء عزفها أحد بعد أم لا. لا تكشف أي صيغة إضافات توزيع المضيف، ولهذا لا يمكن أن توجد هذه إلا داخل DAW كتبها أيضًا. الثلاثة كلها تعلن <strong>تأخيرًا صفريًا</strong>، وبوابتها أن تغيير البنية دون تغيير عيّنة واحدة يغيّر ما تفعله.","changelog.2d95b40d737e":"<strong><code>Waypoint</code> يمسك اللازمة سلفًا حين تصل</strong>، بدل أن يتفاعل معها متأخرًا ببضعة أجزاء من الثانية.","changelog.61058866fd1f":"<strong><code>Guard</code> ينفتح لضربة لم تحدث بعد.</strong> العتبة لا تستطيع ذلك: فحين يبلغ المستوى حدّه يكون العابر قد مضى.","changelog.0a518a9dfc80":"<strong><code>Lantern</code> يفرغ تأخيرًا صدويًا نحو خط المازورة</strong>، فينتهي الذيل بدل أن يُقطع. القطع طقطقة، وهذا الجهاز موجود لتجنّب الفوضى التي يصنعها التفريغ اليدوي.","changelog.3adaa073b4e9":"⛔ <strong>ثلاثة أخرى تعيد الرمي بالطريقة نفسها من بذرة المشروع</strong>، فالتلعثم الذي بدا صحيحًا في التمريرة الثالثة يبقى هناك في الأربعين — وإعادة الرمي عملية واحدة قابلة للتراجع لا مقامرة. <code>Feint</code> و<code>Wear</code> و<code>Skywave</code>.","changelog.faf2b04e72fd":"<strong><code>Gild</code> يتيح لك اختيار التوافقيات.</strong> مشكّل الموجة يعطي أي مزيج يسقط من منحناه؛ أما أساس Chebyshev فيجيب بالتوافقية المطلوبة بالضبط، فالثانية والخامسة عنصرا تحكم منفصلان يفعلان أشياء منفصلة.","changelog.388e74d46c0c":"<strong><code>Toll</code> يجعل أي صوت يرنّ كجسم مضروب</strong>، مدفوعًا بعابرات الدخل نفسه — فطبلة السنير عبر أنبوب ترنّ كأنبوب تضربه سنير، والنوتة الممسوكة بالكاد ترنّه.","changelog.72e4b3c8680a":"<strong><code>Vault</code> يحسب الصدى من غرفة بالأمتار.</strong> الأبعاد تقرر أزمنة وصول الانعكاسات وأطوال خطوط الخزان: أول انعكاس في غرفة من أربعين مترًا يصل فعلًا متأخرًا أربع مرات عن غرفة من ثلاثة أمتار.","changelog.3ab7f011c6f7":"<strong><code>Cleave</code> يفصل الضربات عن النبرة</strong>، بسؤال كل نقطة في الطيف هل هي عالية <em>الآن</em> وهادئة قبلها وبعدها بلحظة — أي ضربة — أم عالية <em>هنا</em> وهادئة على جانبيها بخانة — أي نوتة. لا يحتاج إلى عتبة ولا إلى شيء يتعلّمه: إنه عبارة عن شكل الصوت.","changelog.34f872d520d1":"<strong><code>Strand</code> يعيد بناء الصوت من المكوّنات الجزئية التي يجدها فيه</strong>، فيمكن خفض النفَس وضجيج القوس بمعزل عن النوتات.","changelog.7af3df17572e":"⚠ <strong>ادّعاء «لا إضافة تستطيع أن تكون هذا»، مُعاد فحصه مقابل ما شُحن لا مقابل ما حُدّد</strong> — تطلب بوابة المرحلة 7 ذلك بالضبط، لأن المبالغة في المواصفات تصبح مبالغة في التسويق. ▶ <strong>ستة</strong> من الأحد عشر تستحقه: ثلاثة تقرأ بنية التوزيع (<code>Waypoint</code> و<code>Guard</code> و<code>Lantern</code>) وثلاثة حتمية من بذرة المشروع (<code>Feint</code> و<code>Wear</code> و<code>Skywave</code>)، ولا تكشف أي صيغة إضافات أيًّا منهما. أما الخمسة الأخرى — <code>Gild</code> و<code>Toll</code> و<code>Vault</code> و<code>Cleave</code> و<code>Strand</code> — فمعالجة إشارة مميّزة، موصوفة أعلاه بمزاياها الخاصة، دون ادّعاء أنها ما كانت لتُكتب إضافات. كان README يقول أحد عشر وصار يقول ستة.","changelog.a8c23b6590a7":"أُضيف — ثلاثة أصوات طبول منمذجة لا معيّنة (المرحلة 7، SP-02)","changelog.b45e2a05e0f9":"<strong><code>Skin</code> غشاء مضروب، لا عيّنة.</strong> مكوّناته الجزئية هي أصفار Bessel — الثاني 1.59 ضعف الأول لا ضعفه، وهذا هو الفرق كله بين الطبل والنوتة ذات الطبقة. حيث يقع المضرب يقرر أي الأنماط تُثار، وقوة الضربة تقرر مدة بقائه ملامسًا، وأسلاك السنير لا تخشخش إلا حين يتحرك الرأس بما يكفي لقذفها عنه. <strong>الطبلة الكبيرة تحافظ على طبقتها ضمن سنت واحد على خفوت مدته أربع ثوانٍ.</strong>","changelog.e1820ecc0952":"<strong><code>Bronze</code> صفيحة مُشتِّتة.</strong> أربعة وستون مكوّنًا جزئيًا تتباعد كلما صعدت، ولهذا يكون الصنج غسلًا والوتر تآلفًا. ودوّاسة الهاي هات تشدّه حقًّا: مغلقًا، يصبح الذيل أقصر بأكثر من عشرين ديسيبلًا، والحركة تستغرق الوقت الذي يقوله عنصر التحكم Closure.","changelog.da5d0b60ebad":"<strong><code>Sideband</code> تعديل ترددي FM من أربعة مشغّلات</strong> عبر ثماني خوارزميات، مُفرط الاعتيان، ومشغّل التغذية الراجعة فيه ممسوك تحت الواحد في معالجة الإشارة كما على اللوحة — فالمشغّل الذي يعدّل نفسه عند الواحد مولّد ضجيج لا يعود أبدًا.","changelog.d99f1f1c0dab":"⛔ <strong>المعاملات نفسها تُصيّر الضربة نفسها</strong>، في كل مرة، على كل جهاز. يُعاد بذر كل مولّد حين يُعاد ضبط الصوت بدل أن يكمل من حيث صادف أن يكون، فيبدو التثبيت مثل ما سُمع.","changelog.87dbbf51c469":"أُضيف — ما يحدث للجزء قبل أن يُعزف (المرحلة 7، AM-D1)","changelog.66e2e630602a":"⛔⛔ <strong>صار لجهاز النوتات مكان يعمل فيه الآن</strong>، ولم يكن له حتى هذا.","changelog.0b00d82af6a6":"▶ <strong>كان ستة عشر جهازًا في القائمة بلا وصلة تعمل فيها.</strong> كان الجهاز المرفق لا يستطيع إلا كتابة الصوت، فلم يكن لدى المُفكِّك أي طريقة لإصدار نوتة؛ والشيفرة التي تبني شريط القناة كانت تُسقط كل جهاز نوتات من السلسلة، مع تعليق يقول إنها تفعل. كانت الآلية هي المفقودة لا أن الأجهزة غير مكتوبة — وهذه المرة الخامسة التي يجد فيها هذا المشروع ذلك الشكل.","changelog.06268f644505":"<strong>فكّك التآلف، ونسّق، وأنسِن، وردّد، وصحّح، وحوّر جزءًا</strong>، في سلسلة، قبل أن تسمعه الآلة. أحد عشر من الستة عشر مبنية.","changelog.2308ba050970":"⛔ <strong>لا شيء هنا يستطيع ترك نوتة عالقة.</strong> كل جهاز مُلزم بذلك: المصحّح يحرّك رسالة إيقاف النوتة بالطريقة نفسها التي حرّك بها بدايتها، وباني التآلفات يرفع كل صوت أصدره، ونوتات المُفكِّك الخاصة تتوقف حين يتوقف النقل.","changelog.f94d5f02304a":"⛔ <strong>كل جهاز عشوائي يعيد الرمي بالطريقة نفسها من بذرة المشروع</strong>، فيبدو التثبيت مثل ما سُمع. يسحب <code>Scatter</code> طبقته وشدته وتوقيته من ثلاثة تيارات منفصلة، فإعادة رمي أحدها تترك الأخرى مطابقة بايتًا ببايت — فيستطيع المنتج إصلاح توقيت جزء دون أن يفقد النوتات التي أعجبته.","changelog.b7a88dfc6644":"<strong>سلسلة النوتات التي ينفد منها المكان تقول ذلك</strong>، ويُحفظ العدد. المُفكِّك الذي يفقد تآلفًا بهدوء سيكون عيبًا يُكتشف بعد أسبوع.","changelog.acc86def0061":"<strong><code>Temper</code> يرفع التردد نفسه ويخفضه ولا يُلغي أحدهما الآخر.</strong> هذا هو الغرض كله من المعادل البرامجي السلبي، وهو الجزء الذي يخطئ فيه كل تقليد مبني من معادل بارامتري: الرفع والخفض يتشاركان الملف، فـ 6 dB من كلٍّ منهما عند 100 Hz تترك <strong>+2.0 dB</strong> تحتها وانخفاضًا <strong>−1.4 dB</strong> عند 180 Hz بدل خط مستوٍ.","changelog.b3d85a912eee":"<strong><code>Strata</code> يقسم أربعة نطاقات تُجمع عائدة إلى ما دخل.</strong> ضمن <strong>0.01 dB</strong> عبر كل منطقة عبور، وهذا يتطلب تصحيحات تمرير شامل على النطاقات التي تخطّت عبورًا — ودونها يتمشّط المعالج متعدد النطاقات في الأماكن نفسها التي وُجد ليعمل عليها. كل نطاق يضغط نزولًا ويرفع صعودًا من كاشف <strong>واحد</strong>، فلا يستطيع النصفان أن يختلفا.","changelog.33d3cfb69d0c":"<strong><code>Stance</code> مطابق بتًّا ببت حين لا تطلب منه شيئًا.</strong> ليس «قريبًا بما يكفي» — بل الأرقام نفسها تخرج كما دخلت. كل مرحلة تُتخطّى بدل أن تعمل عند الوحدة، لأن مدوِّر الطور والعبور شبكتا تمرير شامل، وشبكة التمرير الشامل المتروكة تعمل تلطّخ كل عابر على المسار من أجل عنصر تحكم لم يلمسه أحد.","changelog.85c6c680dbe0":"<strong>ثلاثة أصداء، خزان واحد، و«ثانيتان» تعني ثانيتين فيها كلها.</strong> يتشارك <code>Chamber</code> و<code>Foil</code> و<code>Coil</code> شبكة تأخير تغذية راجعة من ستة عشر خطًا بمصفوفة مزج متعامدة، فيُضبط زمن الخفوت بعنصر تحكم الخفوت ولا شيء غيره: يقع RT60 المقيس <strong>ضمن 5 %</strong> مما تقوله اللوحة من 0.2 ثانية إلى 12.","changelog.790ef72775e3":"<strong><code>Coil</code> يقطر، والقطر هو الآلية لا انطباع عنها.</strong> يحمل النابض الترددات المنخفضة أبطأ من العالية، فتعود النبضة زقزقة هابطة؛ وكل نابض 120 مرحلة تمرير شامل مُشتِّتة، وهذا يضع 38 ms من التأخير على 500 Hz مقابل 7.6 ms على 4 kHz. للخزان مجموعة نوابض واحدة ولاقطان، ومن هنا يأتي الستيريو فيه — لا من تشغيل الشيء كله مرتين.","changelog.13fe8240a909":"<strong>باص <code>Foil</code> لا يرنّ أطول من أعاليه</strong>، وهذا هو الشيء الوحيد الذي يفصل الصفيحة عن القاعة الصغيرة، والشيء الذي تخطئ فيه كل محاكاة للصفيحة.","changelog.cbb8261f8b1b":"<strong>تكرارات <code>Spool</code> تصبح أبهت وأوسخ في كل دورة</strong>، لأن التشبّع وخسارة فجوة الرأس داخل حلقة التغذية الراجعة لا على طريق الخروج. شريط أو سلسلة دلاء: عرض نطاق مسار الدلاء يتبع ساعته نزولًا، فالتأخير الطويل تأخير معتم — وهذا ما يكونه جزء سلسلة الدلاء فعلًا، لا تأخيرًا يتبعه مرشّح.","changelog.3ed31dd895e1":"<strong><code>Comb</code> فلانجر حقيقي يمر بالصفر.</strong> المسار الجاف مؤخَّر أيضًا، فيمسح المسار المعدَّل عبره ويخرج من الجهة الأخرى؛ وعند التقاطع يحمل الاثنان العيّنات نفسها بدقة أفضل من <strong>60 dB</strong>، وهذا إلغاء لا يستطيع بلوغه فلانجر لا يقدر إلا على الاقتراب من الصفر. ⚠ ذلك التأخير الجاف تأخير حقيقي ومُعلن، فقلب المفتاح لا يجعل المسار مبكرًا.","changelog.bd48e1488259":"<strong><code>Sparks</code> يغيّر الطبقة دون انجراف</strong>، بدقة أفضل من جزء من ألف من السنت عبر ±24 نصف درجة، ونوافذ حبيباته تُجمع إلى الوحدة عند كل كثافة لا عند التداخل الوحيد الذي يصادف أن تفعل فيه نوافذ Hann ذلك.","changelog.f57ce8edbf1a":"<strong><code>Shoal</code> يحتفظ بعرضه عبر الطيّ الأحادي.</strong> التوسيع لا يحرّك المجموع الأحادي بأي مقدار على الإطلاق، عند كل عرض وكل تردد، لأن المجموع والعرض يُبنيان منفصلين بدل أن يكون العرض حيلة قطبية تُلغى عند الطيّ.","changelog.cee1b6a54d95":"<strong>شريط <code>Oxide</code> أبهت عند 7½ ips منه عند 15</strong>، ويزداد بهتانًا مع تآكل الرأس — لأن رأس التشغيل لا يستطيع تمييز طول موجة أقصر من فجوته، وهذا <code>|sin(x)/x|</code> وسطر واحد لا منحنى رسمه أحد. ونتوء الرأس فيه يتحرك مع سرعة الشريط للسبب نفسه، ويشوّه الحافة الصاعدة بطريقة تختلف عن الهابطة، وهذا ما تفعله الحلقة المغناطيسية ولا يستطيعه مشكّل الموجة.","changelog.1910ed335a88":"<strong><code>Furnace</code> يرتخي بدل أن يصبح أكثر تربيعًا فحسب.</strong> ينخفض إمداده تحت ما تسحبه صمامات الخرج، فيسحب التآلف القضبان إلى الأسفل وتكون النوتة التالية أهدأ حتى تعود: <strong>4 dB من الضغط عند 6 dB بعد القصّ</strong>، ولعنصر التحكم Sag سلطة حقيقية على ذلك الرقم.","changelog.e79ee3f59a10":"<strong><code>Baffle</code> ليس فيه أي استجابات نبضية، وهذا حرفي.</strong> مُشغِّل رنّان، وذروة تفكك المخروط، ومحاذاة بمنفذ، وخطوة حافة الحاجز، وميكروفون بمسافة ومحور، وغرفة قصيرة — كلٌّ منها معامل لا ملف. مُشغِّل الاثنتي عشرة بوصة يرنّ عند 75 Hz، والخمس عشرة أخفض، والثماني أعلى.","changelog.79387b24db13":"<strong>تُصدر صوتًا في التطبيق، لا في اختبار فقط.</strong> الجهاز على المسار يُبنى حين تُبنى خطة التصيير، ويعمل بين مجموع الشريط ومنزلقه — حيث يوضع المؤثر المُدرَج — والتأخير الذي يعلنه هو ما تُسوّى عليه كل المسارات الأخرى. ⛔ هناك مكان واحد بالضبط يمكن فيه إنشاء جهاز مرفق، ويعيد التأخير في الاستدعاء نفسه، فلا يمكن أن ينفصلا.","changelog.3a625cdcb34b":"<strong>لوحة تستطيع تدويرها فعلًا.</strong> غلاف واحد لكل جهاز فتُقرأ كعائلة، ولوحة واحدة مرسومة من وصف الجهاز نفسه. ⛔ اللوحة لا تنسّق رقمًا أبدًا: تُسلَّم السلسلة التي صنعها منسِّق معالجة الإشارة نفسه، فلا تستطيع القراءة أن تخالف ما ستسمعه.","changelog.7e1fc34d1868":"<strong>عناصر تحكم تتصرف كعناصر تحكم.</strong> مدى حركة 270°، ونسبة سحب مطابقة لليد، و<code>Shift</code> للدقة — ويُظهر لك المنزلة العشرية التي كسبها — ومنطقة إمساك دقيقة قرب المركز وخشنة عند الحافة، ونقاط توقف <strong>تقاوم بدل أن تقفز</strong> فيمكن ضبط عنصر ثنائي القطب على +0.3 dB، والنقر مع <code>Alt</code> والنقر المزدوج لإعادة الضبط، والعجلة، ولوحة المفاتيح كاملة، وسحب يواصل التتبع حين يغادر اللوحة.","changelog.5c54fb29c894":"<strong>كل جهاز يقول ما يكلّفك.</strong> الجهاز الذي له تأخير يُظهره، بالعيّنات وبأجزاء الثانية، على لوحته الخاصة.","changelog.8e0f56dd7bcb":"<strong>مقطع MIDI يُصدر صوتًا.</strong> الآلة على المسار تستلم النوتات التي يحملها التوزيع، بدقة العيّنة داخل الكتلة، وخرجها هو ما تعمل عليه سلسلة الشريط ومنزلقه. ⚠ قبل هذا كانت النوتات تبلغ الرسم البياني وتتوقف هناك.","changelog.2e43c657f195":"أُضيف — Oscillate ستيريو، من طرف إلى طرف (المرحلة 7)","changelog.587ea2844a2a":"⛔ <strong>كل مسار صوت في Oscillate يحمل الآن قناتين.</strong> كان يحمل واحدة، ولم يكن ذلك قيدًا في تعليق:","changelog.be58cc9d5843":"<strong>الملف الستيريو يُعزف ستيريو.</strong> كان عامل التشغيل يحسب متوسط الملف الستيريو المستورد في قناة واحدة قبل أن يبلغ رسم التصيير أصلًا. كان المنتج يستطيع استيراد تثبيت ستيريو، والنظر إلى موجة ستيريو، والاستماع إلى مجموع مركزي — دون أي شيء في أي مكان يقول ذلك.","changelog.ddf594435dd8":"<strong>لكل شريط قناة بان يعمل.</strong> لم يكن في المنتج أي بان لكل قناة على الإطلاق: كان قانون البان يُطبَّق مرة واحدة، عند الماستر.","changelog.8ac7863b5f5d":"⛔ <strong>البان والتوازن قانونان مختلفان، وOscillate يستعمل كليهما.</strong> المصدر الأحادي <em>يوضع</em> بقدرة ثابتة، فتحريكه عبر المجال لا يغيّر جهارته. والإشارة الستيريو أصلًا <em>تُمال</em> عند الوحدة، فالناقل الذي يمرّرها لا يخفّضها. تطبيق قانون الوضع عند كل نقطة جمع هو الطريقة التي يفقد بها المزيج بهدوء 3 dB لكل ناقل — وقد فعل ذلك مرة، واختباران يقولان ذلك الآن.","changelog.d0c94d7d1062":"<strong>تعويض التأخير لكل قناة.</strong> خط التأخير ذاكرة؛ والخط الواحد المشترك بين قناتين سيضع تاريخ كل قناة في خرج الأخرى، وهذا مجموع أحادي بخطوات إضافية.","changelog.1ff0289da7b2":"<strong>الملف الذي فيه قنوات أكثر مما لدى Oscillate يُطوى بأمانة.</strong> القناتان 1 و2 هما الزوج؛ وكل ما بعدهما ينضم إلى الجانبين بقدرة متساوية. المسار المنفصل ذو القنوات الست يفقد شيئًا في منتج ثنائي القنوات، وفقدانه بالتساوي هو الجواب الذي لا يختلق مزيجًا لم يصنعه أحد.","changelog.430445e78834":"⚠ <strong>ما لم يُبنَ، بوضوح.</strong>","changelog.ed4cf4e242f9":"<strong>ستة أجهزة</strong>: أربعة مؤثرات صوتية، وآلة واحدة، وواحد يعزف العتاد. ⚠ <strong>كل مؤثر أساسي وكل جهاز نوتات مبني.</strong> كانت واحدًا وعشرين قبل إغلاق وصلة العيّنات وتيار النوتات والقراءة المسبقة ووصلة الإشغال عبر المسارات ووصلة MPE؛ وما بقي معطّل بسبب شيء لا يستطيع الجهاز رؤيته حقًّا، وكلٌّ منها يقول ما هو.","changelog.38a8ee71a0b3":"<strong><code>Frequency Carve</code></strong> يقارن نطاقات هذا المسار مقابل <strong>صوت كل مسار آخر</strong>. وصلة الإشغال تحمل ما <em>تعزفه</em> المسارات الأخرى — نوتاتها — لا كيف <em>يبدو صوتها</em>: نشر طاقة النطاقات لكل مسار شيء مختلف، ويجب ملؤه بعد تصيير كل مسار لا قبل تصيير أيٍّ منها.","changelog.9d4c0bb1c873":"<strong><code>Reverse Reverb</code></strong> يبني ذيله المعكوس من <strong>صوت لم يُعزف بعد</strong>، وهذا يعني خيط عامل يُصيّر المازورات الأربع التالية من توزيع هذا المسار في حلقة. لا شيء في الرسم البياني يُصيّر قبل رأس التشغيل؛ القراءة المسبقة تحمل البنية، لا الصوت.","changelog.a1bd3c93ef36":"<strong><code>Chain Morph</code></strong> يتحوّل بين <strong>سلسلتَي مؤثرات كاملتين</strong> على مستوى المعاملات. يستطيع الجهاز الآن أن يحتوي <em>محرّك</em> جهاز آخر — <code>Quiver</code> يمسك ثمانية و<code>Muster</code> اثني عشر — لكن سلسلة من أجهزة عشوائية لا مكان لها تحفظ فيه عناصر تحكمها: معاملات الجهاز <code>Vec&lt;f64&gt;</code> مسطّحة، ومعاملات السلسلة المتداخلة يجب أن تعيش داخلها.","changelog.a8f92d184a0a":"<strong><code>Ember</code></strong> <em>«يعيد عزف ما عزفه هذا المسار للتو»</em>، فيحتاج إلى <strong>خرج المسار بعد المنزلق</strong> ملتقطًا في حلقة. وصلة العيّنات تسلّم الجهاز ملفًّا؛ وهذا يحتاج إلى نقطة سحب على الرسم البياني، وهذا شكل مسار التسجيل لا مسار العيّنات.","changelog.84b441e09a4b":"<strong><code>Salvage</code></strong> <em>«يبني طقم طبول من مجلداتك أنت»</em>، فيحتاج إلى مكتبة المنتج: هو معطّل بسبب مستعرض الملفات، والمرحلة 8 هي حيث يخرج من هذه القائمة.","changelog.21f63c13e3b3":"<strong><code>Outpost</code> يعزف العتاد الخارجي</strong> عبر منفذ MIDI مع عودة صوتية مقيسة. ⛔ <strong>ليس لدى Oscillate أي إدخال/إخراج لمنافذ MIDI على الإطلاق</strong> — <code>oscillate_audio::midi</code> موجود ولا شيء يستدعيه — فهذا معطّل بسبب طبقة لا بسبب جهاز.","changelog.55b1e9f4ac42":"<strong>ليس لدى <code>Rein</code> عنصر تحكم <code>Pressure Depth</code></strong>، حيث يسرد § 2 واحدًا. النوتة المخزّنة في <code>oscillate_project</code> تحمل طبقة وشدة وشدة إطلاق وقناة؛ والضغط متعدد الأصوات غير مسجّل، فسيكون عنصر التحكم مقبضًا لا شيء خلفه. ⚠ <code>NoteMessage::Pressure</code> موجود منذ <code>Press</code>، فوصلة معالجة الإشارة هناك — المفقود هو النوتة المخزّنة.","changelog.3b6bba40e92d":"<strong><code>Strand</code> يغيّر الطبقة بتحريك الخانات لا بمُرمِّز طوري</strong>، حيث تطلب مواصفاته مذبذبات متصلة الطور — فيقع المكوّن الجزئي المزاح على أقرب مركز خانة ويتلطخ بدل أن يكون نظيفًا. ⚠ يعمل عند 1024 نقطة حيث تطلب المواصفات 4096. يأخذ <code>Stft</code> الآن طول إطاره عند الإنشاء — و<code>Sift</code> و<code>Ply</code> كلاهما يعمل عند 4096 — فهذا إعادة قياس لا قيد، ولم تُجرَ بعد.","changelog.00463fd5e001":"<strong>الأوكتاف الأدنى في <code>Sift</code> ينخفض 8.4 dB من 12 مضبوطة</strong>، بينما يقع كل نطاق من 63 Hz إلى 16 kHz ضمن نصف ديسيبل. عند إطار من 4096 نقطة يكون الأوكتاف من 22 إلى 45 Hz ثلاث خانات، ومتوسط الإطارات الـ 64 الذي يحدده § 2 نفسه 1.4 ثانية — أقصر من أن يتكرر قاع ضجيج حقيقي. تتحقق البوابة مما يفعله فعلًا وتقول السبب.","changelog.14f6fe586263":"<strong><code>Hone</code> و<code>Stack</code> يأخذان مفتاحهما الموسيقي من لوحتهما الخاصة</strong>، حيث تعرض المواصفات أيضًا مفتاح المشروع ومسار التآلفات مصدرين. كلاهما يحتاج إلى المشروع، فلا يُعرض أيٌّ منهما بدل أن يُعرض خاملًا.","changelog.57af5d8acf67":"<strong><code>Approach</code> يبني حشوته مما هو ممسوك</strong>، حيث تطلب المواصفات تآلف القسم القادم. حدّ القسم نفسه حقيقي — يأتي من القراءة المسبقة التي يحسبها المحرّك سلفًا — فتصل الحشوة في المكان الصحيح بالشكل الصحيح.","changelog.cabbe8817e21":"<strong>فحيح <code>Spool</code> وأزيز ساعة <code>Shoal</code> لا يُسمعان إلا حين يمر شيء عبرهما.</strong> الآلة الحقيقية تفحّ سواء عُزف شيء أم لا؛ والإضافة التي تفحّ على مسار صامت يزيلها المنتج في أول مرة يُفرد فيها مقطعًا هادئًا.","changelog.9fc40d6ef00e":"<strong><code>Foil</code> و<code>Coil</code> يتصرفان كصفيحة ونابض؛ وليسا حلولًا للفيزياء.</strong> تطلب المواصفات عدة آلاف من الرنّانات من معادلة الصفيحة الرقيقة المُشتِّتة وثلاثة خزانات من المراحل المنمذجة. وما بُني هو خزان الصدى المشترك مشكّلًا ليتصرف مثل كلٍّ منهما، والتشتّت في <code>Coil</code> هو الآلية الحقيقية، بينما لا يدّعي تباعد الأنماط في <code>Foil</code> أنه يتبع قانون الصفيحة.","changelog.fd6445143eaf":"<strong>ليس لدى <code>Strata</code> وضع عبور خطي الطور</strong>، حيث تطلب مواصفاته واحدًا عند 4096 نقرة و2048 عيّنة من التأخير. لذا لا يوجد منتقي Filter Mode على اللوحة أيضًا — فالمنتقي ذو الموضع العامل الوحيد أسوأ من غيابه. معيار المقدار مُستوفى على مسار LR4؛ ومعيار الطور ±0.5° ينتمي إلى الوضع غير الموجود هنا، ولا تستطيع شجرة LR4 استيفاءه.","changelog.8fb3c0f5fe51":"<strong>تخلّف <code>Oxide</code> المغناطيسي ليس حلًّا بنموذج Jiles-Atherton</strong>، وكومة نبرة <code>Furnace</code> ليست حل الدائرة العُقَدي الذي تطلبه مواصفاته — لذا لا يُدّعى معيار ±0.3 dB للكومة. ما هو كلٌّ منهما <em>فعلًا</em> مكتوب في ترويسة وحدته الخاصة، بجانب ما هو حقيقي: خسارة الفجوة وسلوك السرعة في <code>Oxide</code> هما الفيزياء، والتشتّت في <code>Coil</code> هو الآلية.","changelog.65207b679973":"<strong><code>Temper</code> ينمذج سلوك الشبكة السلبية بدل حلّها.</strong> التفاعل الذي يمدّ المنتج يده إليه مقيس مقابل أرقام المواصفات نفسها؛ وفضاء الحالة العُقَدي من الرتبة الرابعة تحته ليس الدائرة، ومرحلة الدفع فيه لاخطية مُفرطة الاعتيان لا مرحلة صمام بإمداد خاص بها.","changelog.9e9b24e99407":"<strong>لدى <code>Whetstone</code> أربعة نطاقات ولا مسار خطي الطور</strong>، حيث تطلب مواصفاته اثني عشر ووضعَي الطور كليهما.","changelog.1f3f9ed46a23":"<strong>المحلّل وخط خفض الكسب ليسا حيّين.</strong> المنحنى الذي يطبّقه الجهاز مرسوم، ومعايَر، على شبكة حقيقية من الترددات والديسيبلات، ومجموعة البوابات تُلزمه بعُشر ديسيبل من الصوت. وما بجانبه — خفض الكسب والارتباط — هما قيم <strong>السكون</strong> للجهاز، تُقرأ من نسخة مبنية للإجابة عن السؤال ثم تُرمى. الخط المتحرك يحتاج إلى نقطة سحب على نسخة المحرّك نفسها تدفع إلى حلقة بلا أقفال، وهذا غير مبني. ⚠ مقول في ترويسة وحدة <code>panel.rs</code> بدل أن يُترك لأحدهم يتساءل لماذا لا تتحرك الإبرة أبدًا.","changelog.076bf92bab94":"<strong>المنحنى هو الشكل، لا مراحل الكسب.</strong> أين ينخفض الجهاز وأين يرتفع مرسوم ومسوّر ببوابة؛ أما جهارته الإجمالية فلا، لأن مستوى الإشارة الصغيرة في مضخّم الصمامات ثلاثة منحدرات ثلاثية وحلقة تغذية راجعة، ووضع ذلك في المنحنى المرسوم سيكون كتابة النموذج اللاخطي مرة ثانية في مكان لا شيء يُلزمه فيه بالأول.","changelog.a830ff8ce227":"<strong>الأجهزة الستيريو التي كانت معطّلة لم تعد كذلك.</strong> كانت <code>Stance</code> و<code>Chamber</code> و<code>Foil</code> و<code>Coil</code> و<code>Shoal</code> و<code>Vault</code> تنتظر رسم تصيير بقناتين لا وقت أحد. ذلك الرسم هنا و<code>Stance</code> مبني؛ والخمسة الأخرى صارت ببساطة غير مكتوبة، مثل البقية.","changelog.e173fc848dc8":"<strong>لا يمكن إفلات إعداد سلسلة مسبق على مسار من مدير الملفات</strong>، ومكتبة الرفوف التي هو صيغتها (200 رف من صنع المطوّر) غير مكتوبة. المبني هو الصيغة والحفظ والاستدعاء والتحذيرات — والقائمة تطلب ملفًّا عبر نافذة حوار أصلية، وهي الطريق الوحيد الذي سيثق به هذا التطبيق.","changelog.0e86c6b10e81":"<strong>سلاسل الوصفات جهاز واحد.</strong> لصق واحدة على <em>مسار</em> لإنشاء الجهاز هو النصف الثاني من § F-18 وهو غير موصول: تقول المعاينة لأي جهاز هذا السطر ولا تعرض شيئًا، بدل أن تضيف شيئًا لم يطلبه المنتج.","changelog.6070503f26bb":"أُضيف — استضافة الإضافات (المرحلة 6)","changelog.4cdb78939a18":"<strong>يحمّل Oscillate إضافات VST 3 وCLAP التي تملكها سلفًا</strong>، كلٌّ منها في <strong>عملية خاصة بها</strong>. ⛔ الإضافة التي تنهار تجعل جهازًا واحدًا رماديًا واسمه ما زال عليه وزر <em>إعادة التحميل</em> بجانبه؛ ويستمر النقل في الدوران ولا يُمسّ المشروع.","changelog.f1ceb07e2c76":"⛔ <strong>الملف التنفيذي للتطبيق لا يستطيع تحميل إضافة على الإطلاق.</strong> تعيش المحمِّلات خلف ميزة Cargo لا يفعّلها إلا الملف التنفيذي لصندوق العزل — فالعملية التي تشغّلها لا تربط <code>dlopen</code> لملف <code>.vst3</code> أو <code>.clap</code> ولا تستطيع فتح واحد لو طُلب منها. هذه خاصية في البناء، لا قاعدة يتبعها أحد.","changelog.2cc3956eefdc":"⚠ تعمل الإضافة المستضافة <strong>متأخرة بكتلة واحدة</strong>، وهكذا يعمل كل مضيف خارج العملية — وتلك الكتلة <strong>تُضاف إلى التأخير الذي يُبلغ عنه الجهاز</strong>، فيكون التعويض عن التأخير الموجود فعلًا لا عن الذي ادّعته الإضافة.","changelog.d17de61edfa2":"<strong>فحص إضافات لا يجعلك تنتظر أبدًا.</strong> تُفتح كل إضافة في عملية مؤقتة بمهلة، وتقول اللوحة أي ملف تنظر إليه <strong>باسمه</strong>، وتواصل عملك خلاله. وكل ما قتل الفاحص مرتين يُوضع جانبًا — <strong>ظاهرًا</strong>، مع ما حدث وزر <em>إعادة المحاولة</em> — بدل أن يختفي بصمت من مجموعتك.","changelog.6b08669472c3":"<strong>أين يبحث Oscillate قرارك أنت.</strong> المجلدات القياسية للصيغ نفسها مسرودة على أنها كذلك، ويمكن إطفاؤها لا تحريرها، وتضيف حتى <strong>خمسة من مجلداتك</strong> عبر منتقي نظام التشغيل نفسه. ⛔ يُقال الحد بصوت عالٍ مع سببه — فالفحص يبدأ عملية لكل إضافة يجدها. والمجلد على قرص فصلته يُعرض مفقودًا و<strong>يُحتفظ به</strong>.","changelog.cc7e387cb175":"<strong>رف الأجهزة.</strong> بطاقة لكل جهاز، بترتيب السلسلة، تُظهر ما هو (<code>STOCK</code> أو <code>CLAP</code> أو <code>VST3</code>)، وإعداده المسبق، و<strong>كم تأخيرًا يكلّفك — بالعيّنات وبأجزاء الثانية</strong>. لا مضيف يُظهر ذلك جيدًا، والمنتج الذي يسجّل الغناء يحتاج إلى معرفة أي جهاز يكلّفه 40 ms.","changelog.3d1bb7f3c970":"<strong>التجاوز يُبقي الجهاز محمّلًا ويُبقي تأخيره معوَّضًا</strong>، فإطفاء أحدها لا يحرّك كل المسارات الأخرى بالنسبة إليه. هذا هو الفرق بين التجاوز والإزالة، وهو الفرق الذي يلاحظه الناس.","changelog.cccfa4d11c12":"<strong>الإزالة ضغطة تراجع واحدة، ويعود الجهاز بكل ما ضبطته.</strong> خسارة ساعة من الضبط الدقيق بسبب نقرة خاطئة أمر غير مقبول.","changelog.5d696b3bddc6":"<strong>أعد الترتيب بالسحب</strong>، والسلسلة التي لا يجوز أن يدخلها جهاز تقول <em>لماذا</em> — «جهاز النوتات يجب أن يأتي قبل الآلة» — بدل أن ترفض بصمت.","changelog.00a58d0258aa":"<strong>تعويض تأخير الإضافات، على مستوى الرسم البياني كله.</strong> كل نقطة جمع تسوّي ما يصل إليها، فالمسار الذي عليه معادل خطي الطور والمسار الذي ليس عليه شيء يقعان معًا. ⛔ مُثبت باختبار <strong>إلغاء</strong>: الإشارة نفسها عبر جهاز يُبلغ عن تأخيره وحوله، تلغي إحداهما الأخرى حتى الصمت <strong>التام</strong> — والاختبار نفسه مع إزالة التعويض، لإثبات أنه يقيس شيئًا.","changelog.97dfa8211a1f":"<strong>الإضافة غير الموجودة على هذا الجهاز تصبح عنصرًا نائبًا مسمّى</strong> يحتفظ بحالتها وأتمتتها ويعرض <em>تحديد الموقع…</em> — و<em>تحديد الموقع…</em> <strong>يتحقق</strong> من الملف الذي تشير إليه قبل الربط، بدل أن يُلحق إعداداتك بصمت بإضافة مختلفة.","changelog.32a11990f9cc":"<strong>التجميد والتثبيت في المكان</strong>، وهما عن قصد حركتان مختلفتان: التجميد يحرّر عمليات إضافات المسار وقابل للعكس تمامًا؛ والتثبيت يستبدل المقاطع ويزيل الأجهزة. ⛔ التجميد الذي لم يعد يطابق ما على المسار <strong>يُذاب</strong>، ولا يُعزف أبدًا — فسماع صوت الأمس أسوأ من عدم سماع شيء.","changelog.b470dbf6260c":"<strong>عُدّة مطابقة.</strong> يُقاد الملف التنفيذي المشحون لصندوق العزل عبر أنبوب حقيقي في كل تشغيل لـ CI — عليه أن يجيب، وأن يرفض كتلة عدائية دون أن يموت، وأن يسمّي إضافة غير موجودة — وتُحمَّل إضافات مجانية مثبّتة ببصمة SHA256 وتُوصف حيث تكون موجودة.","changelog.4e46ad2f60cf":"قانوني — ترخيص VST 3، مقروءًا لا مفترضًا (المرحلة 6)","changelog.f37a3bfa9028":"⛔ <strong>حزمة تطوير VST 3 من Steinberg مرخّصة بـ MIT</strong>، من الإصدار 3.8 فصاعدًا، ويدوّن <a href=\"https://freallyproducts.com/freally-oscillate/legal/vst3-sdk.md\"><code>docs/legal/vst3-sdk.md</code></a> نص الترخيص من داخل المراجعة المثبّتة — لا من مقال إخباري. مجانية، وقابلة للاستعمال في منتج مملوك، بلا تسجيل، والشرط الوحيد هو الإشعار.","changelog.744c22d64e93":"⛔ <strong>العلامة التجارية مدوّنة على حدة ومرفوضة.</strong> شعار VST اختياري بموجب MIT؛ وOscillate لا يشحنه، و«VST» لا تظهر في أي اسم منتج.","changelog.0bc06d4d7aba":"⛔ <strong>لذا لا توجد أي شيفرة C++ في هذا المستودع.</strong> الجسر الذي سمحت به خارطة الطريق غير مبني: روابط Rust تُشحن مولَّدة مسبقًا، فلا تُضمّ أي حزمة تطوير، ولا تُضاف أي سلسلة أدوات C++ إلى البناء، ولا إلى أيٍّ من مشغّلات CI الثلاثة.","changelog.5a58a9104716":"أُضيف — المحرّرات (المرحلة 5)","changelog.ed12a161eacd":"<strong>التوزيع يُعزف.</strong> تقرأ خطة التصيير مقاطع المشروع: المقطع الصوتي يتدفق من ملفه في مكانه على الخط الزمني، محترمًا إزاحة محتواه وتلاشييه وكسبه، مجموعًا في مساره. ⛔ تأتي العيّنات من القرص عبر حلقة يملؤها عامل — لا قراءة ملف على خيط الصوت أبدًا.","changelog.34bc614e709e":"<strong>لفّة البيانو.</strong> نوتات تُرسم وتُحرَّك ويُغيَّر حجمها وتُنقل طبقتها وتُحذف بالحركات نفسها التي يستعملها التوزيع؛ ومسار شدة؛ ومسارات وحدات تحكم ترسم عبرها منحنى، حيث <strong>المسحة الواحدة ضغطة تراجع واحدة</strong>؛ ومقام للمشروع يطوي الصفوف الخارجة عنه.","changelog.fe21807f67ce":"<strong>محرّر المقاطع الصوتية.</strong> انقر نقرًا مزدوجًا على مقطع صوتي فيُفتح، أخيرًا — بموجته الخاصة وتكبيره الخاص، <strong>حتى مستوى العيّنة</strong>: تحت دقة ذاكرة الذُّرى المؤقتة في التوزيع تُقرأ العيّنات من الملف للنافذة الظاهرة على الشاشة.","changelog.63b986567a23":"<strong>غلاف كسب للمقطع</strong> يُرسم فوق الموجة. ⛔ عنصر تحكم ثالث، منفصل عن الكسب الثابت للمقطع وعن أتمتة المسار — ثلاثة أشياء يخلط معظم برامج DAW بين اثنين منها على الأقل — فتستطيع خفض كلمة واحدة من الغناء دون لمس أي شيء آخر.","changelog.b554f646f97e":"<strong>مقابض التلاشي والحافتان كلتاهما</strong>، وهي عمليات التوزيع نفسها لا مجموعة ثانية قد تخالفها.","changelog.0c638649fa35":"<strong>العكس، وتوحيد المستوى، وإسكات تحديد، وإزالة إزاحة التيار المستمر.</strong> ⛔ كلٌّ منها <strong>غير هدّام</strong>: إنها حقول على المقطع، في سجل التراجع، لا إعادة كتابة للملف أبدًا. مكتبة عيّناتك ليست لنا لنحرّرها.","changelog.abbe7944b38f":"رأس التشغيل فوق الموجة أثناء العزف، ونطاق تسحبه لإسكاته.","changelog.c377ccf80966":"<strong>سبعة تحويلات للنوتات</strong>، كلٌّ منها ضغطة واحدة وضغطة تراجع واحدة: القلب، والعكس، والتمديد، والليجاتو، والتكميم، والأنسنة، والنقل إلى المقام.","changelog.4baac0375406":"⛔ <strong>للتكميم قوة، لا مفتاح.</strong> عند نصف القوة تتحرك النوتة نصف المسافة إلى الشبكة — وهكذا تشدّ لقطة دون تسطيح الأداء الذي جعلها جديرة بالاحتفاظ. والتأرجح (swing) يدفع النبضات الضعيفة فقط.","changelog.b6bb8b6037c9":"⛔ <strong>الأنسنة قابلة للإعادة.</strong> العشوائية مبذورة والبذرة جزء من العملية، فالجلسة نفسها مفتوحة على جهاز آخر — أو معادة من سجلها الخاص — تعيد الموسيقى نفسها.","changelog.1eb70df10591":"⚠ لخمسة منها اختصار لوحة مفاتيح. أما القلب والتمديد فلا: يحتاجان إلى رقم، والمفتاح الذي يخمّنه سيفعل الشيء الخطأ بسرعة.","changelog.8c457c75ee5d":"<strong>قاعدة واحدة تقرر أي محرّر يُفتح</strong>، في مكان واحد: مقطع MIDI يفتح لفّة البيانو، والمقطع الصوتي يفتح محرّر الموجة، ومقطع MIDI على مسار طبول يفتح شبكة الإيقاع.","changelog.b620599ca4c1":"<strong>شبكة الإيقاع.</strong> المقطع على مسار علّمته طقمًا يُفتح شبكةً من المسارات لا لفّة بيانو — مسار لكل صوت، مسمّى، والشدة في التظليل، وكتم لكل مسار و<strong>مجموعات خنق</strong> فيوقف الهاي هات المغلق المفتوح. ⛔ كونه طقمًا خاصية للمسار، وهذا ما تعنيه حين تقول <em>«مسار الطبول الخاص بي»</em>.","changelog.8f31cc77fb13":"<strong>مسارات أتمتة لكل معامل.</strong> أدوات الرسم والقلم والخط والمنحنى؛ وأوضاع القراءة والكتابة والمزلاج واللمس؛ ومقبض منحنى على كل نقطة. ⛔ إنها <strong>بدقة العيّنة</strong>: يُخبَر المحرّك أين يقع كل امتداد من الكتلة على الخط الزمني، فيُمسح المنحنى بشكل صحيح حتى عبر نقطة تكرار تقع في منتصف مخزن مؤقت.","changelog.cf94d06807a3":"<strong>الكاتا — منحنى تستطيع تسميته وإعادة استعماله.</strong> اطبع شكلًا في أي مكان، بمقداره وإزاحته وتباينه الخاص؛ وحرّر الشكل فـ <strong>يتبعه كل طبع</strong>، لأن الطبع مرجع لا نسخة. ⚠ التباين مبذور، فتبدو الجلسة غدًا كما هي.","changelog.06c1460a5f20":"<strong>التجميع بمسارات اللقطات.</strong> سجّل فوق جزء كم شئت من المرات: كل لقطة تحتفظ بمسارها ولا يُكتب فوق شيء. امسح عبر المسارات لتختار أي لقطة تُعزف أين، والوصلات <strong>تلاشيات متقاطعة حقيقية</strong> — تُقرأ اللقطتان وتُمزجان بقدرة متساوية، فلا ينخفض المستوى في منتصف كل وصلة.","changelog.aee6a60fece3":"<strong>اللقطات الظلّية.</strong> اللقطة التي لم تخترها لا تُحذف أبدًا. تنطوي في مسار شبحي وتبقى في الملف حتى تحذف تلك اللقطة صراحةً.","changelog.b74811a88c81":"<strong>القَطْع.</strong> ارسم ضربة نصل عبر التوزيع فينشق كل مقطع تعبره حيث عبرته — و<strong>زاوية الضربة هي التلاشي المتقاطع</strong>: الحادة قطع صارم، والمائلة مزج طويل، والطول بأجزاء الثانية يظهر أثناء الرسم. ⛔ الضربة كلها ضغطة تراجع واحدة.","changelog.ff38926dc74b":"<strong>إرجاع الجلسة.</strong> خط زمني ثانٍ — لا للأغنية، بل للجلسة. اسحبه وشاهد التوزيع يعيد بناء نفسه إلى الوراء. ⛔ <strong>التمرير عرض</strong>: لا يتغير شيء حتى تختار أحد الأشياء الثلاثة المعروضة حين تُفلت — العودة إلى الآن، أو التراجع إلى هنا، أو <strong>التفريع</strong>، الذي يشقّ المشروع من تلك اللحظة ويحتفظ بالاثنين.","changelog.23b8f03491d7":"<strong>لوحات تستطيع سحبها إلى شاشة ثانية.</strong> مستعرض الملفات والمولّدات والمحرّر والمازج والغرفة، كلٌّ منها يُفتح في نافذة خاصة به، بشريط عنوان خاص وشريط حالة خاص. ⛔ كل نافذة تُظهر الجلسة نفسها: التعديل الذي يُجرى في إحداها يظهر فيها كلها، والمسار الذي تحدده في المازج المنفصل هو المسار المحدد في التوزيع، والنقر المزدوج على مقطع يفتحه في النافذة التي فيها المحرّر أيًّا كانت. ⚠ إغلاق لوحة منفصلة يعيدها إلى حيث كانت بدل أن يدمّرها، واللوحات تعود دائمًا داخل التطبيق عند إعادة التشغيل — فالنافذة المستعادة على شاشة فصلتها نافذة لا تستطيع بلوغها.","changelog.8076f4c7a582":"<strong>المقطع يستطيع التكرار ليملأ طوله.</strong> كان الحقل في الملف منذ المرحلة 3، وكان التوزيع يرسم علامات التكرار منذ المرحلة 4؛ والآن هناك زر، في المحرّرين كليهما، والمادة تتكرر فعلًا.","changelog.01bd16d5c3eb":"<strong>اعثر على الضربات في لقطة.</strong> ضغطة واحدة تعلّم كل عابر على الموجة — حيث يقطع المنتج، أو يحاذي إلى الشبكة، أو يقصّ إلى أول نوتة.","changelog.939938b1052f":"<strong>مقاطع MIDI مجدولة.</strong> نوتات النمط تبلغ خيط الصوت، على نبضتها، منقولة الطبقة بحسب الموضع الذي تقع فيه. ⚠ لا يوجد شيء بعد في نهاية التيار ليُصدرها — الآلات في المرحلة 7 — لكن المجدوِل موجود ومُثبت، وهذا ما يمنع تلك المرحلة من اكتشاف أنها تحتاج إلى واحد.","changelog.e12f1a9c473b":"<strong>الملف المسجّل بمعدل عيّنات مختلف عن الجلسة يُعزف الآن بالسرعة الصحيحة.</strong> كانت عيّنة 44.1 kHz في جلسة 48 kHz تخرج أعلى بنحو نصف درجة ونصف وأقصر بـ 9 %، دون أي شيء يقول السبب. ⛔ التحويل مُستكمِل sinc بنافذة يرشّح إلى أدنى ترددَي Nyquist قبل التقليص، فلا ينطوي شيء عائدًا إلى النطاق الذي تسمعه. ⚠ ما زال المحرّر يخبرك بالرقمين: الملف المعاد اعتيانه ليس ملفًّا أصليًا، وإن كنت تطارد آخر نصف ديسيبل في ماستر فمن حقك أن تعرف أي مصادرك تُحوَّل.","changelog.f8e6e5b55387":"أُصلح — ⛔⛔ القائمة كلها كانت بعيدة المنال (المرحلة 7)","changelog.7645fca08728":"<strong>أربعة وخمسون جهازًا، ولوحاتها، ومنحنياتها، وسلاسل وصفاتها — كلها مبنية، وكلها مختبرة، وليس واحد منها في المتصفح.</strong> لم يكن المنتج يستطيع إضافة جهاز واحد من أجهزة Oscillate الخاصة إلى مسار.","changelog.1599669c8454":"▶ يسرد متصفح الإضافات ما وجده <strong>الفاحص</strong> على القرص، والجهاز المرفق مترجم داخل الملف التنفيذي لا مفحوص — <code>scan::describe_one</code> يرفضه باسمه. لم يضع شيء القائمة في ذلك الفهرس قط، فكان <code>device_add</code> يجيب <em>«لا توجد إضافة مفحوصة بالمعرّف hilt»</em> عن كل واحد من الخمسة والسبعين، ولم تُظهر القائمة أيًّا منها. ⚠ <strong>كانت كل بوابة أخرى خضراء</strong>، لأن كل بوابة أخرى سألت هل <em>يعمل</em> الجهاز. ولم تسأل أيٌّ منها هل يستطيع أحد بلوغه.","changelog.268e4269f385":"⛔ <strong>إنها المرة الخامسة التي يشحن فيها هذا المشروع آلية كاملة لا شيء يستدعيها</strong>، والمرة الخامسة التي كان السؤال الذي وجدها هو نفسه: <em>ما الذي سيضغطه المنتج فعلًا؟</em> البوابات الجديدة في <code>plugins::browser</code> تطرحه — كل جهاز في القائمة موجود في المتصفح، والجهاز المرفق يمكن فعلًا إضافته إلى مسار، والقائمة تأتي أولًا والفحص لا يضيع — والثلاث كلها رُئيت تفشل أمام هذا بالضبط.","changelog.54f680c853bb":"⚠ <strong>نصف ثانٍ، في الواجهة.</strong> كانت شارة الصيغة <code>format === 'vst3' ? 'VST3' : 'CLAP'</code> — تعبيرًا بفرعين فوق نوع بثلاثة متغيّرات، فكان كل جهاز من أجهزة Oscillate الخاصة سيوسم <strong>CLAP</strong> لحظة بلوغه القائمة. صارت الآن جدول بحث، فالصيغة الرابعة خطأ ترجمة لا الفرع الخاسر أيًّا كان.","changelog.73c54b400c47":"⚠ <strong>وعيب بلوغ ثانٍ تحته: لم يكن المتصفح يستطيع البحث فيها.</strong> § 1 صريح — <em>«فهرس البحث على ذلك العمود ليس اختياريًا؛ إنه الشيء الوحيد الذي يجعل الاسم الموحي قابلًا للاستعمال، وشحن الأسماء بدونه يجعل المجموعة كلها أسوأ من الأسماء العامة»</em> — وكان المرشّح يقرأ الاسم والمورّد فقط. <code>Vise</code> ضاغط ولا شيء في الكلمة يقول ذلك. صار الجهاز يحمل ما هو عبر الوصلة والبحث ينظر إليه، فكتابة «compressor» تجده.","changelog.9df0131b255e":"⚠ <strong>الذاكرة المؤقتة لا تحمل القائمة أبدًا.</strong> إنها خاصية للبناء، لا للجهاز: فالذاكرة المؤقتة التي كتبتها نسخة وقرأتها أخرى ستُحيي أجهزة لم تعد موجودة، وسيعرض المتصفح جهازًا يجيب عنه السجل بـ <code>None</code>.","changelog.51ab50580236":"أُصلح — ثلاث بوابات كانت تراقب الشيء الخطأ (المرحلة 7)","changelog.3b4ddbdf23f0":"⛔⛔ <strong>كان نوعا Rust يكتبان ملف TypeScript واحدًا، ولم تستطع بوابة الروابط رؤية ذلك.</strong> كان <code>oscillate_dsp::device::Domain</code> و<code>oscillate_project::track::Domain</code> كلاهما يولّدان <code>src/bindings/Domain.ts</code>، فـ <strong>الحزمة التي تشغّل اختباراتها أخيرًا هي التي تفوز</strong> — كانت شجرة العمل تومض، وكان الفحص يُبلغ عن انجراف في شجرة لم يلمسها أحد. ⚠ <strong>أزال الإصلاح الأول <code>export</code> من إحدى الحزمتين وبدا أنه نجح</strong>، لأن الترتيب صادف أن يفضّل المشروع؛ ثم عاد في المرة التالية التي شُغّل فيها اختبار <code>oscillate-dsp</code> أخيرًا. يكتب ts-rs النوع كلما استطاع أي شيء مُصدَّر بلوغه، و<code>DeviceSpec</code> المُصدَّر يحمل <code>domain</code>. ▶ نوع معالجة الإشارة صار الآن <code>DeviceDomain</code> في TypeScript، و<strong><code>check-bindings</code> يرفض أي نوعين مُصدَّرين سيقعان على مسار واحد</strong> — رُئي يفشل أمام هذا العيب بالضبط. وما كانت تلك البوابة ستُبلغ عنه في النهاية هو <em>عدم</em> وجود انجراف في شجرة تغيّرت فعلًا.","changelog.88e9c9b494b0":"⛔ <strong>كان إعداد السلسلة المسبق يُكتب بـ <code>fs::write</code>.</strong> يقول <code>SECURITY.md</code> إن Oscillate يكتب بجانب الهدف بـ <code>O_EXCL</code> ثم يعيد التسمية فوقه — فيُرفض الرابط الرمزي المزروع حيث سيوضع ملف بدل الكتابة عبره — ولم يكن لذلك إلا تنفيذ واحد بالضبط، داخل حفظ المشروع. والكاتب الثاني لم يكن فيه شيء من ذلك. ▶ صار <code>io::write_atomic</code> هو ذلك التنفيذ، والمستدعيان كلاهما يمران عبره.","changelog.786d25e6f7a0":"⚠ <strong>كانت بوابة اللغات تسمّي صيغة جمع مُعلنة بشكل صحيح مفتاحًا مفقودًا.</strong> يحلّ i18next الاستدعاء <code>t('a.b', { count })</code> عبر <code>a.b_one</code> و<code>a.b_other</code> ولا يحلّه أبدًا عبر <code>a.b</code>. صارت البوابة تفهم ذلك و<strong>تطلب الصيغتين كلتيهما</strong> — فالمفتاح الذي ليس له إلا <code>_other</code> يُعرض كالمفتاح نفسه عند العدد واحد، وهذا بالضبط الإخفاق الذي وُجدت لالتقاطه، لكنه أصعب رؤية.","changelog.36ca4917ed10":"أُصلح — قبل أن يُشحن أي شيء مما سبق","changelog.c7dcd3ccbb44":"⚠ كل واحد من هذه وُجد بمراجعة بوابة المرحلة 5 أو بقيادة التطبيق المبني، وكان كل واحد منها أخضر في مجموعة الاختبارات أولًا.","changelog.4c94ae2428be":"<strong>كان التوزيع يصمت لحظة ضغطك على التشغيل.</strong> تمريرة تحدّث الأتمتة أثناء دوران النقل كانت تستبدل خطة التصيير خمسين مرة في الثانية بخطة لا مقاطع ملحقة بها.","changelog.151aee7757e6":"<strong>اللوحات المنفصلة على شاشة ثانية لم تكن تستطيع رؤية الجلسة.</strong> كل نافذة متصفح صغير خاص بها مع نسختها الخاصة من كل شيء، ولم يكن شيء يخبر الأخريات حين يتغير شيء.","changelog.58bfb47479c3":"<strong>كان فصل لوحة قادرًا على تعليق التطبيق</strong>، وكان المشروع الجديد يُفتح على نافذة مليئة باللوحات الفارغة.","changelog.87b86fb5cfb4":"<strong>كان الملف الذي فيه أكثر من قناتين يتلعثم</strong>، وكان قادرًا على إيقاف كل التشغيل بقية الجلسة إن ضُبط المقطع على التكرار.","changelog.665dfeb7d79e":"<strong>الأتمتة المرسومة في وقت متأخر من الجلسة كانت تُعزف بالمستوى الخطأ</strong> وتتدرّج بدل أن تنساب — صحيحة في أول الأغنية، وخاطئة في كل مكان آخر.","changelog.fe41509c874e":"<strong>الكاتا المطبوعة لم تكن تُسمع ولا تُرسم</strong>، رغم أنها كانت تُحفظ وتُعدّ.","changelog.f0c60af56408":"<strong>النوتات التي بعد نوتة طويلة لم تكن تُعزف.</strong> النوتة الممسوكة في أول المازورة كانت تحجب كل ما خلفها حتى تنتهي.","changelog.313751e2faad":"<strong>معظم وصلات التجميع كانت قطعًا حادًا</strong> بدل التلاشي المتقاطع الذي ضبطته.","changelog.e084958ed56f":"<strong>علامات العابرات على مقطع مقصوص</strong> كانت ستكون في المكان الخطأ.","changelog.14f8ce6b8a19":"أُضيف — التوزيع (المرحلة 4)","changelog.b6922d007ca3":"<strong>عرض التوزيع.</strong> خط زمني تستطيع العمل فيه: مسطرة بالمازورات والنبضات، وشبكة تتبع التكبير، ومقاطع مرسومة من محتواها، ورؤوس مسارات على الجانب. التكبير لوغاريتمي ومرتكز تحت المؤشر، فتبقى المازورة التي تنظر إليها حيث تنظر.","changelog.7cae614909e8":"<strong>مقاطع مرسومة مما هي عليه فعلًا.</strong> المقطع الصوتي يرسم موجته الحقيقية من ملف ذُرى مخزّن مؤقتًا؛ ومقطع MIDI يرسم نوتاته، عند الطبقات التي فيه. ⛔ المقطع الذي لم يصل محتواه بعد يرسم جسمه ولا شيء غيره — فالموجة النائبة كذبة عن الصوت.","changelog.b6e510719661":"<strong>النقل والنسخ والقص والتقسيم والتلاشي والكتم والتكرار وإعادة التسمية وإعادة التلوين</strong>، و<strong>كلٌّ منها ضغطة تراجع واحدة</strong> مهما بلغ عدد المقاطع التي مسّها. السحب مع <code>Alt</code> ينسخ. القص من أي حافة؛ والمادة تتحرك مع الحافة بدل أن تنزلق تحتها. والنصل يقطع كل المقاطع المحددة بضربة واحدة.","changelog.a21fb8951d11":"<strong>رأس التشغيل.</strong> خط سماوي — اللون الوحيد المحجوز لـ <em>الآن</em> — يُرسم من الموضع الذي <strong>بلغه فعلًا</strong> خيط الصوت، ستين مرة في الثانية. ⛔ لا يُستكمَل أبدًا قبل المحرّك: رأس التشغيل الذي يتنبأ يخطئ كلما تأخر مخزن مؤقت، ويبدو كأن الصوت يتلعثم وهو لا يتلعثم. انقر المسطرة لتحديد الموضع، واسحب للتمرير.","changelog.0132a0a5cc57":"<strong>خط زمني ينمو.</strong> تمتد المسطرة حين تضع محتوى قرب نهايتها، وتستطيع سحب علامة النهاية أبعد يدويًا. ⛔ السقف <strong>ساعتان</strong>، يُقال بصوت عالٍ في شريط الأدوات ويُبلَّغ عنه حين تبلغه — لا إفلات لا يفعل شيئًا بصمت أبدًا.","changelog.261a9999d38c":"<strong>مجموعات المسارات.</strong> اسحب رأس مسار إلى مجموعة فينطوي فيها. ⛔ المجموعة ناقل حقيقي بمنزلقه وسلسلته الخاصة، فكتمها يُسكت كل ما فيها — لا مجرد تسهيل في الرسم.","changelog.e3f13607ab34":"<strong>العلامات وقوس التكرار والإيقاع والميزان</strong>، كلها على الخط الزمني لا في نافذة حوار. اسحب المسطرة مع <code>Alt</code> لترسم تكرارًا.","changelog.67e7decaa422":"<strong>المحاذاة</strong>، بما فيها <em>التكيّفية</em> — الشبكة تتبع التكبير، فتكون دائمًا أدق قسمة تستطيع رؤيتها فعلًا.","changelog.7bdf979c3936":"<strong>200 مسار × 2 000 مقطع.</strong> مقيس لا مُدّعى: شاشة كاملة من مشروع فيه 400 000 مقطع تُجاب في <strong>2.4 ms</strong> مقابل إطار مدته 16 ms.","changelog.a04b02adb5a0":"أُضيف — المازج يصبح جزءًا من المشروع","changelog.aa23b1e78aec":"<strong>كل عنصر تحكم في المازج صار تغييرًا قابلًا للتراجع.</strong> تحريك المنزلق، والكتم، والإفراد، والتجهيز للتسجيل، واختيار الدخل، وإعادة التسمية، كلها تدخل سجل العمليات والملف وسجل الأعطال — لأن المسار كيان من كيانات <strong>المشروع</strong> والمازج إسقاط له. ⛔ قبل هذا لم يكن أي شيء في الواجهة يعتمد عملية على الإطلاق: كان التراجع والإعادة رماديين دائمًا، ولم يكن عرض الاستعادة يستطيع الظهور أبدًا.","changelog.5800eedeca12":"<strong>حدّد شريطًا واضغط <code>Delete</code></strong> لإزالة ذلك المسار وكل ما عليه، بضغطة تراجع واحدة. ينتقل التحديد إلى المسار التالي. ⛔ لا يمكن حذف الماستر.","changelog.092073003d57":"<strong>اسحب الأشرطة لإعادة ترتيبها</strong>، بضغطة تراجع واحدة. الترتيب ترتيب المشروع، فيتفق المازج والتوزيع والملف المحفوظ دائمًا.","changelog.c53e20e0fcf2":"<strong>منزلق الماستر يُحفظ.</strong> كان عنصر التحكم الوحيد في المازج الذي لا يُتراجع عنه ولا يُكتب في الملف — فالجلسة الممزوجة عند −3 dB كانت تُفتح عند الوحدة صباح اليوم التالي.","changelog.f754a89b56d9":"<strong>انقر نقرًا مزدوجًا على اسم الشريط لإعادة تسمية المسار.</strong>","changelog.71651e6922dd":"أُضيف — شريط النقل","changelog.151c030e6fd3":"<strong>يبدأ التسجيل عند الضغط ويتوقف عند الضغط</strong>، والضغط على التسجيل مرة أخرى يطفئه. ⛔ <strong>لا يوجد عدّ تمهيدي ما لم تفعّله</strong> في الإعدادات ← التسجيل، حيث يعرض 3–5 ثوانٍ أو 1–4 مازورات.","changelog.13a415817735":"<strong>التشغيل والإيقاف والتسجيل والتجهيز والدخل والكتم والإفراد، كلها تجيب فورًا.</strong> كل ضغطة رحلة ذهاب وعودة واحدة بدل اثنتين، والزر يقرّ بالضغطة بينما جواب المحرّك في الطريق. ⛔ ما <em>يرسمه</em> هو ما زال ما نشره المحرّك — فالإقرار بالضغطة، لا ادّعاء بشأن الصوت أبدًا.","changelog.4aa204616e75":"<strong>انتقل شريط النقل من المازج</strong> ليجلس فوق التوزيع، فلم يعد إخفاء لوحة المازج يخفي زر التشغيل.","changelog.6e24c576ac39":"<strong>النقر المزدوج على ملف <code>.oscillate</code> يفتحه</strong>، سواء كان Oscillate يعمل سلفًا أم لا.","changelog.174b3ab19a0f":"**كان شريط الحالة يقول <em>الغرض</em> من اللوحة فوق شريط عنوانها فقط.** وعلى بُعد بكسل واحد تحت العنوان كان يعود إلى جملة الخمول. وهو الآن يقرأ الشيء نفسه من أي مكان داخل المنطقة.","changelog.4b361ad48ca4":"<strong>كان منزلق المازج يبدو كمربع.</strong> كان غطاؤه بلون الشريط خلفه نفسه، فلم يكن لعنصر التحكم حافة في نصفه السفلي. صار له الآن أخدود، وغطاء بمقبض، ومقياس — والتباين <strong>مقيس</strong> مقابل كل خلفية في السمتين كلتيهما لا مقدَّر بالعين.","changelog.3fe647a29dfd":"<strong>الفأرة الساكنة كانت تُسكت لوحة المفاتيح.</strong> مع التلميحات على لوحات كاملة، كانت الفأرة المتروكة في أي مكان من النافذة تتقدم على لوحة المفاتيح بقية الجلسة — فارغًا تمامًا للناس الذين يحتاجون شريط الحالة أكثر من غيرهم. الآن تجيب الحركة التي تحركت <em>أخيرًا</em>.","changelog.d4042456dc28":"أُضيف — التسجيل، كما يعمل المنتج فعلًا (2026-08-26 و27)","changelog.27cea337b5fa":"<strong>اللقطة المنتهية تصبح مقطعًا على المسار المجهَّز.</strong> كانت تكتب <code>.wav</code>، وتُبلغ عن مكانه، وتترك الخط الزمني فارغًا.","changelog.a05ec14dab99":"<strong>كل لقطة مقطع خاص بها</strong>، ولقطتان متتاليتان تقعان كلتاهما — فتكون مادة التجميع موجودة بدل أن تحل لقطة محل أخرى بهدوء على القرص.","changelog.063bae2b2031":"<strong>اللقطة الجديدة تحل محل ما تغطيه.</strong> ادخل بالتسجيل الفوري فوق لقطة موجودة فيتوقف الصوت القديم تمامًا حيث تبدأ الجديدة. ⛔ <strong>لا شيء يُدمَّر</strong>: المقاطع المُزاحة تُقصّ وتُقسم، وكل عيّنة تبقى في ملف مصدرها، وضغطة تراجع واحدة تعيد كل شيء.","changelog.e3c8ed4616e6":"<strong>الموجة تُرسم وأنت تغنّي</strong>، تنمو تحت رأس التشغيل — من الذروة المقيسة في المحرّك نفسه، فلا يستطيع ما تشاهده والمستوى على شريطك أن يختلفا. واللقطة الصامتة ما زالت ترسم مقطعها، بطوله الحقيقي.","changelog.f76d7ffb3369":"<strong>المترونوم يُصدر صوتًا.</strong> كان له إعداد في المشروع، وعملية، وراية في المحرّك، ولا مسار يربط أيًّا منها — كانت النقرات تُحسب في كل كتلة ولا يقرؤها شيء. الآن هناك صوت، ومفتاح في شريط النقل، وعدّ تمهيدي تستطيع سماعه.","changelog.f3d9577ce851":"<strong>عدّ تمهيدي تستطيع رؤيته.</strong> الثواني المتبقية قبل بدء التسجيل تُعرض حيث تستطيع التقاطها بطرف عينك، يعدّها خيط الصوت لا مؤقّت في الصفحة.","changelog.517bce56ac3a":"<strong>التوزيع يقول أين رأس التشغيل</strong> — المازورة والنبضة، والوقت، وأين ينتهي المسار، وسقف الساعتين. كان يقول فقط كم طول المشروع.","changelog.12429092771c":"<strong>تحديد واحد للمسار عبر المازج والتوزيع</strong>، فلا يستطيع التسجيل أن يلتقط في مسار لم تكن تنظر إليه.","changelog.7a13f6667cf5":"<strong>الإيقاف مرتين يعيد رأس التشغيل إلى البداية.</strong>","changelog.a74f61c309b9":"<strong>التلاشيات لا تتقاطع.</strong> سحب التلاشي الداخل إلى ما بعد التلاشي الخارج ينحصر عند المساحة التي يتركها الآخر.","changelog.5635048c1c6c":"<strong>أسماء المسارات محدودة ومقروءة.</strong> تعطي رؤوس التوزيع الاسم سطرًا خاصًا به — فستة أزرار بحجم 24 px في رأس بعرض 196 px كانت قد تركت له نحو عشرة.","changelog.ae173857b667":"أُضيف — عناصر تحكم النقل التي يمدّ المنتج يده إليها (2026-08-27)","changelog.6434635375f9":"<strong>مترونوم تستطيع مشاهدته.</strong> حرف <code>M</code> <strong>بين</strong> نقطتين، والتعبئة تنتقل من واحدة إلى الأخرى في كل نبضة، فيُقرأ الزوج كيد قائد أوركسترا لا كضوء يومض. ⚠ النقطتان بحجم زر التسجيل وتقفزان بدل أن تخفتا — فالنبضة لحظة، والمترونوم الذي يتدرج إليها يبدو متأخرًا حتى حين تكون النقرة في وقتها تمامًا. ⚠ مرسوم من النبضة التي بلغها خيط الصوت فعلًا — فالمؤقّت بسرعة الإيقاع ينجرف عن المحرّك خلال ثوانٍ، والمترونوم الذي يخالف ما تسمعه أسوأ من غيابه.","changelog.a2c66155342b":"<strong>قوس تكرار تستطيع العمل به.</strong> هناك واحد سلفًا حين يُفتح المشروع — من المازورة 1 إلى المازورة 5، مطفأ — فلا تحتاج أبدًا إلى اكتشاف كيف تصنعه. اسحب الموصل فينزلق التكرار كله محتفظًا بطوله؛ واسحب أيًّا من المقبضين فلا يتحرك إلا ذلك الطرف. ⛔ <strong>لا يمكن أن يتقاطعا أبدًا</strong>: كلٌّ منهما ينحصر عند مازورة واحدة <em>من الميزان السائد حيث هو</em>. النقر مع <code>Ctrl</code>/<code>Cmd</code> يفعّل التكرار ويطفئه، وكلٌّ من ذلك ضغطة تراجع واحدة.","changelog.8f16d426462b":"<strong>انقر في أي مكان من التوزيع لتضع رأس التشغيل هناك</strong>، لا على المسطرة ذات الـ 24 بكسل فقط. ⚠ السحب ما زال تحديدًا مستطيلًا — ويُميَّز بينهما بتحرك المؤشر أو عدمه.","changelog.ae32226c7f3d":"<strong>الميزان قابل للتحرير</strong>، بجانب الإيقاع حيث مكانه. هو في النموذج منذ المرحلة 3، وقرأه <code>bars.ts</code> ورسمته المسطرة، ولم يكن في الواجهة ما يستطيع تغييره.","changelog.22ad9b3d722f":"أُصلح — الوصلات التي وجدتها ثلاث مراجعات (2026-08-27)","changelog.fa4907a02da4":"<strong>كانت تعديلات الحركة اللاحقة يُتحقَّق منها مقابل المشروع كما كان قبل تعديلاتها السابقة.</strong> وما إن أُصلح ذلك حتى صار قصّ الحافة اليسرى لمقطع ينتهي عند سقف الساعتين مرفوضًا: فالحالة الوسيطة كانت تتجاوز النهاية مع أن الحالة النهائية لم تكن تتجاوزها.","changelog.1bba613b10b9":"<strong>كانت شبكة المحاذاة تتجاهل كل تغيير في الميزان بعد الأول.</strong> الجلسة التي تنتقل إلى 6/8 عند المازورة 33 كانت تحاذي بقية التوزيع إلى مازورات 4/4 — وحتى الشبكة الصحيحة كانت تُعدّ من النبضة صفر لا من حيث تغيّر الميزان، فكانت المقاطع تقع بين خطوط المازورات التي تراها.","changelog.3a0c33b3e6b3":"<strong>كان التمرير السريع قادرًا على ترك الخط الزمني يُظهر مازورات مرّرت بعيدًا عنها سلفًا</strong>، ويدّعي أنه حمّل مازورات لم يحمّلها قط.","changelog.8597dcaebff6":"<strong>كانت أشرطة الصفوف تنقلب أثناء التمرير</strong>، مع أنها موجودة لتتبّع الصفوف.","changelog.3bb4cc884f29":"<strong>سحب ارتفاع المسار الملغى كان يترك الرأس بالحجم الخطأ</strong> بقية الجلسة.","changelog.0673ae95a689":"<strong>كان سجل الاستعادة قادرًا على التخلص بصمت من كل ما بعد سجلّ كبير الحجم</strong> والإبلاغ عن الملف بوصفه اقتطاعًا عاديًا بسبب عطل.","changelog.c2949c578495":"<strong>ملف <code>.wav</code> يحمل كتلة <code>LIST</code> أو <code>fact</code> أو <code>PAD </code> فارغة قبل <code>fmt </code> كان يُرفض على أنه مقتطع</strong> — بلا موجة، والمقطع يعزف صمتًا.","changelog.6e0584e53a87":"<strong>الرد ذو الشكل الخاطئ كان يُسقط النافذة</strong> بدل أن يُرفض.","changelog.3b546441830b":"<strong>هدف إفلات الملفات في التوزيع</strong>، الذي لم يكن ليعمل أبدًا. عرض الويب لا يرى سحب الملفات أبدًا — Tauri يملك الإفلات — وحتى لو رآه، فالمسار الذي توفره الصفحة هو بالضبط الشيء الذي يرفض هذا المنتج قبوله. ⚠ استيراد الصوت غير متأثر: يمكن بلوغه عبر منتقي الملفات. والإفلات الحقيقي يجب أن يُعالج في Rust، وهذا قرار تصميم لا إصلاح خطأ.","changelog.ae0e37ba6be2":"أُصلح — ما وجدته بوابة المرحلة بقيادة التطبيق المبني","changelog.bbbc9059eb60":"⚠ كل واحد من هذه نجح في مجموعة الاختبارات كاملة وفشل في يدي منتج. وُجدت بقيادة <strong>الملف التنفيذي للإصدار</strong> لا بناء معاينة، وهذا ما وُجدت له التمريرة العملية في البوابة.","changelog.84a878dc90df":"⛔ <strong>كان تعديل المازج غير مرئي للتراجع، ولعلامة التغييرات غير المحفوظة.</strong> إضافة مسار كانت تضع شريطًا في الرف ولا تصل إلى شيء آخر — بقي <code>File ▸ Undo</code> رماديًا، ولم تضئ نقطة التغيير قط، وظلت رؤوس المسارات في التوزيع تُظهر المسارات السابقة. <strong>المنتج الذي قضى جلسة في المازج ثم خرج لم يُخبَر قط أن لديه عملًا غير محفوظ.</strong> كل أمر يغيّر المشروع يجيب الآن بالوصلة كاملة.","changelog.b91883d78df0":"⛔ <strong>كان التراجع يرمي استثناءً، ولا يفعل شيئًا.</strong> كانت <code>project_undo</code> و<code>project_open</code> و<code>project_new</code> و<code>project_save</code> تجيب بملخص مجرد بينما تتوقع الواجهة الأمامية الوصلة كاملة، ففشل التراجع بصمت داخل الشيفرة التي تطبّقه. وفتح مشروع لم يكن يعيد قراءة المازج من مسارات المشروع الجديد قط.","changelog.ebd08c2bb97b":"⛔ <strong>كان <code>File ▸ Undo</code> يُقرأ <code>Undo {{gesture}}</code>.</strong> حين لا يوجد ما يُتراجع عنه، كانت القائمة ترسم قالبها الخاص. هناك الآن وسم منفصل في اللغات الثماني عشرة كلها — فالاستكمال الفارغ لا يكفي، ويترك نقطتين معلّقتين في الروسية وأداة يتيمة في اليابانية.","changelog.b0798ca992b8":"⛔ <strong>كل منزلق في المازج كان يرسم مقياسه بلا علامة الوحدة.</strong> كانت الوحدة تُطابق مع موضع ثابت في المقياس بمساواة الأعداد العائمة، والمازج يحسب موضعه الخاص من مدى الحركة، فلم يتطابق شيء قط. العلامة تُرسم الآن <strong>عند</strong> الوحدة لا عند أقرب تدريجة، وهذا يصلح أيضًا المنزلقات التي تقع وحدتها بعيدًا عن أي تدريجة.","changelog.bca525a074d9":"<strong>العدّ التمهيدي لم يكن يبلغ المحرّك إلا إذا فتحت الإعدادات.</strong> كانت اللوحة التي ترسم المنتقي هي التي تدفعه، فكان المحرّك عند كل تشغيل يعدّ تمهيديًا بلا شيء حتى تُزار تلك الشاشة.","changelog.5ce1635ae9eb":"<strong>كان التوزيع يُعاد عرضه ستين مرة في الثانية وهو متوقف</strong>، معيدًا بناء كل صف مسار، من أجل موضع رأس تشغيل لا يقرؤه إلا زرّان.","changelog.f3c36b3ce60a":"أُصلح — النموذج، وما كان الملف العدائي قادرًا على فعله","changelog.793366e43f5d":"⛔ <strong>كان مسار <code>.wav</code> داخل ملف مشروع يُفتح دون فحص.</strong> يصل ملف <code>.oscillate</code> بالتنزيل أو من متعاون، والملف المحرّر يدويًا كان قادرًا على تسمية مسار على <strong>جهاز آخر</strong> — فيصادق Windows عليه تلقائيًا، مسرّبًا بيانات اعتماد المنتج، لمجرد فتح الملف. يرفض Oscillate الآن أي مسار ليس ملفًّا محليًا عاديًا قبل فتحه.","changelog.772fa7975871":"⛔ <strong>كان أمر استيراد يقبل مسار ملف من الواجهة.</strong> صار يُؤخذ الآن من منتقٍ أصلي فقط، مثل كل مسار آخر في المنتج — واختبار يقرأ المصدر ليُبقي الأمر كذلك.","changelog.62b162f4459b":"⛔ <strong>كانت إزالة مسار قادرة على إضاعة مقاطعه إلى الأبد.</strong> الإزالة المبنية خارج الحركة العادية لم تكن تدوّن أي طريق عودة للمقاطع التي حذفتها، فكان التراجع يعيد المسار فارغًا. وهي مرفوضة الآن.","changelog.ac5b9eebbbf8":"<strong>حذف مجموعة كان يترك المسارات التي داخلها تشير إليها.</strong> كان المازج والتوزيع كلاهما يرسمان مجموعة لم تعد موجودة. أما الآن فيُرفع أبناؤها إلى المجموعة التي فوقها.","changelog.4ced12bd8446":"<strong>التسجيل الذي قطعه عطل كان يُستورد بلا هوية محتوى</strong> وبطول مأخوذ من ترويسته لا مما كان موجودًا فعلًا. صار يُرفض، مع جملة تقول ما حدث.","changelog.82c6f3242320":"<strong>كان المشروع قادرًا على إطفاء حد الساعتين الخاص به</strong> بحقل واحد محرَّر.","changelog.6a9f69980c92":"<strong>كان قارئ الذُّرى يحدد حجم مخزن مؤقت من رقم في الملف.</strong>","changelog.1e1652d0b1fc":"أُضيف — المشروع (المرحلة 3)","changelog.000b52ad8bce":"<strong>نسخة واحدة من Oscillate، لا عدة نسخ.</strong> تشغيل Oscillate وهو يعمل سلفًا يُحضر النافذة الموجودة إلى المقدمة بدل بدء عملية ثانية. ⛔ نسختان من Oscillate ستتنازعان جهاز الصوت و<code>preferences.json</code> ومجلد اللقطات — وأول هذه يظهر لافتة تبدو كعطل في العتاد.","changelog.8289318a37f6":"<strong>سجل العمليات.</strong> كل تغيير يجريه المنتج <code>Operation</code> واحدة، والتراجع والإعادة والتعاون وإرجاع الجلسة ودفتر التأليف أربع قراءات لذلك السجل الواحد. الحركة المركّبة عملية <strong>واحدة</strong> — سحب أربعين نوتة يحتاج ضغطة تراجع واحدة، لا أربعين.","changelog.4eb96d6377e1":"<strong>تراجع وإعادة بلا حدود، لكل مؤلف.</strong> <code>Ctrl</code>/<code>⌘</code>+<code>Z</code> يتراجع عن آخر تغيير <em>لك</em> ولا يتراجع عن تغيير غيرك أبدًا، منذ أول إيداع، قبل أن يوجد أحد تشاركه جلسة. 10,000 عملية تقيس <strong>5.8 MB</strong>، وأبطأ تراجع منفرد <strong>7 µs</strong> — مقابل ميزانيتين من 200 MB و16 ms.","changelog.bdc94205dc9c":"<strong>الأنماط.</strong> المقطع <em>يشير</em> إلى محتواه ولا يملكه أبدًا — في MIDI كما في الصوت. ضع جزء طبول من أربع مازورات اثنتين وثلاثين مرة فيكون هناك اثنان وثلاثون مقطعًا ونمط <strong>واحد</strong>: حرّره مرة فيتغير كل موضع. <em>جعله مستقلًا</em> إجراء صريح يشقّه.","changelog.388422931fa2":"<strong>ملف <code>.oscillate</code>.</strong> حاوية ذات إصدارات: بيان JSON إضافة إلى كتل ثنائية. ⛔ يُفحص كل طول ضمن حدوده قبل أن يبلغ مخصِّصًا، فالملف التالف أو العدائي <strong>يُخطئ مع ذكر السبب</strong> ولا يُجهض العملية أبدًا. وكل بادئة لملف صالح وكل تحوير لبايت واحد فيه مختبرة.","changelog.d522a5cbcc8e":"<strong>الحفظ، والحفظ باسم، والفتح، وسجل جلسات تستطيع التصرف فيه.</strong> يمكن فتح المشاريع الحديثة، و<strong>إظهارها في مدير ملفاتك</strong>، ونسيانها واحدًا تلو الآخر أو مسحها — القائمة سجل لما كنت تعمل عليه، فهي لك لتمسحها. والمشروع الذي انتقل ملفه يصبح رماديًا و<strong>يحتفظ بصفّه</strong>، فإعادة توصيل القرص تستعيده.","changelog.260ee88cb364":"<strong>جلسة افتراضية.</strong> احفظ التوزيع الذي تبدأ منه دائمًا — المسارات والأسماء والألوان والتوجيه وسلاسل الأجهزة والإيقاع والميزان — و<code>New Project</code> يفتحه. ⛔ لا مقاطعك أبدًا ولا صوتك أبدًا. و<em>إعادة الضبط إلى الافتراضي المصنعي</em> تعيد افتراضي Oscillate الخاص.","changelog.b5e407459915":"<strong>استعادة الأعطال حتى لحظة العطل.</strong> كل عملية تُدوَّن في ملف ملحق لحظة حدوثها، فلا شيء يُفعل وقت العطل — العمل على القرص سلفًا. ⛔ الاستعادة <strong>تُعرض</strong> ولا تُطبَّق أبدًا: مشروعك المحفوظ لا يُكتب حتى تقول ذلك. والنافذة الزمنية التي قد يكلّفها انقطاع الكهرباء مذكورة في قائمة ملف لا مُضمرة.","changelog.b31ad4e4a0db":"<strong>الملف من Oscillate أحدث يرفض أن يُفتح، ويسمّي النسختين كلتيهما</strong>، ويعرض الفتح للقراءة فقط. ⛔ والحقل الذي لا يفهمه هذا البناء يُحمل عبر الحفظ بدل أن يسقط بصمت.","changelog.4f94248b72da":"<strong><code>Ctrl</code>/<code>⌘</code> + <code>N</code> و<code>O</code> و<code>S</code> و<code>Shift+S</code> و<code>Z</code> و<code>Shift+Z</code></strong>، كلها قابلة لإعادة التعيين، وكلها تُتجاهل أثناء الكتابة في حقل.","changelog.ee8c3606ce09":"الحفظ لا يقتطع أبدًا الملف الذي يستبدله. يُكتب المشروع الجديد بجانب القديم، ويُزامَن إلى القرص، ولا يُعاد تسميته فوقه إلا بعد ذلك — فلا توجد لحظة يحمل فيها المسار نصف مشروع.","changelog.6ceed1e0814b":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-08-25\">2026-08-25</time></span>","changelog.f67bfa325008":"<strong>الغلاف، وصوت.</strong> المرحلتان 1 و2 معًا — أول درجة يبدو فيها Oscillate كنفسه <strong>و</strong>يفتح جهازًا، ويحافظ على الوقت، ويمزج، ويقيس، ويسجّل. ⚠ مبني ومُتحقَّق منه، <strong>غير منشور</strong> (القاعدة 5 من الميثاق).","changelog.5796e58a5bdd":"<strong>نافذة بلا إطار بشريط عنوان خاص بها</strong> و− □/❐ ✕. منطقة السحب تستثني عناصر التحكم، والنقر المزدوج يكبّر، والالتقاط إلى الحواف (aero-snap) يبقى يعمل لأن السحب يُسلَّم إلى حلقة التحريك الخاصة بنظام التشغيل. موضع النافذة وحجمها محفوظان لكل جهاز — و<strong>لا يُستعادان أبدًا على شاشة لم تعد موصولة</strong>.","changelog.f9b314697ae1":"<strong>نظام اللوحات</strong>: مستعرض الملفات، والمولّدات، والمحرّر، والمازج، والغرفة، كلٌّ منها يُظهَر ويُخفى بزر صورة <em>هو</em> حالة المنطقة، على <code>Ctrl/⌘+1…5</code>.","changelog.a9109db1e242":"<strong>اثنا عشر رمزًا للوحات</strong>، مرسومة داخليًا على شبكة 24 × 24 بـ <code>currentColor</code>، وبوابة تعرض كلًّا منها بحجم 16 px وتفشل إن تشارك اثنان منها الصورة الظلية نفسها.","changelog.69e7b7c3ab85":"<strong>إطار التخطيط</strong> — الشبكة من التصميم، وفواصل قابلة للتشغيل بلوحة المفاتيح، ومناطق تنطوي بترتيب موثَّق كلما ضاقت النافذة، وزر المنطقة التي لا تتسع معطّل ويقول السبب.","changelog.147bb006862f":"<strong>تحجيم تناسبي</strong>: معامل تحجيم واحد، يُحسب في مكان واحد، والخط يتحجّم أبطأ من الهندسة، ومُختبَر على ثمانية عروض من 1280 إلى 3840 بحثًا عن هوامش ميتة وأهداف نقر صغيرة جدًا.","changelog.ac2529873765":"<strong>ثلاث حالات للسمة — النظام والفاتحة والداكنة — محفوظة لكل جهاز</strong>، والتبديل يركب القطع.","changelog.015a610ef72a":"<strong>القطع</strong>: مسحة قطرية واحدة، على محور واحد، تستعملها كل نافذة مشروطة وكل لوحة وتبديل السمة. وتحت <code>prefers-reduced-motion</code> هو مسار مختلف لا مسار أقصر، وطبقة المسح لا تُركَّب أبدًا.","changelog.d1b1a8561adc":"<strong>نافذة الإعدادات</strong> بأقسامها العشرة كلها، و<code>Esc</code>، وحصر للتركيز، وتطبيق حيّ، وحفظ لكل جهاز. الأقسام التي ليس خلفها نظام فرعي بعد تقول ذلك بدل أن ترسم عناصر تحكم لا تغيّر شيئًا.","changelog.9b7d9224e453":"<strong>جدول اختصارات لوحة مفاتيح قابل لإعادة التعيين</strong> — جدول واحد، تقرؤه المعالِجات ويُعرض في الإعدادات، والتعارضات تُرفض بالاسم.","changelog.01315f761e95":"<strong>ستة عناصر تحكم أساسية</strong> — Knob وFader وMeter وToggle وSelector وNumberField — تتشارك حركة واحدة، مع باليستيات مقاييس نقية ومختبرة إطارًا إطارًا.","changelog.297b0ff97ebe":"<strong>شاشة البداية</strong>: يقفز الـ Oscillate، ويضرب النصل، ويمسحه القطع ليكشف التوزيع. أي مفتاح أو نقرة يتخطاها، ولا تطيل بدء التشغيل البارد أبدًا، والرسم ذو الـ 2 MB يُصغَّر وقت البناء.","changelog.1aac2bdb22c4":"<strong>اتفاقية التشغيل الأول</strong>، تُعرض من <code>EULA.md</code> نفسه وتُسجَّل مقابل بصمة ذلك النص، فالاتفاقية المتغيّرة جوهريًا تُطلب مرة أخرى. لا شيء يعمل قبل القبول — بما في ذلك كل اختصار لوحة مفاتيح.","changelog.4413c389097a":"<strong>الإبلاغ عن الأخطاء والأعطال.</strong> ذعر Rust يكتب تقريرًا قبل أن تذهب العملية؛ وإخفاق التصيير يكتب واحدًا و<strong>يترك التشغيل مستمرًا</strong>. التقارير محلية، وتُعرض كاملة، ومحدودة بأحدث عشرين، ومنقّحة من كل مسار مطلق وعنوان. ⛔ لا شيء يُرسل تلقائيًا أبدًا، و<em>افتح بلاغًا معبّأً</em> يسلّم عنوان URL إلى متصفحك بدل أن يُجري الطلب.","changelog.ed49327ae78a":"بوابة <code>bindings</code> بوابة انجراف حقيقية لا اختبار يكتب فوق ما يفحصه: تلتقط لقطة، وتعيد التوليد، وتقارن، وتفشل حين لا ينتج التصدير شيئًا على الإطلاق.","changelog.38d32c539046":"بوابات Playwright تختار بحسب <strong>المشروع</strong> لا بتسمية ملفات المواصفات — فالمواصفة الجديدة كانت تعمل محليًا ولا تعمل في CI أبدًا.","changelog.3f0c0f6da683":"كانت حركة قناع القطع تجري في الاتجاه الخطأ، فكانت كل نافذة مشروطة وكل منطقة وشاشة البداية تخفت إلى <strong>الاختفاء التام</strong> بعد نحو 260 ms من ظهورها، بينما تبقى قابلة للنقر. وُجد بالعين؛ وصار مثبّتًا الآن بتحقق من الإطارات المفتاحية وباختبارات تقارن بكسلات حقيقية.","changelog.666c4c2ea362":"التفضيل الذي يتغير خلال 250 ms من الخروج كان يضيع، لأن الكتابة مؤجَّلة بتأخير ولا شيء كان يفرّغها عند الخروج.","changelog.034ca2037612":"تغيّر — شاشة البداية والأيقونة، بقرار المالك (2026-08-25)","changelog.7f6a52a11899":"⛔ <strong>شاشة البداية نافذة شفافة مستقلة الآن.</strong> كانت طبقة داخل التطبيق، وهذا عنى أمرين لم تستطع الإفلات منهما: لم تكن تستطيع أن تكون أكبر من نافذة التطبيق — 960×600 منطقية على شاشة 2560×1600 بتحجيم 150 % — وكان هناك دائمًا <em>شيء</em> مرسوم خلف الشكل المقصوص. هي الآن <code>splash.html</code>، صفحة منفصلة في نافذة منفصلة بملء الشاشة <strong>بلا خلفية من أي لون</strong>، تُبنى ويُحدَّد حجمها في Rust من الشاشة التي تُفتح عليها. وما يحيط بالـ Oscillate هو سطح مكتبك.","changelog.eccd1dd3e489":"حزمة شاشة البداية <strong>0.7 kB من JavaScript و1 kB من CSS</strong>، منفصلة تمامًا عن الـ 189 kB الخاصة بالتطبيق. وهي أول شيء يُفكّ عند التشغيل البارد.","changelog.405302c0a35a":"<strong>القفزة قفزة.</strong> تدخل من تحت الحافة السفلية، وترتفع إلى قمة، ثم تهبط — مقتربة منك باستمرار عبر النصفين، من تحجيم 0.13 → 2.0، منتهية أبعد بكثير من حواف الشاشة. الإطارات المفتاحية عيّنات من منحنيين ناعمين لا أوضاع موضوعة يدويًا.","changelog.c8138b18399e":"⚠ <strong>تبقى نافذة التطبيق مخفية حتى تسلّم شاشة البداية</strong>، ويُسلّح Rust مراقبًا كي لا تستطيع صفحة لا تعاود الاتصال أبدًا أن تترك عملية تعمل بلا نافذة على الإطلاق.","changelog.c72349087278":"⛔ <strong>أيقونة التطبيق مرسومة من جديد، لا مصوَّرة.</strong> ليوم واحد كانت الأيقونة المشحونة هي شكل شاشة البداية مقصوصًا من قناعه؛ وعند 16 px تكون صورة الجسم الكامل طينًا. هي الآن <strong>كاتانا تخترق حلقة مقطوعة</strong>، مولّدة من رموز التصميم بالحساب — الحلقة لـ <em>أربعة منتجين، جلسة واحدة</em>، والسيف للـ Oscillate، على محور المنتج نفسه −22°.","changelog.480ac8d3405f":"تغيّر — توقيت شاشة البداية وسلوكها","changelog.2ef806b69680":"⛔ <strong>إلزامية ولا يمكن تخطيها، كما في FL Studio.</strong> لا زر تخطٍّ، ولا مستمع لأي مفتاح. تعرض القفزة والضربة والقطع كاملة عند كل تشغيل حتى تطفئها في <strong>الإعدادات ← المظهر</strong>، ولا يُحترم ذلك المفتاح إلا بعد أن تكون شاشة البداية قد عُرضت كاملة مرة واحدة على الأقل على هذا الجهاز — فلا يستطيع ملف تفضيلات منسوخ من جهاز آخر تخطي بطاقة عنوان لم يعرضها هذا الجهاز قط.","changelog.ddddf34a2c57":"⚠ <strong>هذا يعكس قاعدتين من § F-21</strong>، عن قصد: <em>«قابلة للتخطي في أي لحظة»</em> و<em>«لا تطيل بدء التشغيل البارد أبدًا»</em>. صارت تكلّف نحو ثانيتين. ما يبقى هو <strong>سقف</strong> — الإلزامي ليس كاللامحدود، واختبار ما زال يتحقق من أنها تنتهي.","changelog.40d388966a63":"⚠ <strong>كان السلوك القديم أسوأ مما بدا.</strong> كان التسلسل يقفز إلى الضربة لحظة جهوزية التطبيق، والتطبيق يكون جاهزًا فورًا تقريبًا — فعلى أي جهاز حقيقي كانت القفزة تُعرض نحو خُمسها ولم يكن السيف ينزل قط.","changelog.b3f010a5d099":"<strong>الشكل أكبر بكثير ويقفز نحوك حقًّا</strong> — متمركز تمامًا بدل أن يكون عنصرًا مرنًا يصارع الشعار النصي على العمود، ينمو 2.7× عبر القفزة وينتهي بارتفاع يكاد يكون كاملًا.","changelog.5e796ac2c528":"<strong>شاشة البداية داكنة في السمتين كلتيهما.</strong> على جهاز فاتح كانت شكلًا صغيرًا في حقل أبيض؛ وسطر المنتج نفسه هو <em>استوديو داكن فيه نصل واحد من الضوء</em>. إنها السطح الوحيد الذي لا يتبع السمة، و<code>splash.contrast.test.ts</code> يفحص ألوانها الخاصة بدلًا من ذلك.","changelog.be115dfca1d9":"<strong>يُولَّد الرسم بالدقة الكاملة</strong> (بارتفاع 1531 px عند 2×)، لأنه يُعرض الآن كبيرًا بما يكفي ليبدو الأصل القديم ذو الـ 1280 px ضبابيًا.","changelog.4806942da19f":"⛔ <strong>لم تعد شاشة البداية تُمسح دخولًا، بل خروجًا فقط.</strong> هي أول سطح على الشاشة ليس خلفه شيء تُكشف منه، وتقنيعها عند الدخول كان يعني أن إطار التطبيق يظهر <em>عبرها</em> طوال مدة القطع — ومضة من الواجهة نفسها التي وُجدت لتقديمها، عند كل تشغيل.","changelog.917a1f65a62b":"<strong>ما وجدته مراجعات بوابة المرحلة نفسها، وأُصلح هنا:</strong>","changelog.f3f677980569":"⛔ <strong>كان تقرير العطل يغادر الجهاز دون تنقيح.</strong> كان جانب Rust ينقّح في الطريق إلى القرص، لكن نافذة الحوار كانت تعيد ضم الخطأ الخام بنفسها — فالنسخة التي يستطيع المستخدم وضعها في الحافظة أو تنزيلها أو لصقها في <strong>بلاغ GitHub عام</strong> كانت هي التي لم ينقّحها شيء، تحت لافتة تعد بأنها لا تحتوي على أي مسارات ملفات. هناك الآن تقرير واحد: يُركَّب ويُنقَّح مرة واحدة، في Rust، وهو النص المعروض والنص الوحيد الذي يمكن إرساله. وحين لا توجد واجهة خلفية للتنقيح، لا تُعرض أزرار الإرسال على الإطلاق.","changelog.7ddebee8ab10":"⛔ <strong>الخروج والنافذة مكبّرة كان يدمّر حجمها الحقيقي.</strong> كان المستطيل المحفوظ هو المكبَّر، فإلغاء التكبير في التشغيل التالي كان يعيدها إلى الحجم الذي هي عليه سلفًا، ويضيع الحجم المرتّب إلى الأبد.","changelog.b22c92d59e1d":"⛔ <strong>العمليتان اللتان تكتبان <code>preferences.json</code> كانت كلٌّ منهما قادرة على محو نصف الأخرى.</strong> عند الإغلاق ينطلق تفريغ الواجهة الأمامية وحفظ هندسة Rust معًا؛ وأيهما وصل ثانيًا كان يفوز بالملف كله، مكلّفًا إما موضع النافذة وإما آخر ربع ثانية من السمة والتخطيط والقبول. الكتابتان تندمجان الآن، فلم يعد الترتيب يهمّ.","changelog.9355bc11339a":"⛔ <strong>كان الحد الأدنى لحجم النافذة مُعلنًا بالبكسلات المنطقية</strong> بينما كل استعمال آخر للثوابت نفسها فيزيائي. عند تحجيم 150 % كانت النافذة الأولى تُفتح بحجم الشاشة ومتدلية عن الحافة بدل أن تكون متمركزة، ولم يكن لنقاط الطي تحت 1280 أن تنطلق أبدًا.","changelog.a0e64e3152ba":"⛔ <strong>عنوان المشارك في نهاية جملة، أو مع منفذ، لم يكن يُنقَّح</strong> — كان المقطع يحمل النقطة، فينقسم إلى خمسة أجزاء بدل أربعة ويفشل الفحص مفتوحًا. ولم يُنقَّح IPv6 قط على الإطلاق.","changelog.73fe3e54392a":"⛔ <strong>تقريرا عطل في الثانية نفسها كان أحدهما يكتب فوق الآخر</strong>، في ميزة قاعدتها ألا تطلب من المستخدم أبدًا إعادة إنتاج المشكلة قبل جمع الملف.","changelog.fd305290022c":"⛔ <strong>كان قفل إعادة التدفق راية لا عدّادًا</strong>، فأول مؤشر يُحرَّر كان يمسح إمساكًا ما زال سحب آخر يملكه — فيُعاد تدفق النافذة تحت يد ما زالت تسحب، وهذا بالضبط الإخفاق الذي يمنعه § F-35.","changelog.f97e1805f598":"الاختصار المعاد ربطه إلى <code>+</code> لم يكن يستطيع الانطلاق أبدًا: فاصل التركيبة ومفتاحها هما المحرف نفسه، فكان المفتاح يُحلَّل فارغًا. كان يُخزَّن ويُعرض ولا يفعل شيئًا.","changelog.1818dd50dc97":"بطاقة الاتفاقية المرفوضة لم يكن فيها حصر للتركيز، فكان مستخدم لوحة المفاتيح يستطيع الخروج بمفتاح Tab عبر الغطاء المعتم والضغط على أزرار شريط العنوان.","changelog.affbfc927387":"كانت قاعدة اللغة المخزّنة في <code>initialLocale</code> شيفرة لا يمكن بلوغها؛ والقرار الحقيقي كان يتخطى تحققها، مسلّمًا لغة لا يشحنها Oscillate مباشرة إلى i18next. ولم يكن منتقي اللغة في التذييل يحفظ الاختيار قط.","changelog.9e060fae8ad3":"كان التركيز لا يُعاد إلا حين تبقى النافذة المشروطة مركّبة، واثنتان من الثلاث تُزالان بدلًا من ذلك.","changelog.c3a66b9ba90c":"⛔ <strong>النافذة المكبّرة لم تكن تُعاد فتحها مكبّرة قط.</strong> يعطي Windows النافذة المكبّرة إطار تحجيم غير مرئي يتدلى ~11 px عن كل حافة، فيكون <code>y</code> المخزَّن لها <code>-11</code> — وكان حارس الاستعادة يطلب أن يكون شريط العنوان ذو الـ 64 px <em>كله</em> على الشاشة. فكانت كل نافذة مكبّرة خُزّنت يومًا تُعدّ غير صالحة وتُستبدل بصمت بقيمة افتراضية متمركزة. وُجد ببناء الملف التنفيذي للإصدار وتشغيله.","changelog.303430e5157f":"<strong>بوابات لم يكن ممكنًا أن تفشل، صارت حقيقية الآن:</strong>","changelog.b0bcf47ad11e":"لم تكن بوابة الانجراف <code>bindings</code> تُفرغ المجلد قبل إعادة التوليد، وts-rs يكتب فقط — فكان فرعا «الربط القديم» و«لم يُولَّد شيء على الإطلاق» كلاهما لا يمكن بلوغه. تُحقِّق من ذلك بزرع ربط يتيم ومشاهدة البوابة تتحول إلى الأحمر.","changelog.80822e6bc052":"كانت أربعة تحققات طرف لطرف تُحسم مقابل حالة كانت صحيحة سلفًا قبل ضغطة المفتاح التي تختبرها، وكان <code>dismissSplash</code> يأخذ عيّنة لشاشة بداية لم تُركَّب بعد — تاركًا الطبقة تبتلع النقرة التالية في كل اختبار يفتح التطبيق.","changelog.977117c0a2a3":"أُضيف — محرّك الصوت (المرحلة 2)","changelog.e7b90e4f7a6c":"<strong>محرّك صوت في الزمن الحقيقي</strong> يفتح جهازًا ويُصيّر كتلًا <strong>بلا تخصيص، ولا قفل، ولا استدعاء نظام في الاستدعاء الصوتي</strong> — مفروضًا بمخصِّص عام عدّاد مُسلَّح حول الاستدعاء، لا بالمعاينة.","changelog.e61632d46641":"<strong>رسم تصيير بلا أقفال</strong> يُسلَّم إلى خيط الصوت بتبديل مؤشر ذرّي، وتُحرَّر الخطة المتقاعدة على خيط الواجهة. خيط الصوت لا يحرّر شيئًا أبدًا ولا ينتظر أبدًا.","changelog.ad0918e4e397":"<strong>النقل</strong>: التشغيل والإيقاف والتسجيل وتحديد الموضع والتكرار وخريطة الإيقاع وخريطة الميزان والمترونوم والعدّ التمهيدي — كلها بنبضات فرعية ذات فاصلة ثابتة (960 PPQ × 65 536) فلا تنجرف جلسة بطول ساعة.","changelog.c3381e2b7634":"<strong>المازج</strong>: القنوات، والمنزلق، والبان بقدرة ثابتة (−3.01 dB في المركز)، والكتم، والإفراد، والإرسالات، والمجموعات، والماستر، مرتّبة بفرز طوبولوجي على علاقات الأب والإرسال كلتيهما.","changelog.3c007269b511":"<strong>القياس في بنك مشترك</strong>، يُقرأ عبر مخطط URI مخصّص لا عبر JSON IPC — تخطيط ثنائي ثابت، فلا تكلّف ستون قراءة في الثانية أي تحليل.","changelog.b0b53fddf264":"<strong>تسجيل الصوت</strong>: التجهيز، واختيار الدخل، والمراقبة (<strong>مطفأة افتراضيًا</strong>)، والعدّ التمهيدي، والإدخال الفوري، تُكتب مباشرة على القرص عبر حلقة بلا أقفال بواسطة خيط كاتب. تُكتب ترويسة WAV <strong>قبل</strong> العيّنة الأولى، واللقطة التي لم تُرقَّع ترويستها قط يمكن استعادتها من حجم الملف.","changelog.57a6593bdb89":"<strong>دخل MIDI</strong> بتحزيم وفكّ بلا فقدان عبر طابور بلا أقفال.","changelog.ae5e6e02af07":"<strong>التعامل مع التوصيل الساخن للأجهزة وتغيّر معدل العيّنات</strong> — افصل واجهة صوتية فيتوقف النقل، ويسمّي الشريط الجهاز، ولا يُمسّ المشروع؛ و<em>استئناف</em> يعيد فتحه.","changelog.e435ef5b747d":"أُصلح — ما وجدته مراجعة بوابة المرحلة 2","changelog.54faffc42107":"⛔ <strong>ثلاثة من هذه كانت مبنية بالكامل ومختبرة بالكامل على مستوى الوحدات، ولم تعمل إطلاقًا في التطبيق المشحون.</strong> وهي مسرودة بهذه الروح: غطّت الاختبارات القطع ولم تغطِّ الوصلة بينها قط.","changelog.5bba3d0973a6":"⛔ <strong>لم يعمل التسجيل قط خارج الاختبارات.</strong> لم يكن الاستدعاء الإنتاجي يمرّر أي نقطة سحب للتسجيل — كل جزء من المسار كان موجودًا ولا شيء يستدعيه.","changelog.bf141689a01d":"⛔ <strong>كان كل مقياس مسار ميتًا.</strong> خانة مقياس الشريط لم تكن تُسند إلا إلى الماستر، والبنك كان بحجم قناتين بصرف النظر عن عدد المسارات.","changelog.d4e9a63a6aad":"⛔ <strong>لم يكن أي مقياس يستطيع التحرك في البناء المحزوم.</strong> تُقدَّم اللقطة من أصل مختلف عن أصل الصفحة ولم تكن تحمل <code>Access-Control-Allow-Origin</code>. كانت CSP تسمح بالمخطط سلفًا — <strong>CSP ليست CORS</strong>، وخادم التطوير لا يُظهر ذلك أبدًا.","changelog.e27afc804d21":"⛔ <strong>أي تكرار لا يبدأ عند المازورة 1 كان يقفز إلى بداية المشروع.</strong> كان الالتفاف يطرح قيمة <em>نبضة</em> من موضع <em>نبضة فرعية</em>. ⚠ كل اختبار تكرار موجود كان يستعمل المازورة 1، حيث يكون الحساب المعطوب صحيحًا بالمصادفة.","changelog.afe43c0d4e2a":"<strong>الالتفاف في منتصف الكتلة كان يعيد عزف رأس الدخل</strong>، لأن كل امتداد كان يقدّم شريحة الخرج لا شريحة الدخل — تلعثم في كل تكرار أثناء المراقبة.","changelog.ea0d9ab4ca81":"<strong>تحديد الموضع الواصل مع التسجيل كان يلتهم العدّ التمهيدي.</strong> زر عادي واحد («التسجيل من بداية التحديد») يرسل الاثنين داخل فجوة كتلة واحدة.","changelog.212a1425d0de":"⛔ **الضغط على <em>إيقاف</em> كان قادرًا على تجميد النافذة.** كانت اللقطة تُغلق على خيط الواجهة، بانتظار كاتب قد يكون معطّلًا على قرص متوقف — وOscillate يرسم شريط عنوانه بنفسه، فلم يكن هناك إطار من نظام التشغيل يُعتمد عليه.","changelog.5601b4005190":"<strong>الجهاز الذي فشل في كتلته الأولى كان يُعاد فتحه في حلقة محكمة</strong>، بلا توقف وبلا حد؛ والخطأ المرفوع أثناء فتح التدفق كان قادرًا على الضياع، تاركًا تطبيقًا صامتًا يُبلغ عن جهاز سليم.","changelog.6ce4996c40aa":"<strong>تعديلات المازج التي تُجرى أثناء فتح جهاز كانت تسقط</strong> من مسار الصوت، فالمنزلق المحرَّك أثناء إعادة الاتصال كان يقرأ قيمة ويصدح بأخرى.","changelog.8008bbcdc222":"<strong>كان المترونوم قادرًا على الفيض والذعر داخل الاستدعاء الصوتي</strong> عند تحديد موضع قرب نهاية النطاق.","changelog.12e2665533c9":"أُصلح — ما وجدته مراجعة للإصلاحات","changelog.108a22259133":"⛔ <strong>مراجعة ثانية، نطاقها إيداع الإصلاح لا الأخطاء.</strong> وجدت ستة عيوب أخرى، <strong>اثنان منها خطيران، وأحدهما صنعه إصلاح.</strong> مكتوب هنا لأن هذه هي الحجة على وجود هذه الجولة أصلًا.","changelog.198888ba7d98":"⛔ <strong>حلقة لانهائية في الاستدعاء الصوتي.</strong> جعل <code>span_end</code> و<code>first</code> في المترونوم مُشبَعين أغفل خطوة الحلقة نفسها. وفي بناء الإصدار كان يلتف ويدور عبر ~10¹¹ تكرار — <strong>أسوأ من الذعر الذي حلّ محله.</strong>","changelog.3805b261f86a":"⛔ **ضغطة <em>استئناف</em> واحدة كانت تكلّف اثنتين، وكان بوسعها ركن خيط الجهاز إلى الأبد.** كانت حلقتان تستهلكان راية إعادة الفتح نفسها، فالضغطة خلال فتح الجهاز الذي يستغرق من نصف ثانية إلى ثانيتين كانت تهدم الجهاز الذي فُتح للتو.","changelog.7e57ef4b8c08":"<strong>اللقطة لم يكن بوسعها أن تنتهي أبدًا</strong> إن كان النقل ما زال يدور: كان الكاتب لا يقرأ راية التوقف إلا عند تصريف فارغ، وكان خيط الصوت يواصل ملء الحلقة. ذيل التصريف محدود الآن.","changelog.2c2d115a8222":"<strong>الشريط الواقع بعد بنك المقاييس كان يُسلَّم خانة غير موجودة</strong> — عيب المقياس الميت عائدًا عند رقم قناة أعلى. صار لا يحصل على مقياس، وهذا صادق، بدل واحد متجمد عند −∞.","changelog.1b65e543046f":"<strong>كانت لقطة المقاييس تحمل الخانات الـ 1 024 كلها ستين مرة في الثانية</strong> — 16 KB لكل إطار لجلسة فيها شريطان. صارت تحمل القنوات التي حملت عيّنة فعلًا.","changelog.cab3bd8a9f1a":"<strong>كان عدد العيّنات الساقطة يُقرأ قبل التصريف</strong>، فكان يفوّت بالضبط حالات السقوط التي يسبّبها القرص البطيء.","changelog.fb88cf8c59c9":"⚠ <strong>اختباران لم يكن ممكنًا أن يفشلا</strong>، وهذا أسوأ من غيابهما — كلاهما كُتب عند هذه البوابة، وكلاهما مُصلح الآن: اختبار مترونوم لم يكن دخله يدخل الحلقة التي يختبرها قط، واختبار مقياس لكل شريط بمسار واحد، حيث تسرّب الماستر إلى الخانة عبر قانون البان ونجح أمام السلوك نفسه الذي كُتب لرفضه.","changelog.6c6912c7b7c5":"أُصلح — ما صادفته المراجعة الأمنية","changelog.3bc132875a67":"⚠ <strong>لم يجد <code>/security-review</code> أي ثغرة HIGH أو MEDIUM.</strong> برّأ ترويسة CORS لمخطط المقاييس تحديدًا: <code>register_uri_scheme_protocol</code> اعتراض داخل عرض الويب لا مقبس، فلا يمكن بلوغ العنوان من خارج الجهاز. وما وجده في طريقه كان أسوأ مما كان يبحث عنه.","changelog.e6bf7c677991":"⛔ <strong>كان يمكن اقتطاع لقطة بصمت.</strong> كانت ملفات اللقطات تُسمّى من ساعة الحائط تحت تعليق يدّعي عدّادًا رتيبًا، وكان الكاتب يستعمل <code>File::create</code>، الذي يقتطع. ⚠ كان كامنًا حتى انتقل إغلاق اللقطة من خيط الواجهة — وبعدها صار بوسع لقطة جديدة أن تكتب فوق لقطة ما زالت تُكتب. صار الآن <code>create_new</code>، وتسلسلًا حقيقيًا لكل جلسة، وحارسًا يرفض البدء ما دامت اللقطة السابقة قيد الإغلاق.","changelog.b135c10bd85f":"<strong><code>Access-Control-Allow-Origin</code> قائمة سماح لا <code>*</code></strong> — اتُّخذ ذلك تقويةً، لا لأنه كان قابلًا للاستغلال.","changelog.c8f633bba310":"تغيّر — صوت Windows، بقرار المالك (2026-08-25)","changelog.a2460f3b52b6":"⛔ <strong>خرج ASIO من المنتج.</strong> رخّصت Steinberg حزمة التطوير ترخيصًا مزدوجًا في أكتوبر 2025 (GPLv3 أو أحدث، <strong>أو</strong> اتفاقية مملوكة مجانية). ⛔ <strong>رُفض خيار GPLv3</strong>: كان سيضع مصدر Oscillate نفسه تحت الحقوق المتروكة، وGPL <strong>تسمح صراحةً للآخرين ببيع</strong> ما يتلقّونه. أما الخيار المملوك — مجاني، بتوقيع واحد، ويسمح بالمصدر المغلق — فقد رُفض بدل توقيع عقد من أجل قدرة يقدّمها WASAPI سلفًا. ⚠ <strong>يبقى متاحًا وقابلًا للعكس؛ ولا شيء في الشيفرة يعتمد على هذا الاختيار.</strong>","changelog.9b112e158a81":"<strong>التأخير المنخفض على Windows هو WASAPI الحصري + <code>IAudioClient3</code></strong>، مستهدفًا لـ <code>v0.4.0</code>. ⚠ <strong>لا يوجد طريق MIT/Apache إلى ASIO</strong> — كل غلاف مرخّص بترخيص متساهل لكنه يُترجم مقابل ترويسات Steinberg، وترخيص الغلاف لا يستطيع منح حقوق على ما تملكه Steinberg.","changelog.894975a8d218":"<strong>الحد الأدنى المدعوم هو Windows 10 1607+</strong>، الذي يتطلبه <code>IAudioClient3</code> وWebView2 سلفًا. ⛔ <strong>Windows 11 ليس مطلوبًا ويجب ألا يصبح مطلوبًا.</strong>","changelog.f376443b92b4":"<span class=\"release__meta\"><span class=\"release__ver\">v0.0.1</span><time class=\"release__date\" datetime=\"2026-08-24\">2026-08-24</time></span>","changelog.9f343f82939c":"<strong>الأساس، والمستودع، والعمود الفقري لـ CI.</strong> نافذة فارغة تُبنى وتعمل وتحميها كل بوابة سيعتمد عليها هذا المشروع يومًا — كُتبت قبل أن يوجد شيء يستحق الحماية، لأن البوابة المضافة لاحقًا بوابة يجب تركيبها رجعيًا عبر كل ما بُني دونها.","changelog.b9f3e0e185fd":"⚠ <strong>وسم، لا إصدار. لا توجد تنزيلات ولن توجد حتى <code>v1.0.0</code>.</strong> بُنيت مثبّتات هذه الدرجة وثُبّتت وشُغّلت وأُخذت بصماتها، ثم <strong>احتُفظ بها بدل نشرها</strong>.","changelog.1c8b846c2976":"المستودع، وترخيص «جميع الحقوق محفوظة»، واتفاقية EULA، وملف <code>.gitignore</code> يُبقي وثائق التخطيط الخاصة خارجًا <strong>منذ أول إيداع</strong>.","changelog.26c9317c192c":"مساحة عمل Cargo من ثلاثة عشر عضوًا — كل حزمة تتطلبها البنية، كلٌّ منها هيكل قابل للترجمة — وغلاف Tauri 2.","changelog.0ad7dd57c2b3":"الواجهة الأمامية بـ React 19 / Vite / TypeScript / Tailwind 4، ورموز تصميم Oscillate: السمتان كلتاهما، مع تسمية لوحة الألوان الفاتحة مرة واحدة بالضبط.","changelog.b58ef9a54add":"فهارس اللغات الثمانية عشر كلها، مضمّنة لا مجلوبة، والإنجليزية أولًا في المنتقي والسبع عشرة الأخرى أبجديًا.","changelog.de27cfddc011":"<strong>خمس عشرة بوابة</strong>، و<code>npm run ci:local</code> لتشغيلها كما يفعل CI: التنسيق، والتدقيق، والأنواع، واختبارات الوحدات، وclippy تحت <code>-D warnings</code>، وقائمة سماح التراخيص، والشكر المولَّد، وفحص أسماء المنتجات، وفحص «لا ذكاء اصطناعي/لا قياس عن بُعد/لا HTTP»، وPlaywright، ومسح 18 × 2 للسمات واللغات.","changelog.014c5ad1e881":"GitHub Actions عبر Windows وmacOS وLinux، مع تثبيت كل إجراء على بصمة SHA لإيداع، وفحص كل ملف تنفيذي منزَّل مقابل بصمة SHA256.","changelog.6b279b513071":"<code>THIRD-PARTY-NOTICES.md</code> وبيانات الشكر داخل التطبيق، كلاهما مولَّد من رسم الاعتماديات الحقيقي فلا يستطيع أيٌّ منهما الانجراف عمّا هو مربوط فعلًا."};
